	/**
	 * RuneLite doesn't turn plugins off when it closes, so this is the last chance to save. A reply on its way stops
	 * as it does when AI Chat is turned off: what was shown of it is kept, and the question can be retried next time.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown e)
	{
		// RuneLite posts this from the Swing thread, where the chats live; anywhere else, save without waiting.
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() ->
			{
				stopAll(CLOSED);
				saver.close();
			});
			return;
		}
		stopAll(CLOSED);
		ScheduledFuture<?> saved = saver.close();
		if (saved != null)
		{
			// RuneLite waits for this (up to a few seconds) before exiting.
			e.waitFor(saved);
		}
	}

	/** EDT. Stops every chat's request, if any, with {@code note} saying why. */
	private void stopAll(String note)
	{
		for (Chat c : chats)
		{
			runner.stop(c, note);
		}
	}

	private void showError(String message)
	{
		if (panel != null)
		{
			panel.showNote(message);
		}
	}

	/** A message can't go because AI Chat isn't set up: the panel points to its banner, which says why. */
	private void notSetUp()
	{
		if (panel != null)
		{
			panel.notSetUp();
		}
	}

	// ------------------------------------------------------------------
	// Game chat
	// ------------------------------------------------------------------

	private void ping(Chat chat, Chat.Message m)
	{
		boolean ok = m.role == Chat.Role.ASSISTANT;
		String who = ok ? m.who : "AI Chat";
		// An automatic chat name is just the start of the player's question: left out of notifications (they can
		// outlive the session) and of the game chat (where it was just asked).
		String name = chat.namedByPlayer ? chat.name : null;
		String text = m.text;
		String where = name != null ? " in \"" + name + "\"" : "";
		clientThread.invokeLater(() ->
		{
			notifier.notify(config.notifyOnDone(), (ok ? who + " replied" : "AI Chat hit a problem") + where);
			if (!config.echoToChat())
			{
				return;
			}
			String label = ok ? who : "AI Chat (error)";
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				echo(label, name, text);
			}
			else if (heldEchoes.size() < 10)
			{
				// Chat added at the login screen is never seen; keep it for later.
				heldEchoes.add(new String[]{label, name, text});
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN && !heldEchoes.isEmpty())
		{
			for (String[] held : heldEchoes)
			{
				echo(held[0], held[1], held[2]);
			}
			heldEchoes.clear();
		}
	}

	/** Client thread. {@code chatName}: shown with the first message, or null. */
	private void echo(String label, String chatName, String text)
	{
		for (String message : GameChatEcho.echoMessages(label, chatName, text, config.echoMaxChars()))
		{
			queueChat(message);
		}
	}

	private void gameMessage(String text)
	{
		queueChat(GameChatEcho.highlighted(text));
	}

	/** Thread-safe: the queue is flushed on the client thread. ChatMessageBuilder.append(String) escapes tags. */
	private void queueChat(String formatted)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Claude, through Anthropic's Messages API with the player's own API key. */
@Slf4j
class AnthropicApi implements ChatApi
{
	static final HttpUrl URL = HttpUrl.get("https://api.anthropic.com/v1/messages");
	private static final String VERSION = "2023-06-01";
	/** Room for a full answer; replies are billed by what's used, and the system prompt asks for short ones. */
	private static final int MAX_TOKENS = 16000;
	/**
	 * Server-side fallback: when a model's safety filter declines a request, Anthropic answers it with another Claude
	 * model instead of refusing outright. Asked for with every model; a model (or account) that doesn't take it says
	 * so, and is then asked without it for as long as the plugin runs.
	 */
	private static final String FALLBACK_BETA = "server-side-fallback-2026-07-01";
	private static final String FALLBACKS = "fallbacks";
	/** The model list comes in pages of up to 1000; more than a few pages would be something else going wrong. */
	private static final int MAX_MODEL_PAGES = 5;
	private static final String BUSY = "Anthropic is busy";
	private static final String RATE_LIMITED = "Anthropic's rate limit was hit";
	private static final String TOO_LONG = "Claude took too long to answer. Try again, maybe with a shorter question or a faster model.";
	private static final String COULDNT_SEND = "AI Chat couldn't send the next part of this. Check the API key in the Claude section of the settings.";

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl url;
	private final String apiKey;
	/** The plugin's scheduler, for waiting before a retry. */
	private final ScheduledExecutorService scheduler;
	/**
	 * What models have refused, by {@link #refusedKey}: here, server-side fallback. Shared by the plugin's requests (and
	 * with the OpenAI-compatible ones' refused settings) for as long as it runs.
	 */
	private final Map<String, Set<String>> refused;

	AnthropicApi(OkHttpClient http, Gson gson, HttpUrl url, String apiKey, ScheduledExecutorService scheduler,
		Map<String, Set<String>> refused)
	{
		this.http = http;
		this.gson = gson;
		this.url = url;
		this.apiKey = apiKey;
		this.scheduler = scheduler;
		this.refused = refused;
	}

	@Override
	public String displayName()
	{
		return "Claude";
	}

	@Override
	public Pending send(Conversation conversation, Listener listener)
	{
		Run run = new Run(conversation, listener);
		run.request();
		return run.pending;
	}

	static String refusedKey(String model)
	{
		return "anthropic " + model;
	}

	/** The request body for the first round, for tests. */
	JsonObject body(Conversation request, boolean replay, boolean fallback)
	{
		return body(request, replay, fallback, new JsonArray());
	}

	/**
	 * The request body. {@code replay}: send earlier replies back as they came, reasoning and look-ups included, where
	 * they were made under the same model, instructions and tools. {@code produced}: this reply's messages so far, when
	 * it has stopped to look things up.
	 */
	JsonObject body(Conversation request, boolean replay, boolean fallback, JsonArray produced)
	{
		String key = ChatApi.promptKey(request);
		JsonObject body = new JsonObject();
		body.addProperty("model", request.model);
		body.addProperty("max_tokens", request.maxTokens > 0 ? Math.min(MAX_TOKENS, request.maxTokens) : MAX_TOKENS);
		body.addProperty("system", request.system);
		if (!request.tools.isEmpty())
		{
			JsonArray tools = new JsonArray();
			for (ToolSpec t : request.tools)
			{
				JsonObject tool = new JsonObject();
				tool.addProperty("name", t.name);
				tool.addProperty("description", t.description);
				tool.add("input_schema", t.inputSchema);
				tools.add(tool);
			}
			body.add("tools", tools);
		}
		JsonArray messages = new JsonArray();
		for (Turn t : request.turns)
		{
			if (replay && replayable(t, key))
			{
				for (JsonElement m : t.rawMessages)
				{
					messages.add(m);
				}
			}
			else
			{
				JsonObject m = new JsonObject();
				m.addProperty("role", t.user ? "user" : "assistant");
				m.addProperty("content", t.text);
				messages.add(m);
			}
		}
		for (JsonElement m : produced)
		{
			messages.add(m);
		}
		body.add("messages", messages);
		body.addProperty("stream", true);
		// Prompt caching: everything up to the newest message is kept for a few minutes, so the next message in the chat
		// (or the next round of look-ups) reads it at a tenth of the price. The instructions and tools stay the same for a
		// whole chat, so the start of every request matches the one before.
		JsonObject cache = new JsonObject();
		cache.addProperty("type", "ephemeral");
		body.add("cache_control", cache);
		if (fallback)
		{
			body.addProperty(FALLBACKS, "default");
		}
		return body;
	}

	/** An earlier reply that can go back exactly as it came: made under the same prompt as this request. */
	private static boolean replayable(Turn t, String key)
	{
		return !t.user && t.rawMessages != null && t.rawMessages.size() > 0 && key.equals(t.rawKey);
	}

	/** One reply: its rounds of look-ups, its retries, and the one answer the listener gets. */
	private final class Run
	{
		private final Conversation conversation;
		private final Listener listener;
		private final Pending pending = new Pending();
		private final String key;
		/** This reply's messages so far: Claude's, and the tool results sent back. */
		private JsonArray produced = new JsonArray();
		/** The text of the rounds before this one. */
		private final List<String> texts = new ArrayList<>();
		private final Usage usage = new Usage();
		private final AtomicBoolean over = new AtomicBoolean();
		private String model;
		private boolean replay = true;
		private boolean fallback;
		/** Fallback was refused and left out; remembered once a request works without it. */
		private boolean fallbackDropped;
		/** The last request sent reasoning from earlier: Claude may refuse it. */
		private boolean replayed;
		private int toolRounds;
		private int retries;

		Run(Conversation conversation, Listener listener)
		{
			this.conversation = conversation;
			this.listener = listener;
			key = ChatApi.promptKey(conversation);
			model = conversation.model;
			fallback = !refused.getOrDefault(refusedKey(conversation.model), Set.of()).contains(FALLBACKS);
		}

		/** Sends this round's request. Throws if OkHttp won't take it (a header value it rejects). */
		void request()
		{
			JsonObject body = body(conversation, replay, fallback, produced);
			replayed = replay && (produced.size() > 0 || anyReplayable());
			Request.Builder request = new Request.Builder()
				.url(url)
				.header("x-api-key", apiKey)
				.header("anthropic-version", VERSION)
				.post(RequestBody.create(JSON, gson.toJson(body)));
			if (fallback)
			{
				request.header("anthropic-beta", FALLBACK_BETA);
			}
			Call call = http.newCall(request.build());
			pending.set(call);
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(Call c, IOException e)
				{
					failed(e);
				}

				@Override
				public void onResponse(Call c, Response response)
				{
					try (ResponseBody body = response.body())
					{
						answered(response, body);
					}
					catch (RuntimeException e)
					{
						// A bug: the reply still ends, rather than wait forever. Only the type is logged, in case the
						// message quotes a header (the API key).
						log.warn("Claude's answer not read: {}", e.getClass().getName());
						fail("Anthropic sent an answer AI Chat couldn't read.");
					}
				}
			});
		}

		private boolean anyReplayable()
		{
			for (Turn t : conversation.turns)
			{
				if (replayable(t, key))
				{
					return true;
				}
			}
			return false;
		}

		/** A later request (a retry or the next round), from a callback: a problem goes to the listener, not the thread. */
		private void again()
		{
			if (pending.isCancelled())
			{
				return;
			}
			try
			{
				request();
			}
			catch (RuntimeException e)
			{
				// The exception's message can contain the API key: it isn't passed on or logged.
				fail(COULDNT_SEND);
			}
		}

		private void failed(IOException e)
		{
			if (pending.isCancelled())
			{
				return;
			}
			if (ChatApi.tookTooLong(e))
			{
				fail(TOO_LONG);
				return;
			}
			if (!retry("Couldn't reach Anthropic", ChatApi.retryDelay(null, null, retries + 1)))
			{
				fail("Couldn't reach Anthropic: " + e.getMessage());
			}
		}

		private void answered(Response response, ResponseBody body)
		{
			if (pending.isCancelled())
			{
				return;
			}
			if (!response.isSuccessful() || body == null)
			{
				String text;
				try
				{
					text = body == null ? "" : body.string();
				}
				catch (IOException e)
				{
					text = "";
				}
				if (!pending.isCancelled())
				{
					errorAnswer(response, text);
				}
				return;
			}
			if (fallbackDropped)
			{
				// Only a request that worked without it shows fallback was the problem: remember that.
				refused.computeIfAbsent(refusedKey(conversation.model), k -> ConcurrentHashMap.newKeySet()).add(FALLBACKS);
				fallbackDropped = false;
			}
			Message m = new Message();
			try
			{
				if (Sse.isEventStream(response))
				{
					Sse.read(body.source(), (event, data) -> onEvent(m, event, data));
				}
				else
				{
					// Not streamed after all: one answer, read whole.
					String text;
					try
					{
						text = body.string();
					}
					catch (IOException e)
					{
						if (!pending.isCancelled())
						{
							brokeOff(m);
							fail("Couldn't read Anthropic's answer: " + e.getMessage());
						}
						return;
					}
					JsonObject o = ChatApi.fromJson(gson, text, JsonObject.class);
					if (o == null)
					{
						fail("Anthropic sent an empty answer.");
						return;
					}
					m.whole(o);
				}
			}
			catch (IOException e)
			{
				// Stop closes the stream: not a problem to report.
				if (!pending.isCancelled())
				{
					brokeOff(m);
					fail(ChatApi.tookTooLong(e) ? TOO_LONG : CUT_OFF);
				}
				return;
			}
			catch (JsonParseException | IllegalStateException | ClassCastException | UnsupportedOperationException | NumberFormatException e)
			{
				brokeOff(m);
				fail("Anthropic sent an answer AI Chat couldn't read.");
				return;
			}
			if (!pending.isCancelled())
			{
				completed(m);
			}
		}

		/** An error answer: some are worth asking again for, differently or after a wait. */
		private void errorAnswer(Response response, String text)
		{
			int code = response.code();
			String message = ChatApi.errorMessage(gson, text);
			// Claude checks that the reasoning it's given back belongs to this exact conversation; after a settings
			// change it may not. Once, carry on without it: earlier replies as text, and none of this reply's reasoning
			// so far, which was built on them. Checked first: that error also names the anthropic-beta header (for a
			// setting this plugin doesn't use), and isn't about fallback.
			if (replayed && code == 400 && message != null && message.contains("thinking"))
			{
				log.debug("asking again without earlier reasoning: {}", message);
				replay = false;
				produced = withoutThinking(produced);
				again();
				return;
			}
			// The fallback beta was retired, isn't enabled for this account, or this model doesn't take it: do without.
			if (fallback && code == 400 && message != null && (message.contains(FALLBACK_BETA) || message.contains(FALLBACKS)))
			{
				log.debug("asking again without server-side fallback: {}", message);
				fallback = false;
				fallbackDropped = true;
				again();
				return;
			}
			if (ChatApi.tooLongForModel(code, text))
			{
				fail(ChatApi.tooLong(conversation.model, ""));
				return;
			}
			if (ChatApi.retryableStatus(code, text) && retries < MAX_RETRIES)
			{
				long delay = ChatApi.retryDelay(response.header("retry-after-ms"), response.header("retry-after"), retries + 1);
				String why = code == 429 ? RATE_LIMITED : BUSY;
				if (delay > MAX_RETRY_WAIT_MS)
				{
					fail(why + "; it asked to wait " + ChatApi.waitText(delay) + ". Try again then.");
					return;
				}
				retry(why, delay);
				return;
			}
			fail(explain(code, message, conversation.model));
		}

		/** Sends the request again after {@code delay}, if it may be tried again. */
		private boolean retry(String why, long delay)
		{
			if (retries >= MAX_RETRIES)
			{
				return false;
			}
			retries++;
			log.debug("{}; trying again in {}ms", why, delay);
			if (!over.get() && !pending.isCancelled())
			{
				listener.onRetrying(why, ChatApi.seconds(delay));
			}
			if (!ChatApi.later(scheduler, pending, delay, this::again))
			{
				fail(why + ". Try again shortly.");
			}
			return true;
		}

		/** One streamed event. False once the response is over. */
		private boolean onEvent(Message m, String event, String data)
		{
			JsonObject o = ChatApi.fromJson(gson, data, JsonObject.class);
			String type = o == null ? null : string(o, "type");
			if (type == null)
			{
				type = event;
			}
			switch (type)
			{
				case "message_start":
				{
					JsonObject message = object(o, "message");
					if (message != null)
					{
						String started = string(message, "model");
						m.model = started != null ? started : m.model;
						readUsage(object(message, "usage"), m.usage);
					}
					break;
				}
				case "content_block_start":
					m.start(index(o), object(o, "content_block"));
					break;
				case "content_block_delta":
					if (m.delta(index(o), object(o, "delta")))
					{
						partial(m);
					}
					break;
				case "message_delta":
				{
					JsonObject delta = object(o, "delta");
					String stop = delta == null ? null : string(delta, "stop_reason");
					m.stop = stop != null ? stop : m.stop;
					readUsage(object(o, "usage"), m.usage);
					break;
				}
				case "message_stop":
					m.complete = true;
					return false;
				case "error":
				{
					JsonObject error = object(o, "error");
					m.errorType = error == null || string(error, "type") == null ? "error" : string(error, "type");
					m.errorMessage = error == null ? null : string(error, "message");
					return false;
				}
				default:
					// "ping", "content_block_stop", and anything new: nothing to do.
			}
			return true;
		}

		/** The reply so far, for the panel: earlier rounds and this one. */
		private void partial(Message m)
		{
			String now = m.text.toString();
			if (now.trim().isEmpty() || over.get() || pending.isCancelled())
			{
				return;
			}
			m.shown = true;
			listener.onPartial(ChatApi.joinRounds(texts, now));
		}

		/** A whole response: the reply, or the tools it wants run before it carries on. */
		private void completed(Message m)
		{
			if (m.errorType != null)
			{
				streamError(m);
				return;
			}
			if (!m.complete)
			{
				brokeOff(m);
				fail(CUT_OFF);
				return;
			}
			// Counted before anything else can go wrong: this response is billed whatever happens next.
			usage.add(m.usage);
			model = m.model != null ? m.model : model;
			// Checked before anything else: a refusal can cut the reply (or a tool call) off part way. What it wrote
			// before that isn't an answer, so it isn't kept (as Anthropic advises).
			if ("refusal".equals(m.stop))
			{
				Failure declined = new Failure("Claude declined to answer that.");
				declined.withdrawn = true;
				fail(declined);
				return;
			}
			JsonArray content = echo(m.content(gson));
			String text = textOf(content);
			JsonObject assistant = message("assistant", content);
			List<JsonObject> calls = toolUses(content);
			if ("tool_use".equals(m.stop) && !calls.isEmpty())
			{
				if (toolRounds >= MAX_TOOL_ROUNDS)
				{
					fail(TOO_MANY_ROUNDS);
					return;
				}
				toolRounds++;
				produced.add(assistant);
				texts.add(text);
				List<String> names = new ArrayList<>();
				List<JsonObject> inputs = new ArrayList<>();
				for (JsonObject call : calls)
				{
					names.add(string(call, "name") == null ? "" : string(call, "name"));
					JsonObject input = object(call, "input");
					inputs.add(m.badInputs.contains(string(call, "id")) ? null : input == null ? new JsonObject() : input.deepCopy());
				}
				ChatApi.runTools(conversation.toolRunner, names, inputs, results -> toolsDone(calls, results));
				return;
			}
			String all = ChatApi.joinRounds(texts, text);
			if (all.isEmpty())
			{
				fail("Claude sent an empty reply" + (m.stop == null ? "." : " (" + m.stop + ")."));
				return;
			}
			produced.add(assistant);
			Reply r = new Reply();
			r.text = all;
			r.model = model;
			r.cutShort = "max_tokens".equals(m.stop) || "model_context_window_exceeded".equals(m.stop);
			r.historyAsText = !replay;
			// A reply cut off part way can end in a tool call that was never run (Claude wants a result right after
			// one), or in reasoning that was never signed; a last round without text (empty, say) can't go back either.
			// Such a reply goes back as its text from now on; the replies after it are built on that text, so they can
			// still go back as they came.
			if (!r.cutShort && calls.isEmpty() && !text.isEmpty())
			{
				r.rawMessages = produced;
				r.rawKey = key;
			}
			r.usage.add(usage);
			finish(r);
		}

		/** The tools have answered: send their results back, all in one message, in the order they were asked for. */
		private void toolsDone(List<JsonObject> calls, List<ToolResult> results)
		{
			if (pending.isCancelled() || over.get())
			{
				return;
			}
			JsonArray blocks = new JsonArray();
			for (int i = 0; i < calls.size(); i++)
			{
				ToolResult result = results.get(i);
				JsonObject block = new JsonObject();
				block.addProperty("type", "tool_result");
				block.addProperty("tool_use_id", string(calls.get(i), "id"));
				block.addProperty("content", result.content == null || result.content.isEmpty() ? "(nothing)" : result.content);
				if (result.error)
				{
					block.addProperty("is_error", true);
				}
				blocks.add(block);
			}
			produced.add(message("user", blocks));
			retries = 0;
			try
			{
				// Off the thread that ran the last tool, which may be one that mustn't wait on anything.
				scheduler.execute(this::again);
			}
			catch (RejectedExecutionException e)
			{
				fail(COULDNT_SEND);
			}
		}

		/** An error event in the stream: worth a retry if the provider is busy and nothing has been shown yet. */
		private void streamError(Message m)
		{
			String type = m.errorType;
			boolean busy = "overloaded_error".equals(type) || "rate_limit_error".equals(type) || "api_error".equals(type);
			// Text already shown is never quietly swapped for a different reply.
			if (busy && !m.shown && retry("rate_limit_error".equals(type) ? RATE_LIMITED : BUSY, ChatApi.retryDelay(null, null, retries + 1)))
			{
				return;
			}
			brokeOff(m);
			fail(explain(code(type), m.errorMessage, conversation.model));
		}

		/**
		 * A response that broke off: what it counted so far is billed. (One that's asked again was turned away, and
		 * isn't counted.)
		 */
		private void brokeOff(Message m)
		{
			usage.add(m.usage);
			model = m.model != null ? m.model : model;
		}

		private void finish(Reply reply)
		{
			if (!pending.isCancelled() && over.compareAndSet(false, true))
			{
				listener.onReply(reply);
			}
		}

		private void fail(String message)
		{
			fail(new Failure(message));
		}

		/** Fails the reply, with the tokens its requests used so far. */
		private void fail(Failure failure)
		{
			if (!pending.isCancelled() && over.compareAndSet(false, true))
			{
				failure.usage.add(usage);
				failure.model = model;
				listener.onError(failure);
			}
		}
	}

	/** One response from Claude, put together from its stream as it arrives, or read whole. */
	private static final class Message
	{
		private final TreeMap<Integer, Block> blocks = new TreeMap<>();
		/** The content of a response read whole. */
		private JsonArray whole;
		/** The text so far, for the panel. */
		final StringBuilder text = new StringBuilder();
		/** Tool calls (by id) whose input couldn't be read. */
		final Set<String> badInputs = new HashSet<>();
		final Usage usage = new Usage();
		String model;
		String stop;
		/** The stream reached its end ("message_stop"). */
		boolean complete;
		/** Text has been shown to the player. */
		boolean shown;
		/** An error event in the stream, and what it said. */
		String errorType;
		String errorMessage;

		void whole(JsonObject o)
		{
			if ("error".equals(string(o, "type")))
			{
				JsonObject error = object(o, "error");
				errorType = error == null || string(error, "type") == null ? "error" : string(error, "type");
				errorMessage = error == null ? null : string(error, "message");
				return;
			}
			JsonElement content = o.get("content");
			whole = content != null && content.isJsonArray() ? content.getAsJsonArray() : new JsonArray();
			model = string(o, "model");
			stop = string(o, "stop_reason");
			readUsage(object(o, "usage"), usage);
			complete = true;
		}

		void start(int index, JsonObject block)
		{
			if (block == null)
			{
				return;
			}
			Block b = new Block(block.deepCopy());
			blocks.put(index, b);
			String type = string(block, "type");
			if ("text".equals(type) && string(block, "text") != null)
			{
				text.append(string(block, "text"));
			}
			// Another model took over after this one declined: it's the one answering now.
			JsonObject to = "fallback".equals(type) ? object(block, "to") : null;
			if (to != null && string(to, "model") != null)
			{
				model = string(to, "model");
			}
		}

		/** Adds a piece to a block. True if it was more text for the panel. */
		boolean delta(int index, JsonObject delta)
		{
			Block b = blocks.get(index);
			String type = delta == null ? null : string(delta, "type");
			if (b == null || type == null)
			{
				return false;
			}
			switch (type)
			{
				case "text_delta":
				{
					String t = string(delta, "text");
					if (t == null)
					{
						return false;
					}
					b.text = b.builder(b.text, "text").append(t);
					text.append(t);
					return true;
				}
				case "thinking_delta":
					b.thinking = b.builder(b.thinking, "thinking").append(nonNull(string(delta, "thinking")));
					return false;
				case "signature_delta":
					b.signature = b.builder(b.signature, "signature").append(nonNull(string(delta, "signature")));
					return false;
				case "input_json_delta":
					// The input arrives as pieces of JSON text, readable only once it's all there.
					if (b.json == null)
					{
						b.json = new StringBuilder();
					}
					b.json.append(nonNull(string(delta, "partial_json")));
					return false;
				case "citations_delta":
				{
					JsonElement citation = delta.get("citation");
					if (citation != null)
					{
						if (b.citations == null)
						{
							JsonElement existing = b.start.get("citations");
							b.citations = existing != null && existing.isJsonArray() ? existing.getAsJsonArray().deepCopy() : new JsonArray();
						}
						b.citations.add(citation);
					}
					return false;
				}
				default:
					return false;
			}
		}

		/** The content blocks, each exactly as Claude made it: what gets sent back later. */
		JsonArray content(Gson gson)
		{
			if (whole != null)
			{
				for (JsonElement e : whole)
				{
					if (e.isJsonObject() && "tool_use".equals(string(e.getAsJsonObject(), "type")))
					{
						JsonElement input = e.getAsJsonObject().get("input");
						if (input != null && !input.isJsonObject())
						{
							badInputs.add(string(e.getAsJsonObject(), "id"));
						}
					}
				}
				return whole;
			}
			JsonArray content = new JsonArray();
			for (Block b : blocks.values())
			{
				content.add(b.built(badInputs, gson));
			}
			return content;
		}

		private static String nonNull(String s)
		{
			return s == null ? "" : s;
		}
	}

	/** A content block as it streams in: what it started as, and what has been added to it since. */
	private static final class Block
	{
		final JsonObject start;
		StringBuilder text;
		StringBuilder thinking;
		StringBuilder signature;
		StringBuilder json;
		JsonArray citations;

		Block(JsonObject start)
		{
			this.start = start;
		}

		/** The builder for a text field, started from what the block began with. */
		StringBuilder builder(StringBuilder current, String field)
		{
			if (current != null)
			{
				return current;
			}
			String initial = string(start, field);
			return new StringBuilder(initial == null ? "" : initial);
		}

		JsonObject built(Set<String> badInputs, Gson gson)
		{
			JsonObject b = start.deepCopy();
			if (text != null)
			{
				b.addProperty("text", text.toString());
			}
			if (thinking != null)
			{
				b.addProperty("thinking", thinking.toString());
			}
			if (signature != null)
			{
				b.addProperty("signature", signature.toString());
			}
			if (citations != null)
			{
				b.add("citations", citations);
			}
			if (json != null)
			{
				b.add("input", input(json.toString(), b, badInputs, gson));
			}
			return b;
		}

		/** A tool call's input; {} if it was empty or couldn't be read (and then it isn't run). */
		private static JsonObject input(String json, JsonObject block, Set<String> badInputs, Gson gson)
		{
			if (json.trim().isEmpty())
			{
				return new JsonObject();
			}
			try
			{
				JsonElement parsed = ChatApi.fromJson(gson, json, JsonElement.class);
				if (parsed != null && parsed.isJsonObject())
				{
					return parsed.getAsJsonObject();
				}
			}
			catch (JsonParseException e)
			{
				// Below.
			}
			badInputs.add(string(block, "id"));
			return new JsonObject();
		}
	}

	/**
	 * What of a reply goes back on later requests. After a fallback (another model answered once the first declined),
	 * only the text from before the switch may go back; the declining model's reasoning and tool calls stay out
	 * (Anthropic's rules for echoing a fallback turn). Fallback markers themselves are harmless and kept.
	 */
	static JsonArray echo(JsonArray content)
	{
		int last = -1;
		for (int i = 0; i < content.size(); i++)
		{
			if ("fallback".equals(type(content.get(i))))
			{
				last = i;
			}
		}
		if (last < 0)
		{
			return content;
		}
		JsonArray echoed = new JsonArray();
		for (int i = 0; i < content.size(); i++)
		{
			String type = type(content.get(i));
			if (i >= last || "text".equals(type) || "fallback".equals(type))
			{
				echoed.add(content.get(i));
			}
		}
		return echoed;
	}

	/** Messages without their reasoning blocks, for when Claude won't take back reasoning made under an earlier prompt. */
	private static JsonArray withoutThinking(JsonArray messages)
	{
		JsonArray out = new JsonArray();
		for (JsonElement m : messages)
		{
			JsonElement content = m.isJsonObject() ? m.getAsJsonObject().get("content") : null;
			if (content == null || !content.isJsonArray())
			{
				out.add(m);
				continue;
			}
			JsonArray kept = new JsonArray();
			for (JsonElement block : content.getAsJsonArray())
			{
				String type = type(block);
				if (!"thinking".equals(type) && !"redacted_thinking".equals(type))
				{
					kept.add(block);
				}
			}
			JsonObject copy = m.getAsJsonObject().deepCopy();
			copy.add("content", kept);
			out.add(copy);
		}
		return out;
	}

	private static String textOf(JsonArray content)
	{
		StringBuilder text = new StringBuilder();
		for (JsonElement block : content)
		{
			if ("text".equals(type(block)))
			{
				String t = string(block.getAsJsonObject(), "text");
				text.append(t == null ? "" : t);
			}
		}
		return text.toString().trim();
	}

	private static List<JsonObject> toolUses(JsonArray content)
	{
		List<JsonObject> calls = new ArrayList<>();
		for (JsonElement block : content)
		{
			if ("tool_use".equals(type(block)))
			{
				calls.add(block.getAsJsonObject());
			}
		}
		return calls;
	}

	private static JsonObject message(String role, JsonArray content)
	{
		JsonObject m = new JsonObject();
		m.addProperty("role", role);
		m.add("content", content);
		return m;
	}

	/**
	 * Token counts, which come in two parts when streamed: the input at the start, the output (and sometimes the input
	 * again) at the end. Later counts replace earlier ones.
	 */
	private static void readUsage(JsonObject u, Usage usage)
	{
		if (u == null)
		{
			return;
		}
		JsonElement iterations = u.get("iterations");
		if (iterations != null && iterations.isJsonArray() && iterations.getAsJsonArray().size() > 0)
		{
			// Each attempt at the message, when another model took over from one that declined: all of them are billed,
			// but the counts outside cover only the last.
			Usage all = new Usage();
			for (JsonElement attempt : iterations.getAsJsonArray())
			{
				if (attempt.isJsonObject())
				{
					Usage one = new Usage();
					readCounts(attempt.getAsJsonObject(), one);
					all.add(one);
				}
			}
			usage.input = all.input;
			usage.cacheRead = all.cacheRead;
			usage.cacheWrite = all.cacheWrite;
			usage.output = all.output;
			return;
		}
		readCounts(u, usage);
	}

	private static void readCounts(JsonObject u, Usage usage)
	{
		usage.input = count(u, "input_tokens", usage.input);
		usage.cacheRead = count(u, "cache_read_input_tokens", usage.cacheRead);
		usage.cacheWrite = count(u, "cache_creation_input_tokens", usage.cacheWrite);
		usage.output = count(u, "output_tokens", usage.output);
	}

	private static long count(JsonObject o, String key, long otherwise)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() ? e.getAsLong() : otherwise;
	}

	@Override
	public Pending listModels(ModelsListener listener)
	{
		Pending pending = new Pending();
		listModels(listener, pending, new ArrayList<>(), null, 1);
		return pending;
	}

	private void listModels(ModelsListener listener, Pending pending, List<String> ids, String after, int page)
	{
		HttpUrl.Builder list = url.resolve("models").newBuilder().addQueryParameter("limit", "1000");
		if (after != null)
		{
			list.addQueryParameter("after_id", after);
		}
		Call call = http.newCall(new Request.Builder()
			.url(list.build())
			.header("x-api-key", apiKey)
			.header("anthropic-version", VERSION)
			.get()
			.build());
		pending.set(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				if (!pending.isCancelled())
				{
					listener.onError(ChatApi.tookTooLong(e) ? "Anthropic didn't answer in time. Try again in a moment."
						: "Couldn't reach Anthropic: " + e.getMessage());
				}
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				String text;
				try (ResponseBody body = response.body())
				{
					text = body == null ? "" : body.string();
				}
				catch (IOException e)
				{
					if (!pending.isCancelled())
					{
						listener.onError("Couldn't read Anthropic's answer: " + e.getMessage());
					}
					return;
				}
				if (pending.isCancelled())
				{
					return;
				}
				if (!response.isSuccessful())
				{
					listener.onError(explain(response.code(), ChatApi.errorMessage(gson, text), null));
					return;
				}
				try
				{
					JsonObject o = ChatApi.fromJson(gson, text, JsonObject.class);
					JsonElement data = o == null ? null : o.get("data");
					if (data == null || !data.isJsonArray())
					{
						listener.onError("Anthropic sent a model list AI Chat couldn't read.");
						return;
					}
					for (JsonElement m : data.getAsJsonArray())
					{
						String id = m.isJsonObject() ? string(m.getAsJsonObject(), "id") : null;
						if (id != null)
						{
							ids.add(id);
						}
					}
					String last = string(o, "last_id");
					JsonElement more = o.get("has_more");
					if (more != null && more.isJsonPrimitive() && more.getAsBoolean() && last != null && page < MAX_MODEL_PAGES)
					{
						listModels(listener, pending, ids, last, page + 1);
						return;
					}
				}
				catch (JsonParseException | IllegalStateException | ClassCastException | UnsupportedOperationException e)
				{
					listener.onError("Anthropic sent a model list AI Chat couldn't read.");
					return;
				}
				listener.onModels(ids);
			}
		});
	}

	/** The HTTP status that goes with an error type in a stream, so it's explained the same way; 0 if unknown. */
	private static int code(String errorType)
	{
		switch (errorType == null ? "" : errorType)
		{
			case "invalid_request_error":
				return 400;
			case "authentication_error":
				return 401;
			case "billing_error":
				return 402;
			case "permission_error":
				return 403;
			case "not_found_error":
				return 404;
			case "request_too_large":
				return 413;
			case "rate_limit_error":
				return 429;
			case "api_error":
				return 500;
			case "overloaded_error":
				return 529;
			default:
				return 0;
		}
	}

	/** {@code model}: the one asked for, or null when no model was involved (the model list). */
	private static String explain(int code, String message, String model)
	{
		String detail = message == null ? "" : " (" + ChatApi.shorten(message, 200) + ")";
		switch (code)
		{
			case 0:
				return "Anthropic reported a problem" + detail + ".";
			case 401:
				return "Anthropic didn't accept your API key. Check the API key in the Claude section of the AI Chat settings.";
			case 402:
				return "Anthropic says there's a billing problem with your account" + detail + ".";
			case 403:
				return "Your Anthropic API key isn't allowed to do that" + detail + ".";
			case 404:
				return model == null ? "Anthropic answered HTTP 404" + detail + "."
					: "The Claude model \"" + model + "\" isn't available to your key. Pick another model next to Send, or check the model in the Claude section of the AI "
						+ "Chat settings" + detail + ".";
			case 413:
				return "This chat has grown too long to send. Start a new chat.";
			case 429:
				return "Anthropic's rate limit was hit. Try again in a minute" + detail + ".";
			case 500:
			case 502:
			case 503:
			case 504:
			case 529:
				return "Anthropic is overloaded or having trouble right now. Try again shortly.";
			default:
				return "Anthropic answered HTTP " + code + detail + ".";
		}
	}

	/** A block's type, or null if it isn't a block. */
	private static String type(JsonElement block)
	{
		return block != null && block.isJsonObject() ? string(block.getAsJsonObject(), "type") : null;
	}

	private static int index(JsonObject o)
	{
		JsonElement e = o == null ? null : o.get("index");
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() ? e.getAsInt() : 0;
	}

	private static JsonObject object(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}
}

package com.aichat;

import java.awt.BorderLayout;
import java.awt.Color;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.border.EmptyBorder;

/**
 * A short message under the panel's header, shown only when there's something to say: what's missing before a
 * message can be sent, or what Test connection found. Plain text, in the colour of its news (green, orange, red, or
 * muted while a Test runs), with a close button when it can be put away.
 */
final class Banner extends RoundBox
{
	final JTextArea text = PanelStyle.textArea("");
	final FlatButton close = new FlatButton(null, new Glyph(Glyph.Shape.CLOSE, 10), "Close");
	private String shown = "";

	/** {@code closed}: the player closed it. */
	Banner(Runnable closed)
	{
		super(new BorderLayout(4, 0), PanelStyle.FIELD_COLOR, null);
		setBorder(new EmptyBorder(6, 8, 6, 4));
		text.setFont(PanelStyle.SMALL_FONT);
		add(text, BorderLayout.CENTER);
		close.setBorder(new EmptyBorder(2, 2, 2, 2));
		close.addActionListener(e -> closed.run());
		JPanel corner = new JPanel(new BorderLayout());
		corner.setOpaque(false);
		corner.add(close, BorderLayout.NORTH);
		add(corner, BorderLayout.EAST);
		setVisible(false);
	}

	/** Shows {@code message} in {@code color}, with a close button if {@code closable}; null hides the banner. */
	void show(String message, Color color, boolean closable)
	{
		String m = message == null ? "" : message;
		if (!m.equals(shown))
		{
			shown = m;
			text.setText(m);
		}
		text.setForeground(color);
		setColors(PanelStyle.FIELD_COLOR, color == null ? null : faded(color));
		close.setVisible(closable);
		setVisible(!m.isEmpty());
	}

	/** The banner's outline: its colour, but quieter than its words. */
	private static Color faded(Color c)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), 110);
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** The character details sent with a message when the player turns that on. */
final class CharacterInfo
{
	private CharacterInfo()
	{
	}

	/** Client thread only: reading quest states runs a game script. Null when there's no character to describe. */
	static String describe(Client client)
	{
		Player me = client.getLocalPlayer();
		if (me == null || me.getName() == null)
		{
			return null;
		}
		List<String> levels = new ArrayList<>();
		for (Skill s : Skill.values())
		{
			levels.add(s.getName() + " " + client.getRealSkillLevel(s));
		}
		List<String> done = new ArrayList<>();
		List<String> started = new ArrayList<>();
		for (Quest q : Quest.values())
		{
			QuestState state = q.getState(client);
			if (state == QuestState.FINISHED)
			{
				done.add(q.getName());
			}
			else if (state == QuestState.IN_PROGRESS)
			{
				started.add(q.getName());
			}
		}
		return format(me.getName(), accountType(client.getVarbitValue(VarbitID.IRONMAN)), me.getCombatLevel(),
			client.getTotalLevel(), levels, client.getVarpValue(VarPlayerID.QP), done, started);
	}

	/**
	 * The account type as the note puts it, from the game's IRONMAN varbit; null for a value this doesn't know yet. An
	 * ironman can't use the Grand Exchange or trade, which changes most advice, so a regular account says so too.
	 */
	static String accountType(int ironman)
	{
		switch (ironman)
		{
			case 0:
				return "a regular account (not an ironman)";
			case 1:
				return "an ironman";
			case 2:
				return "an ultimate ironman";
			case 3:
				return "a hardcore ironman";
			case 4:
				return "a group ironman";
			case 5:
				return "a hardcore group ironman";
			case 6:
				return "an unranked group ironman";
			default:
				return null;
		}
	}

	/** {@code accountType}: from {@link #accountType}, or null to leave it out. */
	static String format(String name, String accountType, int combat, int total, List<String> levels, int questPoints,
		List<String> done, List<String> started)
	{
		return "[Character: " + name + (accountType == null ? "" : ", " + accountType)
			+ ", combat level " + combat + ", total level " + total + ". "
			+ "Levels: " + String.join(", ", levels) + ". "
			+ "Quest points: " + questPoints + ". "
			+ "Quests completed (" + done.size() + "): " + (done.isEmpty() ? "none" : String.join(", ", done)) + ". "
			+ "Quests in progress: " + (started.isEmpty() ? "none" : String.join(", ", started)) + ".]";
	}
}

package com.aichat;

import com.google.gson.JsonArray;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/** One conversation in the panel. Kept in memory while the plugin runs. Only touched on the Swing EDT. */
class Chat
{
	enum Role
	{
		USER, ASSISTANT, NOTE, ERROR
	}

	static class Message
	{
		final Role role;
		final String text;
		final long time;
		/** Who wrote an ASSISTANT reply: "Claude", "ChatGPT", or the model of an OpenAI-compatible service. */
		String who;
		/** Character details sent along with this USER message, if any. Part of what the provider saw. */
		String context;
		/** A USER message whose request failed or was stopped. Left out of later requests. */
		boolean unanswered;
		/**
		 * An ASSISTANT reply that never finished: what was shown of it before it was stopped or broke off, kept for the
		 * player to read (the note or error after it says why). Never sent.
		 */
		boolean unfinished;
		/** Covered by the chat's {@link Chat#summary}: still shown, but no longer sent. */
		boolean summarized;
		/**
		 * The chat's {@link Chat#summaryVersion} when this was sent or answered. A reply goes back exactly as it came
		 * only while that's unchanged: a new summary changes what came before it.
		 */
		int summaryVersion;
		/**
		 * Anthropic only: the messages this reply was made of (its look-ups included), exactly as exchanged, and the
		 * {@link ChatApi#promptKey} they were made under. Claude expects them back unchanged on the next turn, as long as
		 * nothing before them changed. In memory only.
		 */
		JsonArray rawMessages;
		String rawKey;
		/**
		 * What was looked up or shared while this was being answered, one line each ("Searched the Wiki for ..."): on
		 * the reply, or on the error or note that ended the request. Empty or null when nothing was.
		 */
		List<String> activity;

		Message(Role role, String text)
		{
			this(role, text, System.currentTimeMillis());
		}

		Message(Role role, String text, long time)
		{
			this.role = role;
			this.text = text;
			this.time = time;
		}
	}

	final String id;
	String name;
	/** Whether {@link #name} was made up by us, so the first message can replace it with something better. */
	boolean defaultName = true;
	/** The player named this chat themselves, so the name can appear in notifications (it isn't their question). */
	boolean namedByPlayer;
	final List<Message> messages = new ArrayList<>();
	/**
	 * What the oldest messages were summarised to, sent instead of them (see {@link ConversationBuilder}); null until a
	 * chat gets long.
	 */
	String summary;
	/** Goes up with every new summary. */
	int summaryVersion;
	/**
	 * How many of the chat's oldest messages weren't kept when it was saved in an earlier session, and how many of those
	 * the summary covers (see {@link ChatStore}). Messages still sent to the assistant are never among them.
	 */
	int leftOut;
	int leftOutSummarized;
	/** The note shown in their place, made when the chat was loaded; not saved itself. Null when none were left out. */
	Message leftOutNote;

	/** The request in flight, or null. */
	ChatApi.Pending pending;
	/** When the request in flight started: the summary, then the question itself. */
	long runStartedAt;
	/**
	 * While the oldest messages are being summarised before a question goes out: carries on without the summary, which
	 * is what Stop does then. Null the rest of the time.
	 */
	Runnable skipSummary;

	// What the panel shows of the request in flight, while it runs.

	/** Who's answering: "Claude", "ChatGPT", or the model of an OpenAI-compatible service. */
	String answering;
	/** The reply so far, as it streams in; null until its first words. */
	String liveText;
	/** What has been looked up or shared for it so far; it goes with the message that ends the request. */
	List<String> liveActivity = new ArrayList<>();
	/** The model has stopped writing to look things up, and hasn't carried on yet. */
	boolean lookingUp;
	/** The reply's text when the look-ups started: only text beyond it means the model is writing again. */
	String lookupAfter;
	/** The provider was busy: why ("Anthropic is busy"), and when it's asked again. */
	String retryWhy;
	long retryAt;

	Chat(String name)
	{
		this(UUID.randomUUID().toString(), name);
	}

	/** A chat brought back from {@link ChatStore}. */
	Chat(String id, String name)
	{
		this.id = id;
		this.name = name;
	}

	boolean isRunning()
	{
		return pending != null;
	}

	boolean isSummarizing()
	{
		return skipSummary != null;
	}

	/** A new request starts (or the last one ended): nothing of it to show yet. */
	void resetLive()
	{
		liveText = null;
		liveActivity = new ArrayList<>();
		lookingUp = false;
		lookupAfter = null;
		retryWhy = null;
		retryAt = 0;
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InterruptedIOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import okhttp3.Call;
import okhttp3.MediaType;

/** An AI provider: send the conversation so far, get back one reply or one error. */
interface ChatApi
{
	MediaType JSON = MediaType.get("application/json; charset=utf-8");
	/** Times a reply may stop to look things up before it has to answer. */
	int MAX_TOOL_ROUNDS = 8;
	/**
	 * Look-ups run each time it stops; any more are turned down. The Wiki answers one request at a time, and a reply
	 * that asks for dozens of pages at once would keep it busy for minutes.
	 */
	int MAX_TOOL_CALLS = 10;
	/** Times a request is sent again when the provider is busy or couldn't be reached. */
	int MAX_RETRIES = 2;
	/** The longest wait before sending again; a provider that asks for longer gets an error instead. */
	long MAX_RETRY_WAIT_MS = 60_000;
	/**
	 * Deeper than any answer or tool call needs to go. Gson reads nesting by recursion, and a few thousand levels (a
	 * model stuck writing "[") overflow the stack.
	 */
	int MAX_JSON_DEPTH = 64;
	String TOO_MANY_ROUNDS = "The assistant kept looking things up without answering. Try asking more specifically.";
	String CUT_OFF = "The reply was cut off: the connection closed early.";

	/**
	 * Starts the request: the reply streams in, with any tool calls and retries it takes. The listener hears back
	 * later on OkHttp or executor threads: {@link Listener#onPartial} any number of times, then {@link Listener#onReply}
	 * or {@link Listener#onError} exactly once, unless the request is cancelled first (then nothing more).
	 */
	Pending send(Conversation conversation, Listener listener);

	/** The provider's name for this setup, shown as the author of its replies. */
	String displayName();

	/** Lists the models the key can use, for "Test connection". The listener hears back once, on an OkHttp thread. */
	default Pending listModels(ModelsListener listener)
	{
		listener.onError("This provider can't list its models.");
		return new Pending();
	}

	final class Conversation
	{
		String model;
		String system;
		final List<Turn> turns = new ArrayList<>();
		/** Tools the model may call, in the same order every request (the order is part of the cached prompt). */
		final List<ToolSpec> tools = new ArrayList<>();
		/** Runs the tools the model calls; needed when {@link #tools} isn't empty. */
		ToolRunner toolRunner;
		/** A lower reply length limit than the provider's own, or 0 for that. */
		int maxTokens;
	}

	/** A tool the model may call while answering: a name, what it's for, and a JSON Schema for its input. */
	final class ToolSpec
	{
		final String name;
		final String description;
		final JsonObject inputSchema;

		ToolSpec(String name, String description, JsonObject inputSchema)
		{
			this.name = name;
			this.description = description;
			this.inputSchema = inputSchema;
		}
	}

	/** Runs the tools the model calls. */
	interface ToolRunner
	{
		/**
		 * Runs one call and reports back exactly once, on any thread. Never throws: problems become an error result the
		 * model can read.
		 */
		void run(String name, JsonObject input, Consumer<ToolResult> done);
	}

	final class ToolResult
	{
		final String content;
		final boolean error;

		private ToolResult(String content, boolean error)
		{
			this.content = content;
			this.error = error;
		}

		static ToolResult ok(String content)
		{
			return new ToolResult(content, false);
		}

		static ToolResult error(String message)
		{
			return new ToolResult(message, true);
		}
	}

	/** Tokens a reply used, over all its requests (tool rounds included). */
	final class Usage
	{
		/** Input billed at the full price: not read from or written to the provider's prompt cache. */
		long input;
		long cacheRead;
		long cacheWrite;
		long output;

		void add(Usage u)
		{
			input += u.input;
			cacheRead += u.cacheRead;
			cacheWrite += u.cacheWrite;
			output += u.output;
		}
	}

	interface ModelsListener
	{
		void onModels(List<String> ids);

		void onError(String message);
	}

	/** One turn of the conversation as the provider sees it. */
	final class Turn
	{
		final boolean user;
		final String text;
		/**
		 * Anthropic only: the messages this reply was made of (tool calls and their results included), exactly as
		 * exchanged. Sent back as they are only when {@link #rawKey} matches the request's {@link #promptKey}.
		 */
		JsonArray rawMessages;
		String rawKey;

		Turn(boolean user, String text)
		{
			this.user = user;
			this.text = text;
		}
	}

	final class Reply
	{
		String text;
		/** The model that answered, which can differ from the one asked for (e.g. a fallback). */
		String model;
		/** The reply hit the length limit. */
		boolean cutShort;
		/**
		 * Anthropic only: earlier replies had to be sent as plain text for this one (see AnthropicApi). They can't be
		 * sent any other way from now on, or this reply's reasoning wouldn't match what it was built on.
		 */
		boolean historyAsText;
		/** Anthropic only: see {@link Turn#rawMessages}. */
		JsonArray rawMessages;
		/** The {@link #promptKey} of the requests that made this reply. */
		String rawKey;
		/** The request came with tools, but the model can't use them: it answered without looking anything up. */
		boolean toolsUnavailable;
		final Usage usage = new Usage();
	}

	interface Listener
	{
		/** The reply so far while it streams in: all of its text, not just the new part. On an OkHttp thread. */
		default void onPartial(String textSoFar)
		{
		}

		/**
		 * The provider is busy or couldn't be reached; the request is sent again in {@code seconds}. {@code message}
		 * says why, without a full stop: "Anthropic is busy".
		 */
		default void onRetrying(String message, int seconds)
		{
		}

		void onReply(Reply reply);

		/** The request ended without a reply: why, for the panel, and what it used on the way. */
		void onError(Failure failure);
	}

	/** Why a request ended without a reply. */
	final class Failure
	{
		/** A short, readable explanation for the panel. */
		final String message;
		/** The tokens its requests used before it failed (look-up rounds, a reply cut off part way): billed all the same. */
		final Usage usage = new Usage();
		/** The model that answered before it failed, or null. */
		String model;
		/**
		 * The text shown so far is taken back rather than kept: the provider's safety filter stopped the reply part
		 * way, and what it had written isn't to be read as an answer.
		 */
		boolean withdrawn;
		/** The chat is longer than the model can take in: summarising its earlier messages may get it through. */
		boolean tooLong;

		Failure(String message)
		{
			this.message = message;
		}
	}

	/**
	 * What earlier replies were made under: the model, the instructions and the tools. Replies are sent back exactly as
	 * they came only while it's unchanged.
	 */
	static String promptKey(Conversation c)
	{
		StringBuilder key = new StringBuilder(c.model).append('\u0000').append(c.system);
		for (ToolSpec t : c.tools)
		{
			key.append('\u0000').append(t.name).append('\u0000').append(t.description).append('\u0000').append(t.inputSchema);
		}
		return key.toString();
	}

	/**
	 * A request in flight. A retry or the next tool round replaces the call (or the wait) inside, so cancelling always
	 * stops whatever is running.
	 */
	final class Pending
	{
		private volatile Call call;
		private volatile Future<?> timer;
		private volatile boolean cancelled;

		void set(Call c)
		{
			call = c;
			if (cancelled)
			{
				c.cancel();
			}
		}

		/** A wait before the next attempt. */
		void setTimer(Future<?> f)
		{
			timer = f;
			if (cancelled)
			{
				f.cancel(false);
			}
		}

		void cancel()
		{
			cancelled = true;
			Call c = call;
			if (c != null)
			{
				c.cancel();
			}
			Future<?> f = timer;
			if (f != null)
			{
				f.cancel(false);
			}
		}

		boolean isCancelled()
		{
			return cancelled;
		}
	}

	/**
	 * The error message inside a provider's error body, or null. Anthropic, OpenAI and most others send
	 * {"error":{"message":...}}; Gemini wraps that in a list, some local servers send {"error":"text"}, Mistral
	 * {"detail":...}. The body is read whatever its Content-Type says: OpenAI labels some JSON errors as plain text.
	 */
	static String errorMessage(Gson gson, String body)
	{
		try
		{
			JsonElement parsed = fromJson(gson, body, JsonElement.class);
			if (parsed != null && parsed.isJsonArray() && parsed.getAsJsonArray().size() > 0)
			{
				parsed = parsed.getAsJsonArray().get(0);
			}
			if (parsed == null || !parsed.isJsonObject())
			{
				return null;
			}
			JsonObject o = parsed.getAsJsonObject();
			JsonElement error = o.get("error");
			if (error != null && error.isJsonObject())
			{
				JsonElement message = error.getAsJsonObject().get("message");
				return message != null && message.isJsonPrimitive() ? message.getAsString() : null;
			}
			if (error != null && error.isJsonPrimitive())
			{
				return error.getAsString();
			}
			JsonElement detail = o.get("detail");
			if (detail != null && detail.isJsonPrimitive())
			{
				return detail.getAsString();
			}
			return null;
		}
		catch (JsonParseException | IllegalStateException | ClassCastException | UnsupportedOperationException e)
		{
			return null;
		}
	}

	/**
	 * A pasted API key without what copying tends to add: spaces, line breaks, non-breaking and zero-width spaces.
	 */
	static String cleanKey(String key)
	{
		return key == null ? "" : key.replaceAll("[\\s\\p{Z}\\p{Cf}]", "");
	}

	/** Whether a (cleaned) key can go in an HTTP header: printable ASCII only, so no curly quotes or ellipses. */
	static boolean sendableKey(String key)
	{
		for (int i = 0; i < key.length(); i++)
		{
			char c = key.charAt(i);
			if (c < 0x21 || c > 0x7e)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * The provider was reached but took too long to answer. A connect timeout is a different story: nothing answered.
	 */
	static boolean tookTooLong(IOException e)
	{
		if (!(e instanceof InterruptedIOException))
		{
			return false;
		}
		String m = e.getMessage();
		return m == null || !m.toLowerCase(Locale.ROOT).contains("connect");
	}

	/** Cut to a length that fits the panel. */
	static String shorten(String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		String t = s.trim();
		return t.length() <= max ? t : t.substring(0, max).trim() + "...";
	}

	// ------------------------------------------------------------------
	// Shared by both providers: retries and tool rounds
	// ------------------------------------------------------------------

	/**
	 * Whether an HTTP error is worth sending the same request again for: a timeout, a conflict, a rate limit, or the
	 * provider being overloaded or briefly broken. Not a 429 that says the account is out of credits or over its
	 * quota: waiting won't fix that.
	 */
	static boolean retryableStatus(int code, String body)
	{
		switch (code)
		{
			case 429:
				return !outOfCredits(body);
			case 408:
			case 409:
			case 500:
			case 502:
			case 503:
			case 504:
			case 529:
				return true;
			default:
				return false;
		}
	}

	/**
	 * Whether an error answer says the conversation is longer than the model can take in. Each service words it its own
	 * way: Anthropic's "prompt is too long", OpenAI's and Groq's context_length_exceeded, "maximum context length"
	 * (OpenAI, OpenRouter, vLLM, Mistral), llama.cpp's "context size", Gemini's "exceeds the maximum number of tokens".
	 * {@code body}: the whole answer, which has the error's code as well as its message.
	 */
	static boolean tooLongForModel(int code, String body)
	{
		if (code != 400 && code != 413 && code != 422)
		{
			return false;
		}
		String lower = body == null ? "" : body.toLowerCase(Locale.ROOT);
		return code == 413 || lower.contains("prompt is too long") || lower.contains("context_length_exceeded")
			|| lower.contains("context length") || lower.contains("context window") || lower.contains("context size")
			|| lower.contains("context limit") || lower.contains("maximum context")
			|| lower.contains("exceeds the maximum number of tokens");
	}

	/** The error for a chat the model can't take in. {@code hint}: more to say about it, or "". */
	static Failure tooLong(String model, String hint)
	{
		Failure f = new Failure("This chat is too long for " + model + ". Start a new chat, or choose a model that "
			+ "can take more." + hint);
		f.tooLong = true;
		return f;
	}

	/**
	 * An error that says the account has run out of credits or hit a spending limit (OpenAI's insufficient_quota). Only
	 * words that say so count: Groq's per-minute rate limits end with a link to its billing page, and a rate limit's
	 * code says it is one.
	 */
	static boolean outOfCredits(String body)
	{
		String lower = body == null ? "" : body.toLowerCase(Locale.ROOT);
		if (lower.contains("rate_limit_exceeded"))
		{
			return false;
		}
		return lower.contains("insufficient_quota") || lower.contains("exceeded your current quota")
			|| lower.contains("credit balance") || lower.contains("insufficient credits") || lower.contains("out of credits")
			|| lower.contains("insufficient balance") || lower.contains("spend limit") || lower.contains("spending limit");
	}

	/**
	 * How long to wait before sending a request again, in milliseconds: what the provider asked for in a
	 * retry-after-ms or retry-after (seconds) header, or else 2 seconds before the first retry and 6 before the second.
	 * A retry-after given as a date is rare and ignored.
	 */
	static long retryDelay(String retryAfterMs, String retryAfter, int retry)
	{
		Double ms = number(retryAfterMs);
		if (ms != null)
		{
			return (long) Math.ceil(ms);
		}
		Double seconds = number(retryAfter);
		if (seconds != null)
		{
			return (long) Math.ceil(seconds * 1000);
		}
		return retry <= 1 ? 2000 : 6000;
	}

	/** A header's non-negative number, or null. */
	private static Double number(String header)
	{
		if (header == null)
		{
			return null;
		}
		try
		{
			double d = Double.parseDouble(header.trim());
			return Double.isNaN(d) || Double.isInfinite(d) || d < 0 ? null : d;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Whole seconds, rounded up, for "trying again in 6s". */
	static int seconds(long ms)
	{
		return (int) Math.min(Integer.MAX_VALUE, (ms + 999) / 1000);
	}

	/** "45 seconds", "3 minutes", "2 hours": a wait, for messages. */
	static String waitText(long ms)
	{
		long s = seconds(ms);
		if (s <= 90)
		{
			return s + (s == 1 ? " second" : " seconds");
		}
		long minutes = (s + 59) / 60;
		if (minutes < 120)
		{
			return minutes + " minutes";
		}
		return (minutes + 59) / 60 + " hours";
	}

	/**
	 * Runs {@code again} after {@code ms}, unless the request is cancelled first. The wait goes on the plugin's
	 * scheduler, never a sleeping thread, and Stop cancels it. False if the scheduler is shutting down.
	 */
	static boolean later(ScheduledExecutorService scheduler, Pending pending, long ms, Runnable again)
	{
		try
		{
			pending.setTimer(scheduler.schedule(() ->
			{
				if (!pending.isCancelled())
				{
					again.run();
				}
			}, ms, TimeUnit.MILLISECONDS));
			return true;
		}
		catch (RejectedExecutionException e)
		{
			return false;
		}
	}

	/**
	 * Runs the tool calls of one reply at the same time and hands back their results in the same order once all are
	 * in, on whichever thread finished last. {@code inputs}: null for a call whose arguments couldn't be read; it isn't
	 * run, and the model is told why. Calls beyond {@link #MAX_TOOL_CALLS} aren't run either. A runner that breaks its
	 * promise (throws, or answers twice) can't stall the reply.
	 */
	static void runTools(ToolRunner runner, List<String> names, List<JsonObject> inputs, Consumer<List<ToolResult>> done)
	{
		int n = names.size();
		ToolResult[] results = new ToolResult[n];
		AtomicInteger left = new AtomicInteger(n);
		if (n == 0)
		{
			done.accept(new ArrayList<>());
			return;
		}
		for (int i = 0; i < n; i++)
		{
			int slot = i;
			String name = names.get(i);
			AtomicBoolean answered = new AtomicBoolean();
			Consumer<ToolResult> one = r ->
			{
				if (!answered.compareAndSet(false, true))
				{
					return;
				}
				results[slot] = r != null ? r : ToolResult.error("The tool " + name + " sent nothing back.");
				// The last one in carries on; the counter makes every result visible to it.
				if (left.decrementAndGet() == 0)
				{
					List<ToolResult> all = new ArrayList<>();
					for (ToolResult result : results)
					{
						all.add(result);
					}
					done.accept(all);
				}
			};
			JsonObject input = inputs.get(i);
			if (input == null)
			{
				one.accept(ToolResult.error("Arguments weren't valid JSON. Send them as a JSON object."));
			}
			else if (i >= MAX_TOOL_CALLS)
			{
				one.accept(ToolResult.error("Too many look-ups at once: only the first " + MAX_TOOL_CALLS + " were run. "
					+ "Ask for fewer at a time."));
			}
			else if (runner == null)
			{
				one.accept(ToolResult.error("There's no tool called " + name + "."));
			}
			else
			{
				try
				{
					runner.run(name, input, one);
				}
				catch (RuntimeException e)
				{
					one.accept(ToolResult.error("The tool " + name + " failed. Answer without it."));
				}
			}
		}
	}

	/**
	 * Gson's reading of text from a provider or a model. Text nested deeper than {@link #MAX_JSON_DEPTH} is refused
	 * like any other bad JSON, before Gson can overflow the stack on it: a {@link StackOverflowError} would escape every
	 * handler, and the reply would never end.
	 */
	static <T> T fromJson(Gson gson, String json, Class<T> type)
	{
		if (json != null && tooDeep(json))
		{
			throw new JsonParseException("Nested too deep to read");
		}
		return gson.fromJson(json, type);
	}

	/**
	 * Whether {@code json} might nest arrays and objects deeper than {@link #MAX_JSON_DEPTH}. Brackets inside strings
	 * don't count. Gson also reads text that isn't plain JSON (single quotes, bare words, comments), and in that the
	 * strings can't be told apart this simply: there every bracket counts.
	 */
	static boolean tooDeep(String json)
	{
		int depth = 0;
		boolean inString = false;
		boolean plain = true;
		for (int i = 0; i < json.length() && plain; i++)
		{
			char c = json.charAt(i);
			if (inString)
			{
				if (c == '\\')
				{
					i++;
				}
				else if (c == '"')
				{
					inString = false;
				}
			}
			else if (c == '"')
			{
				// Straight after a bare word, Gson reads a quote as more of the word, not as the start of a string.
				plain = i == 0 || !bareWord(json.charAt(i - 1));
				inString = true;
			}
			else if (c == '[' || c == '{')
			{
				if (++depth > MAX_JSON_DEPTH)
				{
					return true;
				}
			}
			else if (c == ']' || c == '}')
			{
				depth--;
			}
			else
			{
				plain = bareWord(c) || c == ',' || c == ':' || c == ' ' || c == '\t' || c == '\n' || c == '\r';
			}
		}
		if (plain)
		{
			return false;
		}
		int brackets = 0;
		for (int i = 0; i < json.length(); i++)
		{
			char c = json.charAt(i);
			if ((c == '[' || c == '{') && ++brackets > MAX_JSON_DEPTH)
			{
				return true;
			}
		}
		return false;
	}

	/** What plain JSON has outside strings besides punctuation: numbers, true, false and null. */
	private static boolean bareWord(char c)
	{
		return c >= '0' && c <= '9' || "+-.eEtrufalsn".indexOf(c) >= 0;
	}

	/** The text of a reply made in several rounds (it stopped to look things up): each round's text, in order. */
	static String joinRounds(List<String> rounds, String current)
	{
		StringBuilder sb = new StringBuilder();
		for (String r : rounds)
		{
			append(sb, r);
		}
		append(sb, current);
		return sb.toString();
	}

	private static void append(StringBuilder sb, String text)
	{
		String t = text == null ? "" : text.trim();
		if (!t.isEmpty())
		{
			sb.append(sb.length() > 0 ? "\n\n" : "").append(t);
		}
	}
}

package com.aichat;

import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.channels.OverlappingFileLockException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.BooleanSupplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The saved chats on disk, in the plugin's own folder. One RuneLite window at a time owns them: with several open, the
 * first keeps its lock for as long as it runs, and the others never read, write or delete the file, so they can't
 * overwrite each other. Every method does file work, so call them off the Swing and client threads.
 */
@Slf4j
final class ChatFile implements ChatSaver.Disk
{
	enum State
	{
		/** This window loads and saves the chats. */
		OWNER,
		/** Another RuneLite window does. */
		OTHER_WINDOW,
		/** The file is there but couldn't be read: it's left alone rather than written over. */
		UNREADABLE
	}

	static final class Opened
	{
		final State state;
		/** The saved chats, or null for none. */
		final ChatStore.Loaded loaded;

		Opened(State state, ChatStore.Loaded loaded)
		{
			this.state = state;
			this.loaded = loaded;
		}
	}

	private static final String LOCK_NAME = "chats.lock";

	private final Callable<Filepath> folder;
	private final Gson gson;
	/** Held until RuneLite exits, once taken: turning the plugin off and on can't hand the chats to another window. */
	private FileChannel lockChannel;
	private FileLock lock;
	private State state;
	/** The number of the newest save written, so an older one never lands after it. */
	private long written;

	ChatFile(Callable<Filepath> folder, Gson gson)
	{
		this.folder = folder;
		this.gson = gson;
	}

	/** Takes ownership if no other window has it, and reads the saved chats. Only the first call does anything. */
	@Override
	public synchronized Opened open()
	{
		if (state != null)
		{
			return new Opened(state, null);
		}
		try
		{
			Filepath dir = folder.call();
			dir.createDirectories();
			if (!lock(dir))
			{
				state = State.OTHER_WINDOW;
				return new Opened(state, null);
			}
			Filepath file = dir.joinSegment(ChatStore.FILE_NAME);
			if (!file.isFile())
			{
				state = State.OWNER;
				return new Opened(state, null);
			}
			String json;
			try
			{
				json = read(file);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("couldn't read the saved chats; they won't be written over", e);
				state = State.UNREADABLE;
				return new Opened(state, null);
			}
			ChatStore.Loaded loaded = ChatStore.fromJson(gson, json);
			if (loaded == null)
			{
				// Damaged: kept aside for anyone who wants to look, and a fresh file started.
				Filepath aside = dir.joinSegment("chats-damaged-" + System.currentTimeMillis() + ".json");
				file.moveTo(aside);
				log.warn("the saved chats were damaged; moved them to {}", aside.getFileName());
			}
			state = State.OWNER;
			return new Opened(state, loaded);
		}
		catch (Exception e)
		{
			log.warn("couldn't open the saved chats", e);
			state = State.UNREADABLE;
			return new Opened(state, null);
		}
	}

	private boolean lock(Filepath dir) throws IOException
	{
		FileChannel channel = dir.joinSegment(LOCK_NAME).openFileChannel(StandardOpenOption.CREATE, StandardOpenOption.WRITE);
		FileLock taken;
		try
		{
			taken = channel.tryLock();
		}
		catch (OverlappingFileLockException e)
		{
			taken = null;
		}
		if (taken == null)
		{
			channel.close();
			return false;
		}
		lockChannel = channel;
		lock = taken;
		return true;
	}

	private static String read(Filepath file) throws IOException
	{
		StringBuilder sb = new StringBuilder();
		char[] buffer = new char[8192];
		try (BufferedReader r = file.openBufferedReader())
		{
			for (int n; (n = r.read(buffer)) > 0; )
			{
				sb.append(buffer, 0, n);
			}
		}
		return sb.toString();
	}

	/**
	 * Writes save number {@code number}, unless this window doesn't own the chats, a newer save was already written,
	 * or {@code wanted} says saving has been turned off since.
	 */
	@Override
	public synchronized void write(String json, long number, BooleanSupplier wanted)
	{
		if (state != State.OWNER || number < written || !wanted.getAsBoolean())
		{
			return;
		}
		Filepath temp = null;
		try
		{
			Filepath dir = folder.call();
			dir.createDirectories();
			// Written whole, then moved into place: a crash mid-save can't leave half a file.
			temp = dir.createTempFile("chats", ".tmp");
			temp.write(json);
			Filepath file = dir.joinSegment(ChatStore.FILE_NAME);
			try
			{
				temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			temp = null;
			written = number;
		}
		catch (Exception e)
		{
			log.debug("couldn't save the chats", e);
		}
		finally
		{
			if (temp != null)
			{
				try
				{
					temp.deleteIfExists();
				}
				catch (IOException e)
				{
					log.debug("couldn't remove a temporary file", e);
				}
			}
		}
	}

	/**
	 * Deletes the saved chats, and any temporary file a save left behind, unless another RuneLite window owns them: they
	 * are that window's to keep or delete. The lock, if held, stays; if this window hasn't taken it, it's taken only
	 * while deleting, so it doesn't keep a window that saves its chats from owning them later.
	 */
	@Override
	public synchronized void delete()
	{
		boolean borrowed = false;
		try
		{
			Filepath dir = folder.call();
			if (!dir.isDirectory())
			{
				return;
			}
			if (lock == null)
			{
				if (!lock(dir))
				{
					return;
				}
				borrowed = true;
			}
			dir.joinSegment(ChatStore.FILE_NAME).deleteIfExists();
			List<Filepath> temps;
			try (Stream<Filepath> files = dir.walk(1))
			{
				temps = files.filter(f -> f.isFile() && f.getFileName().startsWith("chats") && f.getFileName().endsWith(".tmp"))
					.collect(Collectors.toList());
			}
			for (Filepath f : temps)
			{
				f.deleteIfExists();
			}
		}
		catch (Exception e)
		{
			log.debug("couldn't delete the saved chats", e);
		}
		finally
		{
			if (borrowed)
			{
				unlock();
			}
		}
	}

	/** Gives the lock back (closing its channel releases it). */
	private void unlock()
	{
		try
		{
			lockChannel.close();
		}
		catch (IOException e)
		{
			log.debug("couldn't release the saved chats' lock", e);
		}
		lockChannel = null;
		lock = null;
	}
}

package com.aichat;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

/**
 * "Save chat history": opens the saved chats once and brings them back, saves the chats a moment after they change, and
 * deletes the saved copy when the setting is turned off. Runs on the Swing EDT, where the chats live; the file work
 * goes to {@code executor}, and what it found comes back through {@code edt}.
 */
final class ChatSaver
{
	/** The saved chats on disk: {@link ChatFile} in the game, a stand-in in tests. File work: on the executor only. */
	interface Disk
	{
		/** Takes ownership of the saved chats if no other window has it, and reads them. Only the first call does. */
		ChatFile.Opened open();

		/** Writes save number {@code number}, unless a newer one was written or {@code wanted} says not to any more. */
		void write(String json, long number, BooleanSupplier wanted);

		void delete();
	}

	/** What the saver needs from the plugin. On the EDT, except {@link #rememberChats}. */
	interface Host
	{
		/** "Save chat history", right now. Any thread. */
		boolean rememberChats();

		/** The chats, in order: what a save writes, and where saved chats are brought back to. */
		List<Chat> chats();

		/** The chat that's open. */
		Chat current();

		/** Saved chats were brought back, and {@code current} is the one to show. */
		void restored(Chat current);

		/** Says why this window's chats aren't being remembered. */
		void note(String text);
	}

	static final String OTHER_WINDOW = "Chats in this window won't be remembered: AI Chat already remembers chats in "
		+ "another RuneLite window.";
	static final String UNREADABLE = "Your saved chats couldn't be read, so this session won't save over them. "
		+ "Restarting RuneLite may help.";
	/** Changes this close together make one save. */
	private static final long SAVE_DELAY_SECONDS = 1;

	private final Disk disk;
	private final Gson gson;
	/** Runs a task on the EDT later, never right away: SwingUtilities::invokeLater. */
	private final Executor edt;
	/** Shared with RuneLite: short tasks only. */
	private final ScheduledExecutorService executor;
	private final Host host;
	/** Whether this window owns the saved chats; null until the file has been opened. */
	private ChatFile.State state;
	/** The saved chats are being opened. A save now would write over them, so it waits: one follows the opening. */
	private boolean loading;
	/** The next save, if one is waiting. */
	private ScheduledFuture<?> pendingSave;
	private long saveCount;
	/** RuneLite is closing: save at once instead of a moment later. */
	private boolean closing;

	ChatSaver(Disk disk, Gson gson, Executor edt, ScheduledExecutorService executor, Host host)
	{
		this.disk = disk;
		this.gson = gson;
		this.edt = edt;
		this.executor = executor;
		this.host = host;
	}

	/** Makes the saved chats match the setting: open (and load) them, save, or delete them. */
	void apply()
	{
		if (!host.rememberChats())
		{
			deleteSaved();
		}
		else if (state == null)
		{
			open();
		}
		else if (state == ChatFile.State.OWNER)
		{
			saveSoon();
		}
		else
		{
			showNote();
		}
	}

	/** Opens the saved chats in the background, brings them back, and from then on saves this window's. */
	private void open()
	{
		if (loading)
		{
			return;
		}
		loading = true;
		executor.execute(() ->
		{
			ChatFile.Opened opened = disk.open();
			edt.execute(() -> opened(opened));
		});
	}

	private void opened(ChatFile.Opened opened)
	{
		loading = false;
		state = opened.state;
		if (opened.loaded != null)
		{
			Chat shown = restore(host.chats(), host.current(), opened.loaded);
			if (shown != null)
			{
				host.restored(shown);
			}
		}
		showNote();
		// Brings the file up to date with the chats from before it was opened, if any.
		saveSoon();
	}

	/**
	 * Puts saved chats back in front of {@code chats}, leaving out any that are already there; the empty chat made at
	 * start-up gives way to them. Returns the chat to show, or null when there was nothing to bring back.
	 */
	static Chat restore(List<Chat> chats, Chat current, ChatStore.Loaded loaded)
	{
		List<Chat> fresh = new ArrayList<>();
		for (Chat c : loaded.chats)
		{
			if (chats.stream().noneMatch(existing -> existing.id.equals(c.id)))
			{
				fresh.add(c);
			}
		}
		if (fresh.isEmpty())
		{
			return null;
		}
		chats.removeIf(c -> c.messages.isEmpty() && !c.isRunning() && !c.namedByPlayer);
		chats.addAll(0, fresh);
		if (current != null && chats.contains(current))
		{
			return current;
		}
		return loaded.current != null && chats.contains(loaded.current) ? loaded.current : fresh.get(fresh.size() - 1);
	}

	/** Says why this window's chats aren't being remembered, if they aren't. */
	private void showNote()
	{
		if (!host.rememberChats())
		{
			return;
		}
		if (state == ChatFile.State.OTHER_WINDOW)
		{
			host.note(OTHER_WINDOW);
		}
		else if (state == ChatFile.State.UNREADABLE)
		{
			host.note(UNREADABLE);
		}
	}

	/** Saves the chats a moment from now; more changes in the meantime make it one save. */
	void saveSoon()
	{
		save(SAVE_DELAY_SECONDS);
	}

	void saveNow()
	{
		save(0);
	}

	/** RuneLite is closing: saves now, and from now on every change at once. The save, or null if there's none. */
	ScheduledFuture<?> close()
	{
		closing = true;
		return save(0);
	}

	/** The save scheduled, or null if there's nothing to save to (yet). */
	private ScheduledFuture<?> save(long delaySeconds)
	{
		if (!host.rememberChats() || loading || state != ChatFile.State.OWNER)
		{
			return null;
		}
		// Taken now, on the EDT, where the chats live.
		String json = ChatStore.toJson(gson, host.chats(), host.current());
		long number = ++saveCount;
		if (pendingSave != null)
		{
			pendingSave.cancel(false);
		}
		pendingSave = executor.schedule(() -> disk.write(json, number, host::rememberChats),
			closing ? 0 : delaySeconds, TimeUnit.SECONDS);
		return pendingSave;
	}

	/** "Save chat history" is off: no saves waiting, and no saved copy left. */
	private void deleteSaved()
	{
		if (pendingSave != null)
		{
			pendingSave.cancel(false);
			pendingSave = null;
		}
		executor.execute(disk::delete);
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.List;

/**
 * What's kept of the chats between RuneLite sessions, when "Save chat history" is on: names, messages (with what was
 * looked up for each reply), and the summary sent instead of a long chat's oldest messages; nothing else. API keys
 * aren't part of a chat, and Claude's replayable reasoning stays in memory only. Converting happens on the Swing EDT
 * (where chats live); reading and writing the file happen elsewhere. Files from before a field was added still load:
 * it's just missing (null, 0 or false). Fields that are no longer used (each reply's token counts) are skipped.
 */
final class ChatStore
{
	static final String FILE_NAME = "chats.json";
	/**
	 * Older messages of a long chat aren't kept, as long as they're no longer sent to the assistant (summarised, or
	 * notes and errors); a note takes their place. Messages that are still sent are kept however many there are.
	 */
	static final int MAX_MESSAGES = 200;

	private ChatStore()
	{
	}

	static final class Saved
	{
		int version = 1;
		String current;
		/** Null in a file that isn't ours. */
		List<SavedChat> chats;
	}

	static final class SavedChat
	{
		String id;
		String name;
		boolean defaultName;
		boolean namedByPlayer;
		String summary;
		int summaryVersion;
		/** See {@link Chat#leftOut}: over every save so far. */
		int leftOut;
		int leftOutSummarized;
		List<SavedMessage> messages = new ArrayList<>();
	}

	static final class SavedMessage
	{
		String role;
		String text;
		long time;
		String who;
		String context;
		boolean unanswered;
		boolean unfinished;
		boolean summarized;
		/** Null when nothing was looked up or shared. */
		List<String> activity;
	}

	/** EDT. */
	static String toJson(Gson gson, List<Chat> chats, Chat current)
	{
		Saved saved = new Saved();
		saved.current = current == null ? null : current.id;
		saved.chats = new ArrayList<>();
		for (Chat c : chats)
		{
			SavedChat sc = new SavedChat();
			sc.id = c.id;
			sc.name = c.name;
			sc.defaultName = c.defaultName;
			sc.namedByPlayer = c.namedByPlayer;
			sc.summary = c.summary;
			sc.summaryVersion = c.summaryVersion;
			List<Chat.Message> messages = new ArrayList<>(c.messages);
			messages.remove(c.leftOutNote);
			int cut = cut(messages);
			int summarized = 0;
			for (Chat.Message m : messages.subList(0, cut))
			{
				summarized += m.summarized ? 1 : 0;
			}
			sc.leftOut = c.leftOut + cut;
			sc.leftOutSummarized = c.leftOutSummarized + summarized;
			for (Chat.Message m : messages.subList(cut, messages.size()))
			{
				SavedMessage sm = new SavedMessage();
				sm.role = m.role.name();
				sm.text = m.text;
				sm.time = m.time;
				sm.who = m.who;
				sm.context = m.context;
				// A question still waiting when RuneLite closes won't be answered.
				sm.unanswered = m.unanswered || c.isRunning() && m.role == Chat.Role.USER && m == lastUserMessage(c);
				sm.unfinished = m.unfinished;
				sm.summarized = m.summarized;
				sm.activity = m.activity == null || m.activity.isEmpty() ? null : new ArrayList<>(m.activity);
				sc.messages.add(sm);
			}
			saved.chats.add(sc);
		}
		return gson.toJson(saved);
	}

	/**
	 * How many of the oldest messages to leave out so that at most {@link #MAX_MESSAGES} are kept: only from the start
	 * of the chat, and only up to the first message that's still sent.
	 */
	private static int cut(List<Chat.Message> messages)
	{
		int over = messages.size() - MAX_MESSAGES;
		int cut = 0;
		while (cut < over && !ConversationBuilder.stillSent(messages.get(cut)))
		{
			cut++;
		}
		return cut;
	}

	static final class Loaded
	{
		final List<Chat> chats = new ArrayList<>();
		/** The chat that was open, if it's among them. */
		Chat current;
	}

	/** The chats in a saved file, in their order, or null if the file is damaged (not JSON, or not ours). */
	static Loaded fromJson(Gson gson, String json)
	{
		Loaded loaded = new Loaded();
		Saved saved;
		try
		{
			saved = gson.fromJson(json, Saved.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
		if (saved == null || saved.chats == null)
		{
			return null;
		}
		for (SavedChat sc : saved.chats)
		{
			if (sc == null || sc.id == null || sc.name == null)
			{
				continue;
			}
			Chat c = new Chat(sc.id, sc.name);
			c.defaultName = sc.defaultName;
			c.namedByPlayer = sc.namedByPlayer;
			c.summary = sc.summary == null || sc.summary.trim().isEmpty() ? null : sc.summary;
			c.summaryVersion = sc.summaryVersion;
			c.leftOut = Math.max(0, sc.leftOut);
			c.leftOutSummarized = Math.max(0, Math.min(c.leftOut, sc.leftOutSummarized));
			if (sc.messages != null)
			{
				for (SavedMessage sm : sc.messages)
				{
					Chat.Role role = role(sm == null ? null : sm.role);
					if (role == null || sm.text == null)
					{
						continue;
					}
					Chat.Message m = new Chat.Message(role, sm.text, sm.time);
					m.who = sm.who;
					m.context = sm.context;
					m.unanswered = sm.unanswered;
					m.unfinished = sm.unfinished && role == Chat.Role.ASSISTANT;
					// Without its summary, a summarised message is sent again rather than lost.
					m.summarized = sm.summarized && c.summary != null;
					m.activity = activity(sm.activity);
					c.messages.add(m);
				}
			}
			// The last question never got its answer if nothing came after it.
			if (!c.messages.isEmpty() && c.messages.get(c.messages.size() - 1).role == Chat.Role.USER)
			{
				c.messages.get(c.messages.size() - 1).unanswered = true;
			}
			if (c.leftOut > 0)
			{
				// Where the start of the chat was, so the player knows it's gone and why.
				long time = c.messages.isEmpty() ? System.currentTimeMillis() : c.messages.get(0).time;
				c.leftOutNote = new Chat.Message(Chat.Role.NOTE, leftOutNote(c.leftOut, c.leftOutSummarized), time);
				c.messages.add(0, c.leftOutNote);
			}
			loaded.chats.add(c);
			if (sc.id.equals(saved.current))
			{
				loaded.current = c;
			}
		}
		return loaded;
	}

	/** What the note in place of the messages that weren't kept says. */
	static String leftOutNote(int leftOut, int summarized)
	{
		String covered = summarized > 0 ? ": the summary covers " + (leftOut == 1 ? "it." : "them.") : ".";
		if (leftOut == 1)
		{
			return "The oldest message of this chat wasn't kept when it was saved (AI Chat saves the latest "
				+ MAX_MESSAGES + " of each chat). It wasn't being sent to the assistant any more" + covered;
		}
		return "The " + leftOut + " oldest messages of this chat weren't kept when it was saved (AI Chat saves the "
			+ "latest " + MAX_MESSAGES + " of each chat). None of them were being sent to the assistant any more" + covered;
	}

	/** The saved lines, without any a hand-edited file left empty; null for none. */
	private static List<String> activity(List<String> saved)
	{
		if (saved == null)
		{
			return null;
		}
		List<String> lines = new ArrayList<>();
		for (String line : saved)
		{
			if (line != null && !line.trim().isEmpty())
			{
				lines.add(line);
			}
		}
		return lines.isEmpty() ? null : lines;
	}

	private static Chat.Role role(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (Chat.Role r : Chat.Role.values())
		{
			if (r.name().equals(name))
			{
				return r;
			}
		}
		return null;
	}

	private static Chat.Message lastUserMessage(Chat c)
	{
		for (int i = c.messages.size() - 1; i >= 0; i--)
		{
			if (c.messages.get(i).role == Chat.Role.USER)
			{
				return c.messages.get(i);
			}
		}
		return null;
	}
}

package com.aichat;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.ActionEvent;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.AbstractAction;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JToolTip;
import javax.swing.KeyStroke;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.DefaultEditorKit;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * Where the player writes, at the bottom of the panel as in chat apps: a short note when a message can't go yet, the
 * input box (saying "Ask anything..." while it's empty), and under it the model picker and one round button. The button
 * sends; while a reply is on its way it stops it, and while a long chat's summary is being made it skips that. Enter
 * sends and Shift+Enter starts a new line. The box grows with what's typed in it, up to a few lines, then scrolls.
 * Swing EDT only.
 */
final class Composer extends JPanel
{
	static final String PLACEHOLDER = "Ask anything…";
	static final String SEND_TIP = "Send (Enter)";
	static final String STOP_TIP = "Stop";
	/** While a long chat is summarised before the question goes, the button skips the summary instead. */
	static final String SKIP_TIP = "Skip the summary and send the whole chat this time. Press Stop after that to "
		+ "stop the question too.";
	/** The box is this many lines tall when it's empty, and grows with the text up to {@link #MAX_LINES}. */
	static final int MIN_LINES = 2;
	/** Past this, the text scrolls inside the box instead of pushing the transcript away. */
	static final int MAX_LINES = 6;

	/** What the button does now. */
	enum Mode
	{
		SEND, STOP, SKIP
	}

	/** What the composer asks the panel to do. */
	interface Actions
	{
		/** Sends {@code text}; false if it can't go right now (it stays in the box). */
		boolean send(String text);

		/** Stops the reply on its way, or skips the summary being made. */
		void stop();

		/** The player chose {@code model} in the picker. */
		void chooseModel(String model);

		/** The player asked for the provider's list of models again. */
		void refreshModels();

		/** The input box is about to change height: the transcript above it gets shorter or taller. */
		void inputResizing();
	}

	/** A short note above the box, such as why a message can't be sent yet; hidden when there's none. */
	final JTextArea note = PanelStyle.textArea("");
	final Prompt input = new Prompt();
	/** The input box's scroll pane: as tall as the text in it, within {@link #MIN_LINES} and {@link #MAX_LINES}. */
	final JScrollPane scroll = new JScrollPane(input)
	{
		@Override
		public Dimension getPreferredSize()
		{
			Dimension d = super.getPreferredSize();
			d.height = inputHeight();
			return d;
		}
	};
	final ModelPicker models;
	final ActionButton action = new ActionButton();
	private final RoundBox box = new RoundBox(new BorderLayout(), PanelStyle.FIELD_COLOR, PanelStyle.OUTLINE_COLOR);
	private final Actions actions;
	/** There's a chat to write in. */
	private boolean usable = true;
	/** The input box's height for the text as it last was, to tell when typing makes it grow or shrink. */
	private int shownHeight = -1;
	/** The box's height is checked once the change being made now is in: no need to ask again until then. */
	private boolean resizePending;

	Composer(Actions actions)
	{
		super(new StackLayout(6));
		this.actions = actions;
		models = new ModelPicker(new ModelPicker.Actions()
		{
			@Override
			public void choose(String model)
			{
				actions.chooseModel(model);
			}

			@Override
			public void refresh()
			{
				actions.refreshModels();
			}
		});
		setOpaque(false);

		note.setFont(PanelStyle.SMALL_FONT);
		note.setForeground(PanelStyle.ERROR_COLOR);
		note.setVisible(false);
		add(note);

		input.setLineWrap(true);
		input.setWrapStyleWord(true);
		input.setFont(PanelStyle.TEXT_FONT);
		input.setOpaque(false);
		input.setForeground(PanelStyle.TEXT_COLOR);
		input.setCaretColor(PanelStyle.TEXT_COLOR);
		input.setBorder(new EmptyBorder(0, 0, 0, 0));
		input.setToolTipText("Enter sends, Shift+Enter adds a line");
		input.getInputMap().put(KeyStroke.getKeyStroke("ENTER"), "ai-chat-send");
		input.getInputMap().put(KeyStroke.getKeyStroke("shift ENTER"), DefaultEditorKit.insertBreakAction);
		input.getActionMap().put("ai-chat-send", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				send();
			}
		});
		input.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				changed();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				changed();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				changed();
			}
		});
		// The box's outline brightens while it has the caret, as text fields do.
		input.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusGained(FocusEvent e)
			{
				box.setColors(PanelStyle.FIELD_COLOR, ColorScheme.LIGHT_GRAY_COLOR);
			}

			@Override
			public void focusLost(FocusEvent e)
			{
				box.setColors(PanelStyle.FIELD_COLOR, PanelStyle.OUTLINE_COLOR);
			}
		});
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(lineHeight());
		box.setBorder(new EmptyBorder(6, 8, 6, 4));
		box.add(scroll, BorderLayout.CENTER);
		add(box);

		JPanel controls = new JPanel(new BorderLayout(6, 0));
		controls.setOpaque(false);
		controls.add(models, BorderLayout.CENTER);
		action.addActionListener(e ->
		{
			if (!action.settled())
			{
				return;
			}
			if (action.mode == Mode.SEND)
			{
				send();
			}
			else
			{
				actions.stop();
			}
		});
		controls.add(action, BorderLayout.EAST);
		add(controls);
		refreshAction();
	}

	/** The text changed: Send may have something to send now, and the box may need another height. */
	private void changed()
	{
		refreshAction();
		if (resizePending)
		{
			return;
		}
		// Measured once the text area has taken the change in too: this listener is told before it is (Swing tells the
		// latest listener first), so the text's height right now is still the height before the change. Once for a
		// change made in two steps, as setText's removing then inserting.
		resizePending = true;
		SwingUtilities.invokeLater(() ->
		{
			resizePending = false;
			int height = inputHeight();
			if (height != shownHeight)
			{
				shownHeight = height;
				// The scroll pane is laid out on its own (it's a validate root): the whole composer is, with the panel.
				revalidate();
				actions.inputResizing();
			}
		});
	}

	/**
	 * How tall the input box is for the text in it, at its width: from {@link #MIN_LINES} to {@link #MAX_LINES} lines.
	 * The text area wraps to the box's width, so its own preferred height is what the text needs.
	 */
	int inputHeight()
	{
		int text = input.getPreferredSize().height;
		return Math.max(linesHeight(MIN_LINES), Math.min(linesHeight(MAX_LINES), text));
	}

	/**
	 * How tall the text area is with {@code lines} lines in it: measured as its own preferred height is, by the lines
	 * and the space around them, so that a box of six lines shows six whole lines.
	 */
	int linesHeight(int lines)
	{
		Insets in = input.getInsets();
		return lines * lineHeight() + in.top + in.bottom;
	}

	private int lineHeight()
	{
		return input.getFontMetrics(input.getFont()).getHeight();
	}

	private void send()
	{
		String text = input.getText().trim();
		if (text.isEmpty())
		{
			return;
		}
		if (actions.send(text))
		{
			input.setText("");
			showNote(null);
		}
	}

	/**
	 * Brings the button in line with the chat: {@code usable}, there's a chat to write in; {@code running}, a reply is
	 * on its way; {@code summarising}, a long chat's summary is being made first.
	 */
	void setState(boolean usable, boolean running, boolean summarising)
	{
		this.usable = usable;
		input.setEnabled(usable);
		action.setMode(!running ? Mode.SEND : summarising ? Mode.SKIP : Mode.STOP);
		refreshAction();
	}

	/** Send needs something to send; Stop and Skip are always there to press. */
	private void refreshAction()
	{
		action.setEnabled(action.mode != Mode.SEND || usable && !input.getText().trim().isEmpty());
	}

	/** Puts {@code text} in the box, ready to finish and send: never sends it. */
	void fill(String text)
	{
		input.setText(text);
		input.setCaretPosition(input.getDocument().getLength());
		input.requestFocusInWindow();
	}

	/** Put a message that couldn't be sent back in the box, after anything already there. */
	void restoreDraft(String text)
	{
		String current = input.getText().trim();
		if (current.isEmpty())
		{
			input.setText(text);
		}
		else if (!current.contains(text))
		{
			input.setText(current + "\n\n" + text);
		}
	}

	/** A short note above the box; null clears it. */
	void showNote(String text)
	{
		note.setText(text == null ? "" : text);
		note.setVisible(text != null && !text.isEmpty());
		revalidate();
	}

	/** The input box: plain text, with {@link #PLACEHOLDER} drawn in it, muted, while it's empty. */
	static final class Prompt extends JTextArea
	{
		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			if (getDocument().getLength() > 0)
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g2.setColor(PanelStyle.MUTED_COLOR);
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			Insets in = getInsets();
			g2.drawString(PLACEHOLDER, in.left, in.top + fm.getAscent());
			g2.dispose();
		}

		@Override
		public JToolTip createToolTip()
		{
			JToolTip tip = super.createToolTip();
			tip.putClientProperty("html.disable", Boolean.TRUE);
			return tip;
		}
	}

	/**
	 * The round button beside the model picker: an arrow to send, a square to stop, or "Skip" while a summary is being
	 * made. Drawn whole by itself (shape, icon and word), so it's the same with any look and feel.
	 */
	static final class ActionButton extends JButton
	{
		/** A click this soon after the button changed what it does was meant for what it did before. */
		static final long SETTLE_MILLIS = 500;
		private static final int SIZE = 26;
		private static final Color ON = new Color(235, 235, 235);
		private static final Color INK = ColorScheme.DARKER_GRAY_COLOR;
		Mode mode;
		/** When the button last changed what it does, in {@link System#currentTimeMillis()} time; 0 before then. */
		long changedAt;

		ActionButton()
		{
			putClientProperty("html.disable", Boolean.TRUE);
			setContentAreaFilled(false);
			setBorderPainted(false);
			setFocusPainted(false);
			setOpaque(false);
			setRolloverEnabled(true);
			setFont(PanelStyle.SMALL_FONT);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			setMode(Mode.SEND);
		}

		void setMode(Mode mode)
		{
			if (mode == this.mode)
			{
				return;
			}
			if (this.mode != null)
			{
				changedAt = System.currentTimeMillis();
			}
			this.mode = mode;
			// The words are for screen readers and tests: the button draws an icon for Send and Stop.
			setText(mode == Mode.SEND ? "Send" : mode == Mode.STOP ? "Stop" : "Skip");
			setToolTipText(mode == Mode.SEND ? SEND_TIP : mode == Mode.STOP ? STOP_TIP : SKIP_TIP);
			revalidate();
			repaint();
		}

		/**
		 * Whether a click now is meant for what the button does now. Send turns into Stop the moment a question goes, and
		 * Stop back into Send the moment the reply is in: without this, a double-click on Send would stop the question
		 * it had just sent (which may be paid for by then), and Stop pressed just as the reply came in would send what's
		 * in the box.
		 */
		boolean settled()
		{
			return System.currentTimeMillis() - changedAt >= SETTLE_MILLIS;
		}

		@Override
		public Dimension getPreferredSize()
		{
			if (mode == Mode.SKIP)
			{
				return new Dimension(getFontMetrics(getFont()).stringWidth(getText()) + 20, SIZE);
			}
			return new Dimension(SIZE, SIZE);
		}

		@Override
		public Dimension getMinimumSize()
		{
			return getPreferredSize();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = PanelStyle.smooth(g);
			int w = getWidth();
			int y = (getHeight() - SIZE) / 2;
			Color fill = !isEnabled() ? PanelStyle.OUTLINE_COLOR : getModel().isRollover() ? Color.WHITE : ON;
			g2.setColor(fill);
			if (mode == Mode.SKIP)
			{
				g2.fill(new RoundRectangle2D.Float(0, y, w, SIZE, SIZE, SIZE));
				g2.setColor(INK);
				g2.setFont(getFont());
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				FontMetrics fm = g2.getFontMetrics();
				g2.drawString(getText(), (w - fm.stringWidth(getText())) / 2, y + (SIZE + fm.getAscent() - fm.getDescent()) / 2);
			}
			else
			{
				int x = w - SIZE;
				g2.fill(new Ellipse2D.Float(x, y, SIZE, SIZE));
				int icon = 14;
				new Glyph(mode == Mode.SEND ? Glyph.Shape.SEND : Glyph.Shape.STOP, icon, INK)
					.paintIcon(this, g2, x + (SIZE - icon) / 2, y + (SIZE - icon) / 2);
			}
			g2.dispose();
		}

		@Override
		public JToolTip createToolTip()
		{
			JToolTip tip = super.createToolTip();
			tip.putClientProperty("html.disable", Boolean.TRUE);
			return tip;
		}
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * The provider's list of models, asked for with the player's key: by "Test connection", which says what it means for
 * their setup, and quietly for the model picker next to Send. The result is kept for the provider, address and key it
 * was made with, and read against whichever model is set now, so choosing another model (in the panel or in the
 * settings) updates it without asking again.
 */
final class ConnectionCheck
{
	/** Model ids that aren't for chatting: OpenAI's embeddings, speech, images, moderation and the like. */
	private static final String[] NOT_CHAT = {"embed", "tts", "whisper", "dall-e", "moderation", "image", "audio",
		"transcribe", "realtime", "search"};

	enum Kind
	{
		/** Still asking. */
		TESTING,
		OK,
		/** Connected, but the model needs a look. */
		WARNING,
		ERROR
	}

	/** What the panel's banner says after a Test. */
	static final class Note
	{
		final Kind kind;
		final String text;

		Note(Kind kind, String text)
		{
			this.kind = kind;
			this.text = text;
		}
	}

	/** Which provider, address and key the check was for (see {@link #setupKey}). */
	final String setup;
	/** The chat models listed, or null while asking, after an error, or when the service has no list. */
	final List<String> models;
	/** Why it failed, or null. */
	final String error;

	private ConnectionCheck(String setup, List<String> models, String error)
	{
		this.setup = setup;
		this.models = models;
		this.error = error;
	}

	static ConnectionCheck testing(String setup)
	{
		return new ConnectionCheck(setup, null, null);
	}

	/** {@code sorted}: put them in alphabetical order (Anthropic's list comes newest first, which is better kept). */
	static ConnectionCheck listed(String setup, List<String> ids, boolean sorted)
	{
		return new ConnectionCheck(setup, chatModels(ids, sorted), null);
	}

	static ConnectionCheck failed(String setup, String error)
	{
		return new ConnectionCheck(setup, null, error);
	}

	/**
	 * Tells setups apart without keeping the key itself: a different provider, address or key makes an earlier check
	 * say nothing about this one.
	 */
	static String setupKey(AiChatConfig.Provider provider, String url, String key)
	{
		return provider + "\u0000" + (url == null ? "" : url.trim()) + "\u0000" + (key == null ? 0 : key.hashCode());
	}

	/** The ids worth offering as chat models, without duplicates. */
	static List<String> chatModels(List<String> ids, boolean sorted)
	{
		List<String> models = new ArrayList<>();
		for (String id : ids)
		{
			if (id != null && !id.trim().isEmpty() && !models.contains(id) && isChatModel(id))
			{
				models.add(id);
			}
		}
		if (sorted)
		{
			models.sort(String.CASE_INSENSITIVE_ORDER);
		}
		return models;
	}

	private static boolean isChatModel(String id)
	{
		String lower = id.toLowerCase(Locale.ROOT);
		for (String word : NOT_CHAT)
		{
			if (lower.contains(word))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * What the check says about {@code model} (blank when none is set yet). {@code service}: "Anthropic", "OpenAI", or
	 * the address of a compatible service; {@code keyed}: the player's own key decides which models they get (Claude,
	 * ChatGPT); {@code keyUnchecked}: a key went to a service whose list may not need one, so the list says nothing
	 * about it.
	 */
	Note note(String service, String model, boolean keyed, boolean keyUnchecked)
	{
		if (error != null)
		{
			if (OpenAiApi.NO_MODEL_LIST.equals(error))
			{
				// Any web server answers "not found", so this says little: not even that the URL is right. With no model
				// set, there's none to pick either: say where its name goes.
				if (model == null || model.trim().isEmpty())
				{
					return new Note(Kind.WARNING, service + " answered, but not with a list of models, so Test can't "
						+ "check the URL or offer a model. Type the model's name next to Send, as the service's website "
						+ "gives it.");
				}
				return new Note(Kind.WARNING, service + " answered, but not with a list of models, so Test can't check "
					+ "the URL or the model name. Check both on the service's website.");
			}
			return new Note(Kind.ERROR, error);
		}
		if (models == null)
		{
			return new Note(Kind.TESTING, "Testing the connection\u2026");
		}
		if (models.isEmpty())
		{
			return new Note(Kind.WARNING, "Connected to " + service + ", but it listed no models to chat with.");
		}
		// OpenRouter lists its models for anyone: a wrong key there only shows when a message is sent.
		String key = keyUnchecked ? " Your key is checked when you send: some services list their models for anyone." : "";
		if (model == null || model.trim().isEmpty())
		{
			return new Note(Kind.OK, "Connected to " + service + "." + key + " Pick a model next to Send.");
		}
		if (has(models, model))
		{
			return new Note(Kind.OK, "Connected to " + service + ". " + model + " is available." + key);
		}
		return new Note(Kind.WARNING, (keyed ? "Connected, but " + model + " isn't in the list your key can use."
			: "Connected to " + service + ", but " + model + " isn't one of its models.") + " Pick another next to Send.");
	}

	/** Whether {@code model} is one of {@code models}, as named there (see {@link #sameModel}). */
	private static boolean has(List<String> models, String model)
	{
		for (String id : models)
		{
			if (sameModel(id, model))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether {@code listed}, a model as the provider's list names it, is {@code model} as the player set it: Ollama
	 * lists "llama3.2:latest" for the model asked for as "llama3.2", and Anthropic lists an alias such as
	 * "claude-haiku-4-5" as the dated model it points to, "claude-haiku-4-5-20251001".
	 */
	static boolean sameModel(String listed, String model)
	{
		if (listed.equals(model) || !model.contains(":") && listed.equals(model + ":latest"))
		{
			return true;
		}
		return listed.length() == model.length() + 9 && listed.startsWith(model + "-")
			&& listed.substring(model.length() + 1).matches("\\d{8}");
	}

	/**
	 * What the model picker offers: the model that's set (blank: none), always, and the chat models {@code listed}, in
	 * their order. The model that's set takes the place of the one it is in the list, under the name it's set as (so
	 * "claude-haiku-4-5" isn't offered twice, once by its dated name), or goes first when the list hasn't got it.
	 */
	static List<String> choices(String model, List<String> listed)
	{
		String current = model == null ? "" : model.trim();
		List<String> out = new ArrayList<>();
		boolean placed = current.isEmpty();
		for (String id : listed == null ? Collections.<String>emptyList() : listed)
		{
			if (current.isEmpty() || !sameModel(id, current))
			{
				out.add(id);
			}
			else if (!placed)
			{
				out.add(current);
				placed = true;
			}
		}
		if (!placed)
		{
			out.add(0, current);
		}
		return out;
	}

	/**
	 * The model picker's tooltip: the model that's set, in full (a long one doesn't fit next to Send), how to choose,
	 * and why the list is short when it is (see {@link #listNote}). Plain sentences of our own, starting with our own
	 * words, so they can never be read as HTML.
	 */
	static String pickerTip(ConnectionCheck check, String problem, String service, String model)
	{
		String m = model == null ? "" : model.trim();
		String how = m.isEmpty()
			? "The model new messages go to. Click to pick one, or to type its name."
			: "New messages go to " + m + ". Click to pick another, or to type its name.";
		String note = listNote(check, problem, service);
		return note == null ? how : how + " " + note;
	}

	/**
	 * Why the model picker's list is short, for its tooltip and its menu, or null when it isn't. {@code check}: the
	 * latest list asked for this setup, or null; {@code problem}: why the provider can't be reached (AI requests off
	 * included), or null.
	 */
	static String listNote(ConnectionCheck check, String problem, String service)
	{
		if (problem != null || check == null)
		{
			return "The list fills in once AI requests are on and the provider is set up.";
		}
		if (check.error != null)
		{
			return OpenAiApi.NO_MODEL_LIST.equals(check.error)
				? service + " doesn't list its models: type the name its website gives."
				: "Couldn't list the models: " + check.error;
		}
		if (check.models == null)
		{
			return "Looking up the models you can use\u2026";
		}
		return check.models.isEmpty() ? service + " listed no models to chat with." : null;
	}
}

package com.aichat;

import java.util.List;
import java.util.concurrent.Executor;
import java.util.function.Supplier;

/**
 * Asks the provider which models the key can use, and keeps the latest answer for the provider, address and key it was
 * asked with (see {@link ConnectionCheck}): for "Test connection", which the panel's banner reports on, and quietly for
 * the model picker. Runs on the Swing EDT; the answer comes back through {@code edt}, and counts only if it's for the
 * latest request and that wasn't stopped since.
 */
final class ConnectionTester
{
	/** Runs a task on the EDT later, never right away: SwingUtilities::invokeLater. */
	private final Executor edt;
	/** The result is in: show it. */
	private final Runnable changed;
	/** The latest list asked for, or null. */
	private ConnectionCheck check;
	/** The request in flight, or null. */
	private ChatApi.Pending testing;
	/** The player asked for the latest list with Test, and hasn't closed what the banner says about it. */
	private boolean shown;

	ConnectionTester(Executor edt, Runnable changed)
	{
		this.edt = edt;
		this.changed = changed;
	}

	/**
	 * "Test connection": asks {@code api} for its models, instead of anything still asking, and has the banner say what
	 * the answer means. {@code setup}: the provider, address and key it's for ({@link ProviderSetup#connection});
	 * {@code sorted}: put the models in alphabetical order.
	 */
	void start(ChatApi api, String setup, boolean sorted)
	{
		ask(api, setup, sorted);
		shown = true;
	}

	/**
	 * For the model picker: asks for the models quietly, once for each provider, address and key, until a Test or a
	 * change of setup asks again. Never while {@code problem} says the provider can't be reached (that includes AI
	 * requests being off): then {@code api} isn't even made. Returns whether it asked.
	 */
	boolean list(String problem, String setup, Supplier<ChatApi> api, boolean sorted)
	{
		return (check == null || !check.setup.equals(setup)) && refresh(problem, setup, api, sorted);
	}

	/**
	 * "Refresh list" in the model picker's menu: asks for the models again, quietly, even when the list for this setup
	 * is in, instead of anything still asking. As with {@link #list}, never while {@code problem} says the provider
	 * can't be reached, and not while a Test for this setup is still asking: its answer is the list too, and the
	 * banner is waiting for it. Returns whether it asked.
	 */
	boolean refresh(String problem, String setup, Supplier<ChatApi> api, boolean sorted)
	{
		if (problem != null || shown && testing != null && check(setup) != null)
		{
			return false;
		}
		ChatApi made = api.get();
		if (made == null)
		{
			return false;
		}
		ask(made, setup, sorted);
		shown = false;
		return true;
	}

	private void ask(ChatApi api, String setup, boolean sorted)
	{
		stop();
		check = ConnectionCheck.testing(setup);
		// Set before any answer can be handled: answers are handled on this (the EDT) thread, after this method.
		ChatApi.Pending[] request = new ChatApi.Pending[1];
		try
		{
			request[0] = api.listModels(new ChatApi.ModelsListener()
			{
				@Override
				public void onModels(List<String> ids)
				{
					edt.execute(() -> tested(request[0], ConnectionCheck.listed(setup, ids, sorted)));
				}

				@Override
				public void onError(String message)
				{
					edt.execute(() -> tested(request[0], ConnectionCheck.failed(setup, message)));
				}
			});
		}
		catch (RuntimeException e)
		{
			// As with sending: the exception's message can contain the API key.
			check = ConnectionCheck.failed(setup, RequestRunner.COULDNT_SEND);
		}
		testing = request[0];
	}

	/** The answer to {@code request}: kept only if that's still the request in flight. */
	private void tested(ChatApi.Pending request, ConnectionCheck result)
	{
		if (request == null || testing != request || request.isCancelled())
		{
			return;
		}
		testing = null;
		check = result;
		changed.run();
	}

	/** Stops a request in flight, if any, and forgets the last result. */
	void stop()
	{
		if (testing != null)
		{
			testing.cancel();
			testing = null;
		}
		check = null;
		shown = false;
	}

	/** The player closed the banner: the list is kept for the picker. */
	void dismiss()
	{
		shown = false;
	}

	/**
	 * A message went. Good news from a Test has been read by then, and makes way for the conversation; a warning or an
	 * error stays until it's fixed or closed. Returns whether the banner changed. The arguments are {@link #note}'s.
	 */
	boolean sent(String setup, String service, String model, boolean keyed, boolean keyUnchecked)
	{
		ConnectionCheck.Note n = note(setup, service, model, keyed, keyUnchecked);
		if (n != null && n.kind == ConnectionCheck.Kind.OK)
		{
			shown = false;
			return true;
		}
		return false;
	}

	/**
	 * What the latest Test says about the setup as it is now, for the banner, or null when there's nothing to say: no
	 * Test, the player closed it, or it was for another provider, address or key ({@code setup}). A different model is
	 * fine: the list is read against it.
	 */
	ConnectionCheck.Note note(String setup, String service, String model, boolean keyed, boolean keyUnchecked)
	{
		ConnectionCheck c = check(setup);
		return shown && c != null ? c.note(service, model, keyed, keyUnchecked) : null;
	}

	/** The latest list asked for {@code setup}, by Test or the picker, or null. */
	ConnectionCheck check(String setup)
	{
		return check != null && check.setup.equals(setup) ? check : null;
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What a chat sends: which of its messages go to the provider and how, and the summary that's sent instead of the
 * oldest ones once a chat gets long. No threads or files here; the plugin calls it on the Swing EDT, where chats live.
 */
final class ConversationBuilder
{
	/** Once more messages than this would be sent, the oldest are summarised... */
	static final int SUMMARY_HIGH = 40;
	/** ...and at least this many of the newest are kept as they are. */
	static final int SUMMARY_LOW = 16;
	/**
	 * Plenty for a summary of at most 250 words. Thinking models count their reasoning against it too, so it leaves
	 * room for that; only what's used is billed.
	 */
	static final int SUMMARY_MAX_TOKENS = 4000;
	static final String SUMMARY_PROMPT = "Summarise this conversation between an Old School RuneScape player and an "
		+ "assistant so the assistant can carry on without the original messages. Keep facts about the player's account, "
		+ "goals, decisions, open questions, and anything the player asked to remember. Plain text, at most 250 words.";

	private ConversationBuilder()
	{
	}

	// ------------------------------------------------------------------
	// The request
	// ------------------------------------------------------------------

	/**
	 * The request for {@code message}, the player's newest: the chat's messages that are still sent, with character
	 * notes and the summary where they go. Records on {@code message} what goes with it (its note and the summary it's
	 * sent under), since from now on that's part of what the provider has seen. {@code shareCharacter}: the setting
	 * when the message was sent; {@code context}: the character details read for it, if any.
	 */
	static ChatApi.Conversation conversation(Chat chat, Chat.Message message, String model, String system,
		boolean shareCharacter, String context)
	{
		ChatApi.Conversation conversation = new ChatApi.Conversation();
		conversation.model = model;
		conversation.system = system;
		List<Chat.Message> history = history(chat);

		// Character details go with this message unless the latest ones the provider will see are the same. Decided
		// from what's actually sent: an earlier note may have gone with a failed request or been summarised away.
		boolean newNote = shareCharacter && context != null && !context.equals(latestNote(history, message));
		message.context = newNote ? context : null;
		message.summaryVersion = chat.summaryVersion;

		// With sharing turned off, earlier notes stay out too. That changes earlier turns, so Claude's replies can't be
		// replayed as they were.
		boolean notesLeftOut = false;
		for (Chat.Message m : history)
		{
			notesLeftOut |= !shareCharacter && m.context != null;
		}
		String prefix = chat.summary == null ? null : summaryPrefix(chat.summary);
		for (Chat.Message m : history)
		{
			boolean user = m.role == Chat.Role.USER;
			String text = shareCharacter && m.context != null ? m.context + "\n\n" + m.text : m.text;
			if (user && prefix != null)
			{
				// The summary goes with the oldest message still sent, in the same words until the next summary, so
				// everything before later replies stays the same (for prompt caching and replay).
				text = prefix + text;
				prefix = null;
			}
			ChatApi.Turn t = new ChatApi.Turn(user, text);
			if (replayable(chat, m, notesLeftOut))
			{
				replay(t, m);
			}
			conversation.turns.add(t);
		}
		return conversation;
	}

	/**
	 * The messages the next request sends, oldest first: the player's questions that weren't left unanswered, and the
	 * replies that finished, except those the summary covers. It always starts with the player, as providers require.
	 */
	static List<Chat.Message> history(Chat chat)
	{
		List<Chat.Message> history = new ArrayList<>();
		for (Chat.Message m : chat.messages)
		{
			if (stillSent(m))
			{
				history.add(m);
			}
		}
		while (!history.isEmpty() && history.get(0).role != Chat.Role.USER)
		{
			history.remove(0);
		}
		return history;
	}

	/**
	 * Whether a message goes with the next request (if the chat's start doesn't have to give way: see {@link #history}):
	 * a question that wasn't left unanswered, or a reply that finished, and not covered by the summary. Notes and errors
	 * are for the player only.
	 */
	static boolean stillSent(Chat.Message m)
	{
		boolean sent = m.role == Chat.Role.USER && !m.unanswered || m.role == Chat.Role.ASSISTANT && !m.unfinished;
		return sent && !m.summarized;
	}

	/** The character note the provider will have seen last before {@code message}, or null. */
	private static String latestNote(List<Chat.Message> history, Chat.Message message)
	{
		String seen = null;
		for (Chat.Message m : history)
		{
			if (m != message && m.context != null)
			{
				seen = m.context;
			}
		}
		return seen;
	}

	// ------------------------------------------------------------------
	// Sending replies back as they came (Claude)
	// ------------------------------------------------------------------

	/**
	 * Whether an earlier reply may go back exactly as it came, reasoning included (the provider also checks it was
	 * made with the same model, instructions and tools). Claude accepts that only when everything before it is unchanged: not
	 * once a newer summary is sent in place of older messages, and not with character notes left out.
	 */
	static boolean replayable(Chat chat, Chat.Message m, boolean notesLeftOut)
	{
		return !notesLeftOut && m.summaryVersion == chat.summaryVersion;
	}

	private static void replay(ChatApi.Turn t, Chat.Message m)
	{
		t.rawMessages = m.rawMessages;
		t.rawKey = m.rawKey;
	}

	/** Keeps on a new reply what's needed to send it back exactly as it came next time. */
	static void recordReply(Chat.Message answer, Chat.Message question, ChatApi.Reply reply)
	{
		answer.rawMessages = reply.rawMessages;
		answer.rawKey = reply.rawKey;
		answer.summaryVersion = question.summaryVersion;
	}

	/** A reply was built on the earlier ones as plain text: keep sending them that way, or it won't match. */
	static void forgetRaw(Chat chat)
	{
		for (Chat.Message m : chat.messages)
		{
			m.rawMessages = null;
			m.rawKey = null;
		}
	}

	// ------------------------------------------------------------------
	// Summaries
	// ------------------------------------------------------------------

	/** Put before the oldest message still sent. */
	static String summaryPrefix(String summary)
	{
		return "[Summary of earlier messages in this chat: " + summary + "]\n\n";
	}

	/**
	 * The oldest messages to summarise before the next request, or none. Once more than {@link #SUMMARY_HIGH} would be
	 * sent, it's all but the newest {@link #SUMMARY_LOW} or so: the cut is made before one of the player's messages,
	 * so what's still sent starts with the player.
	 */
	static List<Chat.Message> planSummary(Chat chat)
	{
		return planSummary(chat, false);
	}

	/**
	 * {@code tooLong}: the provider said the chat is too long for its model, however few messages it has (long replies
	 * and look-ups add up). Then everything before the player's newest message is summarised.
	 */
	static List<Chat.Message> planSummary(Chat chat, boolean tooLong)
	{
		List<Chat.Message> history = history(chat);
		if (!tooLong && history.size() <= SUMMARY_HIGH)
		{
			return Collections.emptyList();
		}
		int cut = history.size() - (tooLong ? 1 : SUMMARY_LOW);
		while (cut > 0 && history.get(cut).role != Chat.Role.USER)
		{
			cut--;
		}
		return new ArrayList<>(history.subList(0, Math.max(0, cut)));
	}

	/**
	 * The request that summarises {@code old}, with the chat's summary so far, if any: the same model, no tools. The
	 * messages go as text without character notes; the next message carries the latest note again if it's needed.
	 */
	static ChatApi.Conversation summaryConversation(Chat chat, List<Chat.Message> old, String model)
	{
		ChatApi.Conversation c = new ChatApi.Conversation();
		c.model = model;
		c.system = SUMMARY_PROMPT;
		c.maxTokens = SUMMARY_MAX_TOKENS;
		StringBuilder text = new StringBuilder();
		if (chat.summary != null)
		{
			text.append("The summary so far:\n\n").append(chat.summary).append("\n\nThe conversation since then, to add to it:");
		}
		else
		{
			text.append("The conversation to summarise:");
		}
		for (Chat.Message m : old)
		{
			text.append("\n\n").append(m.role == Chat.Role.USER ? "Player: " : "Assistant: ").append(m.text);
		}
		c.turns.add(new ChatApi.Turn(true, text.toString()));
		return c;
	}

	/**
	 * Sends {@code summary} instead of {@code old} from now on. A note says so and shows the summary, so nothing leaves
	 * the conversation unseen: just before {@code question}, the message it was made for, where the player sees it (the
	 * messages it replaces can be far up the transcript). Returns the note.
	 */
	static Chat.Message applySummary(Chat chat, List<Chat.Message> old, String summary, Chat.Message question)
	{
		chat.summary = summary.trim();
		chat.summaryVersion++;
		for (Chat.Message m : old)
		{
			m.summarized = true;
		}
		// The new summary covers the old one too, so it's sent instead of every message summarised so far, including
		// any that weren't kept when the chat was saved.
		int count = chat.leftOutSummarized;
		for (Chat.Message m : chat.messages)
		{
			count += m.summarized ? 1 : 0;
		}
		String text = (count == 1 ? "Summary of the earlier message, sent instead of it:"
			: "Summary of the " + count + " earlier messages, sent instead of them:") + "\n\n" + chat.summary;
		Chat.Message note = new Chat.Message(Chat.Role.NOTE, text);
		addBefore(chat, question, note);
		return note;
	}

	/** Adds {@code note} just before {@code message}, or at the end if that isn't in the chat (any more). */
	static void addBefore(Chat chat, Chat.Message message, Chat.Message note)
	{
		int at = message == null ? -1 : chat.messages.indexOf(message);
		chat.messages.add(at < 0 ? chat.messages.size() : at, note);
	}

	/** The note when there's no summary this time. {@code reason}: the provider's error, or why it was skipped. */
	static String summaryFailed(String reason)
	{
		String r = reason == null || reason.trim().isEmpty() ? "something went wrong" : ChatApi.shorten(reason, 200);
		if (r.endsWith(".") && !r.endsWith("..."))
		{
			r = r.substring(0, r.length() - 1);
		}
		return "Couldn't summarise the earlier messages (" + r + "), so the whole chat was sent this time.";
	}
}

package com.aichat;

import java.awt.BorderLayout;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.text.StyleConstants;

/**
 * What a chat with no messages yet shows, as chat apps do: a question in the middle, and a few ways to start. A starter
 * only fills the input box, never sends: sending costs the player money, so they always press Send themselves.
 */
final class EmptyChat extends JPanel
{
	/** A way to start: the words on its chip, and what it puts in the input box. */
	static final class Starter
	{
		final String label;
		/** Ends with a space where the player carries on typing, unless it's a whole question. */
		final String text;

		Starter(String label, String text)
		{
			this.label = label;
			this.text = text;
		}
	}

	static final List<Starter> STARTERS = Collections.unmodifiableList(Arrays.asList(
		new Starter("What should I train next?", "What should I train next?"),
		new Starter("Price check an item", "How much is "),
		new Starter("Plan my Slayer task", "Help me plan my Slayer task: "),
		new Starter("Help with a quest", "Help me with the quest ")));

	final List<FlatButton> chips = new ArrayList<>();

	/** {@code fill}: puts a starter's text in the input box. */
	EmptyChat(Consumer<String> fill)
	{
		super(new StackLayout(6));
		setOpaque(false);
		setBorder(new EmptyBorder(0, 8, 0, 8));
		MessageView title = new MessageView();
		title.setTextFont(PanelStyle.HEADING_FONT);
		title.setAlignment(StyleConstants.ALIGN_CENTER);
		title.setPlainText("What can I help with?");
		title.setBorder(new EmptyBorder(0, 0, 6, 0));
		add(title);
		for (Starter s : STARTERS)
		{
			FlatButton chip = new FlatButton(s.label, null, null)
				.filled(null, PanelStyle.OUTLINE_COLOR, false);
			chip.setFont(PanelStyle.TEXT_FONT);
			chip.setForeground(PanelStyle.TEXT_COLOR);
			chip.setBorder(new EmptyBorder(7, 10, 7, 10));
			chip.setHorizontalAlignment(SwingConstants.LEFT);
			chip.addActionListener(e -> fill.accept(s.text));
			JPanel row = new JPanel(new BorderLayout());
			row.setOpaque(false);
			row.add(chip, BorderLayout.CENTER);
			chips.add(chip);
			add(row);
		}
		MessageView tip = MessageRow.mutedLine(StyleConstants.ALIGN_CENTER);
		tip.setPlainText("You can also ask from the game's chatbox: type ::ai and your question.");
		tip.setBorder(new EmptyBorder(6, 0, 0, 0));
		tip.setVisible(true);
		add(tip);
	}
}

package com.aichat;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JToolTip;
import javax.swing.border.EmptyBorder;

/**
 * A small button that's just its icon and words until the mouse is over it, then a soft rounded patch behind them, as
 * in chat apps. It draws that itself, so it looks the same with any look and feel. Optionally filled, as a floating
 * circle. Its words and tooltip are always AI Chat's own.
 */
class FlatButton extends JButton
{
	private Color fill;
	private Color outline;
	private boolean round;

	FlatButton(String text, Icon icon, String tip)
	{
		super(text, icon);
		// Set before any text could be: buttons never render HTML here.
		putClientProperty("html.disable", Boolean.TRUE);
		setToolTipText(tip);
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setOpaque(false);
		setRolloverEnabled(true);
		setFont(PanelStyle.SMALL_FONT);
		setForeground(PanelStyle.MUTED_COLOR);
		setIconTextGap(3);
		setBorder(new EmptyBorder(3, 4, 3, 5));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	/** Always drawn on a filled background, a circle if {@code round}: for a button that floats over other things. */
	FlatButton filled(Color fill, Color outline, boolean round)
	{
		this.fill = fill;
		this.outline = outline;
		this.round = round;
		return this;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		boolean hot = isEnabled() && (getModel().isRollover() || getModel().isPressed());
		Color back = hot ? PanelStyle.BUBBLE_COLOR : fill;
		if (back != null || outline != null)
		{
			Graphics2D g2 = PanelStyle.smooth(g);
			Shape shape = round
				? new Ellipse2D.Float(0.5f, 0.5f, getWidth() - 1f, getHeight() - 1f)
				: new RoundRectangle2D.Float(0.5f, 0.5f, getWidth() - 1f, getHeight() - 1f, 8, 8);
			if (back != null)
			{
				g2.setColor(back);
				g2.fill(shape);
			}
			if (outline != null)
			{
				g2.setColor(outline);
				g2.draw(shape);
			}
			g2.dispose();
		}
		super.paintComponent(g);
	}

	@Override
	public JToolTip createToolTip()
	{
		JToolTip tip = super.createToolTip();
		tip.putClientProperty("html.disable", Boolean.TRUE);
		return tip;
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;

/**
 * Replies as game chat: the start of each one, in the chat font, as a heads-up while playing. The side panel has the
 * whole reply, so this keeps to plain sentences and drops what only makes sense there (Markdown, long links).
 */
final class GameChatEcho
{
	/** Game chat messages per reply (the game wraps each one), not counting the note that it was cut. */
	static final int MAX_MESSAGES = 8;
	/** Longer words (links) are shortened in game chat: the game wraps only at spaces and hyphens. */
	static final int MAX_WORD = 60;
	/** A paragraph isn't started with less than this much of the length setting left: it'd be a stub. */
	private static final int MIN_PART = 20;

	/** "- item", "* item", "+ item", bullet, "1. item", "2) item". */
	private static final Pattern LIST_ITEM = Pattern.compile("([-*+\u2022]|\\d{1,3}[.)])\\s+(.+)");
	/** Markdown that's only layout (rules, table borders, leftover markers): left out of game chat. */
	private static final Pattern LAYOUT_ONLY = Pattern.compile("[-*_=#|`~:+ ]+");
	/** A Markdown table's line: "| a | b |". */
	private static final Pattern TABLE_LINE = Pattern.compile("\\s*\\|.*\\|\\s*");
	/** The line under a table's header: "|---|:--:|". */
	private static final Pattern TABLE_RULE = Pattern.compile("\\s*\\|?(\\s*:?-+:?\\s*\\|)+\\s*:?-*:?\\s*");
	/** A cell border: a pipe that isn't escaped. */
	private static final Pattern CELL_BORDER = Pattern.compile("(?<!\\\\)\\|");
	/** The first and last line of a code block. */
	private static final Pattern FENCE = Pattern.compile("(```|~~~).*");
	/** Block quote markers, nested ones too: "> ", ">> ", "> > ". */
	private static final Pattern QUOTE = Pattern.compile("^(?:> ?)+");
	/** [text](url) and ![picture](url). Wiki addresses can have brackets in them, like Coins_(item). */
	private static final Pattern LINK = Pattern.compile("!?\\[([^\\[\\]]*)]\\(((?:[^()\\s]|\\([^()\\s]*\\))*)\\)");
	/** <https://...>: the game would show the angle brackets. */
	private static final Pattern BRACKETED_URL = Pattern.compile("<(https?://[^<>\\s]+)>");
	/**
	 * __bold__, _italic_ and *italic*. Never inside a word, where underscores are part of names and Wiki addresses
	 * (Abyssal_whip), and never around spaces, where a star is more likely a sum (2 * 3 * 4).
	 */
	private static final Pattern UNDERSCORE_BOLD = Pattern.compile("(?<![\\p{L}\\p{N}_])__([^_\\s](?:[^_]*[^_\\s])?)__(?![\\p{L}\\p{N}_])");
	private static final Pattern UNDERSCORE_ITALIC = Pattern.compile("(?<![\\p{L}\\p{N}_])_([^_\\s](?:[^_]*[^_\\s])?)_(?![\\p{L}\\p{N}_])");
	private static final Pattern STAR_ITALIC = Pattern.compile("(?<![\\p{L}\\p{N}*])\\*([^*\\s](?:[^*]*[^*\\s])?)\\*(?![\\p{L}\\p{N}*])");
	/** A backslash before ASCII punctuation: Markdown for that character as it is (\* is a star, not italics). */
	private static final Pattern ESCAPED = Pattern.compile("\\\\([!-/:-@\\[-`{-~])");
	/**
	 * Escaped characters wait as private-use stand-ins (this plus the character) while the Markdown around them is
	 * taken out, so no pattern takes them for markers.
	 */
	private static final char STAND_IN = '\uE000';

	private GameChatEcho()
	{
	}

	/**
	 * A reply as game chat: one message per paragraph or list item, which the game wraps to the chatbox's width.
	 * Each starts with a marker drawn in the highlight colour (who it's from, or the list marker), so only the game's
	 * own wrapped rows go unmarked. The model's text is escaped and never in the highlight colour: it can't draw a
	 * marker, or pass for one of the game's red warnings.
	 */
	static List<String> echoMessages(String label, String chatName, String text, int maxChars)
	{
		List<String> messages = new ArrayList<>();
		int left = maxChars;
		boolean cut = false;
		String[] lines = text.split("\\r\\n|[\\n\\r\u2028\u2029]");
		boolean[] header = new boolean[lines.length];
		boolean[] row = new boolean[lines.length];
		tables(lines, header, row);
		for (int i = 0; i < lines.length; i++)
		{
			if (header[i])
			{
				// A table's column names: its rows say what they are well enough in a chatbox.
				continue;
			}
			String line = chatText(row[i] ? tableRow(lines[i]) : lines[i]);
			if (line.isEmpty() || LAYOUT_ONLY.matcher(line).matches())
			{
				continue;
			}
			if (messages.size() == MAX_MESSAGES || left <= 0)
			{
				cut = true;
				break;
			}
			String marker = null;
			Matcher item = LIST_ITEM.matcher(line);
			if (item.matches())
			{
				marker = Character.isDigit(line.charAt(0)) ? item.group(1) : "-";
				line = item.group(2);
			}
			if (line.length() > left && left < MIN_PART && !messages.isEmpty())
			{
				cut = true;
				break;
			}
			if (line.length() > left)
			{
				line = cutAtSpace(line, left) + " ...";
				cut = true;
			}
			left -= line.length();
			String lead;
			if (messages.isEmpty())
			{
				lead = label + (chatName == null ? "" : " (" + ChatApi.shorten(chatName, 30) + ")") + ":"
					+ (marker == null ? "" : " " + marker);
			}
			else
			{
				lead = marker != null ? marker : label + ":";
			}
			messages.add(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append(lead + " ")
				.append(ChatColorType.NORMAL).append(line)
				.build());
			if (cut)
			{
				break;
			}
		}
		if (messages.isEmpty())
		{
			messages.add(highlighted(label + ": (empty reply)"));
		}
		if (cut)
		{
			messages.add(highlighted("AI Chat: the full reply is in the side panel."));
		}
		return messages;
	}

	/**
	 * A line of a reply for the chat font: plain punctuation, no Markdown (the panel shows that), no overlong words.
	 * Links keep only their text: the game can't open them, and the panel has them.
	 */
	static String chatText(String raw)
	{
		String s = escape(raw)
			.replace('\u2018', '\'').replace('\u2019', '\'')
			.replace('\u201C', '"').replace('\u201D', '"')
			.replace('\u2013', '-').replace('\u2014', '-')
			.replace("\u2026", "...").replace("**", "")
			.replaceAll("[\\s\\p{Z}\\p{Cc}]+", " ").trim();
		if (FENCE.matcher(s).matches())
		{
			return "";
		}
		s = QUOTE.matcher(s).replaceFirst("").replaceFirst("^#{1,6} ", "");
		s = links(s);
		s = BRACKETED_URL.matcher(s).replaceAll("$1").replace("`", "");
		s = UNDERSCORE_BOLD.matcher(s).replaceAll("$1");
		s = UNDERSCORE_ITALIC.matcher(s).replaceAll("$1");
		s = STAR_ITALIC.matcher(s).replaceAll("$1");
		StringBuilder out = new StringBuilder();
		for (String word : s.trim().split(" "))
		{
			out.append(out.length() == 0 ? "" : " ")
				.append(word.length() <= MAX_WORD ? word : word.substring(0, MAX_WORD - 3) + "...");
		}
		return unescape(out.toString());
	}

	/**
	 * Marks the Markdown tables in {@code lines}: a header line followed by its rule line, then the rows under it. A line
	 * with pipes that isn't in such a table is left as it is.
	 */
	private static void tables(String[] lines, boolean[] header, boolean[] row)
	{
		for (int i = 0; i + 1 < lines.length; i++)
		{
			if (!TABLE_LINE.matcher(lines[i]).matches() || !TABLE_RULE.matcher(lines[i + 1]).matches())
			{
				continue;
			}
			header[i] = true;
			for (int j = i + 2; j < lines.length && TABLE_LINE.matcher(lines[j]).matches()
				&& !TABLE_RULE.matcher(lines[j]).matches(); j++)
			{
				row[j] = true;
			}
		}
	}

	/**
	 * A table row as a list item for the chatbox: "- Extended antifire: Dragonfire" for two columns, the cells joined
	 * by " - " for more.
	 */
	static String tableRow(String line)
	{
		String t = line.trim();
		t = t.substring(1, t.length() - (t.endsWith("\\|") ? 0 : 1));
		List<String> cells = new ArrayList<>();
		for (String cell : CELL_BORDER.split(t, -1))
		{
			if (!cell.trim().isEmpty())
			{
				cells.add(cell.trim());
			}
		}
		if (cells.isEmpty())
		{
			return "";
		}
		return "- " + (cells.size() == 2 ? cells.get(0) + ": " + cells.get(1) : String.join(" - ", cells));
	}

	/** Escaped punctuation as stand-ins, without its backslashes. */
	private static String escape(String s)
	{
		Matcher m = ESCAPED.matcher(s);
		StringBuffer out = new StringBuffer();
		while (m.find())
		{
			m.appendReplacement(out, String.valueOf((char) (STAND_IN + m.group(1).charAt(0))));
		}
		m.appendTail(out);
		return out.toString();
	}

	/** The escaped characters back in place of their stand-ins. */
	private static String unescape(String s)
	{
		StringBuilder out = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			out.append(c >= STAND_IN && c < STAND_IN + 128 ? (char) (c - STAND_IN) : c);
		}
		return out.toString();
	}

	/** [text](url) as its text, or as the address when there's no text. */
	private static String links(String s)
	{
		Matcher m = LINK.matcher(s);
		StringBuffer out = new StringBuffer();
		while (m.find())
		{
			String text = m.group(1).trim();
			m.appendReplacement(out, Matcher.quoteReplacement(text.isEmpty() ? m.group(2) : text));
		}
		m.appendTail(out);
		return out.toString();
	}

	/** {@code s} cut to at most {@code max} characters, at a space if there's one in the second half. */
	static String cutAtSpace(String s, int max)
	{
		int space = s.lastIndexOf(' ', max);
		return (space > max / 2 ? s.substring(0, space) : s.substring(0, max)).trim();
	}

	/** A message all in the highlight colour, for AI Chat's own notes. */
	static String highlighted(String text)
	{
		return new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(text).build();
	}
}

