import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/**
 * The player's own account, for the game-data tools: what they wear and carry, their bank as last seen, their Slayer
 * task and their achievement diaries. Only ever their own: nothing about where they are, what's around them, or other
 * players. Reading happens on the client thread, where the game's data lives, and gives plain values; writing those
 * up for the model is separate (static, any thread), so it can be tested without a game.
 */
final class GameData implements GameDataTools.Game
{
	static final int INVENTORY_SLOTS = 28;
	/** Bank items listed per call: a big bank would otherwise be tens of thousands of tokens. */
	static final int BANK_LINES = 300;
	/** A boss task names its boss in a second table. From SlayerPlugin ([proc,helper_slayer_current_assignment]). */
	private static final int BOSS_TASK = 98;

	/**
	 * Each region's diary tiers, easy to elite: the "complete" varbit and the value it has once that tier is done. The
	 * game's own check ([proc,area_task_complete]) wants 1 everywhere except Karamja's first three tiers, which are 2
	 * when done (1 there means started).
	 */
	private static final Region[] REGIONS = {
		new Region("Ardougne", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE),
		new Region("Desert", VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE),
		new Region("Falador", VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE),
		new Region("Fremennik", VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE),
		new Region("Kandarin", VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE),
		new Region("Karamja", new int[]{VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE,
			VarbitID.KARAMJA_DIARY_ELITE_COMPLETE}, new int[]{2, 2, 2, 1}),
		new Region("Kourend & Kebos", VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE),
		new Region("Lumbridge & Draynor", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE),
		new Region("Morytania", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE),
		new Region("Varrock", VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE),
		new Region("Western Provinces", VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE),
		new Region("Wilderness", VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE),
	};
	private static final String[] TIERS = {"Easy", "Medium", "Hard", "Elite"};

	private final Client client;
	private final ItemManager itemManager;
	/** The bank as last seen, or null before that. Written on the client thread, read anywhere. */
	private volatile BankSnapshot bank;

	/** Keep one for as long as RuneLite runs: the bank seen so far would be forgotten with it. */
	GameData(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	// ------------------------------------------------------------------
	// Plain values: what the reading below gives, and what the writing up takes
	// ------------------------------------------------------------------

	/** One kind of item: a name, how many, and the GE price of one. */
	static final class ItemLine
	{
		/** The equipment slot ("Weapon"), or null for items that aren't worn. */
		final String slot;
		final String name;
		final boolean noted;
		/** One stack, or every stack of the item added up. */
		final long quantity;
		/** RuneLite's GE price for one, or 0 when it has none (untradeable, or the prices haven't loaded yet). */
		final long price;

		ItemLine(String slot, String name, boolean noted, long quantity, long price)
		{
			this.slot = slot;
			this.name = name;
			this.noted = noted;
			this.quantity = quantity;
			this.price = price;
		}
	}

	static final class Items
	{
		final List<ItemLine> lines;
		/** Slots with something in them. */
		final int slotsUsed;

		Items(List<ItemLine> lines, int slotsUsed)
		{
			this.lines = lines;
			this.slotsUsed = slotsUsed;
		}
	}

	static final class Bank
	{
		/** In the bank's own order, placeholders left out. */
		final List<ItemLine> lines;
		/** When it was seen, in {@link System#currentTimeMillis()} time. */
		final long seenAt;

		Bank(List<ItemLine> lines, long seenAt)
		{
			this.lines = lines;
			this.seenAt = seenAt;
		}
	}

	static final class SlayerTask
	{
		/** The monster ("Abyssal demons"), or null when there's no task or it can't be read. */
		final String name;
		/** How many are left; 0 means no task. */
		final int remaining;
		/** How many the task was for, or 0 when that isn't known. */
		final int assigned;
		/** Where the task has to be done (Konar's tasks), or null. */
		final String area;
		final int points;
		final int streak;

		SlayerTask(String name, int remaining, int assigned, String area, int points, int streak)
		{
			this.name = name;
			this.remaining = remaining;
			this.assigned = assigned;
			this.area = area;
			this.points = points;
			this.streak = streak;
		}
	}

	static final class Diary
	{
		final String region;
		/** Easy, medium, hard, elite. */
		final boolean[] done;

		Diary(String region, boolean[] done)
		{
			this.region = region;
			this.done = done;
		}
	}

	/** The bank's items as ids and amounts: cheap to take on the client thread every time the bank changes. */
	static final class BankSnapshot
	{
		final int[] ids;
		final int[] quantities;
		/** Whose bank it is: a bank seen earlier in the session may be another account's. */
		final long accountHash;
		final long seenAt;

		private BankSnapshot(int[] ids, int[] quantities, long accountHash, long seenAt)
		{
			this.ids = ids;
			this.quantities = quantities;
			this.accountHash = accountHash;
			this.seenAt = seenAt;
		}

		/**
		 * Placeholders (none of the item left) and bank fillers left out. Item objects are immutable, but the array
		 * isn't ours to keep.
		 */
		static BankSnapshot of(Item[] items, long accountHash, long seenAt)
		{
			int[] ids = new int[items.length];
			int[] quantities = new int[items.length];
			int n = 0;
			for (Item item : items)
			{
				if (item != null && item.getId() > 0 && item.getQuantity() > 0 && item.getId() != ItemID.BANK_FILLER)
				{
					ids[n] = item.getId();
					quantities[n] = item.getQuantity();
					n++;
				}
			}
			int[] keptIds = new int[n];
			int[] keptQuantities = new int[n];
			System.arraycopy(ids, 0, keptIds, 0, n);
			System.arraycopy(quantities, 0, keptQuantities, 0, n);
			return new BankSnapshot(keptIds, keptQuantities, accountHash, seenAt);
		}
	}

	private static final class Region
	{
		final String name;
		final int[] varbits;
		final int[] doneAt;

		Region(String name, int easy, int medium, int hard, int elite)
		{
			this(name, new int[]{easy, medium, hard, elite}, new int[]{1, 1, 1, 1});
		}

		Region(String name, int[] varbits, int[] doneAt)
		{
			this.name = name;
			this.varbits = varbits;
			this.doneAt = doneAt;
		}
	}

	// ------------------------------------------------------------------
	// Reading (client thread)
	// ------------------------------------------------------------------

	/**
	 * Client thread: the plugin's ItemContainerChanged subscriber passes every change on. The bank can only be read
	 * while it's open, so its contents are kept each time it changes; ids and amounts only, to keep this cheap (names
	 * and prices are looked up when the model asks).
	 */
	void itemContainerChanged(ItemContainerChanged e)
	{
		ItemContainer container = e.getItemContainer();
		if (e.getContainerId() == InventoryID.BANK && container != null)
		{
			bank = BankSnapshot.of(container.getItems(), client.getAccountHash(), System.currentTimeMillis());
		}
	}

	/** "Share items and gear" (or AI requests) turned off: the bank as last seen isn't kept where it can't be shared. */
	void forgetBank()
	{
		bank = null;
	}

	@Override
	public boolean loggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	@Override
	public List<ItemLine> equipment()
	{
		List<ItemLine> lines = new ArrayList<>();
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return lines;
		}
		for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
		{
			Item item = worn.getItem(slot.getSlotIdx());
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				lines.add(line(slotName(slot), item.getId(), item.getQuantity()));
			}
		}
		return lines;
	}

	@Override
	public Items inventory()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		Item[] items = inv == null ? new Item[0] : inv.getItems();
		List<ItemLine> lines = new ArrayList<>();
		for (Map.Entry<Integer, Long> stack : stacks(items).entrySet())
		{
			lines.add(line(null, stack.getKey(), stack.getValue()));
		}
		return new Items(lines, slotsUsed(items));
	}

	@Override
	public Bank bank()
	{
		BankSnapshot seen = bank;
		// A bank seen earlier on another account isn't this player's.
		if (seen == null || seen.accountHash != client.getAccountHash())
		{
			return null;
		}
		List<ItemLine> lines = new ArrayList<>();
		for (int i = 0; i < seen.ids.length; i++)
		{
			ItemComposition item = itemManager.getItemComposition(seen.ids[i]);
			if (item.getPlaceholderTemplateId() == -1)
			{
				lines.add(line(null, seen.ids[i], item, seen.quantities[i]));
			}
		}
		return new Bank(lines, seen.seenAt);
	}

	/** The same reads as the core Slayer plugin: the task is in varps, its name in the game's database tables. */
	@Override
	public SlayerTask slayerTask()
	{
		int points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		// Krystilia's and Mortimer's tasks keep their own streaks; this is the one every other master counts.
		int streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (remaining <= 0)
		{
			return new SlayerTask(null, 0, 0, null, points, streak);
		}

		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		Integer taskRow = null;
		if (taskId == BOSS_TASK)
		{
			List<Integer> bossRows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (!bossRows.isEmpty())
			{
				taskRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
			}
		}
		else
		{
			List<Integer> taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (!taskRows.isEmpty())
			{
				taskRow = taskRows.get(0);
			}
		}
		String name = taskRow == null ? null
			: capitalised((String) client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0]);

		String area = null;
		int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		if (areaId > 0)
		{
			List<Integer> areaRows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
			if (!areaRows.isEmpty())
			{
				area = (String) client.getDBTableField(areaRows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
			}
		}

		int assigned = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		// A task extended (or shortened) after it was given.
		if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == 2)
		{
			int change = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
			assigned += client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1 ? -change : change;
		}
		return new SlayerTask(name, remaining, assigned, area, points, streak);
	}

	@Override
	public List<Diary> diaries()
	{
		return diaries(client::getVarbitValue);
	}

	/** Client thread. */
	private ItemLine line(String slot, int id, long quantity)
	{
		return line(slot, id, itemManager.getItemComposition(id), quantity);
	}

	/** Client thread. getItemPrice follows RuneLite's "Use actively traded price" and prices notes as the item. */
	private ItemLine line(String slot, int id, ItemComposition item, long quantity)
	{
		// The members name: on a free world, getName adds " (Members)" to members' items.
		return new ItemLine(slot, item.getMembersName(), item.getNote() != -1, quantity, itemManager.getItemPrice(id));
	}

	// ------------------------------------------------------------------
	// Plain-data steps of the reading, kept apart so they can be tested
	// ------------------------------------------------------------------

	/** Each item's id with all its stacks added up, in the order they first appear; empty slots left out. */
	static Map<Integer, Long> stacks(Item[] items)
	{
		Map<Integer, Long> stacks = new LinkedHashMap<>();
		for (Item item : items)
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				stacks.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		return stacks;
	}

	static int slotsUsed(Item[] items)
	{
		int used = 0;
		for (Item item : items)
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				used++;
			}
		}
		return used;
	}

	/** Every region's diary, from a varbit reader. */
	static List<Diary> diaries(IntUnaryOperator varbit)
	{
		List<Diary> diaries = new ArrayList<>();
		for (Region r : REGIONS)
		{
			boolean[] done = new boolean[r.varbits.length];
			for (int i = 0; i < done.length; i++)
			{
				done[i] = varbit.applyAsInt(r.varbits[i]) == r.doneAt[i];
			}
			diaries.add(new Diary(r.name, done));
		}
		return diaries;
	}

	/** "Weapon" for WEAPON. */
	static String slotName(EquipmentInventorySlot slot)
	{
		return capitalised(slot.name().toLowerCase(Locale.ROOT));
	}

	private static String capitalised(String s)
	{
		return s == null || s.isEmpty() ? s : s.substring(0, 1).toUpperCase(Locale.ROOT) + s.substring(1);
	}

	// ------------------------------------------------------------------
	// Writing up for the model (any thread)
	// ------------------------------------------------------------------

	static String equipmentText(List<ItemLine> worn)
	{
		if (worn.isEmpty())
		{
			return "The player isn't wearing or wielding anything.";
		}
		StringBuilder out = new StringBuilder("The player's worn equipment, with Grand Exchange prices from RuneLite:");
		appendItems(out, worn, worn.size());
		appendTotal(out, worn, "Total value");
		return out.toString();
	}

	static String inventoryText(Items inventory)
	{
		if (inventory.lines.isEmpty())
		{
			return "The player's inventory is empty (all " + INVENTORY_SLOTS + " slots free).";
		}
		StringBuilder out = new StringBuilder("The player's inventory (")
			.append(inventory.slotsUsed).append(" of ").append(INVENTORY_SLOTS)
			.append(" slots used), with Grand Exchange prices from RuneLite:");
		appendItems(out, inventory.lines, inventory.lines.size());
		appendTotal(out, inventory.lines, "Total value");
		return out.toString();
	}

	/**
	 * The bank as last seen, or just the items whose names contain {@code search} (ignoring case) when it isn't null.
	 * Long lists are cut at {@link #BANK_LINES}, with a note; the total counts everything that matched.
	 */
	static String bankText(Bank bank, String search, long now)
	{
		String seen = "as last seen " + ago(now - bank.seenAt);
		if (search == null)
		{
			if (bank.lines.isEmpty())
			{
				return "The player's bank was empty (" + seen + ").";
			}
			StringBuilder out = new StringBuilder("The player's bank (").append(seen).append("): ")
				.append(count(bank.lines.size(), "item")).append(", placeholders left out. Grand Exchange prices from RuneLite:");
			appendItems(out, bank.lines, BANK_LINES);
			appendTotal(out, bank.lines, "Total value of the bank");
			return out.toString();
		}

		String wanted = search.toLowerCase(Locale.ROOT);
		List<ItemLine> matching = new ArrayList<>();
		for (ItemLine line : bank.lines)
		{
			if (line.name != null && line.name.toLowerCase(Locale.ROOT).contains(wanted))
			{
				matching.add(line);
			}
		}
		if (matching.isEmpty())
		{
			return "Nothing in the player's bank has \"" + search + "\" in its name (" + seen + "; "
				+ count(bank.lines.size(), "item") + " in all). Try a shorter or different search.";
		}
		StringBuilder out = new StringBuilder("Items in the player's bank with \"").append(search).append("\" in their name (")
			.append(seen).append("), with Grand Exchange prices from RuneLite:");
		appendItems(out, matching, BANK_LINES);
		appendTotal(out, matching, "Total value of these");
		return out.toString();
	}

	static String slayerText(SlayerTask task)
	{
		StringBuilder out = new StringBuilder();
		if (task.remaining <= 0)
		{
			out.append("The player has no Slayer task right now.");
		}
		else if (task.name == null)
		{
			out.append("The player has a Slayer task with ").append(number(task.remaining))
				.append(" left, but which monster it is couldn't be read.");
		}
		else
		{
			out.append("The player's Slayer task: ").append(task.name).append(", ").append(number(task.remaining)).append(" left");
			if (task.assigned > 0)
			{
				out.append(" of ").append(number(task.assigned));
			}
			if (task.area != null)
			{
				out.append(", to be done in ").append(task.area);
			}
			out.append('.');
		}
		out.append(" Slayer points: ").append(number(task.points))
			.append(". Task streak: ").append(number(task.streak))
			.append(" (Krystilia's and Mortimer's tasks have their own streaks, not counted here).");
		return out.toString();
	}

	static String diaryText(List<Diary> diaries)
	{
		StringBuilder out = new StringBuilder("The player's achievement diaries, by tier:");
		int done = 0;
		int tiers = 0;
		for (Diary d : diaries)
		{
			List<String> finished = new ArrayList<>();
			List<String> unfinished = new ArrayList<>();
			for (int i = 0; i < d.done.length; i++)
			{
				(d.done[i] ? finished : unfinished).add(TIERS[i]);
			}
			done += finished.size();
			tiers += d.done.length;
			out.append("\n- ").append(d.region).append(": ");
			if (unfinished.isEmpty())
			{
				out.append("all done");
			}
			else if (finished.isEmpty())
			{
				out.append("none done");
			}
			else
			{
				out.append(String.join(", ", finished)).append(" done; ")
					.append(String.join(", ", unfinished)).append(" not done");
			}
		}
		out.append("\nCompleted ").append(done).append(" of ").append(tiers).append(" tiers.");
		return out.toString();
	}

	/**
	 * "Weapon: Abyssal whip (1,402,330 gp)", "Shark x10 (1,032 gp each, 10,320 gp total)", "Coins x5,000 (5,000 gp)".
	 * No price for untradeable items.
	 */
	static String itemText(ItemLine line)
	{
		StringBuilder s = new StringBuilder();
		if (line.slot != null)
		{
			s.append(line.slot).append(": ");
		}
		s.append(line.name);
		if (line.noted)
		{
			s.append(" (noted)");
		}
		if (line.quantity != 1)
		{
			s.append(" x").append(number(line.quantity));
		}
		if (line.price > 0)
		{
			long total = line.price * line.quantity;
			// Coins are worth 1 each: "1 gp each" would add nothing.
			if (line.quantity == 1 || line.price == 1)
			{
				s.append(" (").append(gp(total)).append(')');
			}
			else
			{
				s.append(" (").append(gp(line.price)).append(" each, ").append(gp(total)).append(" total)");
			}
		}
		return s.toString();
	}

	/** "less than a minute ago", "5 minutes ago", "about 2 hours ago". */
	static String ago(long millis)
	{
		long minutes = Math.max(0, millis) / 60_000;
		if (minutes < 1)
		{
			return "less than a minute ago";
		}
		if (minutes < 60)
		{
			return count(minutes, "minute") + " ago";
		}
		return "about " + count(minutes / 60, "hour") + " ago";
	}

	private static void appendItems(StringBuilder out, List<ItemLine> lines, int max)
	{
		for (int i = 0; i < lines.size() && i < max; i++)
		{
			out.append("\n- ").append(itemText(lines.get(i)));
		}
		if (lines.size() > max)
		{
			out.append("\n...and ").append(count(lines.size() - max, "more item"))
				.append(" not listed. Ask again with search to find particular items.");
		}
	}

	private static void appendTotal(StringBuilder out, List<ItemLine> lines, String label)
	{
		long total = 0;
		boolean unpriced = false;
		for (ItemLine line : lines)
		{
			total += line.price * line.quantity;
			unpriced |= line.price <= 0;
		}
		if (total > 0)
		{
			out.append('\n').append(label).append(" at Grand Exchange prices: ").append(gp(total))
				.append(unpriced ? " (items without a price not counted)." : ".");
		}
	}

	/** "1 item", "300 items". */
	private static String count(long n, String thing)
	{
		return number(n) + " " + thing + (n == 1 ? "" : "s");
	}

	private static String gp(long amount)
	{
		return number(amount) + " gp";
	}

	private static String number(long n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}
}

package com.aichat;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * The tools that read the player's own account, offered only with the settings that share it: equipment, inventory
 * and bank with "Share items and gear", Slayer task and achievement diaries with "Share character details". Made for one
 * reply: every call reads the game on the client thread, writes the answer up off it, and ends with one line for the
 * panel saying what was shared ("Shared your equipment"), told to {@code activity} just before the result goes back.
 */
@Slf4j
final class GameDataTools implements ChatApi.ToolRunner
{
	static final String GET_EQUIPMENT = "get_equipment";
	static final String GET_INVENTORY = "get_inventory";
	static final String GET_BANK = "get_bank";
	static final String GET_SLAYER_TASK = "get_slayer_task";
	static final String GET_ACHIEVEMENT_DIARIES = "get_achievement_diaries";

	/** The client thread runs queued work every frame, also on the login screen; this is in case it can't. */
	static final long READ_TIMEOUT_MILLIS = 5000;
	private static final int MAX_SEARCH = 100;
	private static final String FAILED = "Reading the game failed inside AI Chat. Answer without it.";
	private static final String ITEMS_SETTING = "Share items and gear";
	/**
	 * How the lines for what was shared start: the panel names what was shared, from these, on the line over each reply
	 * (see {@link PanelText#summary}).
	 */
	static final String SHARED = "Shared your ";
	static final String SEARCHED = "Searched your bank for ";
	/** Ends the line for what was read but never sent: the request had stopped (see {@link #unshared}). */
	static final String UNSHARED = ", but didn't share it: the request had stopped";
	/** Starts the line for what was read but never sent, in place of {@link #SHARED}. */
	static final String READ = "Read your ";
	private static final String CHARACTER_SETTING = "Share character details";

	/**
	 * Where the answers come from: {@link GameData} in the game, canned data in tests. Client thread only, and only
	 * while the player is logged in.
	 */
	interface Game
	{
		boolean loggedIn();

		List<GameData.ItemLine> equipment();

		GameData.Items inventory();

		/**
		 * Null when the bank hasn't been seen on this account since it could be: since AI Chat, "Share items and gear" or
		 * AI requests was last turned on.
		 */
		GameData.Bank bank();

		GameData.SlayerTask slayerTask();

		List<GameData.Diary> diaries();
	}

	private final Game game;
	/** Runs work on the client thread: ClientThread.invoke in the game. */
	private final Consumer<Runnable> clientThread;
	private final ScheduledExecutorService executor;
	private final BooleanSupplier shareItems;
	private final BooleanSupplier shareCharacter;
	private final Consumer<String> activity;
	private final long timeoutMillis;

	/**
	 * {@code shareItems} and {@code shareCharacter}: the settings, read again for every call, so turning one off while
	 * a reply is being written stops the sharing at once.
	 */
	GameDataTools(Game game, Consumer<Runnable> clientThread, ScheduledExecutorService executor,
		BooleanSupplier shareItems, BooleanSupplier shareCharacter, Consumer<String> activity)
	{
		this(game, clientThread, executor, shareItems, shareCharacter, activity, READ_TIMEOUT_MILLIS);
	}

	GameDataTools(Game game, Consumer<Runnable> clientThread, ScheduledExecutorService executor,
		BooleanSupplier shareItems, BooleanSupplier shareCharacter, Consumer<String> activity, long timeoutMillis)
	{
		this.game = game;
		this.clientThread = clientThread;
		this.executor = executor;
		this.shareItems = shareItems;
		this.shareCharacter = shareCharacter;
		this.activity = activity;
		this.timeoutMillis = timeoutMillis;
	}

	static boolean handles(String name)
	{
		return GET_EQUIPMENT.equals(name) || GET_INVENTORY.equals(name) || GET_BANK.equals(name)
			|| GET_SLAYER_TASK.equals(name) || GET_ACHIEVEMENT_DIARIES.equals(name);
	}

	/**
	 * The tools the settings allow right now, always in the same order and with the same text: they're part of the
	 * prompt the provider caches.
	 */
	List<ChatApi.ToolSpec> specs()
	{
		List<ChatApi.ToolSpec> specs = new ArrayList<>();
		if (shareItems.getAsBoolean())
		{
			specs.add(new ChatApi.ToolSpec(GET_EQUIPMENT,
				"The player's worn equipment right now: the item in each slot, with Grand Exchange prices.",
				schema(new JsonObject())));
			specs.add(new ChatApi.ToolSpec(GET_INVENTORY,
				"The player's inventory right now: items and amounts with Grand Exchange prices, and how many of the "
					+ GameData.INVENTORY_SLOTS + " slots are used.",
				schema(new JsonObject())));
			JsonObject bank = new JsonObject();
			bank.add("search", property("string", "Optional: only items whose names contain this, e.g. \"rune\" or "
				+ "\"potion\". Leave it out for the whole bank; a big bank is cut at " + GameData.BANK_LINES + " items."));
			specs.add(new ChatApi.ToolSpec(GET_BANK,
				"The player's bank as it was the last time they had it open: items and amounts with Grand Exchange "
					+ "prices, placeholders left out. Unknown until they open their bank.",
				schema(bank)));
		}
		if (shareCharacter.getAsBoolean())
		{
			specs.add(new ChatApi.ToolSpec(GET_SLAYER_TASK,
				"The player's current Slayer task: the monster, how many are left of how many, the area it must be "
					+ "done in if any, and their Slayer points and task streak.",
				schema(new JsonObject())));
			specs.add(new ChatApi.ToolSpec(GET_ACHIEVEMENT_DIARIES,
				"Which achievement diary tiers (easy, medium, hard, elite) the player has completed in each region.",
				schema(new JsonObject())));
		}
		return specs;
	}

	private static JsonObject property(String type, String description)
	{
		JsonObject p = new JsonObject();
		p.addProperty("type", type);
		p.addProperty("description", description);
		return p;
	}

	private static JsonObject schema(JsonObject properties)
	{
		JsonObject s = new JsonObject();
		s.addProperty("type", "object");
		s.add("properties", properties);
		return s;
	}

	@Override
	public void run(String name, JsonObject input, Consumer<ChatApi.ToolResult> done)
	{
		Report report = new Report(done);
		try
		{
			if (GET_EQUIPMENT.equals(name))
			{
				readItems(report, "equipment", game::equipment, worn -> shared("equipment", GameData.equipmentText(worn)));
			}
			else if (GET_INVENTORY.equals(name))
			{
				readItems(report, "inventory", game::inventory, inv -> shared("inventory", GameData.inventoryText(inv)));
			}
			else if (GET_BANK.equals(name))
			{
				String search = search(input);
				long now = System.currentTimeMillis();
				readItems(report, "bank", game::bank, bank -> bankOutcome(bank, search, now));
			}
			else if (GET_SLAYER_TASK.equals(name))
			{
				readCharacter(report, "Slayer task", game::slayerTask, task -> shared("Slayer task", GameData.slayerText(task)));
			}
			else if (GET_ACHIEVEMENT_DIARIES.equals(name))
			{
				readCharacter(report, "achievement diaries", game::diaries,
					diaries -> shared("achievement diaries", GameData.diaryText(diaries)));
			}
			else
			{
				report.send(new Outcome("Skipped an unknown look-up \"" + ChatApi.shorten(name, 60) + "\"",
					ChatApi.ToolResult.error("There's no tool called " + name + ".")));
			}
		}
		catch (RuntimeException e)
		{
			// A bug, not the player's or the model's doing; the reply can still carry on without this.
			log.warn("game data tool {} failed", name, e);
			report.send(new Outcome("Couldn't read the game (" + name + ")", ChatApi.ToolResult.error(FAILED)));
		}
	}

	/** A call's ending: its line for the panel and its result for the model. */
	private static final class Outcome
	{
		final String line;
		final ChatApi.ToolResult result;

		Outcome(String line, ChatApi.ToolResult result)
		{
			this.line = line;
			this.result = result;
		}
	}

	private static Outcome shared(String what, String text)
	{
		return new Outcome(SHARED + what, ChatApi.ToolResult.ok(text));
	}

	/**
	 * The line for a call whose result was never sent: the request had stopped by the time the game answered, and a
	 * stopped request sends nothing more. "Shared your bank" becomes "Read your bank, but didn't share it: the request
	 * had stopped". Lines for calls that shared nothing anyway stay as they are.
	 */
	static String unshared(String line)
	{
		if (line.startsWith(SHARED))
		{
			return READ + line.substring(SHARED.length()) + UNSHARED;
		}
		return line.startsWith(SEARCHED) ? line + UNSHARED : line;
	}

	private static Outcome bankOutcome(GameData.Bank bank, String search, long now)
	{
		if (bank == null)
		{
			return new Outcome("Couldn't share your bank: open it once so AI Chat can see it",
				ChatApi.ToolResult.error("The bank can only be read while it's open, and the player hasn't opened it since AI Chat or \""
					+ ITEMS_SETTING + "\" was turned on, or they logged in to this account. Ask them to open their bank once, "
					+ "then ask again."));
		}
		String line = search == null ? SHARED + "bank" : SEARCHED + "\"" + ChatApi.shorten(search, 60) + "\"";
		return new Outcome(line, ChatApi.ToolResult.ok(GameData.bankText(bank, search, now)));
	}

	/** Equipment, inventory and bank: only with "Share items and gear". */
	private <T> void readItems(Report report, String what, Supplier<T> read, Function<T, Outcome> write)
	{
		if (!shareItems.getAsBoolean())
		{
			report.send(settingOff(what, ITEMS_SETTING));
			return;
		}
		readThenWrite(report, what, read, write);
	}

	/** Slayer task and diaries: only with "Share character details". */
	private <T> void readCharacter(Report report, String what, Supplier<T> read, Function<T, Outcome> write)
	{
		if (!shareCharacter.getAsBoolean())
		{
			report.send(settingOff(what, CHARACTER_SETTING));
			return;
		}
		readThenWrite(report, what, read, write);
	}

	private static Outcome settingOff(String what, String setting)
	{
		return new Outcome("Didn't share your " + what + ": \"" + setting + "\" is off",
			ChatApi.ToolResult.error("The player hasn't turned on \"" + setting + "\" in AI Chat's settings, so their "
				+ what + " can't be read. They can turn it on if they'd like you to see it."));
	}

	/**
	 * Reads on the client thread, then writes the answer up off it: the reply carries on from {@code done} (building
	 * and sending the next request), which shouldn't hold up the game.
	 */
	private <T> void readThenWrite(Report report, String what, Supplier<T> read, Function<T, Outcome> write)
	{
		Future<?> timeout = null;
		try
		{
			timeout = executor.schedule(() -> report.send(new Outcome("Couldn't read your " + what + ": the game didn't answer",
				ChatApi.ToolResult.error("The game didn't answer in time, so the player's " + what + " couldn't be "
					+ "read. Try once more, or answer without it."))), timeoutMillis, TimeUnit.MILLISECONDS);
		}
		catch (RuntimeException e)
		{
			// RuneLite is closing; read without a time limit.
			log.debug("no time limit for reading the game", e);
		}
		Future<?> limit = timeout;
		// A Runnable, so it runs once: a lambda that returned a boolean would be taken as the kind that runs again
		// every frame until it returns true.
		Runnable onClientThread = () ->
		{
			if (limit != null)
			{
				limit.cancel(false);
			}
			boolean loggedIn;
			T value;
			try
			{
				loggedIn = game.loggedIn();
				value = loggedIn ? read.get() : null;
			}
			catch (RuntimeException e)
			{
				// The game's data wasn't there to read (a game update, a loading screen).
				log.warn("couldn't read the player's {}", what, e);
				handBack(() -> report.send(new Outcome("Couldn't read your " + what, ChatApi.ToolResult.error(FAILED))));
				return;
			}
			handBack(() -> report.write(what, () -> loggedIn ? write.apply(value) : notLoggedIn(what)));
		};
		try
		{
			clientThread.accept(onClientThread);
		}
		catch (RuntimeException e)
		{
			log.debug("couldn't reach the client thread", e);
			if (limit != null)
			{
				limit.cancel(false);
			}
			report.send(new Outcome("Couldn't read your " + what, ChatApi.ToolResult.error(FAILED)));
		}
	}

	private static Outcome notLoggedIn(String what)
	{
		return new Outcome("Couldn't share your " + what + ": you're not logged in",
			ChatApi.ToolResult.error("The player isn't logged in, so their " + what + " can't be read. Ask them to log "
				+ "in first."));
	}

	/** Off the client thread before the reply carries on. */
	private void handBack(Runnable r)
	{
		try
		{
			executor.execute(r);
		}
		catch (RuntimeException e)
		{
			// RuneLite is closing; the reply won't get far, but it still hears back.
			r.run();
		}
	}

	/** The bank search the model gave, on one line and capped; null for the whole bank. */
	private static String search(JsonObject input)
	{
		JsonElement e = input == null ? null : input.get("search");
		if (e == null || !e.isJsonPrimitive())
		{
			return null;
		}
		String s = e.getAsString().replaceAll("[\\s\\p{Cc}]+", " ").trim();
		if (s.isEmpty())
		{
			return null;
		}
		return s.length() <= MAX_SEARCH ? s : s.substring(0, MAX_SEARCH).trim();
	}

	/** One call's ending: its activity line, then its result, together and only once. */
	private final class Report
	{
		private final AtomicBoolean sent = new AtomicBoolean();
		private final Consumer<ChatApi.ToolResult> done;

		Report(Consumer<ChatApi.ToolResult> done)
		{
			this.done = done;
		}

		/** For an outcome written up later, on another thread: a bug while writing it up still ends the call. */
		void write(String what, Supplier<Outcome> outcome)
		{
			Outcome o;
			try
			{
				o = outcome.get();
			}
			catch (RuntimeException e)
			{
				log.warn("couldn't write up the player's {}", what, e);
				o = new Outcome("Couldn't read your " + what, ChatApi.ToolResult.error(FAILED));
			}
			send(o);
		}

		void send(Outcome o)
		{
			if (!sent.compareAndSet(false, true))
			{
				return;
			}
			try
			{
				activity.accept(o.line);
			}
			catch (RuntimeException e)
			{
				log.warn("game data activity not shown", e);
			}
			done.accept(o.result);
		}
	}
}

package com.aichat;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.Icon;

/**
 * The panel's small icons, drawn with shapes rather than font characters (which not every font has). Each fits a square
 * of {@code size} pixels, in its own colour or the component's text colour, faded while the component is disabled.
 */
final class Glyph implements Icon
{
	enum Shape
	{
		/** An arrow pointing up: Send. */
		SEND,
		/** A square: Stop. */
		STOP,
		/** An arrow pointing down: jump to the latest message. */
		DOWN,
		PLUS,
		/** Three dots: more actions. */
		MORE,
		COPY,
		/** A circling arrow: Retry. */
		RETRY,
		/** A cross: close. */
		CLOSE,
		/** A chevron pointing down: opens a menu, or shows more. */
		CHEVRON_DOWN,
		/** A chevron pointing up: hides what a {@link #CHEVRON_DOWN} showed. */
		CHEVRON_UP,
		/** A tick: the one chosen. */
		CHECK
	}

	private final Shape shape;
	private final int size;
	/** Null: the component's own text colour. */
	private final Color color;

	Glyph(Shape shape, int size)
	{
		this(shape, size, null);
	}

	Glyph(Shape shape, int size, Color color)
	{
		this.shape = shape;
		this.size = size;
		this.color = color;
	}

	@Override
	public int getIconWidth()
	{
		return size;
	}

	@Override
	public int getIconHeight()
	{
		return size;
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = PanelStyle.smooth(g);
		try
		{
			g2.translate(x, y);
			Color base = color != null ? color : c.getForeground();
			g2.setColor(c.isEnabled() ? base : new Color(base.getRed(), base.getGreen(), base.getBlue(), 100));
			g2.setStroke(new BasicStroke(Math.max(1.5f, size / 9f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			draw(g2, size);
		}
		finally
		{
			g2.dispose();
		}
	}

	/** Draws the shape in a square of side {@code s}, positions given as fractions of it. */
	private void draw(Graphics2D g, float s)
	{
		switch (shape)
		{
			case SEND:
				g.draw(line(s, 0.5, 0.82, 0.5, 0.2));
				g.draw(path(s, 0.24, 0.46, 0.5, 0.2, 0.76, 0.46));
				break;
			case DOWN:
				g.draw(line(s, 0.5, 0.18, 0.5, 0.8));
				g.draw(path(s, 0.24, 0.54, 0.5, 0.8, 0.76, 0.54));
				break;
			case STOP:
				g.fill(new RoundRectangle2D.Double(0.27 * s, 0.27 * s, 0.46 * s, 0.46 * s, 0.14 * s, 0.14 * s));
				break;
			case PLUS:
				g.draw(line(s, 0.5, 0.18, 0.5, 0.82));
				g.draw(line(s, 0.18, 0.5, 0.82, 0.5));
				break;
			case MORE:
				for (double cx : new double[]{0.2, 0.5, 0.8})
				{
					double r = Math.max(1.2, 0.08 * s);
					g.fill(new Ellipse2D.Double(cx * s - r, 0.5 * s - r, 2 * r, 2 * r));
				}
				break;
			case COPY:
				// The sheet behind shows only where the front one doesn't cover it.
				g.draw(path(s, 0.34, 0.3, 0.34, 0.14, 0.86, 0.14, 0.86, 0.66, 0.7, 0.66));
				g.draw(new RoundRectangle2D.Double(0.14 * s, 0.34 * s, 0.52 * s, 0.52 * s, 0.12 * s, 0.12 * s));
				break;
			case RETRY:
				// Most of a circle going clockwise, open at the top right where it ends in an open arrowhead. A head
				// of two strokes stays clear at 12 pixels, where a small filled one made the icon read as a "C".
				double r = 0.34 * s;
				g.draw(new Arc2D.Double(0.48 * s - r, 0.52 * s - r, 2 * r, 2 * r, 50, 280, Arc2D.OPEN));
				g.draw(path(s, 0.82, 0.08, 0.82, 0.34, 0.56, 0.34));
				break;
			case CHEVRON_DOWN:
				g.draw(path(s, 0.2, 0.36, 0.5, 0.66, 0.8, 0.36));
				break;
			case CHEVRON_UP:
				g.draw(path(s, 0.2, 0.64, 0.5, 0.34, 0.8, 0.64));
				break;
			case CHECK:
				g.draw(path(s, 0.18, 0.52, 0.4, 0.74, 0.82, 0.28));
				break;
			default:
				g.draw(line(s, 0.28, 0.28, 0.72, 0.72));
				g.draw(line(s, 0.72, 0.28, 0.28, 0.72));
				break;
		}
	}

	private static Line2D line(float s, double x1, double y1, double x2, double y2)
	{
		return new Line2D.Double(x1 * s, y1 * s, x2 * s, y2 * s);
	}

	/** An open line through the points, given as x, y pairs. */
	private static Path2D path(float s, double... xy)
	{
		Path2D.Double p = new Path2D.Double();
		p.moveTo(xy[0] * s, xy[1] * s);
		for (int i = 2; i < xy.length; i += 2)
		{
			p.lineTo(xy[i] * s, xy[i + 1] * s);
		}
		return p;
	}
}

package com.aichat;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
