/**
 * The look-ups the model can call while answering: the OSRS Wiki (search, read a page) and RuneLite's own Grand
 * Exchange prices. Made for one reply: every call it runs ends with one line for the panel saying what was looked up
 * ({@code Searched the Wiki for "abyssal whip"}), told to {@code activity} just before the result goes back.
 */
@Slf4j
final class LookupTools implements ChatApi.ToolRunner
{
	static final String WIKI_SEARCH = "wiki_search";
	static final String WIKI_PAGE = "wiki_page";
	static final String GE_PRICE = "ge_price";
	/**
	 * How the lines for look-ups that went through start. The panel counts or names them on one line over the reply,
	 * and lists them one kind to a line when that's clicked (see {@link PanelText#summary}), by these.
	 */
	static final String SEARCHED_WIKI = "Searched the Wiki for ";
	static final String READ_WIKI_PAGE = "Read the Wiki page ";
	static final String CHECKED_GE_PRICE = "Checked the GE price of ";

	static final int SEARCH_RESULTS = 6;
	/** Wikitext per wiki_page, about 3,000 tokens: most pages fit, and reading a few stays cheap. */
	static final int PAGE_CHARS = 12_000;
	/** A page longer than this lists its sections even when it fits, so the model can ask for one next time. */
	static final int LONG_PAGE_CHARS = 6_000;
	static final int PRICE_RESULTS = 5;
	private static final int SNIPPET_CHARS = 200;
	private static final int MAX_SECTIONS_LISTED = 80;
	/** The Wiki takes at most 300 characters of search, and titles are at most 255. */
	private static final int MAX_QUERY = 200;
	private static final int MAX_TITLE = 255;
	private static final long NOT_A_NUMBER = Long.MIN_VALUE;
	private static final String TRY_AGAIN = " Try again, or answer without the Wiki and say so.";
	private static final String FAILED = "That look-up failed inside AI Chat. Answer without it.";
	/** A wikitext heading on its own line: "== Drops ==". */
	private static final Pattern HEADING_LINE = Pattern.compile("={2,6}[^\n]*={2,6}\\s*");

	/** Where ge_price gets its prices: RuneLite's own price data in the game, canned ones in tests. */
	interface Prices
	{
		/**
		 * Tradeable items whose names contain {@code text}, ignoring case; empty when nothing matches or the prices
		 * haven't loaded yet. Any thread.
		 */
		List<ItemPrice> search(String text);

		/** The price RuneLite shows for the item, following its "Use actively traded price" setting. Any thread. */
		long price(ItemPrice item);

		/** Reports the items' high alchemy values by id, once, on any thread; values it can't read are left out. */
		void highAlchemy(List<Integer> ids, Consumer<Map<Integer, Integer>> done);
	}

	/** Null when Wiki look-ups are off: the Wiki tools aren't offered, and calls to them are turned down. */
	private final WikiClient wiki;
	private final Prices prices;
	private final Consumer<String> activity;
	/** False once the reply these look-ups are for has stopped: Wiki requests still waiting their turn aren't sent. */
	private final BooleanSupplier wanted;

	/** Look-ups that are always wanted. */
	LookupTools(WikiClient wiki, Prices prices, Consumer<String> activity)
	{
		this(wiki, prices, activity, () -> true);
	}

	LookupTools(WikiClient wiki, Prices prices, Consumer<String> activity, BooleanSupplier wanted)
	{
		this.wiki = wiki;
		this.prices = prices;
		this.activity = activity;
		this.wanted = wanted;
	}

	static boolean handles(String name)
	{
		return WIKI_SEARCH.equals(name) || WIKI_PAGE.equals(name) || GE_PRICE.equals(name);
	}

	/**
	 * The tools to offer, always in the same order and with the same text: they're part of the prompt the provider
	 * caches.
	 */
	List<ChatApi.ToolSpec> specs()
	{
		List<ChatApi.ToolSpec> specs = new ArrayList<>();
		if (wiki != null)
		{
			JsonObject search = new JsonObject();
			search.add("query", property("string",
				"What to look for, e.g. \"abyssal whip\" or \"barrows gloves requirements\"."));
			specs.add(new ChatApi.ToolSpec(WIKI_SEARCH,
				"Search the Old School RuneScape Wiki. Returns up to " + SEARCH_RESULTS + " page titles with links and a "
					+ "snippet each; read one with " + WIKI_PAGE + ".",
				schema(search, "query")));

			JsonObject page = new JsonObject();
			page.add("title", property("string", "The exact page title, e.g. \"Abyssal whip\". Redirects are followed."));
			JsonObject section = property("integer", "Optional: one section's number from the page's section list; 0 is "
				+ "the part before the first heading.");
			section.addProperty("minimum", 0);
			page.add("section", section);
			specs.add(new ChatApi.ToolSpec(WIKI_PAGE,
				"Read an OSRS Wiki page's wikitext: infobox stats, requirements, drops, strategy. Long pages are cut and "
					+ "list their sections; then ask for one section. Link the page you used in your answer.",
				schema(page, "title")));
		}

		JsonObject price = new JsonObject();
		price.add("item", property("string", "An item name or part of one, e.g. \"dragon bones\"."));
		JsonObject quantity = property("integer", "Optional: how many, for the total.");
		quantity.addProperty("minimum", 1);
		price.add("quantity", quantity);
		specs.add(new ChatApi.ToolSpec(GE_PRICE,
			"Current Grand Exchange prices from RuneLite's own price data: up to " + PRICE_RESULTS + " tradeable items "
				+ "whose names contain the text, with their high alchemy values. Untradeable items have no price.",
			schema(price, "item")));
		return specs;
	}

	private static JsonObject property(String type, String description)
	{
		JsonObject p = new JsonObject();
		p.addProperty("type", type);
		p.addProperty("description", description);
		return p;
	}

	private static JsonObject schema(JsonObject properties, String required)
	{
		JsonObject s = new JsonObject();
		s.addProperty("type", "object");
		s.add("properties", properties);
		JsonArray r = new JsonArray();
		r.add(required);
		s.add("required", r);
		return s;
	}

	@Override
	public void run(String name, JsonObject input, Consumer<ChatApi.ToolResult> done)
	{
		Report report = new Report(done);
		try
		{
			if (WIKI_SEARCH.equals(name))
			{
				wikiSearch(input, report);
			}
			else if (WIKI_PAGE.equals(name))
			{
				wikiPage(input, report);
			}
			else if (GE_PRICE.equals(name))
			{
				gePrice(input, report);
			}
			else
			{
				report.send("Skipped an unknown look-up " + quote(name),
					ChatApi.ToolResult.error("There's no tool called " + name + "."));
			}
		}
		catch (RuntimeException e)
		{
			// A bug, not the player's or the model's doing; the reply can still carry on without this look-up.
			log.warn("look-up {} failed", name, e);
			report.send("Couldn't finish a look-up (" + name + ")", ChatApi.ToolResult.error(FAILED));
		}
	}

	/**
	 * One call's ending: its activity line, then its result, together and only once. No line for a look-up that wasn't
	 * made because its reply had stopped: there's nothing to list.
	 */
	private final class Report
	{
		private final AtomicBoolean sent = new AtomicBoolean();
		private final Consumer<ChatApi.ToolResult> done;

		Report(Consumer<ChatApi.ToolResult> done)
		{
			this.done = done;
		}

		/**
		 * For a result written later, on another thread: a bug while writing it still ends the call, instead of leaving
		 * the reply waiting for it.
		 */
		void write(String line, Supplier<ChatApi.ToolResult> result)
		{
			ChatApi.ToolResult r;
			try
			{
				r = result.get();
			}
			catch (RuntimeException e)
			{
				log.warn("look-up result not written", e);
				r = ChatApi.ToolResult.error(FAILED);
			}
			send(line, r);
		}

		void send(String line, ChatApi.ToolResult result)
		{
			if (!sent.compareAndSet(false, true))
			{
				return;
			}
			try
			{
				if (line != null)
				{
					activity.accept(line);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("look-up activity not shown", e);
			}
			done.accept(result);
		}
	}

	private void wikiSearch(JsonObject input, Report report)
	{
		if (wiki == null)
		{
			report.send("Skipped a Wiki search: Wiki look-ups are off", wikiOff());
			return;
		}
		String query = text(input, "query", MAX_QUERY);
		if (query == null)
		{
			report.send("Skipped a Wiki search: nothing to search for",
				ChatApi.ToolResult.error(WIKI_SEARCH + " needs a query, e.g. {\"query\": \"abyssal whip\"}."));
			return;
		}
		wiki.search(query, SEARCH_RESULTS, wanted, new WikiClient.Listener<WikiClient.Search>()
		{
			@Override
			public void onResult(WikiClient.Search search)
			{
				report.write(SEARCHED_WIKI + quote(query), () -> ChatApi.ToolResult.ok(searchText(query, search)));
			}

			@Override
			public void onError(String code, String message)
			{
				report.send(WikiClient.STOPPED.equals(code) ? null : "Couldn't search the Wiki for " + quote(query),
					WikiClient.TURNED_OFF.equals(code) ? wikiOff() : ChatApi.ToolResult.error(message + TRY_AGAIN));
			}
		});
	}

	private void wikiPage(JsonObject input, Report report)
	{
		if (wiki == null)
		{
			report.send("Skipped a Wiki page: Wiki look-ups are off", wikiOff());
			return;
		}
		String title = title(text(input, "title", MAX_TITLE + 100));
		long section = whole(input, "section", -1);
		if (title == null)
		{
			report.send("Skipped a Wiki page: no title given",
				ChatApi.ToolResult.error(WIKI_PAGE + " needs a title, e.g. {\"title\": \"Abyssal whip\"}."));
			return;
		}
		if (section < -1 || section > 9999)
		{
			report.send("Skipped the Wiki page " + quote(title) + ": no such section",
				ChatApi.ToolResult.error("section must be a section number from the page's section list, like 2. Leave it "
					+ "out to read the page from the start."));
			return;
		}
		int part = (int) section;
		wiki.page(title, part, wanted, new WikiClient.Listener<WikiClient.Page>()
		{
			@Override
			public void onResult(WikiClient.Page page)
			{
				report.write(READ_WIKI_PAGE + quote(page.title) + sectionName(page, part),
					() -> ChatApi.ToolResult.ok(pageText(page, part)));
			}

			@Override
			public void onError(String code, String message)
			{
				if (WikiClient.STOPPED.equals(code))
				{
					report.send(null, ChatApi.ToolResult.error(message));
				}
				else if ("missingtitle".equals(code) || "invalidtitle".equals(code))
				{
					report.send("Found no Wiki page called " + quote(title), ChatApi.ToolResult.error(
						"The Wiki has no page called " + quote(title) + ". Try " + WIKI_SEARCH + " first."));
				}
				else if ("nosuchsection".equals(code))
				{
					report.send("Found no section " + part + " on the Wiki page " + quote(title), ChatApi.ToolResult.error(
						"The page " + quote(title) + " has no section " + part + ". Read it without a section to see its "
							+ "list of sections."));
				}
				else
				{
					report.send("Couldn't read the Wiki page " + quote(title), WikiClient.TURNED_OFF.equals(code)
						? wikiOff() : ChatApi.ToolResult.error(message + TRY_AGAIN));
				}
			}
		});
	}

	private static ChatApi.ToolResult wikiOff()
	{
		return ChatApi.ToolResult.error("Wiki look-ups are turned off in the AI Chat settings. Answer without the Wiki.");
	}

	/**
	 * The page title the model meant: it sometimes gives a link to the page, or a title with "#Section" on the end;
	 * MediaWiki wants just the title.
	 */
	static String title(String given)
	{
		if (given == null)
		{
			return null;
		}
		String title = given;
		HttpUrl url = HttpUrl.parse(given);
		if (url != null && url.host().equals(WikiClient.BASE.host()) && url.pathSize() > 1
			&& "w".equals(url.pathSegments().get(0)))
		{
			title = String.join("/", url.pathSegments().subList(1, url.pathSize())).replace('_', ' ');
		}
		int hash = title.indexOf('#');
		if (hash > 0)
		{
			title = title.substring(0, hash);
		}
		title = title.trim();
		if (title.isEmpty())
		{
			return null;
		}
		return title.length() <= MAX_TITLE ? title : title.substring(0, MAX_TITLE);
	}

	/** For the activity line: " (Drops)" after the page's title when one section was read. */
	private static String sectionName(WikiClient.Page page, int section)
	{
		if (section < 0)
		{
			return "";
		}
		if (section == 0)
		{
			return " (introduction)";
		}
		String heading = WikiClient.heading(page.wikitext);
		return " (" + (heading == null ? "section " + section : ChatApi.shorten(WikiClient.plainText(heading), 40)) + ")";
	}

	static String searchText(String query, WikiClient.Search search)
	{
		if (search.results.isEmpty())
		{
			return "The Wiki found no pages for " + quote(query) + "."
				+ (search.suggestion == null ? " Try other words." : " Did you mean " + quote(search.suggestion) + "?");
		}
		StringBuilder out = new StringBuilder("Wiki pages for ").append(quote(query)).append(':');
		int n = 0;
		for (WikiClient.SearchResult r : search.results)
		{
			if (n == SEARCH_RESULTS)
			{
				break;
			}
			out.append('\n').append(++n).append(". ").append(r.title).append(" - ").append(r.url);
			if (!r.snippet.isEmpty())
			{
				out.append("\n   ").append(ChatApi.shorten(r.snippet, SNIPPET_CHARS));
			}
		}
		return out.toString();
	}

	/**
	 * The page for the model: its link first (to cite), then the cleaned wikitext, cut to {@link #PAGE_CHARS}. A cut
	 * or long page ends with its sections, so the model can read just the part it needs.
	 */
	static String pageText(WikiClient.Page page, int section)
	{
		StringBuilder out = new StringBuilder(page.url).append('\n');
		out.append("Wiki page ").append(quote(page.title));
		if (page.redirectedFrom != null)
		{
			out.append(" (redirected from ").append(quote(page.redirectedFrom)).append(')');
		}
		if (section >= 0)
		{
			out.append(", section ").append(section).append(" only");
		}
		out.append(":\n\n");
		String text = WikiClient.clean(page.wikitext);
		boolean cut = text.length() > PAGE_CHARS;
		if (cut)
		{
			text = cut(text, PAGE_CHARS);
		}
		out.append(text.isEmpty() ? "(This has no text.)" : text);
		boolean listed = section < 0 && !page.sections.isEmpty();
		if (cut && listed)
		{
			out.append("\n\n[Cut here: the page goes on. Ask for one section with `section`; the page's sections are:\n")
				.append(sectionList(page.sections)).append(']');
		}
		else if (cut)
		{
			out.append("\n\n[Cut here: the rest is on the page itself.]");
		}
		else if (listed && text.length() > LONG_PAGE_CHARS)
		{
			out.append("\n\n[A long page: next time, ask for one section with `section`. Its sections are:\n")
				.append(sectionList(page.sections)).append(']');
		}
		return out.toString();
	}

	private static String sectionList(List<WikiClient.Section> sections)
	{
		StringBuilder out = new StringBuilder("0 (introduction)");
		int listed = 0;
		for (WikiClient.Section s : sections)
		{
			if (listed == MAX_SECTIONS_LISTED)
			{
				out.append("\n...and ").append(sections.size() - listed).append(" more");
				break;
			}
			out.append('\n');
			for (int level = 2; level < s.level; level++)
			{
				out.append("  ");
			}
			out.append(s.index).append(' ').append(s.heading);
			listed++;
		}
		return out.toString();
	}

	/** At most {@code max} characters, ending at a line break (or a space) where there's one in the second half. */
	static String cut(String text, int max)
	{
		if (text.length() <= max)
		{
			return text;
		}
		int end = text.lastIndexOf('\n', max);
		if (end < max / 2)
		{
			end = text.lastIndexOf(' ', max);
		}
		if (end < max / 2)
		{
			end = Character.isHighSurrogate(text.charAt(max - 1)) ? max - 1 : max;
		}
		String kept = text.substring(0, end).trim();
		// A heading with nothing under it would read as an empty section.
		int lastLine = kept.lastIndexOf('\n');
		if (lastLine > 0 && HEADING_LINE.matcher(kept.substring(lastLine + 1)).matches())
		{
			kept = kept.substring(0, lastLine).trim();
		}
		return kept;
	}

	private void gePrice(JsonObject input, Report report)
	{
		String item = text(input, "item", MAX_QUERY);
		long quantity = whole(input, "quantity", 1);
		if (item == null)
		{
			report.send("Skipped a GE price check: no item given",
				ChatApi.ToolResult.error(GE_PRICE + " needs an item name, e.g. {\"item\": \"dragon bones\"}."));
			return;
		}
		if (quantity < 1 || quantity > Integer.MAX_VALUE)
		{
			report.send("Skipped the GE price of " + quote(item) + ": odd quantity",
				ChatApi.ToolResult.error("quantity must be a whole number from 1 up, or left out."));
			return;
		}
		List<ItemPrice> found = matches(item);
		if (found.isEmpty())
		{
			report.send("Found no GE price for " + quote(item), ChatApi.ToolResult.error(
				"RuneLite has no Grand Exchange price for anything called " + quote(item) + ". It may not be tradeable, or "
					+ "go by another name" + (wiki == null ? "" : " (" + WIKI_SEARCH + " can tell)")
					+ ", or RuneLite hasn't loaded its prices yet."));
			return;
		}
		List<ItemPrice> best = best(found, item, PRICE_RESULTS);
		List<Integer> ids = new ArrayList<>();
		List<Long> each = new ArrayList<>();
		for (ItemPrice p : best)
		{
			ids.add(p.getId());
			each.add(prices.price(p));
		}
		String line = CHECKED_GE_PRICE + ChatApi.shorten(best.get(0).getName(), 60);
		prices.highAlchemy(ids, alch -> report.write(line, () -> ChatApi.ToolResult.ok(
			priceText(item, best, each, found.size(), alch == null ? Collections.emptyMap() : alch, quantity))));
	}

	/** RuneLite's matches for the name; "cannonballs" finds Cannonball. */
	private List<ItemPrice> matches(String item)
	{
		List<ItemPrice> found = prices.search(item);
		if ((found == null || found.isEmpty()) && item.length() > 3 && item.toLowerCase(Locale.ROOT).endsWith("s"))
		{
			found = prices.search(item.substring(0, item.length() - 1));
		}
		List<ItemPrice> named = new ArrayList<>();
		if (found != null)
		{
			for (ItemPrice p : found)
			{
				if (p != null && p.getName() != null)
				{
					named.add(p);
				}
			}
		}
		return named;
	}

	/**
	 * The likeliest items first: the exact name, then names starting with the text, then a word starting with it, then
	 * the shortest (RuneLite's own !price command also prefers the exact or the shortest name).
	 */
	static List<ItemPrice> best(List<ItemPrice> found, String query, int max)
	{
		String q = query.toLowerCase(Locale.ROOT);
		List<ItemPrice> sorted = new ArrayList<>(found);
		sorted.sort(Comparator.comparingInt((ItemPrice p) -> rank(p.getName().toLowerCase(Locale.ROOT), q))
			.thenComparingInt(p -> p.getName().length())
			.thenComparing(ItemPrice::getName));
		return new ArrayList<>(sorted.subList(0, Math.min(max, sorted.size())));
	}

	private static int rank(String name, String query)
	{
		if (name.equals(query))
		{
			return 0;
		}
		if (name.startsWith(query))
		{
			return 1;
		}
		return name.contains(" " + query) || name.contains("(" + query) ? 2 : 3;
	}

	/**
	 * One line per item: "Abyssal whip: 1,523,410 gp (GE guide price 1,498,000 gp); high alchemy 72,000 gp". The guide
	 * price is added when it isn't the price RuneLite shows.
	 */
	static String priceText(String query, List<ItemPrice> items, List<Long> each, int matched, Map<Integer, Integer> alch,
		long quantity)
	{
		StringBuilder out = new StringBuilder("Grand Exchange prices from RuneLite (its price list updates every 30 minutes):");
		for (int i = 0; i < items.size(); i++)
		{
			ItemPrice item = items.get(i);
			long price = each.get(i);
			out.append("\n- ").append(item.getName()).append(": ");
			if (price <= 0)
			{
				out.append("no recent price");
			}
			else if (quantity > 1)
			{
				out.append(gp(price)).append(" each, ").append(gp(price * quantity)).append(" for ").append(number(quantity));
			}
			else
			{
				out.append(gp(price));
			}
			if (item.getPrice() > 0 && item.getPrice() != price)
			{
				out.append(" (GE guide price ").append(gp(item.getPrice())).append(quantity > 1 ? " each)" : ")");
			}
			Integer ha = alch.get(item.getId());
			if (ha != null && ha > 0)
			{
				out.append("; high alchemy ").append(gp(ha)).append(quantity > 1 ? " each" : "");
			}
		}
		if (matched > items.size())
		{
			int more = matched - items.size();
			out.append("\n...and ").append(more).append(more == 1 ? " more item matches " : " more items match ")
				.append(quote(query)).append("; ask with a fuller name to see ").append(more == 1 ? "it." : "them.");
		}
		return out.toString();
	}

	private static String gp(long amount)
	{
		return number(amount) + " gp";
	}

	private static String number(long n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}

	/** A text value the model gave, on one line and capped; null when it's missing or blank. */
	private static String text(JsonObject input, String key, int max)
	{
		JsonElement e = input == null ? null : input.get(key);
		if (e == null || !e.isJsonPrimitive())
		{
			return null;
		}
		String s = e.getAsString().replaceAll("[\\s\\p{Cc}]+", " ").trim();
		if (s.isEmpty())
		{
			return null;
		}
		return s.length() <= max ? s : s.substring(0, max).trim();
	}

	/**
	 * A whole number the model gave (2, 2.0 or "2"), {@code absent} when it gave none (or a blank), and
	 * {@link #NOT_A_NUMBER} when it isn't one.
	 */
	private static long whole(JsonObject input, String key, long absent)
	{
		JsonElement e = input == null ? null : input.get(key);
		if (e == null || e.isJsonNull() || (e.isJsonPrimitive() && e.getAsString().trim().isEmpty()))
		{
			return absent;
		}
		if (!e.isJsonPrimitive())
		{
			return NOT_A_NUMBER;
		}
		try
		{
			return e.getAsBigDecimal().longValueExact();
		}
		catch (NumberFormatException | ArithmeticException ex)
		{
			return NOT_A_NUMBER;
		}
	}

	private static String quote(String s)
	{
		return "\"" + ChatApi.shorten(s, 60) + "\"";
	}

	/**
	 * RuneLite's own prices, which it downloads itself every 30 minutes: a price check sends nothing anywhere. High
	 * alchemy values come from the game's item data, read on the client thread.
	 */
	static final class RuneLitePrices implements Prices
	{
		/** The client thread runs queued work every frame, also on the login screen; this is in case it can't. */
		private static final long ALCH_TIMEOUT_MILLIS = 2000;

		private final ItemManager itemManager;
		private final ClientThread clientThread;
		private final ScheduledExecutorService executor;
		private final BooleanSupplier activelyTraded;
		private final long alchTimeoutMillis;

		/** {@code activelyTraded}: RuneLite's "Use actively traded price" setting. */
		RuneLitePrices(ItemManager itemManager, ClientThread clientThread, ScheduledExecutorService executor,
			BooleanSupplier activelyTraded)
		{
			this(itemManager, clientThread, executor, activelyTraded, ALCH_TIMEOUT_MILLIS);
		}

		RuneLitePrices(ItemManager itemManager, ClientThread clientThread, ScheduledExecutorService executor,
			BooleanSupplier activelyTraded, long alchTimeoutMillis)
		{
			this.itemManager = itemManager;
			this.clientThread = clientThread;
			this.executor = executor;
			this.activelyTraded = activelyTraded;
			this.alchTimeoutMillis = alchTimeoutMillis;
		}

		@Override
		public List<ItemPrice> search(String text)
		{
			// Only reads the price list RuneLite keeps in memory: fine off the client thread.
			return itemManager.search(text);
		}

		@Override
		public long price(ItemPrice item)
		{
			// What ItemManager.getItemPrice gives, without its item lookup, which needs the client thread: search finds
			// tradeable items under their own ids, so there's no noted or worn version to map back.
			return activelyTraded.getAsBoolean() ? itemManager.getWikiPrice(item) : item.getPrice();
		}

		@Override
		public void highAlchemy(List<Integer> ids, Consumer<Map<Integer, Integer>> done)
		{
			AtomicBoolean reported = new AtomicBoolean();
			Future<?> timeout;
			try
			{
				timeout = executor.schedule(() ->
				{
					if (reported.compareAndSet(false, true))
					{
						done.accept(Collections.emptyMap());
					}
				}, alchTimeoutMillis, TimeUnit.MILLISECONDS);
			}
			catch (RuntimeException e)
			{
				// RuneLite is closing: prices without alchemy values.
				done.accept(Collections.emptyMap());
				return;
			}
			// A Runnable, so it runs once: a lambda that returns a boolean would be taken as the kind that runs again
			// every frame until it returns true.
			Runnable read = () ->
			{
				Map<Integer, Integer> values = new HashMap<>();
				for (int id : ids)
				{
					try
					{
						values.put(id, itemManager.getItemComposition(id).getHaPrice());
					}
					catch (RuntimeException e)
					{
						// The game's item data isn't loaded yet: leave this one out.
						log.debug("no high alchemy value for {}", id, e);
					}
				}
				timeout.cancel(false);
				if (reported.compareAndSet(false, true))
				{
					handBack(done, values);
				}
			};
			try
			{
				clientThread.invoke(read);
			}
			catch (RuntimeException e)
			{
				log.debug("high alchemy values not read", e);
				timeout.cancel(false);
				if (reported.compareAndSet(false, true))
				{
					done.accept(Collections.emptyMap());
				}
			}
		}

		/** Off the client thread before the reply carries on (formatting, then the next request). */
		private void handBack(Consumer<Map<Integer, Integer>> done, Map<Integer, Integer> values)
		{
			try
			{
				executor.execute(() -> done.accept(values));
			}
			catch (RuntimeException e)
			{
				// RuneLite is closing; the reply won't get far, but it still hears back.
				done.accept(values);
			}
		}
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.BitSet;
import java.util.Collections;
import java.util.List;
import okhttp3.HttpUrl;

/**
 * Reads the bit of Markdown replies are written in into blocks of styled text, for {@link MessageView}: paragraphs,
 * headings, lists, quotes, code, rules and tables; bold, italic, inline code and links. Pure, so any thread can use it.
 * HTML is never interpreted ("<b>" is shown as it is), only http and https addresses become links, and anything
 * unfinished (an unclosed "**" while a reply streams in, half a link) is shown as the plain text it is.
 */
class Markdown
{
	enum BlockKind
	{
		PARAGRAPH, HEADING, BULLET, NUMBERED, QUOTE, CODE, RULE, TABLE
	}

	enum SpanKind
	{
		TEXT, BOLD, ITALIC, BOLD_ITALIC, CODE, LINK
	}

	static class Block
	{
		final BlockKind kind;
		/** HEADING: 1 to 6. */
		final int level;
		/**
		 * BULLET and NUMBERED: how deeply the list is nested, 0 for a list that isn't inside another. Every other kind:
		 * how many list items the block is part of (a second paragraph or a code block under an item), usually 0.
		 */
		final int depth;
		/** NUMBERED: the number to show. */
		final int number;
		/** The text of every kind but CODE, TABLE and RULE; it can contain line breaks. Empty for those. */
		final List<Span> spans;
		/**
		 * CODE: the lines to show as they are, in a monospaced font. TABLE: the table as such lines, cells padded to
		 * line up, which is also how it's copied. Empty for the others.
		 */
		final List<String> lines;
		/** TABLE: its cells, to draw it as a table; null when it's too big to draw, and is shown as its lines. */
		final Table table;

		Block(BlockKind kind, int level, int depth, int number, List<Span> spans, List<String> lines)
		{
			this(kind, level, depth, number, spans, lines, null);
		}

		Block(BlockKind kind, int level, int depth, int number, List<Span> spans, List<String> lines, Table table)
		{
			this.kind = kind;
			this.level = level;
			this.depth = depth;
			this.number = number;
			this.spans = spans;
			this.lines = lines;
			this.table = table;
		}
	}

	/** A table's cells, for drawing it as a table. */
	static class Table
	{
		/** One {@code ALIGN_*} per column. */
		final int[] align;
		/**
		 * The rows, the header first, each with a cell per column (an empty one where the row had too few) holding its
		 * text with its formatting.
		 */
		final List<List<List<Span>>> rows;

		Table(int[] align, List<List<List<Span>>> rows)
		{
			this.align = align;
			this.rows = rows;
		}
	}

	static class Span
	{
		final SpanKind kind;
		final String text;
		/** LINK: the http or https address, as written. Null for the other kinds. */
		final String url;

		Span(SpanKind kind, String text, String url)
		{
			this.kind = kind;
			this.text = text;
			this.url = url;
		}
	}

	/** Longest link text looked for: a stray "[" mustn't make the rest of a long reply be searched again and again. */
	private static final int MAX_LABEL = 1000;
	private static final int MAX_URL = 2000;
	private static final String ASCII_PUNCTUATION = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
	/** Left off the end of a bare address: "see https://example.com." means the address without the full stop. */
	private static final String URL_TRAILERS = ".,;:!?*_~'\"";
	static final int ALIGN_LEFT = 0;
	static final int ALIGN_CENTER = 1;
	static final int ALIGN_RIGHT = 2;
	/**
	 * Most characters a table may take once its cells are padded to line up. Padding fills every row to the longest
	 * cell of each column, so one long cell over thousands of short rows would turn a short reply into hundreds of
	 * megabytes; a table past this is shown as written instead.
	 */
	static final int MAX_TABLE = 20_000;
	/**
	 * Most rows a table may have to be drawn as a table (it's drawn again with every few words of a reply that streams
	 * in); one with more is shown as its lined-up lines, as code is.
	 */
	static final int MAX_TABLE_ROWS = 200;

	private Markdown()
	{
	}

	/** The blocks of {@code text}, in order. Never fails: whatever isn't recognised is text. */
	static List<Block> parse(String text)
	{
		if (text == null || text.isEmpty())
		{
			return Collections.emptyList();
		}
		return new BlockParser(lines(text)).parse();
	}

	/** Spans for text that isn't Markdown (the player's own messages, errors): only bare http(s) addresses are links. */
	static List<Span> linkify(String text)
	{
		return new InlineParser(text == null ? "" : text, false).parse();
	}

	/**
	 * The text as it reads, for copying: list markers and quote marks kept, formatting marks gone, and each link's
	 * address after its text.
	 */
	static String plainText(List<Block> blocks)
	{
		StringBuilder out = new StringBuilder();
		Block previous = null;
		for (Block b : blocks)
		{
			if (previous != null)
			{
				// List items (and what's inside them) go on the next line; everything else gets a blank line between.
				boolean list = isItem(previous) && (isItem(b) || b.depth > 0);
				out.append(list ? "\n" : "\n\n");
			}
			String indent = repeat(' ', 2 * b.depth);
			switch (b.kind)
			{
				case BULLET:
					appendIndented(out, indent + "- ", indent + "  ", plainText(b.spans, true));
					break;
				case NUMBERED:
					String marker = b.number + ". ";
					appendIndented(out, indent + marker, indent + repeat(' ', marker.length()), plainText(b.spans, true));
					break;
				case QUOTE:
					appendIndented(out, indent + "> ", indent + "> ", plainText(b.spans, true));
					break;
				case CODE:
				case TABLE:
					appendIndented(out, indent, indent, String.join("\n", b.lines));
					break;
				case RULE:
					out.append(indent).append("----");
					break;
				default:
					appendIndented(out, indent, indent, plainText(b.spans, true));
					break;
			}
			previous = b;
		}
		return out.toString();
	}

	static String plainText(String markdown)
	{
		return plainText(parse(markdown));
	}

	/** The spans' text run together; with {@code urls}, each link's address follows its text unless they're the same. */
	static String plainText(List<Span> spans, boolean urls)
	{
		StringBuilder out = new StringBuilder();
		for (Span s : spans)
		{
			out.append(s.text);
			if (urls && s.kind == SpanKind.LINK && !s.text.equals(s.url))
			{
				out.append(" (").append(s.url).append(')');
			}
		}
		return out.toString();
	}

	/**
	 * A table as monospaced lines: cells padded to line up, " | " between columns and a rule under the header row.
	 * {@code rows} starts with the header; {@code align} has one {@code ALIGN_*} per column. A table that would take
	 * more than {@link #MAX_TABLE} characters lined up is shown as written: its cells unpadded, missing ones left out.
	 */
	static List<String> tableLines(List<List<String>> rows, int[] align)
	{
		int columns = align.length;
		int[] width = columnChars(rows, columns);
		boolean lineUp = linesUp(rows, width);
		List<String> out = new ArrayList<>();
		for (int r = 0; r < rows.size(); r++)
		{
			List<String> row = rows.get(r);
			StringBuilder line = new StringBuilder();
			for (int c = 0; c < (lineUp ? columns : Math.min(columns, row.size())); c++)
			{
				if (c > 0)
				{
					line.append(" | ");
				}
				line.append(lineUp ? pad(cell(row, c), width[c], align[c]) : row.get(c));
			}
			out.add(line.toString().stripTrailing());
			if (r == 0)
			{
				out.add(lineUp ? rule(width) : repeat('-', Math.max(1, out.get(0).length())));
			}
		}
		return out;
	}

	/** How many characters each column's widest cell has (at least one). */
	private static int[] columnChars(List<List<String>> rows, int columns)
	{
		int[] width = new int[columns];
		Arrays.fill(width, 1);
		for (List<String> row : rows)
		{
			// Only the cells a row has: one that's missing is empty, and looking at it would take as long as padding it.
			for (int c = 0; c < Math.min(columns, row.size()); c++)
			{
				width[c] = Math.max(width[c], row.get(c).length());
			}
		}
		return width;
	}

	/** Whether the table, its columns {@code width} characters wide, takes at most {@link #MAX_TABLE} lined up. */
	private static boolean linesUp(List<List<String>> rows, int[] width)
	{
		long lineWidth = 3L * (width.length - 1);
		for (int w : width)
		{
			lineWidth += w;
		}
		return lineWidth * (rows.size() + 1) <= MAX_TABLE;
	}

	/** The rule under a lined-up header: dashes as wide as each column, "+" where the " | " go. */
	private static String rule(int[] width)
	{
		StringBuilder rule = new StringBuilder();
		for (int c = 0; c < width.length; c++)
		{
			rule.append(c > 0 ? "-+-" : "").append(repeat('-', width[c]));
		}
		return rule.toString();
	}

	private static String cell(List<String> row, int c)
	{
		return c < row.size() ? row.get(c) : "";
	}

	private static String pad(String s, int width, int align)
	{
		int space = width - s.length();
		if (align == ALIGN_RIGHT)
		{
			return repeat(' ', space) + s;
		}
		if (align == ALIGN_CENTER)
		{
			return repeat(' ', space / 2) + s + repeat(' ', space - space / 2);
		}
		return s + repeat(' ', space);
	}

	private static boolean isItem(Block b)
	{
		return b.kind == BlockKind.BULLET || b.kind == BlockKind.NUMBERED;
	}

	private static void appendIndented(StringBuilder out, String first, String rest, String text)
	{
		String[] lines = text.split("\n", -1);
		for (int i = 0; i < lines.length; i++)
		{
			out.append(i == 0 ? "" : "\n").append(i == 0 ? first : rest).append(lines[i]);
		}
	}

	static String repeat(char c, int n)
	{
		if (n <= 0)
		{
			return "";
		}
		char[] chars = new char[n];
		Arrays.fill(chars, c);
		return new String(chars);
	}

	/** Splits on \n, \r\n and \r alike. */
	private static List<String> lines(String text)
	{
		List<String> out = new ArrayList<>();
		int start = 0;
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '\n' || c == '\r')
			{
				out.add(text.substring(start, i));
				if (c == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n')
				{
					i++;
				}
				start = i + 1;
			}
		}
		out.add(text.substring(start));
		return out;
	}

	/** Columns of leading whitespace, a tab reaching the next multiple of 4. */
	private static int indentOf(String line)
	{
		int col = 0;
		for (int i = 0; i < line.length(); i++)
		{
			char c = line.charAt(i);
			if (c == ' ')
			{
				col++;
			}
			else if (c == '\t')
			{
				col += 4 - col % 4;
			}
			else
			{
				break;
			}
		}
		return col;
	}

	private static String stripIndent(String line)
	{
		int i = 0;
		while (i < line.length() && (line.charAt(i) == ' ' || line.charAt(i) == '\t'))
		{
			i++;
		}
		return line.substring(i);
	}

	/** Takes up to {@code cols} columns of indentation off the line (code inside a list item), tabs made spaces. */
	private static String removeIndent(String line, int cols)
	{
		String expanded = expandTabs(line);
		int i = 0;
		while (i < cols && i < expanded.length() && expanded.charAt(i) == ' ')
		{
			i++;
		}
		return expanded.substring(i);
	}

	/** Tabs as spaces up to the next multiple of 4: Swing's tab stops would be far too wide in code. */
	private static String expandTabs(String line)
	{
		if (line.indexOf('\t') < 0)
		{
			return line;
		}
		StringBuilder out = new StringBuilder();
		for (int i = 0; i < line.length(); i++)
		{
			char c = line.charAt(i);
			if (c == '\t')
			{
				out.append(repeat(' ', 4 - out.length() % 4));
			}
			else
			{
				out.append(c);
			}
		}
		return out.toString();
	}

	/** {@code dest} if it's an http or https address that can be opened, else null. */
	static String linkUrl(String dest)
	{
		if (!startsWithIgnoreCase(dest, 0, "http://") && !startsWithIgnoreCase(dest, 0, "https://"))
		{
			return null;
		}
		return HttpUrl.parse(dest) != null ? dest : null;
	}

	private static boolean startsWithIgnoreCase(String s, int at, String prefix)
	{
		return s.regionMatches(true, at, prefix, 0, prefix.length());
	}

	private static boolean isWhitespace(char c)
	{
		return Character.isWhitespace(c) || Character.isSpaceChar(c);
	}

	private static boolean isPunctuation(char c)
	{
		if (c < 128)
		{
			return ASCII_PUNCTUATION.indexOf(c) >= 0;
		}
		switch (Character.getType(c))
		{
			case Character.CONNECTOR_PUNCTUATION:
			case Character.DASH_PUNCTUATION:
			case Character.START_PUNCTUATION:
			case Character.END_PUNCTUATION:
			case Character.INITIAL_QUOTE_PUNCTUATION:
			case Character.FINAL_QUOTE_PUNCTUATION:
			case Character.OTHER_PUNCTUATION:
			case Character.MATH_SYMBOL:
			case Character.CURRENCY_SYMBOL:
			case Character.MODIFIER_SYMBOL:
			case Character.OTHER_SYMBOL:
				return true;
			default:
				return false;
		}
	}

	/** An open list item: where its marker is and how far in a line must be to be part of it. */
	private static class Item
	{
		final int childIndent;
		final boolean numbered;
		final int number;

		Item(int markerIndent, int contentIndent, boolean numbered, int number)
		{
			// Lenient on purpose: "1. a" then "  - b" is meant as a nested list even though "b" isn't under "a".
			this.childIndent = Math.min(markerIndent + 2, contentIndent);
			this.numbered = numbered;
			this.number = number;
		}
	}

	/** "- ", "* ", "+ ", "1. " or "1) " starting a line. */
	private static class Marker
	{
		final boolean numbered;
		final int number;
		/** From the marker to its text, which is where the item's own content starts. */
		final int width;
		final String content;

		Marker(boolean numbered, int number, int width, String content)
		{
			this.numbered = numbered;
			this.number = number;
			this.width = width;
			this.content = content;
		}

		static Marker read(String rest)
		{
			if (rest.isEmpty())
			{
				return null;
			}
			char c = rest.charAt(0);
			int end;
			int number = 0;
			boolean numbered = false;
			if (c == '-' || c == '*' || c == '+')
			{
				end = 1;
			}
			else
			{
				int i = 0;
				while (i < rest.length() && i < 9 && rest.charAt(i) >= '0' && rest.charAt(i) <= '9')
				{
					i++;
				}
				if (i == 0 || i >= rest.length() || (rest.charAt(i) != '.' && rest.charAt(i) != ')'))
				{
					return null;
				}
				number = Integer.parseInt(rest.substring(0, i));
				numbered = true;
				end = i + 1;
			}
			// "-5 coins" and "1.5m" aren't list items.
			if (end < rest.length() && rest.charAt(end) != ' ' && rest.charAt(end) != '\t')
			{
				return null;
			}
			int spaces = 0;
			while (end + spaces < rest.length() && (rest.charAt(end + spaces) == ' ' || rest.charAt(end + spaces) == '\t'))
			{
				spaces++;
			}
			String content = rest.substring(end + spaces).trim();
			return new Marker(numbered, number, end + (spaces >= 1 && spaces <= 4 ? spaces : 1), content);
		}
	}

	/**
	 * Reads lines into blocks. Close to CommonMark, but a single line break stays a line break (replies are often
	 * written line by line), nesting is lenient, and there are no setext headings, indented code or HTML blocks.
	 */
	private static class BlockParser
	{
		private final List<String> lines;
		private final List<Block> blocks = new ArrayList<>();
		/** The list items the next line may still be part of, outermost first. */
		private final List<Item> items = new ArrayList<>();
		private int pos;
		/** The paragraph, list item or quote being read, or null. */
		private StringBuilder text;
		private BlockKind textKind;
		private int textDepth;
		private int textNumber;

		BlockParser(List<String> lines)
		{
			this.lines = lines;
		}

		List<Block> parse()
		{
			while (pos < lines.size())
			{
				String line = lines.get(pos++);
				if (line.isBlank())
				{
					endText();
				}
				else
				{
					readLine(line);
				}
			}
			endText();
			return blocks;
		}

		private void readLine(String line)
		{
			int indent = indentOf(line);
			String rest = stripIndent(line).stripTrailing();

			int[] fence = fence(rest);
			if (fence != null)
			{
				int depth = enter(indent);
				endText();
				readCode((char) fence[0], fence[1], indent, depth);
				return;
			}
			if (isRule(rest))
			{
				int depth = enter(indent);
				endText();
				blocks.add(new Block(BlockKind.RULE, 0, depth, 0, Collections.emptyList(), Collections.emptyList()));
				return;
			}
			int level = headingLevel(rest);
			if (level > 0)
			{
				int depth = enter(indent);
				endText();
				blocks.add(new Block(BlockKind.HEADING, level, depth, 0, inline(headingText(rest, level)), Collections.emptyList()));
				return;
			}
			if (rest.startsWith(">"))
			{
				readQuote(indent, quoteContent(rest));
				return;
			}
			if (tableStartsAt(rest))
			{
				int depth = enter(indent);
				endText();
				readTable(rest, depth);
				return;
			}
			Marker marker = Marker.read(rest);
			if (marker != null && canStartItem(marker))
			{
				startItem(indent, marker);
				return;
			}
			if (text != null && textKind != BlockKind.QUOTE)
			{
				// The next line of the same paragraph or item, however it's indented.
				if (text.length() > 0)
				{
					text.append('\n');
				}
				text.append(rest);
				return;
			}
			int depth = enter(indent);
			endText();
			startText(BlockKind.PARAGRAPH, depth, 0, rest);
		}

		/** Leaves the list items that a line indented this much isn't part of; returns how many it's still in. */
		private int enter(int indent)
		{
			while (!items.isEmpty() && indent < items.get(items.size() - 1).childIndent)
			{
				items.remove(items.size() - 1);
			}
			return items.size();
		}

		/**
		 * Like CommonMark, a list only interrupts a paragraph when it clearly starts one, so "Released in\n2023. It
		 * was..." stays a paragraph.
		 */
		private boolean canStartItem(Marker m)
		{
			if (text == null || textKind != BlockKind.PARAGRAPH)
			{
				return true;
			}
			return !m.content.isEmpty() && (!m.numbered || m.number == 1);
		}

		private void startItem(int indent, Marker m)
		{
			endText();
			Item sibling = null;
			while (!items.isEmpty() && indent < items.get(items.size() - 1).childIndent)
			{
				sibling = items.remove(items.size() - 1);
			}
			int depth = items.size();
			// Numbered like CommonMark: the first item's number, then counting up, whatever the later ones say.
			int number = m.numbered && sibling != null && sibling.numbered ? sibling.number + 1 : m.number;
			items.add(new Item(indent, indent + m.width, m.numbered, number));
			startText(m.numbered ? BlockKind.NUMBERED : BlockKind.BULLET, depth, number, m.content);
		}

		private void readQuote(int indent, String content)
		{
			if (text != null && textKind == BlockKind.QUOTE)
			{
				if (content.isEmpty())
				{
					// A ">" line on its own separates paragraphs inside the quote.
					endText();
				}
				else
				{
					text.append('\n').append(content);
				}
				return;
			}
			int depth = enter(indent);
			endText();
			if (!content.isEmpty())
			{
				startText(BlockKind.QUOTE, depth, 0, content);
			}
		}

		private void readCode(char fenceChar, int fenceLength, int indent, int depth)
		{
			List<String> code = new ArrayList<>();
			while (pos < lines.size())
			{
				String line = lines.get(pos++);
				if (closesFence(stripIndent(line), fenceChar, fenceLength))
				{
					break;
				}
				code.add(removeIndent(line, indent));
			}
			// An unclosed fence (a reply still streaming) runs to the end, like CommonMark.
			blocks.add(new Block(BlockKind.CODE, 0, depth, 0, Collections.emptyList(), code));
		}

		/** This line has cells, and the next one is a delimiter row ("|---|:--:|") with as many. */
		private boolean tableStartsAt(String rest)
		{
			if (pos >= lines.size() || rest.indexOf('|') < 0)
			{
				return false;
			}
			int[] align = delimiterRow(lines.get(pos));
			return align != null && align.length == splitCells(rest).size();
		}

		private void readTable(String header, int depth)
		{
			int[] align = delimiterRow(lines.get(pos++));
			List<List<List<Span>>> cells = new ArrayList<>();
			cells.add(tableCells(header, align.length));
			while (pos < lines.size() && !lines.get(pos).isBlank() && lines.get(pos).indexOf('|') >= 0)
			{
				cells.add(tableCells(lines.get(pos++), align.length));
			}
			// As text, formatting marks dropped: how it's copied, and shown when it's too big to draw.
			List<List<String>> rows = new ArrayList<>();
			for (List<List<Span>> row : cells)
			{
				List<String> plain = new ArrayList<>();
				for (List<Span> cell : row)
				{
					plain.add(plainText(cell, false));
				}
				rows.add(plain);
			}
			boolean drawn = rows.size() <= MAX_TABLE_ROWS && linesUp(rows, columnChars(rows, align.length));
			if (drawn)
			{
				// Every row as many cells as there are columns, for the drawing.
				for (List<List<Span>> row : cells)
				{
					while (row.size() < align.length)
					{
						row.add(Collections.emptyList());
					}
				}
			}
			blocks.add(new Block(BlockKind.TABLE, 0, depth, 0, Collections.emptyList(), tableLines(rows, align),
				drawn ? new Table(align, cells) : null));
		}

		private void startText(BlockKind kind, int depth, int number, String first)
		{
			text = new StringBuilder(first);
			textKind = kind;
			textDepth = depth;
			textNumber = number;
		}

		private void endText()
		{
			if (text != null)
			{
				blocks.add(new Block(textKind, 0, textDepth, textNumber, inline(text.toString()), Collections.emptyList()));
				text = null;
			}
		}
	}

	/** "```" or "~~~" (or longer) opening a code block: {fence character, length}, or null. */
	private static int[] fence(String rest)
	{
		if (rest.length() < 3 || (rest.charAt(0) != '`' && rest.charAt(0) != '~'))
		{
			return null;
		}
		char c = rest.charAt(0);
		int n = 0;
		while (n < rest.length() && rest.charAt(n) == c)
		{
			n++;
		}
		// "```js```" on one line is inline code, not a fence.
		if (n < 3 || (c == '`' && rest.indexOf('`', n) >= 0))
		{
			return null;
		}
		return new int[]{c, n};
	}

	private static boolean closesFence(String rest, char c, int length)
	{
		int n = 0;
		while (n < rest.length() && rest.charAt(n) == c)
		{
			n++;
		}
		return n >= length && rest.substring(n).isBlank();
	}

	/** "---", "***", "___" or spaced out like "* * *". */
	private static boolean isRule(String rest)
	{
		char c = rest.charAt(0);
		if (c != '-' && c != '*' && c != '_')
		{
			return false;
		}
		int n = 0;
		for (int i = 0; i < rest.length(); i++)
		{
			char ch = rest.charAt(i);
			if (ch == c)
			{
				n++;
			}
			else if (ch != ' ' && ch != '\t')
			{
				return false;
			}
		}
		return n >= 3;
	}

	/** 1 to 6 for "# Title" to "###### Title", else 0 ("#hashtag" isn't a heading). */
	private static int headingLevel(String rest)
	{
		int n = 0;
		while (n < rest.length() && rest.charAt(n) == '#')
		{
			n++;
		}
		if (n == 0 || n > 6 || (n < rest.length() && rest.charAt(n) != ' ' && rest.charAt(n) != '\t'))
		{
			return 0;
		}
		return n;
	}

	private static String headingText(String rest, int level)
	{
		String s = rest.substring(level).trim();
		int end = s.length();
		while (end > 0 && s.charAt(end - 1) == '#')
		{
			end--;
		}
		// Closing hashes ("## Title ##") aren't part of the title, but the one in "C#" is.
		if (end == 0)
		{
			return "";
		}
		if (end < s.length() && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t'))
		{
			return s.substring(0, end).trim();
		}
		return s;
	}

	/** The text after the ">" marks (all of them: a quote inside a quote is shown as one). */
	private static String quoteContent(String rest)
	{
		int i = 0;
		while (i < rest.length() && rest.charAt(i) == '>')
		{
			i++;
			while (i < rest.length() && (rest.charAt(i) == ' ' || rest.charAt(i) == '\t'))
			{
				i++;
			}
		}
		return rest.substring(i).trim();
	}

	/** The alignment of each column if the line is a table's delimiter row ("| --- | :-: | --: |"), else null. */
	private static int[] delimiterRow(String line)
	{
		if (line.indexOf('|') < 0)
		{
			// "---" alone is a rule.
			return null;
		}
		List<String> cells = splitCells(line.trim());
		int[] align = new int[cells.size()];
		for (int c = 0; c < cells.size(); c++)
		{
			String cell = cells.get(c);
			boolean left = cell.startsWith(":");
			boolean right = cell.endsWith(":");
			String dashes = cell.substring(left ? 1 : 0, Math.max(left ? 1 : 0, cell.length() - (right ? 1 : 0)));
			if (dashes.isEmpty() || !dashes.chars().allMatch(ch -> ch == '-'))
			{
				return null;
			}
			align[c] = right && left ? ALIGN_CENTER : right ? ALIGN_RIGHT : ALIGN_LEFT;
		}
		return align;
	}

	/** A table row's cells, the first {@code columns} of them: those past the header's are left out. */
	private static List<List<Span>> tableCells(String line, int columns)
	{
		List<List<Span>> cells = new ArrayList<>();
		for (String cell : splitCells(line.trim()))
		{
			if (cells.size() == columns)
			{
				break;
			}
			cells.add(inline(cell));
		}
		return cells;
	}

	/** Splits a row at its "|"s (not "\|"), without the optional ones at either end. Cells come back trimmed. */
	private static List<String> splitCells(String row)
	{
		int start = row.startsWith("|") ? 1 : 0;
		int end = row.length();
		if (end > start && row.charAt(end - 1) == '|' && (end < 2 || row.charAt(end - 2) != '\\'))
		{
			end--;
		}
		List<String> cells = new ArrayList<>();
		StringBuilder cell = new StringBuilder();
		for (int i = start; i < end; i++)
		{
			char c = row.charAt(i);
			if (c == '\\' && i + 1 < end && row.charAt(i + 1) == '|')
			{
				cell.append('|');
				i++;
			}
			else if (c == '|')
			{
				cells.add(cell.toString().trim());
				cell.setLength(0);
			}
			else
			{
				cell.append(c);
			}
		}
		cells.add(cell.toString().trim());
		return cells;
	}

	static List<Span> inline(String text)
	{
		return new InlineParser(text, true).parse();
	}

	/** A piece of a block's text on its way to becoming spans. */
	private static class Node
	{
		static final int TEXT = 0;
		static final int CODE = 1;
		static final int LINK = 2;
		/** A run of "*" or "_" that may open or close bold or italic. */
		static final int DELIMITER = 3;

		final int type;
		final String text;
		final String url;
		final int index;
		final char ch;
		/** The run's length as written, and how much of it is still unused (shown as text if it stays unused). */
		final int length;
		int count;
		final boolean canOpen;
		final boolean canClose;

		Node(int type, String text, String url, int index, char ch, int length, boolean canOpen, boolean canClose)
		{
			this.type = type;
			this.text = text;
			this.url = url;
			this.index = index;
			this.ch = ch;
			this.length = length;
			this.count = length;
			this.canOpen = canOpen;
			this.canClose = canClose;
		}
	}

	/**
	 * Inline Markdown, after CommonMark: code spans first, then links, then "*" and "_" paired up by the spec's
	 * delimiter rules (so "snake_case_name" isn't italic, and "**bold *both* bold**" nests). Linear time, even for
	 * odd input like thousands of "[" or "*": replies are re-read many times a second while they stream.
	 */
	private static class InlineParser
	{
		private final String s;
		private final int n;
		/** False for text that isn't Markdown: only bare addresses are picked out. */
		private final boolean markdown;
		private final List<Node> nodes = new ArrayList<>();
		private final List<Node> delimiters = new ArrayList<>();
		private final StringBuilder text = new StringBuilder();
		/** Lengths of backtick runs known to have no closing run further on. */
		private final BitSet noCloser = new BitSet();
		/** How far bare addresses have been read: nothing before here ends one. */
		private int addressScanned;

		InlineParser(String s, boolean markdown)
		{
			this.s = s;
			this.n = s.length();
			this.markdown = markdown;
		}

		List<Span> parse()
		{
			int i = 0;
			while (i < n)
			{
				char c = s.charAt(i);
				int next = -1;
				if ((c == 'h' || c == 'H') && (i == 0 || !Character.isLetterOrDigit(s.charAt(i - 1))))
				{
					next = bareUrl(i);
				}
				else if (!markdown)
				{
					next = -1;
				}
				else if (c == '\\' && i + 1 < n && ASCII_PUNCTUATION.indexOf(s.charAt(i + 1)) >= 0)
				{
					text.append(s.charAt(i + 1));
					next = i + 2;
				}
				else if (c == '\\' && i + 1 < n && s.charAt(i + 1) == '\n')
				{
					// A backslash at the end of a line is Markdown for a line break, which lines already are here.
					next = i + 1;
				}
				else if (c == '`')
				{
					next = codeSpan(i);
				}
				else if (c == '[')
				{
					next = link(i);
				}
				else if (c == '!' && i + 1 < n && s.charAt(i + 1) == '[')
				{
					// An image: never loaded, but its address is still a link.
					next = link(i + 1);
				}
				else if (c == '<')
				{
					next = autolink(i);
				}
				else if (c == '*' || c == '_')
				{
					next = delimiterRun(i);
				}
				if (next < 0)
				{
					text.append(c);
					next = i + 1;
				}
				i = next;
			}
			flushText();
			return spans(emphasis());
		}

		private void flushText()
		{
			if (text.length() > 0)
			{
				nodes.add(new Node(Node.TEXT, text.toString(), null, nodes.size(), '\0', 0, false, false));
				text.setLength(0);
			}
		}

		private void add(int type, String content, String url)
		{
			flushText();
			nodes.add(new Node(type, content, url, nodes.size(), '\0', 0, false, false));
		}

		private int runLength(int i, char c)
		{
			int j = i;
			while (j < n && s.charAt(j) == c)
			{
				j++;
			}
			return j - i;
		}

		/** "`code`" or "``code with ` in it``": the index after it, or -1 if the run of backticks isn't closed. */
		private int codeSpan(int i)
		{
			int run = runLength(i, '`');
			int close = noCloser.get(run) ? -1 : findCloser(i + run, run);
			if (close < 0)
			{
				noCloser.set(run);
				text.append(repeat('`', run));
				return i + run;
			}
			String code = s.substring(i + run, close).replace('\n', ' ');
			if (code.length() >= 2 && code.startsWith(" ") && code.endsWith(" ") && !code.isBlank())
			{
				code = code.substring(1, code.length() - 1);
			}
			add(Node.CODE, code, null);
			return close + run;
		}

		private int findCloser(int from, int run)
		{
			int j = from;
			while (j < n)
			{
				if (s.charAt(j) == '`')
				{
					int length = runLength(j, '`');
					if (length == run)
					{
						return j;
					}
					j += length;
				}
				else
				{
					j++;
				}
			}
			return -1;
		}

		/** "[text](address)" at {@code i}: the index after it, or -1. Link text can't contain "[" or a line break. */
		private int link(int i)
		{
			int j = i + 1;
			int limit = Math.min(n, i + 1 + MAX_LABEL);
			while (j < limit)
			{
				char c = s.charAt(j);
				if (c == '\\' && j + 1 < n && s.charAt(j + 1) != '\n')
				{
					j += 2;
					continue;
				}
				if (c == ']' || c == '[' || c == '\n')
				{
					break;
				}
				j++;
			}
			if (j + 1 >= n || s.charAt(j) != ']' || s.charAt(j + 1) != '(')
			{
				return -1;
			}
			String label = s.substring(i + 1, j);
			int k = skipSpaces(j + 2);
			String dest;
			if (k < n && s.charAt(k) == '<')
			{
				int close = k + 1;
				while (close < n && close - k <= MAX_URL && s.charAt(close) != '>' && s.charAt(close) != '<' && s.charAt(close) != '\n')
				{
					close++;
				}
				if (close >= n || s.charAt(close) != '>')
				{
					return -1;
				}
				dest = s.substring(k + 1, close);
				k = close + 1;
			}
			else
			{
				StringBuilder d = new StringBuilder();
				int depth = 0;
				int start = k;
				while (k < n && k - start <= MAX_URL)
				{
					char c = s.charAt(k);
					if (c == '\\' && k + 1 < n && ASCII_PUNCTUATION.indexOf(s.charAt(k + 1)) >= 0)
					{
						d.append(s.charAt(k + 1));
						k += 2;
						continue;
					}
					if (c <= ' ')
					{
						break;
					}
					// Balanced brackets belong to the address: wiki pages like "Rune_platebody_(g)". No real address nests
					// them deeply (CommonMark's reference parser stops at 32 too).
					if (c == '(' && ++depth > 32)
					{
						return -1;
					}
					else if (c == ')')
					{
						if (depth == 0)
						{
							break;
						}
						depth--;
					}
					d.append(c);
					k++;
				}
				dest = d.toString();
			}
			k = skipSpaces(k);
			if (k < n && (s.charAt(k) == '"' || s.charAt(k) == '\'' || (s.charAt(k) == '(' && k > 0 && s.charAt(k - 1) <= ' ')))
			{
				// A title ("[text](address "title")"), which isn't shown.
				char close = s.charAt(k) == '(' ? ')' : s.charAt(k);
				int end = s.indexOf(close, k + 1);
				if (end < 0 || end - k > MAX_URL)
				{
					return -1;
				}
				k = skipSpaces(end + 1);
			}
			if (k >= n || s.charAt(k) != ')')
			{
				return -1;
			}
			String shown = plainText(new InlineParser(label, true).parse(), false);
			String url = linkUrl(dest);
			if (url == null)
			{
				// Not a web address (javascript:, file:, a relative path): the text alone, as text.
				text.append(shown);
			}
			else
			{
				add(Node.LINK, shown.isBlank() ? url : shown, url);
			}
			return k + 1;
		}

		private int skipSpaces(int k)
		{
			while (k < n && (s.charAt(k) == ' ' || s.charAt(k) == '\t'))
			{
				k++;
			}
			return k;
		}

		/** "<https://...>": the index after it, or -1. Anything else in angle brackets (HTML) stays text. */
		private int autolink(int i)
		{
			for (int j = i + 1; j < n && j - i <= MAX_URL; j++)
			{
				char c = s.charAt(j);
				if (c == '>')
				{
					String url = linkUrl(s.substring(i + 1, j));
					if (url == null)
					{
						return -1;
					}
					add(Node.LINK, url, url);
					return j + 1;
				}
				if (c == '<' || c <= ' ')
				{
					return -1;
				}
			}
			return -1;
		}

		/** A bare "https://..." address: the index after it (trailing punctuation left out), or -1. */
		private int bareUrl(int i)
		{
			int host = startsWithIgnoreCase(s, i, "https://") ? i + 8 : startsWithIgnoreCase(s, i, "http://") ? i + 7 : -1;
			if (host < 0 || host >= n || !Character.isLetterOrDigit(s.charAt(host)))
			{
				return -1;
			}
			// Where the address stops: a space, a quote, angle brackets. What's before addressScanned has been looked
			// at already, so odd text like "http://a(http://a(..." isn't read again for every "http".
			int end = Math.max(host, addressScanned);
			while (end < n && end - i <= MAX_URL && !endsAddress(s.charAt(end)))
			{
				end++;
			}
			addressScanned = end;
			if (end - i > MAX_URL)
			{
				return -1;
			}
			int opens = 0;
			int closes = 0;
			int squareOpens = 0;
			int squareCloses = 0;
			for (int k = i; k < end; k++)
			{
				char c = s.charAt(k);
				opens += c == '(' ? 1 : 0;
				closes += c == ')' ? 1 : 0;
				squareOpens += c == '[' ? 1 : 0;
				squareCloses += c == ']' ? 1 : 0;
			}
			while (end > i)
			{
				char c = s.charAt(end - 1);
				if (URL_TRAILERS.indexOf(c) >= 0)
				{
					end--;
				}
				else if (c == ')' && closes > opens)
				{
					// "(see https://example.com)": the bracket closes the sentence's, not the address's.
					closes--;
					end--;
				}
				else if (c == ']' && squareCloses > squareOpens)
				{
					squareCloses--;
					end--;
				}
				else
				{
					break;
				}
			}
			String url = linkUrl(s.substring(i, end));
			if (url == null)
			{
				return -1;
			}
			add(Node.LINK, url, url);
			return end;
		}

		private static boolean endsAddress(char c)
		{
			return isWhitespace(c) || c == '<' || c == '>' || c == '"' || c == '`';
		}

		private int delimiterRun(int i)
		{
			char c = s.charAt(i);
			int length = runLength(i, c);
			char before = i == 0 ? ' ' : s.charAt(i - 1);
			char after = i + length >= n ? ' ' : s.charAt(i + length);
			boolean leftFlanking = !isWhitespace(after) && (!isPunctuation(after) || isWhitespace(before) || isPunctuation(before));
			boolean rightFlanking = !isWhitespace(before) && (!isPunctuation(before) || isWhitespace(after) || isPunctuation(after));
			boolean canOpen;
			boolean canClose;
			if (c == '*')
			{
				canOpen = leftFlanking;
				canClose = rightFlanking;
			}
			else
			{
				// "_" inside a word (snake_case, wiki_page_names) is just a character.
				canOpen = leftFlanking && (!rightFlanking || isPunctuation(before));
				canClose = rightFlanking && (!leftFlanking || isPunctuation(after));
			}
			flushText();
			Node run = new Node(Node.DELIMITER, null, null, nodes.size(), c, length, canOpen, canClose);
			nodes.add(run);
			delimiters.add(run);
			return i + length;
		}

		/**
		 * Pairs up the delimiter runs (CommonMark's "process emphasis", with its stack bottoms so it stays linear).
		 * Returns how bold and italic change at each node: +1 where a pair's content starts, -1 at its closer.
		 */
		private int[][] emphasis()
		{
			int[][] change = new int[2][nodes.size() + 1];
			int m = delimiters.size();
			int[] prev = new int[m];
			int[] next = new int[m];
			for (int k = 0; k < m; k++)
			{
				prev[k] = k - 1;
				next[k] = k + 1;
			}
			int[] bottom = new int[12];
			Arrays.fill(bottom, -1);
			int ci = 0;
			while (ci < m)
			{
				Node closer = delimiters.get(ci);
				if (!closer.canClose || closer.count == 0)
				{
					ci = next[ci];
					continue;
				}
				int key = (closer.ch == '*' ? 0 : 6) + (closer.canOpen ? 3 : 0) + closer.length % 3;
				int oi = prev[ci];
				while (oi > bottom[key] && !pairs(delimiters.get(oi), closer))
				{
					oi = prev[oi];
				}
				if (oi > bottom[key])
				{
					Node opener = delimiters.get(oi);
					int use = opener.count >= 2 && closer.count >= 2 ? 2 : 1;
					int[] style = change[use == 2 ? 0 : 1];
					style[opener.index + 1]++;
					style[closer.index]--;
					opener.count -= use;
					closer.count -= use;
					// Runs between the two can't pair with anything any more.
					next[oi] = ci;
					prev[ci] = oi;
					if (opener.count == 0)
					{
						unlink(oi, prev, next);
					}
					if (closer.count == 0)
					{
						int after = next[ci];
						unlink(ci, prev, next);
						ci = after;
					}
				}
				else
				{
					// Nothing below here can open for a closer like this one: later ones needn't look again.
					bottom[key] = prev[ci];
					int after = next[ci];
					if (!closer.canOpen)
					{
						unlink(ci, prev, next);
					}
					ci = after;
				}
			}
			return change;
		}

		private static boolean pairs(Node opener, Node closer)
		{
			if (opener.ch != closer.ch || !opener.canOpen || opener.count == 0)
			{
				return false;
			}
			// CommonMark's "rule of 3", which keeps "*a**b*" from pairing the wrong way.
			boolean both = opener.canClose || closer.canOpen;
			return !(both && (opener.length + closer.length) % 3 == 0 && !(opener.length % 3 == 0 && closer.length % 3 == 0));
		}

		private static void unlink(int k, int[] prev, int[] next)
		{
			if (prev[k] >= 0)
			{
				next[prev[k]] = next[k];
			}
			if (next[k] < next.length)
			{
				prev[next[k]] = prev[k];
			}
		}

		private List<Span> spans(int[][] change)
		{
			List<Span> out = new ArrayList<>();
			StringBuilder run = new StringBuilder();
			SpanKind runKind = SpanKind.TEXT;
			int bold = 0;
			int italic = 0;
			for (Node node : nodes)
			{
				bold += change[0][node.index];
				italic += change[1][node.index];
				if (node.type == Node.CODE || node.type == Node.LINK)
				{
					addSpan(out, runKind, run);
					out.add(new Span(node.type == Node.CODE ? SpanKind.CODE : SpanKind.LINK, node.text, node.url));
					continue;
				}
				// Unpaired "*" and "_" are shown as they are.
				String t = node.type == Node.DELIMITER ? repeat(node.ch, node.count) : node.text;
				if (t.isEmpty())
				{
					continue;
				}
				SpanKind kind = bold > 0 ? (italic > 0 ? SpanKind.BOLD_ITALIC : SpanKind.BOLD) : (italic > 0 ? SpanKind.ITALIC : SpanKind.TEXT);
				if (kind != runKind)
				{
					addSpan(out, runKind, run);
					runKind = kind;
				}
				run.append(t);
			}
			addSpan(out, runKind, run);
			return out;
		}

		private static void addSpan(List<Span> out, SpanKind kind, StringBuilder run)
		{
			if (run.length() > 0)
			{
				out.add(new Span(kind, run.toString(), null));
				run.setLength(0);
			}
		}
	}
}

package com.aichat;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.text.StyleConstants;

/**
 * One message in the transcript, drawn the way chat apps draw them: the player's questions in a bubble on the right,
 * replies across the full width with one line above them saying what was shared and looked up, and small actions
 * under them, notes small and centred, errors in a red box. A row is made for one kind of message and shown again as
 * the chat changes, so a new message doesn't redraw every earlier one. Swing EDT only.
 */
abstract class MessageRow extends JPanel
{
	/** The player's bubbles take at most this share of the width, as in chat apps: the rest shows whose they are. */
	static final float BUBBLE_SHARE = 0.85f;

	/** What a row's buttons do, for the panel. */
	interface Actions
	{
		/** Retry on {@code m}, the chat's last message: sends its question again, or writes its reply again. */
		void retry(Chat.Message m);
	}

	/** The message shown, for the buttons; null for the reply on its way. */
	Chat.Message message;

	MessageRow(int gap)
	{
		super(new StackLayout(gap));
		setOpaque(false);
	}

	/** A row for a message of {@code m}'s kind. */
	static MessageRow of(Chat.Message m, Actions actions)
	{
		switch (m.role)
		{
			case USER:
				return new Question(actions);
			case ASSISTANT:
				return new Reply(actions);
			case ERROR:
				return new Problem(actions);
			default:
				return new Note(actions);
		}
	}

	/**
	 * Shows {@code m}. {@code latest}: it's the chat's latest reply, whose actions always show (an older one's show while
	 * the mouse is over it). {@code retry}: Retry goes on it, the chat's last message, which can be retried.
	 */
	abstract void show(Chat.Message m, boolean latest, boolean retry);

	/** Whether Retry is offered on this row now. */
	abstract boolean offersRetry();

	// ------------------------------------------------------------------
	// The kinds of message
	// ------------------------------------------------------------------

	/** The player's message: a bubble on the right, hugging short text, and what was sent with it under it. */
	static final class Question extends MessageRow
	{
		final Bubble bubble = new Bubble();
		/** Under a message sent with the character details: says so, and shows them when clicked. */
		final ShowMore shared = new ShowMore("Click to see what was sent with this message", StyleConstants.ALIGN_RIGHT);
		/** Only when RuneLite closed while the question waited, with nothing after it to carry Retry. */
		final FlatButton retry;
		private final JPanel retryRow = buttonRow(FlowLayout.RIGHT);

		Question(Actions actions)
		{
			super(3);
			retry = retryButton("Send this question again", actions, this);
			retryRow.add(retry);
			add(bubble);
			add(shared);
			add(retryRow);
		}

		@Override
		void show(Chat.Message m, boolean latest, boolean retry)
		{
			message = m;
			// What the assistant no longer sees as written is drawn fainter: the summary note stands in for it.
			bubble.body.setTextColor(m.summarized ? PanelStyle.MUTED_COLOR : PanelStyle.TEXT_COLOR);
			bubble.body.setPlainText(m.text);
			tip(PanelText.tooltip(m), bubble, bubble.body);
			shared.show(m.context == null || m.context.isEmpty() ? null : "Sent your character details", m.context);
			retryRow.setVisible(retry);
		}

		@Override
		boolean offersRetry()
		{
			return retryRow.isVisible();
		}
	}

	/**
	 * A reply: across the full width with no box, what was looked up or shared for it above it, and Copy and Retry
	 * under it. Also the reply on its way, with a line saying what it's doing while there are no new words.
	 */
	static final class Reply extends MessageRow
	{
		final ShowMore activity = activityLine(StyleConstants.ALIGN_LEFT);
		final MessageView body = new MessageView();
		/** "Thinking..." and the like under the reply on its way; under a reply that broke off, that it didn't finish. */
		final MessageView status = mutedLine(StyleConstants.ALIGN_LEFT);
		final ActionBar actions;
		private boolean latest;
		private boolean hovered;

		Reply(Actions handler)
		{
			super(4);
			actions = new ActionBar(this, handler);
			body.setTextFont(PanelStyle.TEXT_FONT);
			add(activity);
			add(body);
			add(status);
			add(actions);
			trackHover(this, over ->
			{
				hovered = over;
				actions.setShown(latest || hovered);
			});
		}

		@Override
		void show(Chat.Message m, boolean latest, boolean retry)
		{
			message = m;
			this.latest = latest;
			showActivity(activity, m.activity);
			body.setTextColor(m.summarized ? PanelStyle.MUTED_COLOR : PanelStyle.TEXT_COLOR);
			body.setMarkdown(m.text);
			body.setVisible(true);
			tip(PanelText.tooltip(m), body);
			status.setPlainText(m.unfinished ? "This reply didn't finish." : "");
			status.setVisible(m.unfinished);
			actions.setVisible(true);
			actions.retry.setToolTipText(m.unfinished ? "Send the question again"
				: "Write this reply again: the same question goes again");
			actions.show(latest || hovered, retry);
		}

		/**
		 * The reply on its way. {@code text}: null until its first words; {@code lines}: what it has looked up so far;
		 * {@code line}: what it's doing, or null while it writes.
		 */
		void showLive(String who, String text, List<String> lines, String line)
		{
			message = null;
			showActivity(activity, lines);
			body.setTextColor(PanelStyle.TEXT_COLOR);
			body.setMarkdown(text);
			body.setVisible(text != null);
			tip(who == null ? null : who + " is answering", body);
			status.setPlainText(line == null ? "" : line);
			status.setVisible(line != null);
			// Nothing to copy or retry until it's in.
			actions.setVisible(false);
		}

		@Override
		boolean offersRetry()
		{
			return actions.isVisible() && actions.offersRetry();
		}
	}

	/**
	 * A note from AI Chat (a summary, "Stopped.", a chat too long for the model): small, muted and centred, between the
	 * messages rather than one of them. A summary's note shows the summary a click away.
	 */
	static final class Note extends MessageRow
	{
		final ShowMore activity = activityLine(StyleConstants.ALIGN_CENTER);
		final ShowMore text = new ShowMore("Click to see the summary that's sent instead of them", StyleConstants.ALIGN_CENTER);
		final FlatButton retry;
		private final JPanel retryRow = buttonRow(FlowLayout.CENTER);

		Note(Actions actions)
		{
			super(2);
			setBorder(new EmptyBorder(2, 12, 2, 12));
			retry = retryButton("Send the question again", actions, this);
			retryRow.add(retry);
			add(activity);
			add(text);
			add(retryRow);
		}

		@Override
		void show(Chat.Message m, boolean latest, boolean retry)
		{
			message = m;
			showActivity(activity, m.activity);
			PanelText.Note note = PanelText.note(m.text);
			text.setPlainTip(PanelText.tooltip(m));
			text.show(note.line, note.details);
			retryRow.setVisible(retry);
		}

		@Override
		boolean offersRetry()
		{
			return retryRow.isVisible();
		}
	}

	/** An error: in a red outlined box, with Retry inside it when the question can go again. */
	static final class Problem extends MessageRow
	{
		final ShowMore activity = activityLine(StyleConstants.ALIGN_LEFT);
		final MessageView body = new MessageView();
		final FlatButton retry;
		private final JPanel retryRow = buttonRow(FlowLayout.LEFT);

		Problem(Actions actions)
		{
			super(4);
			retry = retryButton("Send the question again", actions, this);
			retry.setForeground(PanelStyle.TEXT_COLOR);
			retryRow.add(retry);
			RoundBox box = new RoundBox(new StackLayout(4), new Color(255, 107, 107, 22), PanelStyle.ERROR_COLOR);
			box.setBorder(new EmptyBorder(6, 8, 6, 8));
			body.setTextColor(PanelStyle.ERROR_COLOR);
			box.add(body);
			box.add(retryRow);
			add(activity);
			add(box);
		}

		@Override
		void show(Chat.Message m, boolean latest, boolean retry)
		{
			message = m;
			showActivity(activity, m.activity);
			body.setPlainText(m.text);
			tip(PanelText.tooltip(m), body);
			retryRow.setVisible(retry);
		}

		@Override
		boolean offersRetry()
		{
			return retryRow.isVisible();
		}
	}

	// ------------------------------------------------------------------
	// Parts
	// ------------------------------------------------------------------

	/** The player's words in a rounded bubble, as wide as they need up to {@link #BUBBLE_SHARE} of the row. */
	static final class Bubble extends RoundBox implements StackLayout.Fitted
	{
		final MessageView body = new MessageView();

		Bubble()
		{
			super(new BorderLayout(), PanelStyle.BUBBLE_COLOR, null);
			setBorder(new EmptyBorder(6, 10, 6, 10));
			setAlignmentX(RIGHT_ALIGNMENT);
			body.setTextFont(PanelStyle.TEXT_FONT);
			add(body, BorderLayout.CENTER);
		}

		@Override
		public int fittedWidth(int available)
		{
			int padding = getInsets().left + getInsets().right;
			return Math.min(body.naturalWidth() + padding, Math.round(available * BUBBLE_SHARE));
		}
	}

	/**
	 * Copy and Retry under a reply. It keeps its height while its buttons are hidden, so the transcript doesn't jump when
	 * the mouse comes over a reply and they appear.
	 */
	static final class ActionBar extends JPanel
	{
		/** How long Copy says "Copied". */
		private static final int COPIED_MILLIS = 1500;

		final FlatButton copy = new FlatButton("Copy", new Glyph(Glyph.Shape.COPY, 12), "Copy this reply as plain text");
		final FlatButton retry = new FlatButton("Retry", new Glyph(Glyph.Shape.RETRY, 12), null);
		private final Timer copied = new Timer(COPIED_MILLIS, e -> copy.setText("Copy"));
		private boolean shown;
		private boolean retryOffered;

		ActionBar(Reply reply, Actions actions)
		{
			super(new FlowLayout(FlowLayout.LEFT, 0, 0));
			setOpaque(false);
			copied.setRepeats(false);
			copy.addActionListener(e ->
			{
				reply.body.copyAll();
				copy.setText("Copied");
				copied.restart();
			});
			retry.addActionListener(e ->
			{
				if (reply.message != null)
				{
					actions.retry(reply.message);
				}
			});
			add(copy);
			add(retry);
			show(false, false);
		}

		/**
		 * Shows the buttons ({@code shown}), or hides them while keeping their place. {@code retry}: Retry is offered on
		 * this reply, and shows along with Copy.
		 */
		void show(boolean shown, boolean retry)
		{
			this.shown = shown;
			retryOffered = retry;
			copy.setVisible(shown);
			this.retry.setVisible(shown && retry);
			revalidate();
			repaint();
		}

		/** The mouse came over the reply or left it: the buttons show or hide, Retry still offered or not. */
		void setShown(boolean shown)
		{
			if (shown != this.shown)
			{
				show(shown, retryOffered);
			}
		}

		/** Whether the buttons show now (while the row is shown at all). */
		boolean isShown()
		{
			return shown;
		}

		boolean offersRetry()
		{
			return retryOffered;
		}

		@Override
		public Dimension getPreferredSize()
		{
			Dimension d = super.getPreferredSize();
			d.height = Math.max(d.height, copy.getPreferredSize().height);
			return d;
		}
	}

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------

	/**
	 * The line over a message saying what was looked up or shared for it, such as "Shared your equipment · Looked up 3
	 * things": hidden while nothing was.
	 */
	static ShowMore activityLine(int alignment)
	{
		return new ShowMore("Click to see everything that was shared and looked up for this message", alignment);
	}

	/**
	 * Shows {@code lines} (a message's {@link Chat.Message#activity}) on {@code line}: what was shared always named,
	 * then the look-ups by name or counted, as the width allows, and every line a click away.
	 */
	static void showActivity(ShowMore line, List<String> lines)
	{
		PanelText.Summary summary = PanelText.summary(lines);
		line.show(summary.isEmpty() ? null : summary::line, summary.details);
	}

	/** A small muted line of plain text. */
	static MessageView mutedLine(int alignment)
	{
		MessageView v = new MessageView();
		v.setTextFont(PanelStyle.SMALL_FONT);
		v.setTextColor(PanelStyle.MUTED_COLOR);
		v.setAlignment(alignment);
		v.setVisible(false);
		return v;
	}

	private static JPanel buttonRow(int align)
	{
		JPanel p = new JPanel(new FlowLayout(align, 0, 0));
		p.setOpaque(false);
		p.setVisible(false);
		return p;
	}

	private static FlatButton retryButton(String tip, Actions actions, MessageRow row)
	{
		FlatButton b = new FlatButton("Retry", new Glyph(Glyph.Shape.RETRY, 12), tip);
		b.addActionListener(e ->
		{
			if (row.message != null)
			{
				actions.retry(row.message);
			}
		});
		return b;
	}

	/** The message's tooltip, on each part of it the mouse can be over. */
	private static void tip(String tip, JComponent... parts)
	{
		for (JComponent c : parts)
		{
			c.setToolTipText(tip);
		}
	}

	/**
	 * Tells {@code hover} true when the mouse comes over {@code root} or anything in it, false when it leaves them all.
	 * Each part gets the listener, since the mouse over a part doesn't count as over the panel around it.
	 */
	static void trackHover(Container root, Consumer<Boolean> hover)
	{
		MouseAdapter listener = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover.accept(true);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Into another part of the same row is still over it.
				Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), root);
				hover.accept(root.contains(p));
			}
		};
		addDeep(root, listener);
	}

	private static void addDeep(Component c, MouseAdapter listener)
	{
		c.addMouseListener(listener);
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				addDeep(child, listener);
			}
		}
	}
}

package com.aichat;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Insets;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Rectangle2D;
import java.util.Collections;
import java.util.List;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.JTextPane;
import javax.swing.JToolTip;
import javax.swing.SwingUtilities;
import javax.swing.ToolTipManager;
import javax.swing.border.EmptyBorder;
import javax.swing.text.AbstractDocument;
import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.BoxView;
import javax.swing.text.DefaultCaret;
import javax.swing.text.DefaultStyledDocument;
import javax.swing.text.Element;
import javax.swing.text.LabelView;
import javax.swing.text.ParagraphView;
import javax.swing.text.SimpleAttributeSet;
import javax.swing.text.StyleConstants;
import javax.swing.text.StyledEditorKit;
import javax.swing.text.TabSet;
import javax.swing.text.TabStop;
import javax.swing.text.View;
import javax.swing.text.ViewFactory;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;
import okhttp3.HttpUrl;

/**
 * One message in the transcript, or a line about one: {@link Markdown} (or plain text) drawn with text attributes,
 * never as HTML. Read-only but selectable, see-through, and wrapped to whatever width its container gives it, with the
 * height to match (it works in {@link StackLayout} like a wrapped text area); it can also say how wide it would be
 * unwrapped, for a bubble that hugs a short message. Links show their address on hover and open in the browser on
 * click; right-click copies. Swing EDT only.
 *
 * <pre>
 * MessageView body = new MessageView();
 * body.setTextColor(Color.WHITE);
 * body.setMarkdown(reply);  // again with the longer text as it streams in: cheap, and skipped when unchanged
 * </pre>
 */
class MessageView extends JTextPane
{
	/** The character attribute holding a link's address. */
	static final Object LINK = new AttributeKey("link");
	/** The character attribute holding a table to draw, on the table's text: a {@link Markdown.Table}. */
	private static final Object TABLE = new AttributeKey("table");
	/** The paragraph attribute holding what to draw behind it: a {@link Decor}. */
	private static final Object DECOR = new AttributeKey("decor");

	/** The same font as the panel's other text. */
	private static final Font DEFAULT_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
	private static final Color LINK_COLOR = new Color(110, 180, 255);
	private static final Color QUOTE_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
	/** Translucent, so they suit both the player's and the assistant's bubble colours. */
	private static final Color CODE_BACKGROUND = new Color(255, 255, 255, 20);
	private static final Color CODE_SPAN_BACKGROUND = new Color(255, 255, 255, 30);
	private static final Color LINE_COLOR = new Color(255, 255, 255, 70);
	/** Space above a block, in pixels: between paragraphs, list items, and around headings. */
	private static final int BLOCK_GAP = 6;
	private static final int LIST_GAP = 4;
	private static final int ITEM_GAP = 2;
	private static final int HEADING_GAP = 8;
	private static final int AFTER_HEADING_GAP = 3;
	/** Space inside a code block's box, around the text. */
	private static final int CODE_PAD_X = 5;
	private static final int CODE_PAD_Y = 3;
	private static final int QUOTE_BAR_WIDTH = 2;
	private static final int QUOTE_INDENT = 9;
	/** Lists nested deeper than this aren't indented further: the panel is narrow. */
	private static final int MAX_INDENT_DEPTH = 4;
	/** A list marker is followed by a tab to this stop, so an item's text lines up with its wrapped lines. */
	private static final TabSet MARKER_TAB = new TabSet(new TabStop[]{new TabStop(0)});

	private String source = "";
	private boolean markdown = true;
	private List<Markdown.Block> blocks = Collections.emptyList();
	private Color textColor = Color.WHITE;
	private Font textFont = DEFAULT_FONT;
	/** How lines sit across the width: one of StyleConstants' ALIGN_LEFT, ALIGN_CENTER and ALIGN_RIGHT. */
	private int alignment = StyleConstants.ALIGN_LEFT;
	/** {@link #naturalWidth}, worked out once per text; -1 until then. */
	private int naturalWidth = -1;
	private boolean overLink;
	/** The latest mouse press or release opened the menu. */
	private boolean menuOpened;

	MessageView()
	{
		setEditorKit(new Kit());
		setEditable(false);
		setOpaque(false);
		setBorder(new EmptyBorder(0, 0, 0, 0));
		setCaret(new StillCaret());
		// Read-only, so the caret is never drawn: no need to keep a pixel free for it at the right edge.
		putClientProperty("caretWidth", 0);
		// Never HTML, whatever the content type might become; tooltips get the same in createToolTip.
		putClientProperty("html.disable", Boolean.TRUE);
		ToolTipManager.sharedInstance().registerComponent(this);

		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				showHand(linkAt(e.getPoint()) != null);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				showHand(false);
			}

			@Override
			public void mouseClicked(MouseEvent e)
			{
				// Not when the click opened the menu (a Ctrl-click on a Mac is both).
				String url = !menuOpened && SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1 ? linkAt(e.getPoint()) : null;
				if (url != null)
				{
					open(url);
				}
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				// The menu opens on press on some systems and on release on others.
				menuOpened = e.isPopupTrigger();
				if (menuOpened)
				{
					showMenu(e);
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (e.isPopupTrigger())
				{
					menuOpened = true;
					showMenu(e);
				}
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
		render();
	}

	/** Shows {@code text} as Markdown. Cheap to call again with the same text (nothing happens). */
	void setMarkdown(String text)
	{
		String t = text == null ? "" : text;
		if (markdown && t.equals(source))
		{
			return;
		}
		source = t;
		markdown = true;
		blocks = Markdown.parse(t);
		render();
	}

	/** Shows {@code text} as it is (the player's own words, errors), with only bare web addresses made links. */
	void setPlainText(String text)
	{
		String t = text == null ? "" : text;
		if (!markdown && t.equals(source))
		{
			return;
		}
		source = t;
		markdown = false;
		blocks = t.isEmpty() ? Collections.emptyList() : Collections.singletonList(
			new Markdown.Block(Markdown.BlockKind.PARAGRAPH, 0, 0, 0, Markdown.linkify(t), Collections.emptyList()));
		render();
	}

	/** The colour of ordinary text (links, quotes and code keep their own). */
	void setTextColor(Color color)
	{
		if (color != null && !color.equals(textColor))
		{
			textColor = color;
			render();
		}
	}

	/** The font of ordinary text; headings and code are sized from it. */
	void setTextFont(Font f)
	{
		if (f != null && !f.equals(textFont))
		{
			textFont = f;
			render();
		}
	}

	/** How lines sit across the width: StyleConstants.ALIGN_LEFT (the default), ALIGN_CENTER or ALIGN_RIGHT. */
	void setAlignment(int alignment)
	{
		if (alignment != this.alignment)
		{
			this.alignment = alignment;
			render();
		}
	}

	/** The text last given to {@link #setMarkdown} or {@link #setPlainText}. */
	String getSource()
	{
		return source;
	}

	/** The whole message as plain text, as the menu's "Copy message" puts it on the clipboard. */
	String plainText()
	{
		return markdown ? Markdown.plainText(blocks) : source;
	}

	/**
	 * The selection as plain text, with a table in it as its lines: in the document, a table's lines are kept apart by
	 * {@link TableView#ROW_BREAK}, as a line break would split it into paragraphs. Ctrl+C copies this too.
	 */
	@Override
	public String getSelectedText()
	{
		String selected = super.getSelectedText();
		return selected == null ? null : selected.replace(TableView.ROW_BREAK, "\n");
	}

	/** Copies the selection, or the whole message if nothing is selected. */
	void copyToClipboard()
	{
		String selected = getSelectedText();
		toClipboard(selected != null && !selected.isEmpty() ? selected : plainText());
	}

	/** Copies the whole message as plain text, whatever is selected. */
	void copyAll()
	{
		toClipboard(plainText());
	}

	/**
	 * How wide the text is without wrapping, its longest line, in pixels: what a bubble needs to hug a short message.
	 * Measured by the same views that lay the text out, so a box this wide holds it without a wrap.
	 */
	int naturalWidth()
	{
		if (naturalWidth < 0)
		{
			// The views' unwrapped width, which their wrapping doesn't change. Asked of the views themselves, not the
			// look and feel: its preferred size can be wider than the text (FlatLaf, which RuneLite's is built on, makes
			// every text component at least 64 pixels wide), which would put "ok" in a bubble far too big for it. One
			// more pixel for what rounding loses.
			Insets in = getInsets();
			float text = getUI().getRootView(this).getPreferredSpan(View.X_AXIS);
			naturalWidth = (int) Math.ceil(text) + in.left + in.right + 1;
		}
		return naturalWidth;
	}

	@Override
	public Dimension getPreferredSize()
	{
		Dimension d = super.getPreferredSize();
		// Wrapped text has no width of its own: a long line mustn't ask for a wider panel.
		if (getWidth() > 0)
		{
			d.width = getWidth();
		}
		return d;
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	/** A link's address over a link; anywhere else, the tooltip set on the view (the message's time, say), if any. */
	@Override
	public String getToolTipText(MouseEvent e)
	{
		String url = linkAt(e.getPoint());
		return url != null ? url : getToolTipText();
	}

	@Override
	public JToolTip createToolTip()
	{
		JToolTip tip = super.createToolTip();
		tip.putClientProperty("html.disable", Boolean.TRUE);
		return tip;
	}

	/**
	 * Builds the text into a new document and swaps it in: one layout instead of one per insert, and the old document
	 * keeps showing until the new one is complete. Each document has its own style context: a shared one would collect
	 * a listener from every document ever made.
	 */
	private void render()
	{
		DefaultStyledDocument doc = new DefaultStyledDocument();
		try
		{
			write(doc);
		}
		catch (BadLocationException e)
		{
			// Text only ever goes at the end of the document, which is always a valid place.
			throw new IllegalStateException(e);
		}
		int dot = getCaret().getDot();
		int mark = getCaret().getMark();
		naturalWidth = -1;
		setDocument(doc);
		// Keep a selection made while the reply streams in, as far as the new text allows.
		if (dot != mark && Math.max(dot, mark) <= doc.getLength())
		{
			getCaret().setDot(mark);
			getCaret().moveDot(dot);
		}
	}

	private void write(DefaultStyledDocument doc) throws BadLocationException
	{
		// Where the text of the latest list item at each depth starts: what's nested in it lines up there.
		int[] textStart = new int[MAX_INDENT_DEPTH + 1];
		for (int d = 0; d < textStart.length; d++)
		{
			textStart[d] = (d + 1) * 16;
		}
		Markdown.Block previous = null;
		AttributeSet tail = null;
		for (Markdown.Block b : blocks)
		{
			if (previous != null)
			{
				// Ends the previous block's last line, in its font, so that line keeps its own height.
				doc.insertString(doc.getLength(), "\n", tail);
			}
			tail = writeBlock(doc, b, gapBefore(previous, b), textStart);
			previous = b;
		}
	}

	/**
	 * Adds one block at the end of the document. Returns the attributes of its text, for the line break that ends it:
	 * a drawn table's own, so that the line break is part of the table's view, and not a sliver of text beside it (it
	 * would show a selection of its own there).
	 */
	private AttributeSet writeBlock(DefaultStyledDocument doc, Markdown.Block b, int gap, int[] textStart) throws BadLocationException
	{
		int start = doc.getLength();
		int depth = Math.min(b.depth, MAX_INDENT_DEPTH);
		int base = depth == 0 ? 0 : textStart[depth - 1];
		SimpleAttributeSet text = textAttributes();
		AttributeSet tail = text;
		// Paragraph attributes: for every line of the block, then extra ones for its first and last lines.
		SimpleAttributeSet lines = new SimpleAttributeSet();
		SimpleAttributeSet first = new SimpleAttributeSet();
		SimpleAttributeSet last = new SimpleAttributeSet();
		StyleConstants.setLeftIndent(lines, base);
		StyleConstants.setAlignment(lines, alignment);
		StyleConstants.setSpaceAbove(first, gap);
		switch (b.kind)
		{
			case HEADING:
				StyleConstants.setBold(text, true);
				StyleConstants.setFontSize(text, textFont.getSize() + Math.max(0, 4 - b.level));
				writeSpans(doc, b.spans, text);
				break;
			case BULLET:
			case NUMBERED:
				// The marker hangs out to the left, so wrapped lines line up with the item's text.
				String marker = b.kind == Markdown.BlockKind.BULLET ? "\u2022" : b.number + ".";
				int hang = markerWidth(marker, b.kind == Markdown.BlockKind.BULLET);
				StyleConstants.setLeftIndent(lines, base + hang);
				StyleConstants.setTabSet(lines, MARKER_TAB);
				StyleConstants.setFirstLineIndent(first, -hang);
				textStart[depth] = base + hang;
				doc.insertString(doc.getLength(), marker + "\t", text);
				writeSpans(doc, b.spans, text);
				break;
			case QUOTE:
				StyleConstants.setForeground(text, QUOTE_COLOR);
				StyleConstants.setLeftIndent(lines, base + QUOTE_INDENT);
				lines.addAttribute(DECOR, new Decor(Decor.BAR, LINE_COLOR, base, 0));
				first.addAttribute(DECOR, new Decor(Decor.BAR, LINE_COLOR, base, gap));
				writeSpans(doc, b.spans, text);
				break;
			case TABLE:
				if (b.table != null)
				{
					// Drawn by a TableView. Its lines are its text, so selecting and copying the message takes it.
					SimpleAttributeSet table = new SimpleAttributeSet(text);
					table.addAttribute(TABLE, b.table);
					doc.insertString(doc.getLength(), String.join(TableView.ROW_BREAK, b.lines), table);
					tail = table;
					break;
				}
				// Too big to draw: its lines, as code.
				writeLines(doc, b, base, gap, text, lines, first, last);
				break;
			case CODE:
				writeLines(doc, b, base, gap, text, lines, first, last);
				break;
			case RULE:
				// An empty line in a small font, with a line drawn through it.
				StyleConstants.setFontSize(text, Math.max(1, textFont.getSize() / 2));
				lines.addAttribute(DECOR, new Decor(Decor.RULE, LINE_COLOR, base, 0));
				first.addAttribute(DECOR, new Decor(Decor.RULE, LINE_COLOR, base, gap));
				break;
			default:
				writeSpans(doc, b.spans, text);
				break;
		}
		int end = doc.getLength();
		// The block's font goes on its paragraphs too: the document's own last line break takes it from there.
		lines.addAttributes(text);
		// Replaced, not merged: a new line starts with a copy of the previous block's paragraph attributes.
		doc.setParagraphAttributes(start, end - start + 1, lines, true);
		doc.setParagraphAttributes(start, 0, first, false);
		if (last.getAttributeCount() > 0)
		{
			doc.setParagraphAttributes(end, 0, last, false);
		}
		return tail;
	}

	/** A block's lines as they are, monospaced, in a box: code, or a table too big to draw. */
	private void writeLines(DefaultStyledDocument doc, Markdown.Block b, int base, int gap, SimpleAttributeSet text,
		SimpleAttributeSet lines, SimpleAttributeSet first, SimpleAttributeSet last) throws BadLocationException
	{
		StyleConstants.setFontFamily(text, Font.MONOSPACED);
		StyleConstants.setFontSize(text, Math.max(1, textFont.getSize() - 1));
		StyleConstants.setLeftIndent(lines, base + CODE_PAD_X);
		StyleConstants.setRightIndent(lines, CODE_PAD_X);
		lines.addAttribute(DECOR, new Decor(Decor.BOX, CODE_BACKGROUND, base, 0));
		first.addAttribute(DECOR, new Decor(Decor.BOX, CODE_BACKGROUND, base, gap));
		StyleConstants.setSpaceAbove(first, gap + CODE_PAD_Y);
		StyleConstants.setSpaceBelow(last, CODE_PAD_Y);
		doc.insertString(doc.getLength(), String.join("\n", b.lines), text);
	}

	/** How far a list item's text is from its marker's left edge: the same for every item up to 99 in a list. */
	private int markerWidth(String marker, boolean bullet)
	{
		FontMetrics fm = getFontMetrics(textFont);
		int space = fm.charWidth(' ');
		int width = bullet ? fm.stringWidth(marker) + space : Math.max(fm.stringWidth("00."), fm.stringWidth(marker));
		return width + space + 2;
	}

	private static void writeSpans(DefaultStyledDocument doc, List<Markdown.Span> spans, AttributeSet base) throws BadLocationException
	{
		for (Markdown.Span s : spans)
		{
			SimpleAttributeSet a = new SimpleAttributeSet(base);
			switch (s.kind)
			{
				case BOLD:
					StyleConstants.setBold(a, true);
					break;
				case ITALIC:
					StyleConstants.setItalic(a, true);
					break;
				case BOLD_ITALIC:
					StyleConstants.setBold(a, true);
					StyleConstants.setItalic(a, true);
					break;
				case CODE:
					StyleConstants.setFontFamily(a, Font.MONOSPACED);
					StyleConstants.setFontSize(a, Math.max(1, StyleConstants.getFontSize(base) - 1));
					StyleConstants.setBackground(a, CODE_SPAN_BACKGROUND);
					break;
				case LINK:
					StyleConstants.setForeground(a, LINK_COLOR);
					StyleConstants.setUnderline(a, true);
					a.addAttribute(LINK, s.url);
					break;
				default:
					break;
			}
			doc.insertString(doc.getLength(), s.text, a);
		}
	}

	/** Ordinary text. Every run gets all of these, so nothing depends on the document's defaults. */
	private SimpleAttributeSet textAttributes()
	{
		SimpleAttributeSet a = new SimpleAttributeSet();
		StyleConstants.setFontFamily(a, textFont.getFamily());
		StyleConstants.setFontSize(a, textFont.getSize());
		StyleConstants.setBold(a, textFont.isBold());
		StyleConstants.setItalic(a, textFont.isItalic());
		StyleConstants.setForeground(a, textColor);
		return a;
	}

	private static int gapBefore(Markdown.Block previous, Markdown.Block b)
	{
		if (previous == null)
		{
			return 0;
		}
		if (b.kind == Markdown.BlockKind.HEADING)
		{
			return HEADING_GAP;
		}
		if (previous.kind == Markdown.BlockKind.HEADING)
		{
			return AFTER_HEADING_GAP;
		}
		if (inList(previous) && inList(b))
		{
			return isItem(previous) && isItem(b) ? ITEM_GAP : LIST_GAP;
		}
		return BLOCK_GAP;
	}

	private static boolean isItem(Markdown.Block b)
	{
		return b.kind == Markdown.BlockKind.BULLET || b.kind == Markdown.BlockKind.NUMBERED;
	}

	private static boolean inList(Markdown.Block b)
	{
		return isItem(b) || b.depth > 0;
	}

	/** The address of the link under {@code p}, or null. */
	String linkAt(Point p)
	{
		int pos = viewToModel2D(p);
		int length = getDocument().getLength();
		// viewToModel gives the nearest gap between characters: look at the characters on both sides of it.
		for (int i = Math.max(0, pos - 1); i <= pos && i < length; i++)
		{
			Object url = getStyledDocument().getCharacterElement(i).getAttributes().getAttribute(LINK);
			if (url instanceof String && characterBounds(i).contains(p))
			{
				return (String) url;
			}
		}
		return null;
	}

	private Rectangle2D characterBounds(int i)
	{
		try
		{
			Rectangle2D from = modelToView2D(i);
			Rectangle2D to = modelToView2D(i + 1);
			if (from == null || to == null)
			{
				return new Rectangle2D.Double();
			}
			if (Math.abs(from.getY() - to.getY()) < 1 && to.getX() > from.getX())
			{
				return new Rectangle2D.Double(from.getX(), from.getY(), to.getX() - from.getX(), from.getHeight());
			}
			// The last character on a line: the next one is on the line below.
			Font f = getStyledDocument().getFont(getStyledDocument().getCharacterElement(i).getAttributes());
			int width = getFontMetrics(f).charWidth(getDocument().getText(i, 1).charAt(0));
			return new Rectangle2D.Double(from.getX(), from.getY(), width, from.getHeight());
		}
		catch (BadLocationException e)
		{
			return new Rectangle2D.Double();
		}
	}

	private void showHand(boolean hand)
	{
		if (hand != overLink)
		{
			overLink = hand;
			// Null goes back to the panel's own cursor.
			setCursor(hand ? Cursor.getPredefinedCursor(Cursor.HAND_CURSOR) : null);
		}
	}

	private void showMenu(MouseEvent e)
	{
		JPopupMenu menu = new JPopupMenu();
		String selected = getSelectedText();
		JMenuItem copy = new JMenuItem(selected != null && !selected.isEmpty() ? "Copy" : "Copy message");
		copy.addActionListener(a -> copyToClipboard());
		menu.add(copy);
		String url = linkAt(e.getPoint());
		if (url != null)
		{
			JMenuItem copyLink = new JMenuItem("Copy link");
			copyLink.addActionListener(a -> toClipboard(url));
			menu.add(copyLink);
		}
		menu.show(this, e.getX(), e.getY());
	}

	private static void toClipboard(String text)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
		}
		catch (IllegalStateException e)
		{
			// Another program has the clipboard open right now; copying again will work.
		}
	}

	private static void open(String url)
	{
		// Written the way browsers expect (spaces and accents encoded), or LinkBrowser refuses it.
		HttpUrl parsed = HttpUrl.parse(url);
		if (parsed == null)
		{
			return;
		}
		try
		{
			LinkBrowser.browse(parsed.toString());
		}
		catch (IllegalArgumentException e)
		{
			// An address Java can't read even so: there's nothing to open.
		}
	}

	private static class AttributeKey
	{
		private final String name;

		AttributeKey(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	/** What's drawn behind a paragraph: a code block's box, a quote's bar or a rule. */
	private static class Decor
	{
		static final int BOX = 0;
		static final int BAR = 1;
		static final int RULE = 2;

		final int kind;
		final Color color;
		/** From the paragraph's left edge. */
		final int x;
		/** The space above the paragraph that's a gap between blocks, left clear. */
		final int top;

		Decor(int kind, Color color, int x, int top)
		{
			this.kind = kind;
			this.color = color;
			this.x = x;
			this.top = top;
		}

		void paint(Graphics g, Rectangle r)
		{
			int y = r.y + top;
			int height = r.height - top;
			g.setColor(color);
			switch (kind)
			{
				case BOX:
					g.fillRect(r.x + x, y, r.width - x, height);
					break;
				case BAR:
					g.fillRect(r.x + x, y, QUOTE_BAR_WIDTH, height);
					break;
				default:
					g.fillRect(r.x + x, y + height / 2, r.width - x, 1);
					break;
			}
		}
	}

	/** Paragraphs that draw their {@link Decor} first. */
	static class BlockView extends ParagraphView
	{
		private boolean firstRowPainted;

		BlockView(Element elem)
		{
			super(elem);
		}

		/** The width its lines are laid out in, or {@link Integer#MAX_VALUE} before they have been. */
		int flowWidth()
		{
			return layoutSpan;
		}

		@Override
		public void paint(Graphics g, Shape a)
		{
			Object decor = getAttributes().getAttribute(DECOR);
			if (decor instanceof Decor)
			{
				((Decor) decor).paint(g, a.getBounds());
			}
			firstRowPainted = false;
			super.paint(g, a);
		}

		@Override
		protected void paintChild(Graphics g, Rectangle alloc, int index)
		{
			// ParagraphView paints a first line that hangs out to the left (a list item's) twice, which makes
			// anti-aliased text look bold.
			if (index == 0)
			{
				if (firstRowPainted)
				{
					return;
				}
				firstRowPainted = true;
			}
			super.paintChild(g, alloc, index);
		}
	}

	/** Text that can break inside a word: a long address wraps instead of making the message wider than the panel. */
	private static class WrapLabelView extends LabelView
	{
		WrapLabelView(Element elem)
		{
			super(elem);
		}

		@Override
		public float getMinimumSpan(int axis)
		{
			return axis == View.X_AXIS ? 0 : super.getMinimumSpan(axis);
		}
	}

	private static class Kit extends StyledEditorKit
	{
		private static final ViewFactory VIEWS = elem ->
		{
			String name = elem.getName();
			if (AbstractDocument.ParagraphElementName.equals(name))
			{
				return new BlockView(elem);
			}
			if (AbstractDocument.SectionElementName.equals(name))
			{
				return new BoxView(elem, View.Y_AXIS);
			}
			// A table's text, which it draws as a table. Its own attribute only: a paragraph's don't count.
			if (elem.getAttributes().isDefined(TABLE))
			{
				return new TableView(elem, (Markdown.Table) elem.getAttributes().getAttribute(TABLE));
			}
			// Only text is ever inserted: no components or icons.
			return new WrapLabelView(elem);
		};

		@Override
		public ViewFactory getViewFactory()
		{
			return VIEWS;
		}
	}

	/** A caret that never scrolls the transcript (the text is replaced while a reply streams in, moving it). */
	private static class StillCaret extends DefaultCaret
	{
		@Override
		protected void adjustVisibility(Rectangle nloc)
		{
		}
	}
}

