/**
 * The model picker next to Send, as chat apps have it: the model's name and a chevron, with no box, that opens a menu
 * of the provider's models (the one that's set ticked), then "Type a model name…" and "Refresh list". Choosing a
 * model, or typing a name and pressing Enter, sets the provider's model as the settings would. Nothing else does: not
 * what the panel shows itself (a model changed in the settings, a list that came in), not Escape, not leaving the box.
 * Plain text only, menu, box and tooltips alike: model names come from the provider. Swing EDT only.
 */
final class ModelPicker extends JPanel
{
	static final String TYPE = "Type a model name…";
	static final String REFRESH = "Refresh list";
	/** On the button while no model is set. */
	static final String NONE = "Choose a model";
	/** Models the menu shows before its list scrolls. */
	static final int MENU_ROWS = 8;
	/** The menu is at least this wide, even over a narrow picker. */
	private static final int MENU_MIN_WIDTH = 180;
	/** Where the text of the menu's note and of its rows starts: in line with its items' text. */
	private static final int TEXT_INSET = 6;

	/** What the picker asks the panel to do. */
	interface Actions
	{
		/** The player chose {@code model}: the provider's model becomes it. */
		void choose(String model);

		/** The player asked for the provider's list of models again. */
		void refresh();
	}

	/** The model's name and a chevron: opens the menu. */
	final FlatButton button = new FlatButton(NONE, new Glyph(Glyph.Shape.CHEVRON_DOWN, 9), null);
	/** Where a model's name is typed, in place of the button, after "Type a model name…". */
	final NameField field = new NameField();
	private final RoundBox fieldBox = new RoundBox(new BorderLayout(), PanelStyle.FIELD_COLOR, PanelStyle.OUTLINE_COLOR);
	/** Hears the player's choice, a moment later on the EDT (it changes the settings, which redraws the panel). */
	private final Actions actions;
	/** The model that's set, as far as the picker knows. */
	private String current = "";
	private List<String> choices = Collections.emptyList();
	/** Why the list is short, for the menu; null when it isn't. */
	private String note;
	/** Why Refresh list can't ask the provider now, or null when it can. */
	private String refreshProblem;

	ModelPicker(Actions actions)
	{
		super(null);
		this.actions = actions;
		setOpaque(false);
		button.setFont(PanelStyle.SMALL_FONT);
		button.setForeground(PanelStyle.MUTED_COLOR);
		// The chevron after the name, as a menu button's.
		button.setHorizontalTextPosition(SwingConstants.LEADING);
		button.setHorizontalAlignment(SwingConstants.LEFT);
		button.setIconTextGap(4);
		button.setBorder(new EmptyBorder(4, 6, 4, 6));
		button.addActionListener(e -> openMenu());
		add(button);

		field.setFont(PanelStyle.SMALL_FONT);
		field.setForeground(PanelStyle.TEXT_COLOR);
		field.setCaretColor(PanelStyle.TEXT_COLOR);
		field.setOpaque(false);
		field.setBorder(new EmptyBorder(3, 6, 3, 6));
		// Enter saves the name; Escape, or going elsewhere, puts the button back as it was.
		field.addActionListener(e -> typed());
		field.getInputMap().put(KeyStroke.getKeyStroke("ESCAPE"), "ai-chat-cancel");
		field.getActionMap().put("ai-chat-cancel", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				stopTyping();
			}
		});
		field.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				// Not when the focus is only away for a moment, such as in another window.
				if (!e.isTemporary())
				{
					stopTyping();
				}
			}
		});
		fieldBox.add(field, BorderLayout.CENTER);
		fieldBox.setVisible(false);
		add(fieldBox);
	}

	/**
	 * Shows {@code model}, the one that's set, with {@code choices} for the menu (see {@link ConnectionCheck#choices}),
	 * {@code tip} saying how to choose (see {@link ConnectionCheck#pickerTip}), {@code note} saying why the list is
	 * short or null, and {@code refreshProblem} saying why the list can't be asked for again now, or null. Never taken
	 * for the player's choice, and leaves a name being typed alone.
	 */
	void show(String model, List<String> choices, String tip, String note, String refreshProblem)
	{
		String m = model == null ? "" : model.trim();
		if (!m.equals(current) || !button.getText().equals(m.isEmpty() ? NONE : m))
		{
			current = m;
			button.setText(m.isEmpty() ? NONE : m);
			revalidate();
			repaint();
		}
		this.choices = new ArrayList<>(choices);
		this.note = note;
		this.refreshProblem = refreshProblem;
		button.setToolTipText(tip);
	}

	/** Whether a model's name is being typed, in place of the button. */
	boolean isTyping()
	{
		return fieldBox.isVisible();
	}

	@Override
	public void doLayout()
	{
		int w = getWidth();
		int h = getHeight();
		// As wide as the name needs, so the chevron comes right after it; a long name is cut at its end, with the whole
		// of it in the tooltip.
		Dimension b = button.getPreferredSize();
		button.setBounds(0, (h - b.height) / 2, Math.min(b.width, w), b.height);
		Dimension f = fieldBox.getPreferredSize();
		fieldBox.setBounds(0, (h - f.height) / 2, w, f.height);
	}

	@Override
	public Dimension getPreferredSize()
	{
		Dimension b = button.getPreferredSize();
		return new Dimension(b.width, Math.max(b.height, fieldBox.getPreferredSize().height));
	}

	@Override
	public Dimension getMinimumSize()
	{
		// A long name gives way to the button beside it.
		return new Dimension(0, getPreferredSize().height);
	}

	// ------------------------------------------------------------------
	// The menu
	// ------------------------------------------------------------------

	private void openMenu()
	{
		JPopupMenu menu = menu();
		// Over the composer, from its left edge: the picker sits at the bottom of the panel.
		menu.show(this, 0, -menu.getPreferredSize().height - 2);
	}

	/**
	 * The menu: why the list is short (when it is), the models, then "Type a model name…" and "Refresh list". Made
	 * again each time it opens, from what the picker was last shown.
	 */
	JPopupMenu menu()
	{
		JPopupMenu menu = new JPopupMenu();
		Container row = getParent();
		int width = Math.max(MENU_MIN_WIDTH, row != null ? row.getWidth() : getWidth());
		Insets in = menu.getInsets();
		int inner = width - in.left - in.right;
		if (note != null)
		{
			menu.add(noteArea(note, inner));
		}
		if (!choices.isEmpty())
		{
			menu.add(modelList(menu, inner));
			menu.addSeparator();
		}
		JMenuItem type = PanelStyle.menuItem(TYPE);
		type.setToolTipText("Type the name of a model that isn't listed, as the provider gives it");
		type.addActionListener(e -> startTyping());
		menu.add(type);
		JMenuItem refresh = PanelStyle.menuItem(REFRESH);
		for (JMenuItem item : new JMenuItem[]{type, refresh})
		{
			// As the models over them are: their font, colour and height, rather than a menu's own (smaller, greyer
			// and closer together, which read as greyed out next to the models).
			item.setFont(PanelStyle.TEXT_FONT);
			item.setForeground(PanelStyle.TEXT_COLOR);
			// As wide as it needs; the menu stretches it to its own width.
			item.setPreferredSize(new Dimension(item.getPreferredSize().width, rowHeight()));
		}
		refresh.setEnabled(refreshProblem == null);
		refresh.setToolTipText(refreshProblem == null ? "Ask the provider for its models again" : refreshProblem);
		refresh.addActionListener(e -> actions.refresh());
		menu.add(refresh);
		return menu;
	}

	/** A short, muted, wrapped line of plain text at the top of the menu. */
	private static JTextArea noteArea(String note, int width)
	{
		JTextArea area = PanelStyle.textArea(note);
		area.setFont(PanelStyle.SMALL_FONT);
		area.setForeground(PanelStyle.MUTED_COLOR);
		area.setBorder(new EmptyBorder(4, TEXT_INSET, 6, 8));
		area.setFocusable(false);
		// Its height for the menu's width: wrapped, not one long line that widens the menu.
		area.setSize(width, Short.MAX_VALUE);
		area.setPreferredSize(new Dimension(width, area.getPreferredSize().height));
		return area;
	}

	/** The models, the one that's set ticked; it scrolls past {@link #MENU_ROWS}. */
	private JScrollPane modelList(JPopupMenu menu, int width)
	{
		JList<String> list = new JList<String>(choices.toArray(new String[0]))
		{
			@Override
			public JToolTip createToolTip()
			{
				JToolTip tip = super.createToolTip();
				tip.putClientProperty("html.disable", Boolean.TRUE);
				return tip;
			}
		};
		list.setName("models");
		list.setCellRenderer(new ModelRow());
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setOpaque(false);
		list.setFocusable(false);
		list.setFixedCellHeight(rowHeight());
		list.setVisibleRowCount(Math.min(MENU_ROWS, choices.size()));
		list.setSelectedIndex(choices.indexOf(current));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				// The row under the mouse lights up, as a menu's items do.
				int i = rowAt(list, e.getPoint());
				if (i >= 0)
				{
					list.setSelectedIndex(i);
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				int i = rowAt(list, e.getPoint());
				if (i >= 0 && SwingUtilities.isLeftMouseButton(e))
				{
					menu.setVisible(false);
					choose(list.getModel().getElementAt(i));
				}
			}
		};
		list.addMouseListener(mouse);
		list.addMouseMotionListener(mouse);
		JScrollPane scroll = new JScrollPane(list);
		scroll.setName("models");
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(list.getFixedCellHeight());
		// The menu's width, the scroll bar's included when there is one.
		int bar = choices.size() > MENU_ROWS ? scroll.getVerticalScrollBar().getPreferredSize().width : 0;
		list.setFixedCellWidth(width - bar);
		// Opening on the model that's set when it's further down a long list than the rows shown reach, as the last of
		// them; from the top otherwise, so the models over it (the newest, for Anthropic) show too. Set as a position,
		// as the list has no height yet to scroll in.
		int set = list.getSelectedIndex();
		if (set >= MENU_ROWS)
		{
			scroll.getViewport().setViewPosition(new Point(0, (set - MENU_ROWS + 1) * list.getFixedCellHeight()));
		}
		return scroll;
	}

	/** How tall each of the menu's rows is: models and items alike. */
	private int rowHeight()
	{
		return getFontMetrics(PanelStyle.TEXT_FONT).getHeight() + 10;
	}

	/** The row at {@code p}, or -1 when it isn't on one. */
	private static int rowAt(JList<String> list, Point p)
	{
		int i = list.locationToIndex(p);
		return i >= 0 && list.getCellBounds(i, i).contains(p) ? i : -1;
	}

	/** The player chose {@code item}: the provider's model becomes it, unless it's blank or already set. */
	private void choose(String item)
	{
		String model = item == null ? "" : item.trim();
		if (model.isEmpty() || model.equals(current))
		{
			return;
		}
		current = model;
		button.setText(model);
		revalidate();
		// Not from inside the menu's or the box's own event: setting the model redraws the panel, this picker included.
		SwingUtilities.invokeLater(() -> actions.choose(model));
	}

	// ------------------------------------------------------------------
	// Typing a name
	// ------------------------------------------------------------------

	/** "Type a model name…": a small box in the button's place, with the model that's set in it, selected. */
	void startTyping()
	{
		field.setText(current);
		field.selectAll();
		button.setVisible(false);
		fieldBox.setVisible(true);
		revalidate();
		repaint();
		// Once the menu that asked for this has closed, and given the focus back.
		SwingUtilities.invokeLater(field::requestFocusInWindow);
	}

	/** Enter: the name typed is chosen (nothing, if it's blank or the model that's set). */
	private void typed()
	{
		String name = field.getText();
		stopTyping();
		choose(name);
	}

	/** The button again, in the box's place. */
	void stopTyping()
	{
		if (!fieldBox.isVisible())
		{
			return;
		}
		fieldBox.setVisible(false);
		button.setVisible(true);
		revalidate();
		repaint();
	}

	/** The box a name is typed in: plain text, as is its tooltip, saying what it's for while it's empty. */
	static final class NameField extends JTextField
	{
		NameField()
		{
			putClientProperty("html.disable", Boolean.TRUE);
			setToolTipText("Enter sets the model; Escape goes back");
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			if (getDocument().getLength() > 0)
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g2.setColor(PanelStyle.MUTED_COLOR);
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			Insets in = getInsets();
			int middle = (getHeight() - in.top - in.bottom + fm.getAscent() - fm.getDescent()) / 2;
			g2.drawString(TYPE, in.left, in.top + middle);
			g2.dispose();
		}

		@Override
		public JToolTip createToolTip()
		{
			JToolTip tip = super.createToolTip();
			tip.putClientProperty("html.disable", Boolean.TRUE);
			return tip;
		}
	}

	/** A row of the menu's list: the model's name, plain text and cut at its end if long, and a tick on the one set. */
	private final class ModelRow extends JPanel implements ListCellRenderer<String>
	{
		private final JLabel name = new JLabel();
		private final JLabel tick = new JLabel();
		private final Glyph ticked = new Glyph(Glyph.Shape.CHECK, 11, PanelStyle.TEXT_COLOR);

		ModelRow()
		{
			super(new BorderLayout(6, 0));
			// Before any text is set: the HTML renderer is picked when it is.
			for (JLabel l : new JLabel[]{name, tick})
			{
				l.putClientProperty("html.disable", Boolean.TRUE);
			}
			name.setFont(PanelStyle.TEXT_FONT);
			name.setForeground(PanelStyle.TEXT_COLOR);
			// The names line up with the menu's items under them.
			setBorder(new EmptyBorder(0, TEXT_INSET, 0, 8));
			add(name, BorderLayout.CENTER);
			add(tick, BorderLayout.EAST);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends String> list, String value, int index,
			boolean selected, boolean focus)
		{
			name.setText(value);
			tick.setIcon(Objects.equals(value, current) ? ticked : null);
			setOpaque(selected);
			// Lit as the menu's items are under the mouse.
			Color lit = UIManager.getColor("MenuItem.selectionBackground");
			setBackground(lit != null ? lit : PanelStyle.BUBBLE_COLOR);
			// The whole name, for one too long for the menu; the list shows the row's tooltip as its own.
			setToolTipText(value);
			return this;
		}
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The Chat Completions API: OpenAI itself (ChatGPT), and the many services that copy it (OpenRouter, Groq, Gemini's
 * compatibility endpoint, Ollama, LM Studio...), each with the player's own URL, key and model.
 */
@Slf4j
class OpenAiApi implements ChatApi
{
	static final HttpUrl OPENAI_URL = HttpUrl.get("https://api.openai.com/v1/");
	/** OpenAI's small, fast model: plenty for chat, and cheap. */
	static final String DEFAULT_MODEL = "gpt-6-luna";
	/** What {@link #listModels} says about a service without a model list, or with one AI Chat can't find. */
	static final String NO_MODEL_LIST = "This service doesn't list its models; check the model name on its website.";
	/**
	 * Reply length limits. Most services count the model's reasoning against them too, so they leave plenty of room;
	 * only what's used is billed, and the system prompt asks for short answers.
	 */
	private static final int OPENAI_MAX_TOKENS = 8000;
	private static final int COMPATIBLE_MAX_TOKENS = 16000;
	/** Some models (Qwen, DeepSeek R1 on some hosts, local models) put their reasoning inside the reply. */
	private static final Pattern THINKING = Pattern.compile("(?s)<think>.*?</think>");
	private static final String COULDNT_SEND = "AI Chat couldn't send the next part of this. Check the API key and URL in the settings.";
	/**
	 * Added to the instructions when the model can't use tools: they say which setting allows a game-data tool that
	 * isn't offered, which would be the wrong advice when none can be.
	 */
	static final String NO_TOOLS = "\n\n(This model can't use tools here, so you have none, whatever the player's "
		+ "settings: answer from what you know.)";

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl base;
	private final String apiKey;
	private final String name;
	/** OpenAI itself, rather than a compatible service with its own quirks. */
	private final boolean openai;
	/** The reasoning effort to ask for, or null for the model's own default. */
	private final String reasoningEffort;
	/** The plugin's scheduler, for waiting before a retry. */
	private final ScheduledExecutorService scheduler;
	/**
	 * Optional settings each service and model has refused, by {@link #refusedKey}: left out of later requests instead
	 * of being refused again every time. Shared by the plugin's requests for as long as it runs.
	 */
	private final Map<String, Set<String>> refused;

	OpenAiApi(OkHttpClient http, Gson gson, HttpUrl base, String apiKey, String name, boolean openai,
		String reasoningEffort, ScheduledExecutorService scheduler, Map<String, Set<String>> refused)
	{
		this.http = http;
		this.gson = gson;
		this.base = base;
		this.apiKey = apiKey;
		this.name = name;
		this.openai = openai;
		this.reasoningEffort = reasoningEffort;
		this.scheduler = scheduler;
		this.refused = refused;
	}

	@Override
	public String displayName()
	{
		return name;
	}

	@Override
	public Pending send(Conversation conversation, Listener listener)
	{
		Run run = new Run(conversation, listener);
		run.request();
		return run.pending;
	}

	/**
	 * The request body. {@code skip}: optional settings to leave out, because they were refused. {@code produced}: this
	 * reply's messages so far (tool calls and their results), when it has stopped to look things up.
	 */
	JsonObject body(Conversation conversation, Set<String> skip, JsonArray produced)
	{
		JsonObject body = new JsonObject();
		body.addProperty("model", conversation.model);
		boolean noTools = !conversation.tools.isEmpty() && skip.contains("tools");
		JsonArray messages = new JsonArray();
		messages.add(message("system", noTools ? conversation.system + NO_TOOLS : conversation.system));
		for (Turn t : conversation.turns)
		{
			messages.add(message(t.user ? "user" : "assistant", t.text));
		}
		for (JsonElement m : produced)
		{
			messages.add(m);
		}
		body.add("messages", messages);
		body.addProperty("stream", true);
		if (!skip.contains("stream_options"))
		{
			// The token counts come in one last piece, only when asked for.
			JsonObject options = new JsonObject();
			options.addProperty("include_usage", true);
			body.add("stream_options", options);
		}
		if (!conversation.tools.isEmpty() && !noTools)
		{
			JsonArray tools = new JsonArray();
			for (ToolSpec t : conversation.tools)
			{
				JsonObject function = new JsonObject();
				function.addProperty("name", t.name);
				function.addProperty("description", t.description);
				function.add("parameters", t.inputSchema);
				JsonObject tool = new JsonObject();
				tool.addProperty("type", "function");
				tool.add("function", function);
				tools.add(tool);
			}
			body.add("tools", tools);
		}
		// "low" asks reasoning models to think briefly. Most think more than that by default, so replies come much
		// faster (a local Qwen: ~11s instead of ~40s). A few think less or not at all by default, and "low" makes them
		// think a little; for those the player can choose the model's default. Services and models that don't take
		// it say so, and we ask again without it.
		if (reasoningEffort != null && !skip.contains("reasoning_effort"))
		{
			body.addProperty("reasoning_effort", reasoningEffort);
		}
		if (openai)
		{
			if (!skip.contains("max_completion_tokens"))
			{
				body.addProperty("max_completion_tokens", limit(OPENAI_MAX_TOKENS, conversation.maxTokens));
			}
			// OpenAI otherwise keeps chat completions for new accounts.
			body.addProperty("store", false);
		}
		else if (!skip.contains("max_tokens"))
		{
			// The name every compatible service knows (Ollama ignores the newer max_completion_tokens).
			body.addProperty("max_tokens", limit(COMPATIBLE_MAX_TOKENS, conversation.maxTokens));
		}
		return body;
	}

	/** The provider's limit, or the conversation's own when that's lower. */
	private static int limit(int ours, int asked)
	{
		return asked > 0 ? Math.min(ours, asked) : ours;
	}

	/** One service and model: what one refuses, another may take. */
	private String refusedKey(String model)
	{
		return base + " " + model;
	}

	/**
	 * Settings a request can do without. Not "store": that one keeps OpenAI from storing the chat, so if it's ever
	 * refused the player sees the error rather than a quiet retry without it. "tools" too: a model that can't call them
	 * (Ollama: "... does not support tools") still answers, just without looking things up.
	 */
	private static final Set<String> OPTIONAL = new LinkedHashSet<>(Arrays.asList(
		"reasoning_effort", "max_completion_tokens", "max_tokens", "stream_options", "tools"));

	/**
	 * The optional setting a 400/422 answer complains about, if it's one we sent: by its "param", by name anywhere in
	 * the answer (Mistral lists invalid fields), or, for reasoning_effort, a complaint about thinking or reasoning
	 * (Ollama's "does not support thinking" for models that don't think, and on 0.11.8-0.17.6 "think value "low" is
	 * not supported for this model").
	 */
	static String rejectedOption(Gson gson, JsonObject body, String errorBody)
	{
		String param = errorParam(gson, errorBody);
		String message = ChatApi.errorMessage(gson, errorBody);
		String lower = message == null ? "" : message.toLowerCase(Locale.ROOT);
		for (String key : OPTIONAL)
		{
			if (!body.has(key))
			{
				continue;
			}
			Pattern named = Pattern.compile("(?<![A-Za-z_])" + Pattern.quote(key) + "(?![A-Za-z_])");
			if (key.equals(param) || message != null && named.matcher(message).find() || errorBody != null && named.matcher(errorBody).find()
				|| key.equals("reasoning_effort") && (lower.contains("think") || lower.contains("reasoning")))
			{
				return key;
			}
		}
		return null;
	}

	/** How a model or service says it can't take tools without naming the field: "tool use", "tool choice"... */
	private static final Pattern NO_TOOLS_HERE = Pattern.compile(
		"(?i)tool[ _-]?(use|choice|calling)|function[ _-]?calling|support(s|ed)? tools");

	/**
	 * Whether an error answer says tools can't be used at all, in other words than {@link #rejectedOption} looks for:
	 * OpenRouter's 404 "No endpoints found that support tool use" (no host of the model takes them), and vLLM's
	 * "auto" tool choice requiring --enable-auto-tool-choice (a server started without them).
	 */
	static boolean refusesTools(int code, String errorBody)
	{
		return (code == 400 || code == 404 || code == 422) && errorBody != null && NO_TOOLS_HERE.matcher(errorBody).find();
	}

	/** OpenAI names the offending parameter in error.param. */
	private static String errorParam(Gson gson, String errorBody)
	{
		try
		{
			JsonElement parsed = ChatApi.fromJson(gson, errorBody, JsonElement.class);
			JsonElement error = parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject().get("error") : null;
			return error != null && error.isJsonObject() ? string(error.getAsJsonObject(), "param") : null;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	private static JsonObject message(String role, String content)
	{
		JsonObject m = new JsonObject();
		m.addProperty("role", role);
		m.addProperty("content", content);
		return m;
	}

	/** One reply: its rounds of tool calls, its retries, and the one answer the listener gets. */
	private final class Run
	{
		private final Conversation conversation;
		private final Listener listener;
		private final Pending pending = new Pending();
		/** This reply's messages so far: the model's tool calls and their results. */
		private final JsonArray produced = new JsonArray();
		/** The text of the rounds before this one. */
		private final List<String> texts = new ArrayList<>();
		private final Usage usage = new Usage();
		private final AtomicBoolean over = new AtomicBoolean();
		/** Optional settings refused during this reply and left out since; remembered once a request works without them. */
		private final Set<String> dropped = new LinkedHashSet<>();
		/** The last request's body, which a refusal is checked against. */
		private JsonObject sent;
		private String model;
		private int toolRounds;
		private int retries;

		Run(Conversation conversation, Listener listener)
		{
			this.conversation = conversation;
			this.listener = listener;
			model = conversation.model;
		}

		/** Sends this round's request. Throws if OkHttp won't take it (a header value it rejects). */
		void request()
		{
			Set<String> skip = new HashSet<>(refused.getOrDefault(refusedKey(conversation.model), Set.of()));
			skip.addAll(dropped);
			sent = body(conversation, skip, produced);
			Request.Builder request = new Request.Builder()
				.url(base.resolve("chat/completions"))
				.post(RequestBody.create(JSON, gson.toJson(sent)));
			if (!apiKey.isEmpty())
			{
				request.header("Authorization", "Bearer " + apiKey);
			}
			Call call = http.newCall(request.build());
			pending.set(call);
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(Call c, IOException e)
				{
					failed(e);
				}

				@Override
				public void onResponse(Call c, Response response)
				{
					try (ResponseBody body = response.body())
					{
						answered(response, body);
					}
					catch (RuntimeException e)
					{
						// A bug: the reply still ends, rather than wait forever. Only the type is logged, in case the
						// message quotes a header (the API key).
						log.warn("{}'s answer not read: {}", describe(base), e.getClass().getName());
						fail(describe(base) + " sent an answer AI Chat couldn't read.");
					}
				}
			});
		}

		/** A later request (a retry or the next round), from a callback: a problem goes to the listener, not the thread. */
		private void again()
		{
			if (pending.isCancelled())
			{
				return;
			}
			try
			{
				request();
			}
			catch (RuntimeException e)
			{
				// The exception's message can contain the API key: it isn't passed on or logged.
				fail(COULDNT_SEND);
			}
		}

		private void failed(IOException e)
		{
			if (pending.isCancelled())
			{
				return;
			}
			boolean local = isPrivate(base.host());
			if (ChatApi.tookTooLong(e))
			{
				fail(describe(base) + " took too long to answer."
					+ (local ? " Models on your own computer can be slow; try a smaller one." : " Try again."));
				return;
			}
			// A service on this computer or network that can't be reached isn't running: waiting won't help.
			if (!local && retry("Couldn't reach " + describe(base), ChatApi.retryDelay(null, null, retries + 1)))
			{
				return;
			}
			fail("Couldn't reach " + describe(base) + ": " + e.getMessage() + (local ? ". Is the service running?" : ""));
		}

		private void answered(Response response, ResponseBody body)
		{
			if (pending.isCancelled())
			{
				return;
			}
			if (!response.isSuccessful() || body == null)
			{
				String text;
				try
				{
					text = body == null ? "" : body.string().trim();
				}
				catch (IOException e)
				{
					text = "";
				}
				if (!pending.isCancelled())
				{
					errorAnswer(response, text);
				}
				return;
			}
			// Only a request that worked without them shows the dropped settings were the problem: remember those.
			if (!dropped.isEmpty())
			{
				refused.computeIfAbsent(refusedKey(conversation.model), k -> ConcurrentHashMap.newKeySet()).addAll(dropped);
			}
			Message m = new Message();
			try
			{
				if (Sse.isEventStream(response))
				{
					Sse.read(body.source(), (event, data) -> onChunk(m, data));
				}
				else
				{
					// Not streamed after all: one answer, read whole.
					String text;
					try
					{
						text = body.string().trim();
					}
					catch (IOException e)
					{
						if (!pending.isCancelled())
						{
							brokeOff(m);
							fail("Couldn't read the answer from " + describe(base) + ": " + e.getMessage());
						}
						return;
					}
					m.whole(gson, text);
				}
			}
			catch (IOException e)
			{
				// Stop closes the stream: not a problem to report.
				if (pending.isCancelled())
				{
					return;
				}
				// The reply had ended (its finish reason came after everything else), and only the counts or [DONE] were
				// lost with the connection: it's whole, its counts unknown.
				if (m.finish != null && m.error == null)
				{
					completed(m);
					return;
				}
				brokeOff(m);
				fail(ChatApi.tookTooLong(e) ? describe(base) + " took too long to answer." : CUT_OFF);
				return;
			}
			catch (JsonParseException | IllegalStateException | ClassCastException | UnsupportedOperationException | NumberFormatException e)
			{
				brokeOff(m);
				fail(describe(base) + " sent an answer AI Chat couldn't read.");
				return;
			}
			if (!pending.isCancelled())
			{
				completed(m);
			}
		}

		/** An error answer: some are worth asking again for, differently or after a wait. */
		private void errorAnswer(Response response, String text)
		{
			int code = response.code();
			// A model that doesn't take one of our optional settings says so: once per setting, do without it.
			// 400 from most services, 422 from those that validate the request's fields (Mistral). One that can't take
			// tools at all may say so in its own words, and OpenRouter with a 404.
			String rejected = sent.has("tools") && refusesTools(code, text) ? "tools"
				: code == 400 || code == 422 ? rejectedOption(gson, sent, text) : null;
			// A model that has just called tools can use them: an error about them now is about something else.
			if ("tools".equals(rejected) && produced.size() > 0)
			{
				rejected = null;
			}
			if (rejected != null)
			{
				log.debug("asking again without {}", rejected);
				dropped.add(rejected);
				again();
				return;
			}
			// After the optional settings: a reply length limit bigger than a small model's context is refused in the
			// same words, and leaving it out is all that takes.
			if (ChatApi.tooLongForModel(code, text))
			{
				fail(ChatApi.tooLong(conversation.model, !openai && isPrivate(base.host())
					? " A model on your own computer may also take more with a bigger context size in its own settings." : ""));
				return;
			}
			if (ChatApi.retryableStatus(code, text) && retries < MAX_RETRIES)
			{
				long delay = ChatApi.retryDelay(response.header("retry-after-ms"), response.header("retry-after"), retries + 1);
				String why = code == 429 ? describe(base) + "'s rate limit was hit" : describe(base) + " is busy";
				if (delay > MAX_RETRY_WAIT_MS)
				{
					fail(why + "; it asked to wait " + ChatApi.waitText(delay) + ". Try again then.");
					return;
				}
				retry(why, delay);
				return;
			}
			fail(explain(code, ChatApi.errorMessage(gson, text), conversation.model));
		}

		/** Sends the request again after {@code delay}, if it may be tried again. */
		private boolean retry(String why, long delay)
		{
			if (retries >= MAX_RETRIES)
			{
				return false;
			}
			retries++;
			log.debug("{}; trying again in {}ms", why, delay);
			if (!over.get() && !pending.isCancelled())
			{
				listener.onRetrying(why, ChatApi.seconds(delay));
			}
			if (!ChatApi.later(scheduler, pending, delay, this::again))
			{
				fail(why + ". Try again shortly.");
			}
			return true;
		}

		/** One streamed piece of the reply. False once it's over. */
		private boolean onChunk(Message m, String data)
		{
			if (Sse.DONE.equals(data.trim()))
			{
				m.done = true;
				return false;
			}
			JsonElement parsed = ChatApi.fromJson(gson, data, JsonElement.class);
			if (parsed == null || !parsed.isJsonObject())
			{
				return true;
			}
			JsonObject o = parsed.getAsJsonObject();
			// OpenRouter reports a failure part way through as a piece with an error in it.
			String error = errorIn(o);
			if (error != null)
			{
				m.error = error;
				return false;
			}
			m.read(o);
			JsonObject choice = firstChoice(o);
			JsonObject delta = choice == null ? null : object(choice, "delta");
			if (delta != null)
			{
				String piece = content(delta.get("content"));
				if (!piece.isEmpty())
				{
					m.content.append(piece);
					partial(m, piece);
				}
				String refusal = string(delta, "refusal");
				if (refusal != null)
				{
					m.refusal = m.refusal == null ? refusal : m.refusal + refusal;
				}
				String reasoning = string(delta, "reasoning_content");
				if (reasoning != null)
				{
					m.reasoning.append(reasoning);
				}
				JsonElement calls = delta.get("tool_calls");
				if (calls != null && calls.isJsonArray())
				{
					for (JsonElement call : calls.getAsJsonArray())
					{
						if (call.isJsonObject())
						{
							m.streamedCall(call.getAsJsonObject());
						}
					}
				}
			}
			return true;
		}

		/** The reply so far, for the panel: earlier rounds, and this one without any reasoning written into it. */
		private void partial(Message m, String piece)
		{
			m.thinks |= piece.contains("think>") || m.content.indexOf("think>", Math.max(0, m.content.length() - piece.length() - 8)) >= 0;
			String now = m.thinks ? withoutThinking(m.content.toString()) : m.content.toString().trim();
			// The start of a tag that hasn't finished arriving.
			if (now.isEmpty() || "<think>".startsWith(now) || now.equals(m.lastShown) || over.get() || pending.isCancelled())
			{
				return;
			}
			m.lastShown = now;
			listener.onPartial(ChatApi.joinRounds(texts, now));
		}

		/** A whole response: the reply, or the tools it wants run before it carries on. */
		private void completed(Message m)
		{
			if (m.error != null)
			{
				brokeOff(m);
				fail(describe(base) + ": " + ChatApi.shorten(m.error, 300));
				return;
			}
			if (!m.done && m.finish == null)
			{
				brokeOff(m);
				fail(m.whole ? describe(base) + " sent no reply." : CUT_OFF);
				return;
			}
			// Counted before anything else can go wrong: this response is billed whatever happens next.
			usage.add(m.usage);
			model = m.model != null ? m.model : model;
			String text = withoutThinking(m.content.toString());
			boolean cutShort = "length".equals(m.finish);
			if ("content_filter".equals(m.finish))
			{
				// What it wrote before that isn't an answer, so it isn't kept.
				Failure filtered = new Failure(name + "'s content filter stopped the reply.");
				filtered.withdrawn = true;
				fail(filtered);
				return;
			}
			// A call cut off by the length limit has half its arguments: not run.
			if (!m.calls.isEmpty() && !cutShort)
			{
				toolRound(m, text);
				return;
			}
			String all = ChatApi.joinRounds(texts, text);
			if (all.isEmpty())
			{
				fail(m.refusal != null ? name + " declined: " + ChatApi.shorten(m.refusal, 300)
					: name + " sent an empty reply" + (cutShort ? ": it used up its reply length, probably thinking. Try again, or a different model." : "."));
				return;
			}
			Reply r = new Reply();
			r.text = all;
			r.model = model;
			r.cutShort = cutShort;
			r.toolsUnavailable = !conversation.tools.isEmpty() && !sent.has("tools");
			r.usage.add(usage);
			finish(r);
		}

		/** The model asked for tools: run them, then send the call and the results back and carry on. */
		private void toolRound(Message m, String text)
		{
			if (toolRounds >= MAX_TOOL_ROUNDS)
			{
				fail(TOO_MANY_ROUNDS);
				return;
			}
			toolRounds++;
			JsonArray calls = new JsonArray();
			List<String> ids = new ArrayList<>();
			List<String> names = new ArrayList<>();
			List<JsonObject> inputs = new ArrayList<>();
			for (ToolCall c : m.calls.values())
			{
				// Some local services leave the id out; the results must still say which call they answer.
				String id = c.id != null ? c.id : "call_" + toolRounds + "_" + ids.size();
				JsonObject function = new JsonObject();
				function.addProperty("name", c.name == null ? "" : c.name);
				function.addProperty("arguments", c.arguments.toString());
				JsonObject call = new JsonObject();
				call.addProperty("id", id);
				call.addProperty("type", "function");
				call.add("function", function);
				if (c.extra != null)
				{
					call.add("extra_content", c.extra);
				}
				calls.add(call);
				ids.add(id);
				names.add(c.name == null ? "" : c.name);
				inputs.add(arguments(gson, c.arguments.toString()));
			}
			JsonObject assistant = new JsonObject();
			assistant.addProperty("role", "assistant");
			// Empty rather than null: Gson leaves nulls out unless told otherwise, and some services want the field.
			assistant.addProperty("content", text);
			// DeepSeek and Kimi want the reasoning behind tool calls back while the reply carries on, and refuse the next
			// round without it. Only where the service sent it: others may not take the field.
			if (m.reasoning.length() > 0)
			{
				assistant.addProperty("reasoning_content", m.reasoning.toString());
			}
			assistant.add("tool_calls", calls);
			produced.add(assistant);
			texts.add(text);
			ChatApi.runTools(conversation.toolRunner, names, inputs, results -> toolsDone(ids, results));
		}

		/** The tools have answered: one message per result, in the order they were asked for. */
		private void toolsDone(List<String> ids, List<ToolResult> results)
		{
			if (pending.isCancelled() || over.get())
			{
				return;
			}
			for (int i = 0; i < ids.size(); i++)
			{
				JsonObject result = new JsonObject();
				result.addProperty("role", "tool");
				result.addProperty("tool_call_id", ids.get(i));
				result.addProperty("content", results.get(i).content == null ? "" : results.get(i).content);
				produced.add(result);
			}
			retries = 0;
			try
			{
				// Off the thread that ran the last tool, which may be one that mustn't wait on anything.
				scheduler.execute(this::again);
			}
			catch (RejectedExecutionException e)
			{
				fail(COULDNT_SEND);
			}
		}

		private void finish(Reply reply)
		{
			if (!pending.isCancelled() && over.compareAndSet(false, true))
			{
				listener.onReply(reply);
			}
		}

		private void fail(String message)
		{
			fail(new Failure(message));
		}

		/** A response that broke off: what it counted so far is billed. */
		private void brokeOff(Message m)
		{
			usage.add(m.usage);
			model = m.model != null ? m.model : model;
		}

		/** Fails the reply, with the tokens its requests used so far. */
		private void fail(Failure failure)
		{
			if (!pending.isCancelled() && over.compareAndSet(false, true))
			{
				failure.usage.add(usage);
				failure.model = model;
				listener.onError(failure);
			}
		}
	}

	/** One response, put together from its streamed pieces as they arrive, or read whole. */
	private static final class Message
	{
		final StringBuilder content = new StringBuilder();
		/** Reasoning the service sent apart from the reply (reasoning_content): never shown. */
		final StringBuilder reasoning = new StringBuilder();
		/** Tool calls by their index, their arguments still arriving in pieces. */
		final TreeMap<Integer, ToolCall> calls = new TreeMap<>();
		final Usage usage = new Usage();
		String model;
		String refusal;
		String finish;
		String error;
		/** Read whole, not streamed. */
		boolean whole;
		/** The stream said it was done. */
		boolean done;
		/** The content has reasoning tags in it, so what's shown has to leave them out. */
		boolean thinks;
		String lastShown;

		/** What any piece can carry: the model, and (in the last one) the token counts. */
		void read(JsonObject o)
		{
			String m = string(o, "model");
			model = m != null && !m.isEmpty() ? m : model;
			JsonObject u = object(o, "usage");
			if (u != null)
			{
				long prompt = count(u, "prompt_tokens");
				JsonObject details = object(u, "prompt_tokens_details");
				long cached = details == null ? 0 : count(details, "cached_tokens");
				usage.input = Math.max(0, prompt - cached);
				usage.cacheRead = cached;
				usage.cacheWrite = 0;
				usage.output = count(u, "completion_tokens");
			}
			JsonObject choice = firstChoice(o);
			String f = choice == null ? null : string(choice, "finish_reason");
			finish = f != null ? f : finish;
		}

		/** A piece of a tool call: the first has its id and name, the rest more of its arguments. */
		void streamedCall(JsonObject c)
		{
			JsonElement index = c.get("index");
			String id = string(c, "id");
			int i;
			if (index != null && index.isJsonPrimitive() && index.getAsJsonPrimitive().isNumber())
			{
				i = index.getAsInt();
			}
			else if (calls.isEmpty())
			{
				i = 0;
			}
			else if (id != null && !id.equals(calls.lastEntry().getValue().id))
			{
				// No index (some local services): a new id is a new call.
				i = calls.lastKey() + 1;
			}
			else
			{
				i = calls.lastKey();
			}
			calls.computeIfAbsent(i, k -> new ToolCall()).add(c);
		}

		void whole(Gson gson, String json)
		{
			whole = true;
			JsonElement parsed = ChatApi.fromJson(gson, json, JsonElement.class);
			if (parsed == null || !parsed.isJsonObject())
			{
				throw new JsonParseException("not an object");
			}
			JsonObject o = parsed.getAsJsonObject();
			// OpenRouter can report a failure inside a 200 answer, with or without choices.
			error = errorIn(o);
			if (error != null)
			{
				return;
			}
			JsonObject choice = firstChoice(o);
			if (choice == null)
			{
				return;
			}
			read(o);
			done = true;
			JsonObject message = object(choice, "message");
			if (message == null)
			{
				return;
			}
			content.append(content(message.get("content")));
			String r = string(message, "reasoning_content");
			reasoning.append(r == null ? "" : r);
			refusal = string(message, "refusal");
			JsonElement toolCalls = message.get("tool_calls");
			if (toolCalls != null && toolCalls.isJsonArray())
			{
				int i = 0;
				for (JsonElement call : toolCalls.getAsJsonArray())
				{
					if (call.isJsonObject())
					{
						calls.computeIfAbsent(i++, k -> new ToolCall()).add(call.getAsJsonObject());
					}
				}
			}
		}
	}

	/** A tool call the model made. */
	private static final class ToolCall
	{
		String id;
		String name;
		final StringBuilder arguments = new StringBuilder();
		/**
		 * What else the service put on the call, to go back with it: Gemini's signature for the reasoning behind it
		 * ({"google": {"thought_signature": ...}}), without which it refuses the next round.
		 */
		JsonElement extra;

		void add(JsonObject piece)
		{
			String i = string(piece, "id");
			id = i != null && !i.isEmpty() ? i : id;
			JsonElement e = piece.get("extra_content");
			extra = e != null && !e.isJsonNull() ? e.deepCopy() : extra;
			JsonObject function = object(piece, "function");
			if (function == null)
			{
				return;
			}
			String n = string(function, "name");
			name = name == null && n != null && !n.isEmpty() ? n : name;
			JsonElement args = function.get("arguments");
			if (args != null && args.isJsonPrimitive())
			{
				arguments.append(args.getAsString());
			}
			else if (args != null && args.isJsonObject())
			{
				// A few services send the arguments as an object rather than as JSON text.
				arguments.append(args);
			}
		}
	}

	/** A call's arguments as an object; null if they aren't valid JSON (then it isn't run, and the model is told). */
	private static JsonObject arguments(Gson gson, String json)
	{
		if (json.trim().isEmpty())
		{
			return new JsonObject();
		}
		try
		{
			JsonElement parsed = ChatApi.fromJson(gson, json, JsonElement.class);
			if (parsed == null || parsed.isJsonNull())
			{
				return new JsonObject();
			}
			return parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
		}
		catch (JsonParseException e)
		{
			return null;
		}
	}

	/** The error a response or streamed piece carries, at its top or in its choice, or null. */
	private static String errorIn(JsonObject o)
	{
		String top = errorText(o.get("error"));
		if (top != null)
		{
			return top;
		}
		JsonObject choice = firstChoice(o);
		return choice == null ? null : errorText(choice.get("error"));
	}

	/** An error's message: {"message": ...} or plain text. Null if there's no error. */
	private static String errorText(JsonElement error)
	{
		if (error == null || error.isJsonNull())
		{
			return null;
		}
		String message = error.isJsonPrimitive() ? error.getAsString() : error.isJsonObject() ? string(error.getAsJsonObject(), "message") : null;
		return message != null ? message : "the service reported an error";
	}

	private static JsonObject firstChoice(JsonObject o)
	{
		JsonElement choices = o.get("choices");
		return choices != null && choices.isJsonArray() && choices.getAsJsonArray().size() > 0
			&& choices.getAsJsonArray().get(0).isJsonObject() ? choices.getAsJsonArray().get(0).getAsJsonObject() : null;
	}

	@Override
	public Pending listModels(ModelsListener listener)
	{
		Pending pending = new Pending();
		listModels(listener, pending, false);
		return pending;
	}

	/**
	 * Asks for {@code base}/models, or with {@code withV1} for {@code base}/v1/models: a URL that leaves out the /v1
	 * most services need (Ollama's "http://localhost:11434") isn't found, and chats sent there wouldn't be either.
	 */
	private void listModels(ModelsListener listener, Pending pending, boolean withV1)
	{
		Request.Builder request = new Request.Builder().url(base.resolve(withV1 ? "v1/models" : "models")).get();
		if (!apiKey.isEmpty())
		{
			request.header("Authorization", "Bearer " + apiKey);
		}
		Call call = http.newCall(request.build());
		pending.set(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				if (pending.isCancelled())
				{
					return;
				}
				if (withV1)
				{
					listener.onError(NO_MODEL_LIST);
					return;
				}
				listener.onError(ChatApi.tookTooLong(e) ? describe(base) + " didn't answer in time. Try again in a moment."
					: "Couldn't reach " + describe(base) + ": " + e.getMessage() + (isPrivate(base.host()) ? ". Is the service running?" : ""));
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				String text;
				try (ResponseBody body = response.body())
				{
					text = body == null ? "" : body.string().trim();
				}
				catch (IOException e)
				{
					if (!pending.isCancelled())
					{
						listener.onError(withV1 ? NO_MODEL_LIST : "Couldn't read the answer from " + describe(base) + ": " + e.getMessage());
					}
					return;
				}
				if (pending.isCancelled())
				{
					return;
				}
				if (withV1)
				{
					String fixed = base.resolve("v1").toString();
					listener.onError(response.isSuccessful() && modelIds(gson, text) != null
						? "The URL is missing /v1: set the Base URL in the AI Chat settings to " + fixed + "."
						: NO_MODEL_LIST);
					return;
				}
				if (response.code() == 404)
				{
					if (!base.encodedPath().endsWith("/v1/"))
					{
						listModels(listener, pending, true);
						return;
					}
					listener.onError(NO_MODEL_LIST);
					return;
				}
				if (!response.isSuccessful())
				{
					// No model is involved in listing them; explain only names one for a 404, handled above.
					listener.onError(explain(response.code(), ChatApi.errorMessage(gson, text), ""));
					return;
				}
				List<String> ids = modelIds(gson, text);
				if (ids == null)
				{
					listener.onError(describe(base) + " sent a model list AI Chat couldn't read.");
					return;
				}
				listener.onModels(ids);
			}
		});
	}

	/** The ids in a model list: {"data": [{"id": ...}, ...]}, or just the list. Null if it isn't one. */
	static List<String> modelIds(Gson gson, String json)
	{
		try
		{
			JsonElement parsed = ChatApi.fromJson(gson, json, JsonElement.class);
			JsonElement data = parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject().get("data") : parsed;
			if (data == null || !data.isJsonArray())
			{
				return null;
			}
			List<String> ids = new ArrayList<>();
			for (JsonElement m : data.getAsJsonArray())
			{
				String id = m.isJsonObject() ? string(m.getAsJsonObject(), "id") : null;
				if (id != null)
				{
					ids.add(id);
				}
			}
			return ids;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	/**
	 * The reply without reasoning some models write into it: whole {@code <think>} blocks, reasoning that ran out of
	 * room before its closing tag, and reasoning whose opening tag was part of the prompt.
	 */
	static String withoutThinking(String content)
	{
		String text = THINKING.matcher(content).replaceAll("");
		int close = text.lastIndexOf("</think>");
		if (close >= 0)
		{
			text = text.substring(close + "</think>".length());
		}
		int open = text.indexOf("<think>");
		if (open >= 0)
		{
			text = text.substring(0, open);
		}
		return text.trim();
	}

	/** Content is usually a string; some services send a list of parts, including thinking we don't show. */
	private static String content(JsonElement content)
	{
		if (content == null || content.isJsonNull())
		{
			return "";
		}
		if (content.isJsonPrimitive())
		{
			return content.getAsString();
		}
		StringBuilder sb = new StringBuilder();
		if (content.isJsonArray())
		{
			for (JsonElement part : content.getAsJsonArray())
			{
				if (!part.isJsonObject())
				{
					continue;
				}
				String type = string(part.getAsJsonObject(), "type");
				String t = string(part.getAsJsonObject(), "text");
				if (t != null && (type == null || type.equals("text") || type.equals("output_text")))
				{
					sb.append(t);
				}
			}
		}
		return sb.toString();
	}

	private String explain(int code, String message, String model)
	{
		String detail = message == null ? "" : " (" + ChatApi.shorten(message, 200) + ")";
		String where = describe(base);
		String lower = message == null ? "" : message.toLowerCase(Locale.ROOT);
		// Gemini answers a bad key with 400, not 401.
		if (code == 401 || code == 400 && lower.contains("api key"))
		{
			return where + " didn't accept the API key. Check it in the AI Chat settings" + detail + ".";
		}
		switch (code)
		{
			case 402:
				return where + " says your account is out of credits" + detail + ".";
			case 403:
				return where + " refused the request" + detail + ".";
			case 404:
				return "Not found at " + where + ": check the model \"" + model + "\"" + (openai ? "" : " and the URL") + " in the AI Chat settings" + detail + ".";
			case 429:
				return ChatApi.outOfCredits(message)
					? where + " says your account is out of credits or over its limit" + detail + "."
					: where + "'s rate limit was hit. Try again in a minute" + detail + ".";
			case 500:
			case 502:
			case 503:
			case 504:
			case 529:
				return where + " is having trouble right now. Try again shortly" + detail + ".";
			default:
				return where + " answered HTTP " + code + detail + ".";
		}
	}

	/**
	 * The base URL a player typed, e.g. "http://localhost:11434/v1" or "https://openrouter.ai/api/v1", or null if
	 * it isn't one. A pasted ".../chat/completions" is fine too. Nothing is added: services differ in their paths.
	 */
	static HttpUrl parseBaseUrl(String typed)
	{
		if (typed == null || typed.trim().isEmpty())
		{
			return null;
		}
		String s = typed.trim();
		while (s.endsWith("/"))
		{
			s = s.substring(0, s.length() - 1);
		}
		if (s.endsWith("/chat/completions"))
		{
			s = s.substring(0, s.length() - "/chat/completions".length());
		}
		return HttpUrl.parse(s + "/");
	}

	/** "localhost:11434" or "openrouter.ai", for messages. */
	static String describeUrl(String typed)
	{
		HttpUrl url = parseBaseUrl(typed);
		return url == null ? "?" : describe(url);
	}

	private static String describe(HttpUrl url)
	{
		boolean defaultPort = url.port() == HttpUrl.defaultPort(url.scheme());
		return url.host() + (defaultPort ? "" : ":" + url.port());
	}

	/**
	 * This computer or the home network, where plain http:// doesn't cross the internet: "localhost", ".local" names
	 * (resolved on the local network), and IP addresses in the loopback, private and link-local ranges. Only literal
	 * addresses count: a name like 10.example.com could point anywhere.
	 */
	static boolean isPrivate(String host)
	{
		String h = host.toLowerCase(Locale.ROOT);
		if (h.equals("localhost") || h.endsWith(".localhost") || h.endsWith(".local"))
		{
			return true;
		}
		if (h.startsWith("[") && h.endsWith("]"))
		{
			h = h.substring(1, h.length() - 1);
		}
		if (h.contains(":"))
		{
			// IPv6: loopback, unique local (fc00::/7) and link-local (fe80::/10).
			return h.equals("::1") || h.matches("f[cd][0-9a-f]{0,2}:.*") || h.matches("fe[89ab][0-9a-f]?:.*");
		}
		int[] ip = ipv4(h);
		if (ip == null)
		{
			return false;
		}
		return ip[0] == 127 || ip[0] == 10 || ip[0] == 192 && ip[1] == 168 || ip[0] == 172 && ip[1] >= 16 && ip[1] <= 31
			|| ip[0] == 169 && ip[1] == 254;
	}

	/** The four numbers of a dotted IPv4 address, or null if the host isn't one. */
	private static int[] ipv4(String host)
	{
		String[] parts = host.split("\\.", -1);
		if (parts.length != 4)
		{
			return null;
		}
		int[] ip = new int[4];
		for (int i = 0; i < 4; i++)
		{
			if (!parts[i].matches("\\d{1,3}"))
			{
				return null;
			}
			ip[i] = Integer.parseInt(parts[i]);
			if (ip[i] > 255)
			{
				return null;
			}
		}
		return ip;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}

	private static JsonObject object(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
	}

	private static long count(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() ? e.getAsLong() : 0;
	}
}

package com.aichat;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JMenuItem;
import javax.swing.JTextArea;
import javax.swing.JToolTip;
import net.runelite.client.ui.ColorScheme;

/**
 * The panel's fonts and colours, and the plain-text components it's built from. Colours come from RuneLite's own
 * {@link ColorScheme}, apart from the few it has no word for (errors, warnings, success).
 */
final class PanelStyle
{
	static final Font TEXT_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
	static final Font SMALL_FONT = TEXT_FONT.deriveFont(11f);
	static final Font TITLE_FONT = TEXT_FONT.deriveFont(Font.BOLD, 13f);
	static final Font HEADING_FONT = TEXT_FONT.deriveFont(Font.BOLD, 15f);

	static final Color TEXT_COLOR = Color.WHITE;
	static final Color MUTED_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
	static final Color ERROR_COLOR = new Color(0xff6b6b);
	static final Color OK_COLOR = new Color(0x5fd068);
	static final Color WARNING_COLOR = new Color(0xffb347);
	static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
	/** The player's bubbles, and what buttons show under the mouse: a little lighter than the panel. */
	static final Color BUBBLE_COLOR = ColorScheme.DARKER_GRAY_HOVER_COLOR;
	/** Boxes that hold something: the input, the banner. A little darker than the panel. */
	static final Color FIELD_COLOR = ColorScheme.DARKER_GRAY_COLOR;
	static final Color OUTLINE_COLOR = ColorScheme.MEDIUM_GRAY_COLOR;
	/** How round the corners of bubbles and boxes are. */
	static final int ARC = 12;

	private PanelStyle()
	{
	}

	/** Smooth edges for the shapes the panel draws itself. */
	static Graphics2D smooth(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		return g2;
	}

	/** A menu item whose words and tooltip are plain text, never HTML. */
	static JMenuItem menuItem(String text)
	{
		JMenuItem item = new JMenuItem()
		{
			@Override
			public JToolTip createToolTip()
			{
				JToolTip tip = super.createToolTip();
				tip.putClientProperty("html.disable", Boolean.TRUE);
				return tip;
			}
		};
		// Before the text is set: the HTML renderer is picked when it is.
		item.putClientProperty("html.disable", Boolean.TRUE);
		item.setText(text);
		return item;
	}

	/** A read-only, wrapping, selectable block of plain text (a text area never renders HTML, nor does its tooltip). */
	static JTextArea textArea(String text)
	{
		JTextArea t = new JTextArea(text)
		{
			@Override
			public JToolTip createToolTip()
			{
				JToolTip tip = super.createToolTip();
				tip.putClientProperty("html.disable", Boolean.TRUE);
				return tip;
			}
		};
		t.setEditable(false);
		t.setLineWrap(true);
		t.setWrapStyleWord(true);
		t.setFont(TEXT_FONT);
		t.setBorder(null);
		t.setOpaque(false);
		return t;
	}
}

package com.aichat;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Date;
import java.util.List;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The panel's words around the messages: the line under a reply on its way saying what it's doing, each message's
 * tooltip, how notes read, and the line saying what was looked up or shared for a message. Pure, so it's tested
 * without Swing.
 */
final class PanelText
{
	/** "Thinking" counts its dots for this long; then the seconds count instead, for a model that's slow to start. */
	static final int THINKING_DOTS_SECONDS = 5;
	/** A summary's note, as {@link ConversationBuilder#applySummary} writes it: how many messages, then the summary. */
	private static final Pattern SUMMARY_NOTE = Pattern.compile(
		"Summary of the (?:(\\d+) earlier messages, sent instead of them|earlier message, sent instead of it):\\n\\n(.*)",
		Pattern.DOTALL);

	private PanelText()
	{
	}

	/**
	 * The muted line under the reply on its way, at {@code now} (milliseconds): what it's doing while there are no new
	 * words to read. Null while it's writing.
	 */
	static String live(Chat chat, long now)
	{
		if (chat.retryWhy != null && chat.retryAt > now)
		{
			return chat.retryWhy + "; trying again in " + ChatApi.seconds(chat.retryAt - now) + "s";
		}
		long ms = now - chat.runStartedAt;
		if (chat.isSummarizing())
		{
			return "Summarising earlier messages\u2026 " + elapsed(ms);
		}
		if (chat.lookingUp)
		{
			// What it looked up is listed just above, as each look-up comes back: this line only says it's still going.
			return "Looking things up\u2026 " + elapsed(ms);
		}
		return chat.liveText == null ? thinking(ms) : null;
	}

	/**
	 * Before the first words: "Thinking" with one, two, then three dots, a step a second (the panel's ticker redraws it
	 * each second), then the seconds it's been, since a model on the player's own computer can take minutes to start.
	 */
	static String thinking(long ms)
	{
		long secs = Math.max(0, ms / 1000);
		if (secs < THINKING_DOTS_SECONDS)
		{
			return "Thinking" + "...".substring(0, (int) (secs % 3) + 1);
		}
		return "Thinking\u2026 " + elapsed(ms);
	}

	/** "12s", "3m 5s". */
	static String elapsed(long ms)
	{
		long secs = Math.max(0, ms / 1000);
		return secs < 60 ? secs + "s" : (secs / 60) + "m " + (secs % 60) + "s";
	}

	/**
	 * A message's tooltip: when it was sent, and for a reply who wrote it, with what the transcript no longer spells out
	 * under each message: a question that went unanswered, a reply that didn't finish, a message the summary now
	 * stands in for.
	 */
	static String tooltip(Chat.Message m)
	{
		String time = new SimpleDateFormat("HH:mm").format(new Date(m.time));
		StringBuilder tip = new StringBuilder();
		if (m.role == Chat.Role.ASSISTANT)
		{
			tip.append(m.who != null ? m.who : "Assistant").append(" \u00b7 ");
		}
		tip.append(time);
		if (m.role == Chat.Role.USER && m.unanswered)
		{
			tip.append(" \u00b7 not answered");
		}
		if (m.unfinished)
		{
			tip.append(" \u00b7 didn't finish");
		}
		if (m.summarized)
		{
			tip.append(" \u00b7 summarised: the summary further down is sent instead");
		}
		return tip.toString();
	}

	/** How the transcript shows a note: one line, and what's a click away from it. */
	static final class Note
	{
		final String line;
		/** Null for nothing more. */
		final String details;

		private Note(String line, String details)
		{
			this.line = line;
			this.details = details;
		}
	}

	/**
	 * A note as the transcript shows it: a summary's note is a short line, "Summary of 24 earlier messages", with the
	 * summary itself a click away (it can be long); any other note is shown as it is.
	 */
	static Note note(String text)
	{
		Matcher m = SUMMARY_NOTE.matcher(text == null ? "" : text);
		if (!m.matches())
		{
			return new Note(text == null ? "" : text, null);
		}
		String count = m.group(1);
		String line = count == null ? "Summary of 1 earlier message" : "Summary of " + count + " earlier messages";
		return new Note(line, m.group(2).trim());
	}

	/**
	 * What was looked up or shared for a message, as the panel shows it: one muted line over the message, with
	 * everything a click away. What the player shared of their own is named first, and always in full; then the Wiki
	 * pages and GE prices, by name when they fit, or counted ("Looked up 3 things", "3 look-ups") when they don't.
	 */
	static final class Summary
	{
		/** Between the parts of the line. */
		static final String SEPARATOR = " \u00b7 ";
		static final String ELLIPSIS = "\u2026";
		/** What a line cut short doesn't end on, before its ellipsis: spaces, and the marks that join words. */
		private static final Pattern TRAILING = Pattern.compile("[\\s:;,\u00b7]+$");

		/** "Shared your equipment and inventory", or null when nothing of the player's was shared. */
		final String sharing;
		/** "Looked up Vorkath, Dragon bones (GE price)", or null when nothing was. */
		final String lookups;
		/**
		 * "Looked up 3 things", or null when nothing was. Also null for one thing when nothing was shared: its name cut
		 * short says more than "Looked up 1 thing".
		 */
		final String count;
		/** "3 look-ups": the count, shorter. Null when {@link #count} is. */
		final String tally;
		/** When nothing was shared or looked up: the first line there is (a skipped look-up, say), or null. */
		final String other;
		/**
		 * Everything, for when the line is clicked: each line as it was recorded (what was shared, skipped or went
		 * wrong), then what was looked up, one kind to a line ("Wiki pages: ...", "Wiki searches: ...", "GE prices:
		 * ..."). Empty when there's nothing.
		 */
		final String details;

		private Summary(String sharing, String lookups, int things, String other, String details)
		{
			this.sharing = sharing;
			this.lookups = lookups;
			boolean counted = things > 1 || things == 1 && sharing != null;
			this.count = counted ? "Looked up " + things + (things == 1 ? " thing" : " things") : null;
			this.tally = counted ? things + (things == 1 ? " look-up" : " look-ups") : null;
			this.other = other;
			this.details = details;
		}

		/** Whether there's nothing to show: no line at all. */
		boolean isEmpty()
		{
			return details.isEmpty();
		}

		/**
		 * The line, as long as {@code fits} says fits on one row: the look-ups by name, else counted ("Looked up 3
		 * things", then "3 look-ups"), else cut short at the end. Never cut into what was shared: after it, the look-ups
		 * are cut down to an ellipsis, or left off (the line's chevron says there's more); only if what was shared
		 * doesn't fit by itself is the line longer than a row: it wraps, with the count on a row of its own.
		 */
		String line(Predicate<String> fits)
		{
			String named = join(sharing, lookups != null ? lookups : other);
			if (fits.test(named))
			{
				return named;
			}
			if (count != null && fits.test(join(sharing, count)))
			{
				return join(sharing, count);
			}
			if (tally != null && fits.test(join(sharing, tally)))
			{
				return join(sharing, tally);
			}
			if (sharing != null)
			{
				if (tally == null)
				{
					// Only what was shared, which is never cut.
					return sharing;
				}
				// A count cut short says nothing: all of it goes, after what was shared.
				for (String shorter : new String[]{sharing + SEPARATOR + ELLIPSIS, sharing + ELLIPSIS, sharing})
				{
					if (fits.test(shorter))
					{
						return shorter;
					}
				}
				// Longer than a row by itself: the count on a row of its own, rather than a separator left at the end
				// of one row or the start of the next.
				return sharing + "\n" + tally;
			}
			if (tally != null)
			{
				return tally;
			}
			// One thing looked up, or a line of its own: the longest start of it that fits with the ellipsis after it;
			// widths only grow with the length.
			int lo = 0;
			int hi = named.length() - 1;
			int best = -1;
			while (lo <= hi)
			{
				int mid = (lo + hi) >>> 1;
				if (fits.test(cut(named, mid)))
				{
					best = mid;
					lo = mid + 1;
				}
				else
				{
					hi = mid - 1;
				}
			}
			if (best < 0)
			{
				return named;
			}
			if (best < named.length() && named.charAt(best) != ' ')
			{
				// Not in the middle of a word: back to the space before it, if there's one.
				int space = named.lastIndexOf(' ', best - 1);
				best = space > 0 ? space : best;
			}
			return cut(named, best);
		}

		/** The first {@code length} characters of {@code text}, and an ellipsis: no stray space or colon before it. */
		static String cut(String text, int length)
		{
			return TRAILING.matcher(text.substring(0, length)).replaceFirst("") + ELLIPSIS;
		}

		private static String join(String first, String second)
		{
			if (first == null || second == null)
			{
				return first != null ? first : second == null ? "" : second;
			}
			return first + SEPARATOR + second;
		}
	}

	/**
	 * Sums up {@code lines} (a message's {@link Chat.Message#activity}; null for none) for the line over the message.
	 * Lines from {@link GameDataTools} for what was shared are put together ("Shared your equipment and bank"), and the
	 * Wiki and GE price look-ups from {@link LookupTools} too, each thing named once: the Wiki pages read (or, when none
	 * was, what was searched for), then the GE prices. A line for each was too much to read over every reply. Done only
	 * when shown: the saved lines keep every look-up, and chats saved by earlier versions show the same way.
	 */
	static Summary summary(List<String> lines)
	{
		List<String> pages = new ArrayList<>();
		List<String> searches = new ArrayList<>();
		List<String> prices = new ArrayList<>();
		List<String> rest = new ArrayList<>();
		for (String line : lines == null ? Collections.<String>emptyList() : lines)
		{
			if (line != null && !fold(line, pages, searches, prices))
			{
				rest.add(line);
			}
		}
		List<String> details = new ArrayList<>(rest);
		if (!pages.isEmpty())
		{
			details.add("Wiki pages: " + String.join(", ", pages));
		}
		if (!searches.isEmpty())
		{
			details.add("Wiki searches: " + quoted(searches));
		}
		if (!prices.isEmpty())
		{
			details.add("GE prices: " + String.join(", ", prices));
		}

		String sharing = sharing(rest);
		// The pages say what the searches found: the searches count only when no page was read.
		List<String> wiki = pages.isEmpty() ? quotedEach(searches) : pages;
		int things = wiki.size() + prices.size();
		String lookups = null;
		if (things > 0)
		{
			List<String> names = new ArrayList<>(wiki);
			if (!prices.isEmpty())
			{
				names.add(String.join(", ", prices) + (prices.size() == 1 ? " (GE price)" : " (GE prices)"));
			}
			lookups = "Looked up " + String.join(", ", names);
		}
		String other = sharing == null && lookups == null && !rest.isEmpty() ? brief(rest.get(0)) : null;
		return new Summary(sharing, lookups, things, other, String.join("\n", details));
	}

	/**
	 * What the player shared of their own, from {@link GameDataTools}' lines: "Shared your equipment, inventory and
	 * bank", "Searched your bank", "Shared your equipment and searched your bank"; null for nothing. Lines for what
	 * wasn't shared after all (the request had stopped, a setting is off) don't count.
	 */
	private static String sharing(List<String> lines)
	{
		List<String> shared = new ArrayList<>();
		boolean searched = false;
		for (String line : lines)
		{
			if (line.startsWith(GameDataTools.SHARED))
			{
				addOnce(shared, line.substring(GameDataTools.SHARED.length()));
			}
			else if (line.startsWith(GameDataTools.SEARCHED) && !line.endsWith(GameDataTools.UNSHARED))
			{
				searched = true;
			}
		}
		// Sharing the whole bank says it all for a search of it too.
		searched &= !shared.contains("bank");
		if (shared.isEmpty())
		{
			return searched ? "Searched your bank" : null;
		}
		String what = "Shared your " + and(shared);
		if (!searched)
		{
			return what;
		}
		return what + (shared.size() > 1 ? ", and" : " and") + " searched your bank";
	}

	/** "a", "a and b", "a, b and c". */
	private static String and(List<String> items)
	{
		if (items.size() == 1)
		{
			return items.get(0);
		}
		return String.join(", ", items.subList(0, items.size() - 1)) + " and " + items.get(items.size() - 1);
	}

	/** A line on its own, as the summary shows it when it's all there is: the long ones said shorter. */
	private static String brief(String line)
	{
		if (RequestRunner.NO_LOOKUPS.equals(line))
		{
			return "No look-ups: this model can't use tools";
		}
		if (line.endsWith(GameDataTools.UNSHARED))
		{
			// What was read but never sent (see GameDataTools.unshared): the details have the line in full.
			String read = line.substring(0, line.length() - GameDataTools.UNSHARED.length());
			if (read.startsWith(GameDataTools.READ))
			{
				return "Didn't share your " + read.substring(GameDataTools.READ.length()) + " (stopped)";
			}
			if (read.startsWith(GameDataTools.SEARCHED))
			{
				return "Didn't share your bank search (stopped)";
			}
		}
		return line;
	}

	/**
	 * For a line {@link LookupTools} wrote for a look-up that went through: adds what was looked up to its list, once.
	 * False for any other line, which is shown as it is.
	 */
	private static boolean fold(String line, List<String> pages, List<String> searches, List<String> prices)
	{
		if (line.startsWith(LookupTools.SEARCHED_WIKI))
		{
			return addOnce(searches, unquote(line.substring(LookupTools.SEARCHED_WIKI.length())));
		}
		if (line.startsWith(LookupTools.READ_WIKI_PAGE))
		{
			return addOnce(pages, pageTitle(line.substring(LookupTools.READ_WIKI_PAGE.length())));
		}
		if (line.startsWith(LookupTools.CHECKED_GE_PRICE))
		{
			String item = line.substring(LookupTools.CHECKED_GE_PRICE.length()).trim();
			return addOnce(prices, item.isEmpty() ? null : item);
		}
		return false;
	}

	/** False when there's no {@code name}: the line wasn't one the look-ups make after all. */
	private static boolean addOnce(List<String> names, String name)
	{
		if (name == null)
		{
			return false;
		}
		if (!names.contains(name))
		{
			names.add(name);
		}
		return true;
	}

	/** {@code Abyssal whip} from {@code "Abyssal whip"}; null for anything else. */
	private static String unquote(String s)
	{
		return s.length() > 2 && s.startsWith("\"") && s.endsWith("\"") ? s.substring(1, s.length() - 1) : null;
	}

	/** The title from {@code "Abyssal whip"}, or from {@code "Abyssal whip" (Drops)} when one section was read. */
	private static String pageTitle(String s)
	{
		int end = s.indexOf("\" (");
		return unquote(end > 0 && s.endsWith(")") ? s.substring(0, end + 1) : s);
	}

	private static List<String> quotedEach(List<String> names)
	{
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			out.add('"' + name + '"');
		}
		return out;
	}

	private static String quoted(List<String> names)
	{
		return String.join(", ", quotedEach(names));
	}
}

package com.aichat;

import com.google.gson.Gson;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;

/**
 * The chosen provider as the settings describe it: what's still missing, what answers new messages, and the API to
 * send with. Reads the settings each time it's asked, so it's always the current choice. Any thread.
 */
final class ProviderSetup
{
	static final String BAD_KEY = "Your API key has a character that can't be sent, like a curly quote copied along "
		+ "with it. Paste it into the AI Chat settings again.";

	private final AiChatConfig config;

	ProviderSetup(AiChatConfig config)
	{
		this.config = config;
	}

	/** What's missing before messages can be sent, or null when the chosen provider is set up. */
	String problem()
	{
		String connection = connectionProblem();
		if (connection != null || !blank(model()))
		{
			return connection;
		}
		switch (config.provider())
		{
			case CLAUDE:
				return "Pick a Claude model next to Send, or set one in the Claude section of the AI Chat settings.";
			case CHATGPT:
				return "Pick a ChatGPT model next to Send, or set one in the ChatGPT section of the AI Chat settings.";
			default:
				return "Pick a model next to Send, or set one in the Other (OpenAI-compatible) section of the AI Chat "
					+ "settings.";
		}
	}

	/**
	 * What's missing before the provider can be reached, or null: {@link #problem()} without the model, which "Test"
	 * doesn't need (it's how a player finds one).
	 */
	String connectionProblem()
	{
		if (!config.aiRequests())
		{
			return "Turn on \"Enable AI requests\" in the AI Chat settings, then choose a provider and add your API key.";
		}
		switch (config.provider())
		{
			case CLAUDE:
			{
				String key = ChatApi.cleanKey(config.claudeApiKey());
				if (key.isEmpty())
				{
					return "Add your Claude API key in the Claude section of the AI Chat settings (from console.anthropic.com).";
				}
				return ChatApi.sendableKey(key) ? null : BAD_KEY;
			}
			case CHATGPT:
			{
				String key = ChatApi.cleanKey(config.openaiApiKey());
				if (key.isEmpty())
				{
					return "Add your OpenAI API key in the ChatGPT section of the AI Chat settings (from platform.openai.com).";
				}
				return ChatApi.sendableKey(key) ? null : BAD_KEY;
			}
			default:
			{
				HttpUrl url = OpenAiApi.parseBaseUrl(config.compatibleUrl());
				if (url == null)
				{
					return "Set the Base URL in the Other (OpenAI-compatible) section of the AI Chat settings, for example "
						+ "http://localhost:11434/v1.";
				}
				String key = ChatApi.cleanKey(config.compatibleApiKey());
				if (!ChatApi.sendableKey(key))
				{
					return BAD_KEY;
				}
				if (!url.isHttps() && !key.isEmpty() && !OpenAiApi.isPrivate(url.host()))
				{
					return "Use an https:// URL for " + url.host() + ": with http:// your API key would cross the internet unencrypted.";
				}
				return null;
			}
		}
	}

	/**
	 * The provider's API, with the player's key; null while something's missing (see {@link #problem()}).
	 * {@code refused}: optional request settings services and models have refused, shared while the plugin runs.
	 */
	ChatApi api(OkHttpClient http, Gson gson, ScheduledExecutorService scheduler, Map<String, Set<String>> refused)
	{
		return problem() != null ? null : build(http, gson, scheduler, refused);
	}

	/**
	 * The provider's API for "Test", which needs no model yet; null while it can't be reached (see
	 * {@link #connectionProblem()}).
	 */
	ChatApi testApi(OkHttpClient http, Gson gson, ScheduledExecutorService scheduler, Map<String, Set<String>> refused)
	{
		return connectionProblem() != null ? null : build(http, gson, scheduler, refused);
	}

	private ChatApi build(OkHttpClient http, Gson gson, ScheduledExecutorService scheduler, Map<String, Set<String>> refused)
	{
		switch (config.provider())
		{
			case CLAUDE:
				return new AnthropicApi(http, gson, AnthropicApi.URL, ChatApi.cleanKey(config.claudeApiKey()), scheduler, refused);
			case CHATGPT:
				return new OpenAiApi(http, gson, OpenAiApi.OPENAI_URL, ChatApi.cleanKey(config.openaiApiKey()), "ChatGPT", true,
					"low", scheduler, refused);
			default:
				return new OpenAiApi(http, gson, OpenAiApi.parseBaseUrl(config.compatibleUrl()),
					ChatApi.cleanKey(config.compatibleApiKey()), model(), false, config.compatibleThinking().effort, scheduler, refused);
		}
	}

	String model()
	{
		switch (config.provider())
		{
			case CLAUDE:
				return config.claudeModel().trim();
			case CHATGPT:
				return config.openaiModel().trim();
			default:
				return config.compatibleModel().trim();
		}
	}

	/** The setting {@link #model()} comes from, for the model picker. */
	String modelKey()
	{
		switch (config.provider())
		{
			case CLAUDE:
				return "claudeModel";
			case CHATGPT:
				return "openaiModel";
			default:
				return "compatibleModel";
		}
	}

	/** Who "Test" talks to, for its note: "Anthropic", "OpenAI", or a compatible service's address. */
	String service()
	{
		switch (config.provider())
		{
			case CLAUDE:
				return "Anthropic";
			case CHATGPT:
				return "OpenAI";
			default:
				return OpenAiApi.describeUrl(config.compatibleUrl());
		}
	}

	/** Whether the player's key decides which models they can use (not so for a compatible service's list). */
	boolean keyed()
	{
		return config.provider() != AiChatConfig.Provider.OPENAI_COMPATIBLE;
	}

	/**
	 * Whether "Test" can't vouch for the key: a compatible service may list its models for anyone (OpenRouter does),
	 * so a wrong key there only shows when a message is sent.
	 */
	boolean keyUnchecked()
	{
		return !keyed() && !ChatApi.cleanKey(config.compatibleApiKey()).isEmpty();
	}

	/** The provider, address and key: what a "Test" result holds for (see {@link ConnectionCheck#setupKey}). */
	String connection()
	{
		switch (config.provider())
		{
			case CLAUDE:
				return ConnectionCheck.setupKey(config.provider(), null, ChatApi.cleanKey(config.claudeApiKey()));
			case CHATGPT:
				return ConnectionCheck.setupKey(config.provider(), null, ChatApi.cleanKey(config.openaiApiKey()));
			default:
				return ConnectionCheck.setupKey(config.provider(), config.compatibleUrl(), ChatApi.cleanKey(config.compatibleApiKey()));
		}
	}

	private static boolean blank(String s)
	{
		return s == null || s.trim().isEmpty();
	}
}

package com.aichat;

import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

/**
 * Sends a chat's messages and puts the answers in it: the summary a long chat needs first, the character details, the
 * tools, the reply as it streams in, Stop and Retry. Everything here runs on the Swing EDT, where the chats live. The
 * providers answer on their own threads; their answers come back through {@code edt} and count only while their
 * request is still the chat's current one (not stopped, not replaced, the chat not deleted).
 */
@Slf4j
final class RequestRunner
{
	/** The reply is redrawn at most this often while it streams in (about 15 times a second): each redraw is a layout. */
	static final long LIVE_GAP_MILLIS = 66;
	/** How the notes that say a request was stopped start. */
	static final String STOPPED = "Stopped";
	static final String COULDNT_SEND = "AI Chat couldn't send this. Check the API key and URL in the settings.";
	/** Under a reply from a model that can't use tools, whatever the settings say. */
	static final String NO_LOOKUPS = "No look-ups: this model can't use tools, so it answered from memory";

	/** What the runner needs from the plugin. On the EDT unless it says otherwise. */
	interface Host
	{
		/** "Enable AI requests", right now. */
		boolean aiRequests();

		/**
		 * "Share character details" (and AI requests), right now. A message keeps the setting it was sent with, but a summary
		 * first can take a while: turning it off meanwhile leaves the details out all the same.
		 */
		boolean shareCharacter();

		/**
		 * Reads the character details to send with a message and hands them to {@code done}, on any thread: null when
		 * there are none (not logged in, or they couldn't be read).
		 */
		void readCharacter(Consumer<String> done);

		/**
		 * The tools for one request, with the settings in {@code setup}. {@code wanted}: false once the request has
		 * stopped. {@code activity} hears one line per call, and {@code started} when a call starts, all on the tools' own
		 * threads.
		 */
		ToolBox tools(Setup setup, BooleanSupplier wanted, Consumer<String> activity, Runnable started);

		/** Whether the chat is still one of the plugin's (not deleted). */
		boolean has(Chat chat);

		/** The chat's messages changed: show them and save. */
		void changed(Chat chat);

		/** Only what's shown of the request in flight changed (its text, look-ups or status): nothing to save. */
		void live(Chat chat);

		/** A request ended with a reply or an error: tell the player (a notification, game chat). */
		void ended(Chat chat, Chat.Message m);
	}

	/** What a message is sent with: the provider, and the settings of when the player sent it. */
	static final class Setup
	{
		final ChatApi api;
		final String model;
		final String system;
		final boolean shareCharacter;
		final boolean shareItems;
		final boolean wikiLookups;

		Setup(ChatApi api, String model, String system, boolean shareCharacter, boolean shareItems, boolean wikiLookups)
		{
			this.api = api;
			this.model = model;
			this.system = system;
			this.shareCharacter = shareCharacter;
			this.shareItems = shareItems;
			this.wikiLookups = wikiLookups;
		}
	}

	/** A message on its way, with what it's sent with. */
	private static final class Outgoing
	{
		final Chat chat;
		final Chat.Message message;
		final Setup setup;
		/** It was too long for the model once, and goes again after a summary: if that's not enough, it's an error. */
		final boolean shortened;

		Outgoing(Chat chat, Chat.Message message, Setup setup, boolean shortened)
		{
			this.chat = chat;
			this.message = message;
			this.setup = setup;
			this.shortened = shortened;
		}
	}

	private final Host host;
	/** Runs a task on the EDT later, never right away: SwingUtilities::invokeLater. */
	private final Executor edt;
	/** Only for the short waits between redraws of a streaming reply. */
	private final ScheduledExecutorService scheduler;

	RequestRunner(Host host, Executor edt, ScheduledExecutorService scheduler)
	{
		this.host = host;
		this.edt = edt;
		this.scheduler = scheduler;
	}

	// ------------------------------------------------------------------
	// Sending
	// ------------------------------------------------------------------

	/** Sends {@code text} as the chat's next message. Only when the chat isn't waiting for a reply. */
	void send(Chat chat, String text, Setup setup)
	{
		Chat.Message message = new Chat.Message(Chat.Role.USER, text);
		chat.messages.add(message);
		if (chat.defaultName)
		{
			chat.name = ChatApi.shorten(text.replaceAll("\\s+", " "), 40);
			chat.defaultName = false;
		}
		start(new Outgoing(chat, message, setup, false));
	}

	/**
	 * The question Retry would send again, or null: the player's last message, when it went unanswered and nothing but
	 * errors, notes (a "Stopped" one, or the one saying a chat too long for the model is summarised first) or what was
	 * shown of a reply that didn't finish came after it (or RuneLite closed while it waited).
	 */
	static Chat.Message retryable(Chat chat)
	{
		if (chat.isRunning())
		{
			return null;
		}
		for (int i = chat.messages.size() - 1; i >= 0; i--)
		{
			Chat.Message m = chat.messages.get(i);
			if (m.role == Chat.Role.USER)
			{
				return m.unanswered ? m : null;
			}
			if (m.role == Chat.Role.ASSISTANT && !m.unfinished)
			{
				return null;
			}
		}
		return null;
	}

	/**
	 * Sends the chat's unanswered question again: the same message, with the settings of now, and a new request
	 * (summary first, if the chat needs one). False if there's nothing to retry.
	 */
	boolean retry(Chat chat, Setup setup)
	{
		Chat.Message question = retryable(chat);
		if (question == null)
		{
			return false;
		}
		question.unanswered = false;
		start(new Outgoing(chat, question, setup, false));
		return true;
	}

	/**
	 * The reply Retry would write again, or null: the chat's last message, when it's a reply that finished, to a question
	 * that's still sent. Only the latest one: writing an older reply again would change what every later message was
	 * built on.
	 */
	static Chat.Message regenerable(Chat chat)
	{
		if (chat.isRunning() || chat.messages.isEmpty())
		{
			return null;
		}
		Chat.Message last = chat.messages.get(chat.messages.size() - 1);
		if (last.role != Chat.Role.ASSISTANT || last.unfinished)
		{
			return null;
		}
		Chat.Message question = questionOf(chat, last);
		return question != null && ConversationBuilder.stillSent(question) ? last : null;
	}

	/**
	 * The player's message {@code reply} answers: the nearest one before it, with nothing in between but notes, errors
	 * and what was shown of replies that didn't finish. Null if there's none.
	 */
	private static Chat.Message questionOf(Chat chat, Chat.Message reply)
	{
		for (int i = chat.messages.indexOf(reply) - 1; i >= 0; i--)
		{
			Chat.Message m = chat.messages.get(i);
			if (m.role == Chat.Role.USER)
			{
				return m;
			}
			if (m.role == Chat.Role.ASSISTANT && !m.unfinished)
			{
				return null;
			}
		}
		return null;
	}

	/**
	 * Retry on the latest reply: it's taken out, and its question goes again with the settings of now, as a new
	 * request. Everything before the question stays exactly as it was sent, so the provider's cache and Claude's earlier
	 * replies, sent back as they came, still apply. False unless {@code reply} is the one {@link #regenerable} names.
	 */
	boolean regenerate(Chat chat, Chat.Message reply, Setup setup)
	{
		if (reply == null || reply != regenerable(chat))
		{
			return false;
		}
		Chat.Message question = questionOf(chat, reply);
		chat.messages.remove(reply);
		start(new Outgoing(chat, question, setup, false));
		return true;
	}

	private void start(Outgoing out)
	{
		Chat chat = out.chat;
		// Busy from now on, so nothing else is sent in this chat while the request is put together.
		chat.pending = new ChatApi.Pending();
		chat.runStartedAt = System.currentTimeMillis();
		chat.resetLive();
		chat.answering = out.setup.api.displayName();
		List<Chat.Message> old = ConversationBuilder.planSummary(chat);
		if (old.isEmpty())
		{
			readCharacter(out);
		}
		else
		{
			summarise(out, old);
		}
		host.changed(chat);
	}

	/**
	 * The chat has grown long: its oldest messages are summarised with one extra request, and the message goes out
	 * after that, with the summary instead of them or, if there's none, with the whole chat.
	 */
	private void summarise(Outgoing out, List<Chat.Message> old)
	{
		Chat chat = out.chat;
		// The setting may have been turned off just now, with the stop it brings still waiting its turn on the EDT.
		if (!host.aiRequests())
		{
			stop(chat, "Stopped: AI requests are turned off.");
			return;
		}
		// Set before any answer can be handled: answers are handled on this (the EDT) thread, after this method.
		ChatApi.Pending[] request = new ChatApi.Pending[1];
		try
		{
			request[0] = out.setup.api.send(ConversationBuilder.summaryConversation(chat, old, out.setup.model), new ChatApi.Listener()
			{
				@Override
				public void onRetrying(String message, int seconds)
				{
					edt.execute(() -> retrying(chat, request[0], message, seconds));
				}

				@Override
				public void onReply(ChatApi.Reply reply)
				{
					edt.execute(() -> summarised(out, old, request[0], reply, null));
				}

				@Override
				public void onError(ChatApi.Failure failure)
				{
					edt.execute(() -> summarised(out, old, request[0], null, failure));
				}
			});
		}
		catch (RuntimeException e)
		{
			couldntSend(out);
			return;
		}
		chat.pending = request[0];
		// Stop (the panel calls it Skip meanwhile) skips the summary, not the message: this time the whole chat is sent
		// instead. Pressed again, it stops the message.
		chat.skipSummary = () ->
		{
			request[0].cancel();
			afterSummary(out, old, null, new ChatApi.Failure("you skipped it"));
		};
	}

	/** The answer to a summary request, if it still counts. */
	private void summarised(Outgoing out, List<Chat.Message> old, ChatApi.Pending request, ChatApi.Reply reply,
		ChatApi.Failure failure)
	{
		logUsage("summary", out, reply, failure);
		if (current(out.chat, request))
		{
			afterSummary(out, old, reply, failure);
		}
	}

	/**
	 * Sends the summary instead of the oldest messages from now on, or says why there's none this time (then nothing is
	 * left out, and the next message tries again). Either note goes just before the question, where the player sees it.
	 * Then the question goes out.
	 */
	private void afterSummary(Outgoing out, List<Chat.Message> old, ChatApi.Reply reply, ChatApi.Failure failure)
	{
		Chat chat = out.chat;
		chat.skipSummary = null;
		// Still busy: the question itself is next, and its time starts now.
		chat.pending = new ChatApi.Pending();
		chat.runStartedAt = System.currentTimeMillis();
		chat.resetLive();
		// A summary cut off by its length limit (a thinking model can spend most of it thinking) would lose the rest of
		// what it was meant to keep, for good: none rather than that.
		boolean whole = reply != null && reply.text != null && !reply.text.trim().isEmpty() && !reply.cutShort;
		if (whole)
		{
			ConversationBuilder.applySummary(chat, old, reply.text, out.message);
		}
		else
		{
			String reason = failure != null ? failure.message
				: reply != null && reply.cutShort ? "the summary was cut short" : "the summary came back empty";
			ConversationBuilder.addBefore(chat, out.message, new Chat.Message(Chat.Role.NOTE, ConversationBuilder.summaryFailed(reason)));
		}
		host.changed(chat);
		readCharacter(out);
	}

	/** Reads the character details first if they go with the message, then sends it. */
	private void readCharacter(Outgoing out)
	{
		if (!shareCharacter(out))
		{
			dispatch(out, null);
			return;
		}
		Chat chat = out.chat;
		ChatApi.Pending placeholder = chat.pending;
		host.readCharacter(context -> edt.execute(() ->
		{
			// Not if it was stopped (or the plugin turned off) in the meantime.
			if (current(chat, placeholder))
			{
				dispatch(out, context);
			}
		}));
	}

	/** Whether character details go with the message: they did when it was sent, and still do. */
	private boolean shareCharacter(Outgoing out)
	{
		return out.setup.shareCharacter && host.shareCharacter();
	}

	/** Sends the chat so far. {@code context}: the character details read for the message, if any. */
	private void dispatch(Outgoing out, String context)
	{
		Chat chat = out.chat;
		if (!host.aiRequests())
		{
			stop(chat, "Stopped: AI requests are turned off.");
			return;
		}
		ChatApi.Conversation conversation = ConversationBuilder.conversation(chat, out.message, out.setup.model,
			out.setup.system, shareCharacter(out), context);
		if (out.message.context != null)
		{
			// The character details go with it: the transcript says so under the message, and the chat is saved with them.
			host.changed(chat);
		}
		// This request's look-ups. They go with whatever ends it, so a look-up that finishes after a Stop is still shown.
		List<String> activity = chat.liveActivity;
		// Set before any answer can be handled: answers are handled on this (the EDT) thread, after this method.
		ChatApi.Pending[] request = new ChatApi.Pending[1];
		// The same, for the tools' own threads: whether the request still wants their results.
		AtomicReference<ChatApi.Pending> sent = new AtomicReference<>();
		BooleanSupplier wanted = () ->
		{
			ChatApi.Pending p = sent.get();
			return p == null || !p.isCancelled();
		};
		Throttle<String> partial = new Throttle<>(edt, scheduler, LIVE_GAP_MILLIS, text -> writing(chat, request[0], text));
		ToolBox tools = host.tools(out.setup, wanted,
			line ->
			{
				// Whether the result goes on its way is decided now, on this thread: the provider checks the same flag
				// before sending it. By the time the EDT gets to the line, a Stop that was waiting there may have set it.
				boolean stoppedFirst = !wanted.getAsBoolean();
				edt.execute(() -> lookedUp(chat, request[0], activity, line, stoppedFirst));
			},
			() ->
			{
				// The text so far, which a look-up that's quicker than the redraws mustn't be mistaken for new.
				String before = partial.latest();
				edt.execute(() -> lookingUp(chat, request[0], before));
			});
		tools.addTo(conversation);
		try
		{
			request[0] = out.setup.api.send(conversation, new ChatApi.Listener()
			{
				@Override
				public void onPartial(String textSoFar)
				{
					partial.offer(textSoFar);
				}

				@Override
				public void onRetrying(String message, int seconds)
				{
					edt.execute(() -> retrying(chat, request[0], message, seconds));
				}

				@Override
				public void onReply(ChatApi.Reply reply)
				{
					edt.execute(() -> finished(out, request[0], reply, null, null));
				}

				@Override
				public void onError(ChatApi.Failure failure)
				{
					// The newest text, which may be a moment ahead of what's drawn: the reply as far as it got.
					String shown = partial.latest();
					edt.execute(() -> finished(out, request[0], null, failure, shown));
				}
			});
		}
		catch (RuntimeException e)
		{
			couldntSend(out);
			return;
		}
		sent.set(request[0]);
		chat.pending = request[0];
	}

	/**
	 * Building the request failed (OkHttp rejects some header values). The exception's message can contain the API
	 * key: it isn't passed on or logged.
	 */
	private void couldntSend(Outgoing out)
	{
		Chat chat = out.chat;
		chat.pending = null;
		chat.skipSummary = null;
		chat.resetLive();
		out.message.unanswered = true;
		chat.messages.add(new Chat.Message(Chat.Role.ERROR, COULDNT_SEND));
		host.changed(chat);
	}

	// ------------------------------------------------------------------
	// The request in flight
	// ------------------------------------------------------------------

	/** Whether an answer to {@code request} still counts: it's the chat's current request, and the chat is still there. */
	private boolean current(Chat chat, ChatApi.Pending request)
	{
		return request != null && chat.pending == request && !request.isCancelled() && host.has(chat);
	}

	/** The reply so far, at most every {@link #LIVE_GAP_MILLIS}. */
	private void writing(Chat chat, ChatApi.Pending request, String text)
	{
		if (!current(chat, request) || text == null || text.equals(chat.liveText))
		{
			return;
		}
		chat.liveText = text;
		// More words: the look-ups are over. (Not the text from before them, arriving late.)
		if (!text.equals(chat.lookupAfter))
		{
			chat.lookingUp = false;
		}
		host.live(chat);
	}

	/** A tool call started. {@code before}: the reply's text at that moment. */
	private void lookingUp(Chat chat, ChatApi.Pending request, String before)
	{
		if (!current(chat, request))
		{
			return;
		}
		chat.lookingUp = true;
		chat.lookupAfter = before;
		host.live(chat);
	}

	/**
	 * A tool call finished: {@code line} says what it looked up or shared. {@code stoppedFirst}: the request had been
	 * stopped when it did, so the result went nowhere.
	 */
	private void lookedUp(Chat chat, ChatApi.Pending request, List<String> activity, String line, boolean stoppedFirst)
	{
		// Kept whatever happened to the request since: it was looked up, and the player sees what was. But game data read
		// after a Stop wasn't shared after all. (Read just before one, it may have been: it's listed as shared.)
		boolean live = current(chat, request);
		activity.add(stoppedFirst ? GameDataTools.unshared(line) : line);
		if (live)
		{
			host.live(chat);
		}
		else if (host.has(chat))
		{
			// After the request ended: the line went with the message that ended it.
			host.changed(chat);
		}
	}

	/** The provider is busy; the request goes again in {@code seconds}. */
	private void retrying(Chat chat, ChatApi.Pending request, String why, int seconds)
	{
		if (current(chat, request))
		{
			chat.retryWhy = why;
			chat.retryAt = System.currentTimeMillis() + seconds * 1000L;
			host.live(chat);
		}
	}

	/**
	 * The request's answer: a reply, or an error ({@code failure}). {@code shown}: the reply's text so far when it
	 * failed, which stays in the transcript unless the provider took it back.
	 */
	private void finished(Outgoing out, ChatApi.Pending request, ChatApi.Reply reply, ChatApi.Failure failure, String shown)
	{
		logUsage("reply", out, reply, failure);
		Chat chat = out.chat;
		// Only the answer to the request still in flight counts: not one that was stopped, or a chat that's gone.
		if (!current(chat, request))
		{
			return;
		}
		String before = shown != null ? shown : chat.liveText;
		if (failure != null && failure.tooLong && !out.shortened && shorten(out, before))
		{
			return;
		}
		chat.pending = null;
		List<String> activity = chat.liveActivity;
		chat.resetLive();
		Chat.Message m;
		if (reply != null)
		{
			if (reply.historyAsText)
			{
				// This reply was built on plain-text history; keep sending the earlier replies that way.
				ConversationBuilder.forgetRaw(chat);
			}
			m = new Chat.Message(Chat.Role.ASSISTANT, reply.text + (reply.cutShort ? "\n\n(The reply was cut short.)" : ""));
			m.who = out.setup.api.displayName();
			ConversationBuilder.recordReply(m, out.message, reply);
			if (reply.toolsUnavailable)
			{
				activity.add(NO_LOOKUPS);
			}
		}
		else
		{
			out.message.unanswered = true;
			if (!failure.withdrawn)
			{
				keepUnfinished(chat, out.setup.api.displayName(), before);
			}
			m = new Chat.Message(Chat.Role.ERROR, failure.message);
		}
		m.activity = activity;
		chat.messages.add(m);
		host.ended(chat, m);
		host.changed(chat);
	}

	/**
	 * The chat was too long for the model: once per question, everything before it is summarised, however few
	 * messages that is, and it goes again. A note says so, and keeps what this attempt looked up. False when there's
	 * nothing before it to summarise.
	 */
	private boolean shorten(Outgoing out, String shown)
	{
		Chat chat = out.chat;
		List<Chat.Message> old = ConversationBuilder.planSummary(chat, true);
		if (old.isEmpty())
		{
			return false;
		}
		List<String> activity = chat.liveActivity;
		keepUnfinished(chat, out.setup.api.displayName(), shown);
		Chat.Message note = new Chat.Message(Chat.Role.NOTE, "This chat was too long for " + out.setup.model
			+ ", so the earlier messages are summarised first and the question is sent again.");
		note.activity = activity;
		chat.messages.add(note);
		// Still busy: the summary is next, then the question again.
		chat.pending = new ChatApi.Pending();
		chat.runStartedAt = System.currentTimeMillis();
		chat.resetLive();
		summarise(new Outgoing(chat, out.message, out.setup, true), old);
		host.changed(chat);
		return true;
	}

	/**
	 * What was shown of a reply that won't finish stays where the player was reading it, marked unfinished (the note or
	 * error after it says why), rather than vanishing. It isn't sent: Retry asks the question again from the start.
	 */
	private static void keepUnfinished(Chat chat, String who, String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			return;
		}
		Chat.Message m = new Chat.Message(Chat.Role.ASSISTANT, text);
		m.who = who;
		m.unfinished = true;
		chat.messages.add(m);
	}

	/**
	 * One debug line for each request that ends, whether its answer still counts or not: the tokens it used, and the
	 * model that answered (or the one asked for). With ./gradlew run, which logs at debug, a developer can see that
	 * prompt caching works. Counts and the model only: nothing that was said, and never the key.
	 */
	private static void logUsage(String what, Outgoing out, ChatApi.Reply reply, ChatApi.Failure failure)
	{
		ChatApi.Usage usage = reply != null ? reply.usage : failure.usage;
		String model = reply != null ? reply.model : failure.model;
		log.debug("{} from {}: {} input, {} from cache, {} written to cache, {} output tokens",
			reply != null ? what : "failed " + what, model != null ? model : out.setup.model,
			usage.input, usage.cacheRead, usage.cacheWrite, usage.output);
	}

	// ------------------------------------------------------------------
	// Stopping
	// ------------------------------------------------------------------

	/**
	 * The player pressed Stop: while summarising, that skips the summary (the button says Skip then); otherwise the
	 * request stops.
	 */
	void stop(Chat chat)
	{
		if (chat.isSummarizing())
		{
			chat.skipSummary.run();
		}
		else
		{
			stop(chat, STOPPED + ".");
		}
	}

	/** Stops the chat's request, if any, and says so with {@code note}; the question can be retried. */
	void stop(Chat chat, String note)
	{
		if (chat.pending == null)
		{
			return;
		}
		List<String> activity = chat.liveActivity;
		// What the player was reading when they pressed Stop, often because they'd read enough.
		String shown = chat.liveText;
		String who = chat.answering;
		cancel(chat);
		// The unanswered question stays in the transcript but isn't sent again.
		for (int i = chat.messages.size() - 1; i >= 0; i--)
		{
			Chat.Message m = chat.messages.get(i);
			if (m.role == Chat.Role.USER)
			{
				m.unanswered = true;
				break;
			}
		}
		keepUnfinished(chat, who, shown);
		Chat.Message stopped = new Chat.Message(Chat.Role.NOTE, note);
		stopped.activity = activity;
		chat.messages.add(stopped);
		host.changed(chat);
	}

	/** Cancels whatever the chat is waiting for, if anything; its answer won't be heard. */
	static void cancel(Chat chat)
	{
		if (chat.pending != null)
		{
			chat.pending.cancel();
			chat.pending = null;
		}
		chat.skipSummary = null;
		chat.resetLive();
	}
}

package com.aichat;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.geom.RoundRectangle2D;
import java.util.Objects;
import javax.swing.JPanel;

/** A panel drawn as a box with rounded corners: filled, outlined, or both. Its children go inside its border. */
class RoundBox extends JPanel
{
	private Color fill;
	private Color outline;

	RoundBox(LayoutManager layout, Color fill, Color outline)
	{
		super(layout);
		this.fill = fill;
		this.outline = outline;
		// The corners outside the box show what's behind it.
		setOpaque(false);
	}

	void setColors(Color fill, Color outline)
	{
		if (!Objects.equals(fill, this.fill) || !Objects.equals(outline, this.outline))
		{
			this.fill = fill;
			this.outline = outline;
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = PanelStyle.smooth(g);
		RoundRectangle2D box = new RoundRectangle2D.Float(0.5f, 0.5f, getWidth() - 1f, getHeight() - 1f,
			PanelStyle.ARC, PanelStyle.ARC);
		if (fill != null)
		{
			g2.setColor(fill);
			g2.fill(box);
		}
		if (outline != null)
		{
			g2.setColor(outline);
			g2.draw(box);
		}
		g2.dispose();
	}
}

package com.aichat;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Rectangle2D;
import java.util.function.Function;
import java.util.function.Predicate;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.text.BadLocationException;
import javax.swing.text.StyleConstants;

/**
 * A muted line about a message with more to it than fits there, such as "Sent your character details" or "Shared your
 * bank · Looked up 3 things", the way chat apps show what a reply did: a chevron after the line says it opens, a click
 * on the line shows the rest in a block under it (the chevron turns up), and another click hides it again. Both are
 * plain text, which never renders HTML: they can hold words the model chose. The line sits left, centred or right, like
 * what it's about, and its words can be chosen for the width it gets (see {@link #show(Function, String)}); the block
 * is always left-aligned, set in a little.
 */
final class ShowMore extends JPanel
{
	/** Kept after the line's last word for the chevron: spaces that never break from the word before them. */
	static final String CHEVRON_ROOM = "    ";
	/** Pixels of the line's width its words leave free: the text is laid out a bit differently than it's measured. */
	static final int SPARE_WIDTH = 2;
	private static final int CHEVRON_SIZE = 9;
	/** The line under the mouse, when it opens: brighter, as a button would be. */
	private static final Color HOVER_COLOR = new Color(225, 225, 225);

	final Line line = new Line();
	final MessageView more = new MessageView();
	/** For the line, while it has more to show. */
	private final String tip;
	/** For the line while it hasn't, or null. */
	private String plainTip;
	/** The line's words for the room it has, as whether a text fits it; null while there's nothing to show. */
	private Function<Predicate<String>, String> text;
	private boolean hovered;

	/** {@code alignment}: where the line sits, StyleConstants.ALIGN_LEFT, ALIGN_CENTER or ALIGN_RIGHT. */
	ShowMore(String tip, int alignment)
	{
		super(new StackLayout(0));
		this.tip = tip;
		setOpaque(false);
		setVisible(false);
		for (MessageView v : new MessageView[]{line, more})
		{
			v.setTextFont(PanelStyle.SMALL_FONT);
			v.setTextColor(PanelStyle.MUTED_COLOR);
			add(v);
		}
		line.setAlignment(alignment);
		// Set in a little, so it reads as the line's own and not as what comes after it.
		more.setBorder(new EmptyBorder(2, 8, 2, alignment == StyleConstants.ALIGN_LEFT ? 0 : 8));
		more.setVisible(false);
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && hasMore())
				{
					more.setVisible(!more.isVisible());
					showLine();
					// Taller or shorter now: measured again, with the transcript around it.
					revalidate();
					repaint();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				hovered = true;
				showLine();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hovered = false;
				showLine();
			}
		};
		line.addMouseListener(mouse);
	}

	/**
	 * Shows {@code text} (null: nothing at all), with {@code details} a click away (null: just the line). Shown or
	 * hidden, the details stay as they were when they change: a list still growing over a reply on its way doesn't
	 * close on the player.
	 */
	void show(String text, String details)
	{
		show(text == null || text.isEmpty() ? null : fits -> text, details);
	}

	/** As {@link #show(String, String)}, with the line's words chosen for the room it has: {@code text} picks them. */
	void show(Function<Predicate<String>, String> text, String details)
	{
		this.text = text;
		String d = text == null || details == null ? "" : details;
		more.setPlainText(d);
		if (d.isEmpty())
		{
			more.setVisible(false);
		}
		setVisible(text != null);
		showLine();
	}

	/** The line's tooltip while it has nothing more to show, such as when its message was sent. */
	void setPlainTip(String tip)
	{
		plainTip = tip;
		showLine();
	}

	/** The line's words as shown, without the room for the chevron. */
	String lineText()
	{
		String s = line.getSource();
		return s.endsWith(CHEVRON_ROOM) ? s.substring(0, s.length() - CHEVRON_ROOM.length()) : s;
	}

	/** Whether the rest shows under the line. */
	boolean isOpen()
	{
		return more.isVisible();
	}

	/** The chevron after the line: down while the rest is hidden, up while it shows; null when there's no rest. */
	Glyph.Shape chevron()
	{
		return !hasMore() ? null : isOpen() ? Glyph.Shape.CHEVRON_UP : Glyph.Shape.CHEVRON_DOWN;
	}

	private boolean hasMore()
	{
		return !more.getSource().isEmpty();
	}

	private void showLine()
	{
		boolean any = hasMore();
		line.setCursor(Cursor.getPredefinedCursor(any ? Cursor.HAND_CURSOR : Cursor.TEXT_CURSOR));
		line.setToolTipText(any ? tip : plainTip);
		line.setTextColor(any && hovered ? HOVER_COLOR : PanelStyle.MUTED_COLOR);
		line.fit();
		line.repaint();
	}

	/**
	 * The line: its words for the width it has, and the chevron drawn after the last of them when there's more to show.
	 * Its words are chosen again when it gets another width.
	 */
	final class Line extends MessageView
	{
		@Override
		public void setBounds(int x, int y, int width, int height)
		{
			boolean widthChanged = width != getWidth();
			super.setBounds(x, y, width, height);
			if (widthChanged)
			{
				fit();
			}
		}

		/** Chooses the words for the width the line has now; any fit until it has one. */
		void fit()
		{
			if (text == null)
			{
				setPlainText("");
				return;
			}
			String room = hasMore() ? CHEVRON_ROOM : "";
			Insets in = getInsets();
			int width = getWidth() - in.left - in.right - SPARE_WIDTH;
			FontMetrics fm = getFontMetrics(PanelStyle.SMALL_FONT);
			setPlainText(text.apply(s -> width <= 0 || fm.stringWidth(s + room) <= width) + room);
		}

		@Override
		String plainText()
		{
			return lineText();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			Glyph.Shape chevron = chevron();
			if (chevron == null)
			{
				return;
			}
			try
			{
				// Where the room kept for it starts: just after the last word, on whichever row that is.
				Rectangle2D at = modelToView2D(getDocument().getLength() - CHEVRON_ROOM.length());
				if (at != null)
				{
					int x = (int) Math.round(at.getX()) + 3;
					int y = (int) Math.round(at.getCenterY() - CHEVRON_SIZE / 2.0);
					Color color = hovered ? HOVER_COLOR : PanelStyle.MUTED_COLOR;
					new Glyph(chevron, CHEVRON_SIZE, color).paintIcon(this, g, x, y);
				}
			}
			catch (BadLocationException e)
			{
				// The text changed under the paint: the next one draws it.
			}
		}
	}
}

package com.aichat;

import java.io.IOException;
import java.util.Locale;
import okhttp3.Response;
import okio.BufferedSource;

/**
 * Server-sent events, the format both providers stream replies in: "event:" and "data:" lines, and a blank line after
 * each event. Read straight from the response as it arrives, on OkHttp's thread (that's what its callbacks are for).
 */
final class Sse
{
	/** What OpenAI-style streams send as their last event's data. */
	static final String DONE = "[DONE]";

	private Sse()
	{
	}

	interface Handler
	{
		/**
		 * One event: its name ("message" when it has none) and its data, the lines of a multi-line data joined with line
		 * breaks. Returns false when nothing more is wanted from the stream.
		 */
		boolean onEvent(String event, String data);
	}

	/** Whether the answer is a stream of events, rather than one JSON answer: some services ignore "stream". */
	static boolean isEventStream(Response response)
	{
		String type = response.header("Content-Type");
		return type != null && type.trim().toLowerCase(Locale.ROOT).startsWith("text/event-stream");
	}

	/**
	 * Reads events until the handler has had enough or the stream ends. An event the end cuts off (no blank line after
	 * it) isn't passed on: it may be missing lines. Comments (":" lines, often sent to keep the connection open) and the
	 * fields for reconnecting ("id", "retry") are skipped; a reply can't pick up where it left off anyway.
	 */
	static void read(BufferedSource source, Handler handler) throws IOException
	{
		String event = null;
		StringBuilder data = null;
		boolean first = true;
		String line;
		while ((line = source.readUtf8Line()) != null)
		{
			if (first && line.startsWith("﻿"))
			{
				line = line.substring(1);
			}
			first = false;
			if (line.isEmpty())
			{
				if (data != null && data.length() > 0 && !handler.onEvent(event == null || event.isEmpty() ? "message" : event, data.toString()))
				{
					return;
				}
				event = null;
				data = null;
				continue;
			}
			if (line.startsWith(":"))
			{
				continue;
			}
			int colon = line.indexOf(':');
			String field = colon < 0 ? line : line.substring(0, colon);
			String value = colon < 0 ? "" : line.substring(colon + 1);
			if (value.startsWith(" "))
			{
				value = value.substring(1);
			}
			if (field.equals("data"))
			{
				if (data == null)
				{
					data = new StringBuilder();
				}
				else
				{
					data.append('\n');
				}
				data.append(value);
			}
			else if (field.equals("event"))
			{
				event = value;
			}
		}
	}
}

package com.aichat;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import javax.swing.JTextArea;
import net.runelite.client.ui.PluginPanel;

/**
 * Stacks visible children top to bottom at the container's full width. Unlike BoxLayout, each child's height is
 * asked for at that width, so wrapping text areas get the right height on the first layout instead of one line. A
 * {@link Fitted} child can be narrower, such as a bubble around a short message: it's placed by its alignment (see
 * {@link Component#getAlignmentX}: 0 left, 1 right).
 */
class StackLayout implements LayoutManager
{
	/** A child that may be narrower than the container. */
	interface Fitted
	{
		/** How wide it is when the container has {@code available} pixels for it: at most that. */
		int fittedWidth(int available);
	}

	/** Width to assume before the sidebar has been laid out: the panel minus AiChatPanel's border. */
	private static final int FALLBACK_WIDTH = PluginPanel.PANEL_WIDTH + PluginPanel.SCROLLBAR_WIDTH - 16;

	private final int gap;

	StackLayout(int gap)
	{
		this.gap = gap;
	}

	@Override
	public void addLayoutComponent(String name, Component comp)
	{
	}

	@Override
	public void removeLayoutComponent(Component comp)
	{
	}

	@Override
	public Dimension preferredLayoutSize(Container parent)
	{
		Insets in = parent.getInsets();
		int outer = parent.getWidth() > 0 ? parent.getWidth() : FALLBACK_WIDTH;
		int w = Math.max(0, outer - in.left - in.right);
		int h = in.top + in.bottom;
		int n = 0;
		for (Component c : parent.getComponents())
		{
			if (c.isVisible())
			{
				h += height(c, width(c, w));
				n++;
			}
		}
		if (n > 1)
		{
			h += gap * (n - 1);
		}
		return new Dimension(outer, h);
	}

	@Override
	public Dimension minimumLayoutSize(Container parent)
	{
		return preferredLayoutSize(parent);
	}

	@Override
	public void layoutContainer(Container parent)
	{
		Insets in = parent.getInsets();
		int w = Math.max(0, parent.getWidth() - in.left - in.right);
		int y = in.top;
		for (Component c : parent.getComponents())
		{
			if (!c.isVisible())
			{
				continue;
			}
			int cw = width(c, w);
			int h = height(c, cw);
			int x = in.left + Math.round((w - cw) * Math.max(0f, Math.min(1f, c.getAlignmentX())));
			c.setBounds(x, y, cw, h);
			y += h + gap;
		}
	}

	/** The width {@code c} gets when the container has {@code w} for it: all of it, unless it's {@link Fitted}. */
	static int width(Component c, int w)
	{
		return c instanceof Fitted ? Math.max(0, Math.min(w, ((Fitted) c).fittedWidth(w))) : w;
	}

	/**
	 * The height {@code c} gets at width {@code w}. A child that hasn't changed since the last layout (still valid, and
	 * as wide) keeps the height it has: while a reply streams in, only its own bubble is measured again, not every
	 * message above it.
	 */
	private static int height(Component c, int w)
	{
		if (c.isValid() && c.getWidth() == w && c.getHeight() > 0)
		{
			return c.getHeight();
		}
		return heightFor(c, w);
	}

	/** Preferred height of {@code c} when it is {@code w} wide. */
	static int heightFor(Component c, int w)
	{
		if (c instanceof JTextArea)
		{
			// A wrapped text area computes its preferred height from its current size.
			c.setSize(w, Short.MAX_VALUE);
		}
		else if (c instanceof Container)
		{
			// Lay the children out at this width first, so nested text areas know theirs.
			c.setSize(w, Short.MAX_VALUE);
			((Container) c).doLayout();
		}
		return c.getPreferredSize().height;
	}
}

package com.aichat;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Toolkit;
import java.awt.geom.Area;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.Element;
import javax.swing.text.JTextComponent;
import javax.swing.text.Position;
import javax.swing.text.StyleConstants;
import javax.swing.text.StyledDocument;
import javax.swing.text.View;

/**
 * A Markdown table in a {@link MessageView}, drawn the way chat apps draw tables: a rounded outline, a bold header row
 * over a line, light lines between the rows, and cells that wrap, the columns sharing the width by what's in them.
 * When the columns don't fit the narrow panel (more than {@link #MAX_COLUMNS}, or one squeezed under
 * {@link #MIN_COLUMN}), each row is a small card instead: its first cell in bold, then a "Header: value" line for each
 * other cell. Bold, italic and code in the cells keep their look; links are plain text. The table's text is in the
 * document as its lined-up lines (see {@link MessageView}), so selecting and copying the message takes the table along:
 * this view only draws it. Swing EDT only.
 */
final class TableView extends View
{
	/**
	 * Between the table's lines in the document: not a line break, which would make each line a paragraph. Unicode's
	 * line separator, written as an escape so that it can't be lost unseen.
	 */
	static final String ROW_BREAK = "\u2028";
	/** A table with more columns than this, that doesn't fit as it is, is drawn as cards. */
	static final int MAX_COLUMNS = 3;
	/** A column squeezed narrower than this is too narrow to read: the table is drawn as cards. */
	static final int MIN_COLUMN = 60;
	/** Space inside a cell, around its text. */
	private static final int PAD_X = 6;
	private static final int PAD_Y = 4;
	/** Space inside a card, around its text, and between cards. */
	private static final int CARD_PAD_X = 8;
	private static final int CARD_PAD_Y = 5;
	private static final int CARD_GAP = 6;
	private static final int ARC = 10;
	private static final Color OUTLINE = new Color(255, 255, 255, 60);
	private static final Color DIVIDER = new Color(255, 255, 255, 28);
	private static final Color HEADER_FILL = new Color(255, 255, 255, 14);
	private static final Color CODE_FILL = new Color(255, 255, 255, 30);
	/** A word, or the space between words. */
	private static final Pattern TOKEN = Pattern.compile("\\s+|\\S+");

	private final Markdown.Table table;
	/** How wide each column is unwrapped, padding included: the same at any width, so worked out once. */
	private int[] natural;
	/** The latest layout, for the width it was made for. */
	private Layout layout;

	TableView(Element elem, Markdown.Table table)
	{
		super(elem);
		this.table = table;
	}

	// ------------------------------------------------------------------
	// How wide the columns are, and when it's cards (pure)
	// ------------------------------------------------------------------

	/**
	 * Each column's width when the table has {@code available} pixels, from how wide each is unwrapped
	 * ({@code natural}, padding included): as wide as that when they all fit; otherwise the columns that fit in an equal
	 * share of the room keep their width, and the others share what's left equally (their text wraps).
	 */
	static int[] columnWidths(int[] natural, int available)
	{
		int n = natural.length;
		long total = 0;
		for (int w : natural)
		{
			total += w;
		}
		if (total <= available)
		{
			return natural.clone();
		}
		int[] widths = new int[n];
		boolean[] kept = new boolean[n];
		int left = Math.max(0, available);
		int open = n;
		boolean changed = true;
		while (changed && open > 0)
		{
			changed = false;
			int share = left / open;
			for (int c = 0; c < n; c++)
			{
				if (!kept[c] && natural[c] <= share)
				{
					kept[c] = true;
					widths[c] = natural[c];
					left -= natural[c];
					open--;
					changed = true;
				}
			}
		}
		// What's left, shared equally; the odd pixels to the first of them.
		int extra = open == 0 ? 0 : left % open;
		for (int c = 0; c < n; c++)
		{
			if (!kept[c])
			{
				widths[c] = left / open + (extra-- > 0 ? 1 : 0);
			}
		}
		return widths;
	}

	/**
	 * Whether a table whose columns want {@code natural} pixels and get {@code widths} is drawn as cards: not when it
	 * fits as it is; when it doesn't, if it has more than {@link #MAX_COLUMNS} columns, or a column gets less than it
	 * wants and less than {@link #MIN_COLUMN} (a narrow column that has all it wants is fine).
	 */
	static boolean cards(int[] natural, int[] widths)
	{
		boolean squeezed = false;
		boolean narrow = false;
		for (int c = 0; c < natural.length; c++)
		{
			squeezed |= widths[c] < natural[c];
			narrow |= widths[c] < natural[c] && widths[c] < MIN_COLUMN;
		}
		return squeezed && (natural.length > MAX_COLUMNS || narrow);
	}

	// ------------------------------------------------------------------
	// The view
	// ------------------------------------------------------------------

	/** Whether it's drawn as cards at the width it has now; for tests. */
	boolean isCards()
	{
		return layout(availableWidth()).cards;
	}

	@Override
	public float getPreferredSpan(int axis)
	{
		Layout l = layout(availableWidth());
		return axis == X_AXIS ? l.width : l.height;
	}

	@Override
	public float getMinimumSpan(int axis)
	{
		// It never makes its paragraph wider than the message: it wraps or turns into cards instead.
		return axis == X_AXIS ? 0 : getPreferredSpan(axis);
	}

	@Override
	public float getMaximumSpan(int axis)
	{
		return getPreferredSpan(axis);
	}

	@Override
	public Shape modelToView(int pos, Shape a, Position.Bias b) throws BadLocationException
	{
		if (pos < getStartOffset() || pos > getEndOffset())
		{
			throw new BadLocationException("Not in the table", pos);
		}
		// One piece: anywhere in its text is before it, and its end after it.
		Rectangle r = a.getBounds();
		return new Rectangle(pos < textEnd() ? r.x : r.x + r.width, r.y, 0, r.height);
	}

	/**
	 * Where the table's text ends: before the line break that ends its paragraph, when there's one. That's in this
	 * view too (see {@link MessageView}), so that nothing beside the table shows a selection.
	 */
	private int textEnd()
	{
		int end = getEndOffset();
		try
		{
			return end > getStartOffset() && getDocument().getText(end - 1, 1).equals("\n") ? end - 1 : end;
		}
		catch (BadLocationException e)
		{
			return end;
		}
	}

	@Override
	public int viewToModel(float x, float y, Shape a, Position.Bias[] biasReturn)
	{
		Rectangle r = a.getBounds();
		biasReturn[0] = Position.Bias.Forward;
		return y < r.y + r.height / 2f ? getStartOffset() : textEnd();
	}

	@Override
	public void paint(Graphics g, Shape a)
	{
		Rectangle r = a.getBounds();
		Layout l = layout(availableWidth());
		Graphics2D g2 = PanelStyle.smooth(g);
		try
		{
			Object hints = Toolkit.getDefaultToolkit().getDesktopProperty("awt.font.desktophints");
			if (hints instanceof Map)
			{
				g2.addRenderingHints((Map<?, ?>) hints);
			}
			else
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			}
			Rectangle clip = g.getClipBounds();
			if (l.cards)
			{
				paintCards(g2, l, r.x, r.y, clip);
			}
			else
			{
				paintTable(g2, l, r.x, r.y, clip);
			}
			paintSelection(g2, l, r.x, r.y);
		}
		finally
		{
			g2.dispose();
		}
	}

	private void paintTable(Graphics2D g, Layout l, int x, int y, Rectangle clip)
	{
		if (l.rows.isEmpty())
		{
			return;
		}
		RoundRectangle2D outline = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, l.width - 1, l.height - 1, ARC, ARC);
		int headerHeight = l.rows.get(0).height;
		Area header = new Area(outline);
		header.intersect(new Area(new Rectangle(x, y, l.width, 1 + headerHeight)));
		g.setColor(HEADER_FILL);
		g.fill(header);
		int top = y + 1;
		for (int r = 0; r < l.rows.size(); r++)
		{
			Row row = l.rows.get(r);
			if (r > 0)
			{
				// The header's line is stronger than the lines between rows.
				g.setColor(r == 1 ? OUTLINE : DIVIDER);
				g.fillRect(x + 1, top - 1, l.width - 2, 1);
			}
			if (clip == null || top < clip.y + clip.height && top + row.height > clip.y)
			{
				int left = x + 1;
				for (int c = 0; c < row.cells.size(); c++)
				{
					int inner = l.columns[c] - 2 * PAD_X;
					drawLines(g, row.cells.get(c), left + PAD_X, top + PAD_Y, inner, table.align[c], l.lineHeight,
						l.ascent);
					left += l.columns[c];
				}
			}
			top += row.height + 1;
		}
		g.setColor(OUTLINE);
		g.draw(outline);
	}

	private void paintCards(Graphics2D g, Layout l, int x, int y, Rectangle clip)
	{
		int top = y;
		for (Row card : l.rows)
		{
			if (clip == null || top < clip.y + clip.height && top + card.height > clip.y)
			{
				g.setColor(OUTLINE);
				g.draw(new RoundRectangle2D.Float(x + 0.5f, top + 0.5f, l.width - 1, card.height - 1, ARC, ARC));
				int lineTop = top + 1 + CARD_PAD_Y;
				for (List<Line> field : card.cells)
				{
					drawLines(g, field, x + 1 + CARD_PAD_X, lineTop, l.width - 2 - 2 * CARD_PAD_X, Markdown.ALIGN_LEFT,
						l.lineHeight, l.ascent);
					lineTop += field.size() * l.lineHeight;
				}
			}
			top += card.height + CARD_GAP;
		}
	}

	private static void drawLines(Graphics2D g, List<Line> lines, int x, int y, int width, int align, int lineHeight,
		int ascent)
	{
		int baseline = y + ascent;
		for (Line line : lines)
		{
			int left = x + (align == Markdown.ALIGN_RIGHT ? width - line.width
				: align == Markdown.ALIGN_CENTER ? (width - line.width) / 2 : 0);
			for (Piece p : line.pieces)
			{
				if (p.run.code)
				{
					g.setColor(CODE_FILL);
					g.fillRoundRect(left + p.x - 1, baseline - ascent, p.width + 2, lineHeight, 4, 4);
				}
				g.setColor(p.run.color);
				g.setFont(p.run.font);
				g.drawString(p.text, left + p.x, baseline);
			}
			baseline += lineHeight;
		}
	}

	/** Over the table while the selection takes it in: it's selected and copied whole, with the text around it. */
	private void paintSelection(Graphics2D g, Layout l, int x, int y)
	{
		Container c = getContainer();
		if (!(c instanceof JTextComponent))
		{
			return;
		}
		JTextComponent text = (JTextComponent) c;
		int start = text.getSelectionStart();
		int end = text.getSelectionEnd();
		Color color = text.getSelectionColor();
		// As the text around it: only while the selection shows (the view has the focus).
		boolean shown = text.getCaret() != null && text.getCaret().isSelectionVisible();
		if (!shown || start == end || start >= textEnd() || end <= getStartOffset() || color == null)
		{
			return;
		}
		g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 90));
		g.fill(new RoundRectangle2D.Float(x, y, l.width, l.height, ARC, ARC));
	}

	// ------------------------------------------------------------------
	// Layout
	// ------------------------------------------------------------------

	/** The room the paragraph gives the table, or {@link Integer#MAX_VALUE} before it's been laid out. */
	private int availableWidth()
	{
		for (View v = getParent(); v != null; v = v.getParent())
		{
			if (v instanceof MessageView.BlockView)
			{
				return ((MessageView.BlockView) v).flowWidth();
			}
		}
		return Integer.MAX_VALUE;
	}

	/** The table laid out in {@code available} pixels; worked out once for each width. */
	private Layout layout(int available)
	{
		if (layout != null && layout.available == available)
		{
			return layout;
		}
		Component c = getContainer();
		Layout before = layout;
		layout = c == null ? new Layout(available) : layOut(c, available);
		if (before != null && before.height != layout.height)
		{
			// Taller or shorter at the new width. The paragraph keeps its rows' heights from before (text lines are
			// all as tall as ever): it's told, so it asks again.
			preferenceChanged(null, true, true);
		}
		return layout;
	}

	private Layout layOut(Component c, int available)
	{
		AttributeSet attrs = getAttributes();
		Font base = ((StyledDocument) getDocument()).getFont(attrs);
		Color color = StyleConstants.getForeground(attrs);
		Fonts fonts = new Fonts(base, color);
		FontMetrics fm = c.getFontMetrics(base);
		Layout l = new Layout(available);
		l.lineHeight = fm.getHeight();
		l.ascent = fm.getAscent();

		int columns = table.align.length;
		if (natural == null)
		{
			natural = new int[columns];
			for (int r = 0; r < table.rows.size(); r++)
			{
				for (int col = 0; col < columns; col++)
				{
					List<Run> runs = runs(table.rows.get(r).get(col), fonts, r == 0);
					natural[col] = Math.max(natural[col], unwrapped(c, runs) + 2 * PAD_X);
				}
			}
		}
		// Inside the outline.
		int room = available == Integer.MAX_VALUE ? Integer.MAX_VALUE : available - 2;
		int[] widths = columnWidths(natural, room);
		l.cards = cards(natural, widths);
		if (l.cards)
		{
			layOutCards(c, l, fonts, available);
		}
		else
		{
			l.columns = widths;
			l.width = 2;
			for (int w : widths)
			{
				l.width += w;
			}
			l.height = 1;
			for (int r = 0; r < table.rows.size(); r++)
			{
				Row row = new Row();
				int lines = 1;
				for (int col = 0; col < columns; col++)
				{
					List<Line> cell = wrap(c, runs(table.rows.get(r).get(col), fonts, r == 0), widths[col] - 2 * PAD_X);
					row.cells.add(cell);
					lines = Math.max(lines, cell.size());
				}
				row.height = lines * l.lineHeight + 2 * PAD_Y;
				l.rows.add(row);
				// The row and the line under it (the outline, under the last).
				l.height += row.height + 1;
			}
		}
		return l;
	}

	/** One card per row (the header's own when there's no other yet): the first cell in bold, then the others. */
	private void layOutCards(Component c, Layout l, Fonts fonts, int available)
	{
		l.width = available == Integer.MAX_VALUE ? 0 : available;
		int inner = l.width - 2 - 2 * CARD_PAD_X;
		List<List<Markdown.Span>> header = table.rows.get(0);
		boolean headerOnly = table.rows.size() == 1;
		for (int r = headerOnly ? 0 : 1; r < table.rows.size(); r++)
		{
			List<List<Markdown.Span>> cells = table.rows.get(r);
			Row card = new Row();
			if (!cells.get(0).isEmpty())
			{
				card.cells.add(wrap(c, runs(cells.get(0), fonts, true), inner));
			}
			for (int col = 1; col < cells.size(); col++)
			{
				if (cells.get(col).isEmpty())
				{
					continue;
				}
				List<Run> field = new ArrayList<>();
				if (!headerOnly && !header.get(col).isEmpty())
				{
					String label = Markdown.plainText(header.get(col), false) + ": ";
					field.add(new Run(label, fonts.base, false, fonts.label));
				}
				field.addAll(runs(cells.get(col), fonts, false));
				card.cells.add(wrap(c, field, inner));
			}
			int lines = 0;
			for (List<Line> field : card.cells)
			{
				lines += field.size();
			}
			card.height = Math.max(1, lines) * l.lineHeight + 2 * CARD_PAD_Y + 2;
			l.rows.add(card);
			l.height += card.height + (l.rows.size() > 1 ? CARD_GAP : 0);
		}
	}

	/** The fonts and colours a table is drawn in, from its text's. */
	private static final class Fonts
	{
		final Font base;
		final Font bold;
		final Font italic;
		final Font boldItalic;
		final Font code;
		final Color color;
		/** For a card's "Header:", quieter than the value after it. */
		final Color label;

		Fonts(Font base, Color color)
		{
			this.base = base;
			bold = base.deriveFont(Font.BOLD);
			italic = base.deriveFont(Font.ITALIC);
			boldItalic = base.deriveFont(Font.BOLD | Font.ITALIC);
			code = new Font(Font.MONOSPACED, Font.PLAIN, Math.max(1, base.getSize() - 1));
			this.color = color;
			label = new Color(color.getRed(), color.getGreen(), color.getBlue(), 150);
		}
	}

	/** A cell's spans as runs of text, each in its font; a header's in bold. Links are plain text here. */
	private static List<Run> runs(List<Markdown.Span> spans, Fonts fonts, boolean header)
	{
		List<Run> runs = new ArrayList<>();
		for (Markdown.Span s : spans)
		{
			Font font;
			switch (s.kind)
			{
				case BOLD:
					font = fonts.bold;
					break;
				case ITALIC:
					font = header ? fonts.boldItalic : fonts.italic;
					break;
				case BOLD_ITALIC:
					font = fonts.boldItalic;
					break;
				case CODE:
					font = fonts.code;
					break;
				default:
					font = header ? fonts.bold : fonts.base;
					break;
			}
			runs.add(new Run(s.text, font, s.kind == Markdown.SpanKind.CODE, fonts.color));
		}
		return runs;
	}

	/** How wide {@code runs} are on one line. */
	private static int unwrapped(Component c, List<Run> runs)
	{
		List<Line> lines = wrap(c, runs, Integer.MAX_VALUE);
		return lines.isEmpty() ? 0 : lines.get(0).width;
	}

	/**
	 * {@code runs} wrapped to {@code width}: lines break between words, and inside a word too long for a line of its
	 * own. Words of one run on a line are one piece of text, measured and drawn whole, so their spaces are the font's.
	 */
	static List<Line> wrap(Component c, List<Run> runs, int width)
	{
		List<Line> lines = new ArrayList<>();
		Line line = new Line();
		boolean space = false;
		for (Run run : runs)
		{
			FontMetrics fm = c.getFontMetrics(run.font);
			Matcher m = TOKEN.matcher(run.text);
			while (m.find())
			{
				String word = m.group();
				if (Character.isWhitespace(word.charAt(0)))
				{
					// None at the start of a line.
					space = !line.pieces.isEmpty();
					continue;
				}
				if (!line.pieces.isEmpty() && line.widthWith(word, run, space, fm) > width)
				{
					lines.add(line);
					line = new Line();
					space = false;
				}
				// Too long for a line of its own: as much as fits on each.
				while (word.length() > 1 && fm.stringWidth(word) > width)
				{
					int n = fitting(fm, word, width);
					line.add(word.substring(0, n), run, false, fm);
					lines.add(line);
					line = new Line();
					word = word.substring(n);
				}
				line.add(word, run, space, fm);
				space = false;
			}
		}
		if (!line.pieces.isEmpty() || lines.isEmpty())
		{
			lines.add(line);
		}
		return lines;
	}

	/** How many of {@code word}'s first characters fit in {@code width}: at least one. */
	private static int fitting(FontMetrics fm, String word, int width)
	{
		int n = 1;
		while (n < word.length() && fm.stringWidth(word.substring(0, n + 1)) <= width)
		{
			n++;
		}
		return n;
	}

	/** Text in one font and colour, maybe code (drawn on a faint patch). */
	static final class Run
	{
		final String text;
		final Font font;
		final boolean code;
		final Color color;

		Run(String text, Font font, boolean code, Color color)
		{
			this.text = text;
			this.font = font;
			this.code = code;
			this.color = color;
		}
	}

	/** Words of one run on a line, and where they start on it. */
	private static final class Piece
	{
		final Run run;
		final int x;
		String text;
		int width;

		Piece(Run run, int x, String text, int width)
		{
			this.run = run;
			this.x = x;
			this.text = text;
			this.width = width;
		}
	}

	/** A wrapped line: its pieces, and how wide they are together. */
	static final class Line
	{
		final List<Piece> pieces = new ArrayList<>();
		int width;

		/** How wide the line would be with {@code word} of {@code run} added, after a space if {@code space}. */
		int widthWith(String word, Run run, boolean space, FontMetrics fm)
		{
			Piece last = pieces.isEmpty() ? null : pieces.get(pieces.size() - 1);
			if (last != null && last.run == run)
			{
				return last.x + fm.stringWidth(last.text + (space ? " " : "") + word);
			}
			return width + (space ? fm.charWidth(' ') : 0) + fm.stringWidth(word);
		}

		void add(String word, Run run, boolean space, FontMetrics fm)
		{
			Piece last = pieces.isEmpty() ? null : pieces.get(pieces.size() - 1);
			if (last != null && last.run == run)
			{
				last.text += (space ? " " : "") + word;
				last.width = fm.stringWidth(last.text);
				width = last.x + last.width;
				return;
			}
			int x = width + (space ? fm.charWidth(' ') : 0);
			int w = fm.stringWidth(word);
			pieces.add(new Piece(run, x, word, w));
			width = x + w;
		}
	}

	/** A row of the table (its cells' lines), or a card (its fields' lines). */
	private static final class Row
	{
		final List<List<Line>> cells = new ArrayList<>();
		int height;
	}

	/** The table laid out for one width. */
	private static final class Layout
	{
		final int available;
		boolean cards;
		/** The table's columns' widths, padding included; unused for cards. */
		int[] columns = new int[0];
		final List<Row> rows = new ArrayList<>();
		int width;
		int height;
		int lineHeight;
		int ascent;

		Layout(int available)
		{
			this.available = available;
		}
	}
}

package com.aichat;

import java.util.concurrent.Executor;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;

/**
 * Passes on the newest of a quick stream of values, such as a reply's text as it streams in, at most once every
 * {@code gapMillis}: each pass redraws the reply, so the values in between are skipped. Values come from any thread;
 * passes run on {@code edt}, one at a time, and the last value offered is always passed on.
 */
final class Throttle<T>
{
	private final Executor edt;
	private final ScheduledExecutorService scheduler;
	private final long gapNanos;
	private final Consumer<T> pass;
	private final AtomicReference<T> latest = new AtomicReference<>();
	/** A pass is on its way: it will take whatever is newest when it runs. */
	private final AtomicBoolean queued = new AtomicBoolean();
	/** When the next pass may run, in {@link System#nanoTime()} time. */
	private volatile long nextAt = System.nanoTime();

	/** {@code scheduler}: only for the short waits between passes. */
	Throttle(Executor edt, ScheduledExecutorService scheduler, long gapMillis, Consumer<T> pass)
	{
		this.edt = edt;
		this.scheduler = scheduler;
		this.gapNanos = TimeUnit.MILLISECONDS.toNanos(gapMillis);
		this.pass = pass;
	}

	/** Any thread. */
	void offer(T value)
	{
		latest.set(value);
		if (!queued.compareAndSet(false, true))
		{
			return;
		}
		long wait = nextAt - System.nanoTime();
		if (wait <= 0)
		{
			edt.execute(this::pass);
			return;
		}
		try
		{
			scheduler.schedule(() -> edt.execute(this::pass), wait, TimeUnit.NANOSECONDS);
		}
		catch (RejectedExecutionException e)
		{
			// RuneLite is closing: no waiting, then.
			edt.execute(this::pass);
		}
	}

	/** The newest value offered so far, or null. Any thread. */
	T latest()
	{
		return latest.get();
	}

	private void pass()
	{
		// Cleared before reading: a value offered from now on queues another pass rather than being missed.
		queued.set(false);
		nextAt = System.nanoTime() + gapNanos;
		pass.accept(latest.get());
	}
}

package com.aichat;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

/**
 * The tools that go with one request, and the runner that answers the model's calls to them: the look-ups first
 * (wiki_search and wiki_page with "Wiki look-ups", ge_price always), then the game-data tools the sharing settings allow
 * (get_equipment, get_inventory, get_bank, get_slayer_task, get_achievement_diaries). Always in that order: the tools
 * are part of the prompt the provider caches, and changing them sends earlier replies as plain text.
 */
@Slf4j
final class ToolBox implements ChatApi.ToolRunner
{
	/** What the tools of every request are made from: the plugin's own, or a test's stand-ins. */
	static final class Parts
	{
		private final WikiClient wiki;
		private final LookupTools.Prices prices;
		private final GameDataTools.Game game;
		private final Consumer<Runnable> clientThread;
		private final ScheduledExecutorService executor;
		private final BooleanSupplier shareItems;
		private final BooleanSupplier shareCharacter;

		/**
		 * {@code shareItems}, {@code shareCharacter}: whether the settings allow sharing right now, AI requests
		 * included; read on the tools' own threads.
		 */
		Parts(WikiClient wiki, LookupTools.Prices prices, GameDataTools.Game game, Consumer<Runnable> clientThread,
			ScheduledExecutorService executor, BooleanSupplier shareItems, BooleanSupplier shareCharacter)
		{
			this.wiki = wiki;
			this.prices = prices;
			this.game = game;
			this.clientThread = clientThread;
			this.executor = executor;
			this.shareItems = shareItems;
			this.shareCharacter = shareCharacter;
		}

		/**
		 * The tools for a request sent with {@code setup}. {@code wanted}: false once the request has stopped.
		 * {@code activity} hears one line per call, and {@code started} when a call starts.
		 */
		ToolBox forRequest(RequestRunner.Setup setup, BooleanSupplier wanted, Consumer<String> activity, Runnable started)
		{
			LookupTools lookups = new LookupTools(setup.wikiLookups ? wiki : null, prices, activity, wanted);
			// The settings as they were when the player sent the message, and as they are at each call: turning one off
			// while a reply is being written stops the sharing at once.
			GameDataTools gameData = new GameDataTools(game, clientThread, executor,
				() -> setup.shareItems && shareItems.getAsBoolean(),
				() -> setup.shareCharacter && shareCharacter.getAsBoolean(),
				activity);
			return new ToolBox(lookups, gameData, started);
		}
	}

	private final LookupTools lookups;
	private final GameDataTools gameData;
	/** Told when a call starts, on the provider's thread, so the panel can say it's looking things up. */
	private final Runnable started;

	ToolBox(LookupTools lookups, GameDataTools gameData, Runnable started)
	{
		this.lookups = lookups;
		this.gameData = gameData;
		this.started = started;
	}

	List<ChatApi.ToolSpec> specs()
	{
		List<ChatApi.ToolSpec> specs = new ArrayList<>(lookups.specs());
		specs.addAll(gameData.specs());
		return specs;
	}

	/** Offers the tools with {@code conversation}, and answers its calls to them. */
	void addTo(ChatApi.Conversation conversation)
	{
		conversation.tools.addAll(specs());
		conversation.toolRunner = this;
	}

	@Override
	public void run(String name, JsonObject input, Consumer<ChatApi.ToolResult> done)
	{
		try
		{
			started.run();
		}
		catch (RuntimeException e)
		{
			// Only the status line is lost.
			log.warn("look-up start not shown", e);
		}
		// Each runner checks its own settings again, so a call to a tool that wasn't offered is turned down there.
		if (LookupTools.handles(name))
		{
			lookups.run(name, input, done);
		}
		else if (GameDataTools.handles(name))
		{
			gameData.run(name, input, done);
		}
		else
		{
			done.accept(ChatApi.ToolResult.error("There's no tool called " + name + "."));
		}
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The Old School RuneScape Wiki's MediaWiki API: search, and a page's wikitext. Requests go through RuneLite's own HTTP
 * client, one at a time (the Wiki asks tools not to send several at once), and answer on an OkHttp thread.
 */
@Slf4j
final class WikiClient
{
	/** The error code for a request that wasn't sent because Wiki look-ups were turned off. */
	static final String TURNED_OFF = "turned-off";
	/** The error code for a request that wasn't sent because the reply it was for had stopped. */
	static final String STOPPED = "stopped";
	/** Where people read the Wiki: links in replies point here, also in tests. */
	static final HttpUrl BASE = HttpUrl.get("https://oldschool.runescape.wiki/");
	static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	/** The Wiki asks tools to say who they are and where to find them; RuneLite puts its own name in front. */
	static final String USER_AGENT = "osrs-ai-chat (RuneLite plugin; https://github.com/brendanciccone/osrs-ai-chat)";
	private static final long TIMEOUT_MILLIS = 15_000;
	/**
	 * Seconds the Wiki's own servers may keep an answer, so asking again in the same chat costs it little. Nothing is
	 * kept on this computer: the searches come from the player's questions.
	 */
	private static final String CACHE_SECONDS = "300";

	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern ENTITY = Pattern.compile("&(#[0-9]{1,7}|#[xX][0-9a-fA-F]{1,6}|[a-zA-Z]{2,8});");
	private static final Pattern SPACES = Pattern.compile("\\s+");
	/** An HTML comment, also one left open at the end. */
	private static final Pattern COMMENT = Pattern.compile("(?s)<!--.*?(-->|$)");
	/** Where the footnotes were listed. */
	private static final Pattern REFLIST = Pattern.compile("(?i)\\{\\{\\s*reflist\\s*}}");
	/** Images, sounds and the page's categories. A link to one starts with a colon instead and is left alone. */
	private static final Pattern FILE_LINK = Pattern.compile("(?i)\\[\\[\\s*(file|image|media|category)\\s*:");
	/** Page layout switches such as __NOTOC__. */
	private static final Pattern MAGIC_WORD = Pattern.compile("__[A-Z]+__");
	/**
	 * Spaces at the end of a line, matched only from where a run of them starts: tried from every space of a long run
	 * that doesn't end the line (anyone can edit the Wiki), it would take seconds.
	 */
	private static final Pattern TRAILING_SPACES = Pattern.compile("(?m)(?<![ \\t])[ \\t]++$");
	private static final Pattern BLANK_LINES = Pattern.compile("\n{3,}");
	/** The deepest heading level: "====== Six ======". */
	private static final int MAX_HEADING = 6;

	/** What a look-up hears back: one of the two, once, on an OkHttp thread. */
	interface Listener<T>
	{
		void onResult(T result);

		/**
		 * {@code code}: the Wiki's own error code ("missingtitle", "nosuchsection"...) when it answered with one,
		 * {@link #TURNED_OFF} when look-ups were turned off before the request went out, {@link #STOPPED} when it was no
		 * longer wanted by then, or null when the Wiki couldn't be reached or understood. {@code message} says what went
		 * wrong in a sentence.
		 */
		void onError(String code, String message);
	}

	static final class SearchResult
	{
		final String title;
		final String url;
		/** Plain text, on one line; may be empty. */
		final String snippet;

		SearchResult(String title, String url, String snippet)
		{
			this.title = title;
			this.url = url;
			this.snippet = snippet;
		}
	}

	static final class Search
	{
		final List<SearchResult> results;
		/** The Wiki's "did you mean", or null. */
		final String suggestion;

		Search(List<SearchResult> results, String suggestion)
		{
			this.results = results;
			this.suggestion = suggestion;
		}
	}

	static final class Section
	{
		/** What to ask for to read only this section. */
		final int index;
		/** 2 for "== A ==", 3 for "=== B ===", and so on. */
		final int level;
		final String heading;

		Section(int index, int level, String heading)
		{
			this.index = index;
			this.level = level;
			this.heading = heading;
		}
	}

	static final class Page
	{
		/** The page's own title, after following redirects. */
		final String title;
		/** The title asked for, when it redirected here; otherwise null. */
		final String redirectedFrom;
		/** The page (or the one section asked for) as written, not yet cleaned. */
		final String wikitext;
		/** The page's own sections, in order; empty when only one section was asked for. */
		final List<Section> sections;
		/** The page's address, at the section asked for if its heading is plain enough to link to. */
		final String url;

		Page(String title, String redirectedFrom, String wikitext, List<Section> sections, String url)
		{
			this.title = title;
			this.redirectedFrom = redirectedFrom;
			this.wikitext = wikitext;
			this.sections = sections;
			this.url = url;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl api;
	/** Checked just before each request goes out: Wiki look-ups (and AI requests) may be turned off while one waits. */
	private final BooleanSupplier allowed;
	/** Requests waiting for the one in flight to finish. */
	private final Deque<Runnable> waiting = new ArrayDeque<>();
	private boolean busy;

	WikiClient(OkHttpClient http, Gson gson, BooleanSupplier allowed)
	{
		this(http, gson, allowed, API, TIMEOUT_MILLIS);
	}

	WikiClient(OkHttpClient http, Gson gson, BooleanSupplier allowed, HttpUrl api, long timeoutMillis)
	{
		this.http = http.newBuilder()
			.cache(null)
			.connectTimeout(timeoutMillis, TimeUnit.MILLISECONDS)
			.readTimeout(timeoutMillis, TimeUnit.MILLISECONDS)
			.callTimeout(timeoutMillis, TimeUnit.MILLISECONDS)
			.build();
		this.gson = gson;
		this.allowed = allowed;
		this.api = api;
	}

	/**
	 * Full-text search of the Wiki's articles: up to {@code limit} results with a snippet each. {@code wanted}: checked
	 * just before it goes out, like the settings; false once the reply it's for has stopped.
	 */
	void search(String query, int limit, BooleanSupplier wanted, Listener<Search> listener)
	{
		HttpUrl url = common(api.newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", query)
			.addQueryParameter("srlimit", String.valueOf(limit))
			.addQueryParameter("srprop", "snippet")
			.addQueryParameter("srnamespace", "0"));
		get(url, wanted, listener, WikiClient::search);
	}

	/**
	 * A page's wikitext, redirects followed. {@code section} -1 reads the whole page and lists its sections; 0 or more
	 * reads only that section (0 is the part before the first heading). {@code wanted}: as for {@link #search}.
	 */
	void page(String title, int section, BooleanSupplier wanted, Listener<Page> listener)
	{
		HttpUrl.Builder url = api.newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", title)
			.addQueryParameter("prop", section < 0 ? "wikitext|sections" : "wikitext")
			// MediaWiki takes any value as yes; leaving it out is no.
			.addQueryParameter("redirects", "1");
		if (section >= 0)
		{
			url.addQueryParameter("section", String.valueOf(section));
		}
		get(common(url), wanted, listener, o -> page(o, section));
	}

	private static HttpUrl common(HttpUrl.Builder url)
	{
		return url
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			// Asks the Wiki to turn the request away rather than add to its load while it's struggling.
			.addQueryParameter("maxlag", "5")
			.addQueryParameter("maxage", CACHE_SECONDS)
			.addQueryParameter("smaxage", CACHE_SECONDS)
			.build();
	}

	/** Sends a GET once no other request is in flight, and turns the answer into a result with {@code read}. */
	private <T> void get(HttpUrl url, BooleanSupplier wanted, Listener<T> listener, Function<JsonObject, T> read)
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();
		Runnable send = () -> send(request, wanted, listener, read);
		if (startNow(send))
		{
			send.run();
		}
	}

	/**
	 * Runs as the one request in flight. {@link #finished} follows exactly once whatever happens, before the listener
	 * hears back: a listener that throws can't hold up the requests waiting. A request whose reply was stopped while it
	 * waited its turn isn't sent: the Wiki has nothing to answer, and the next reply's look-ups don't wait behind it.
	 */
	private <T> void send(Request request, BooleanSupplier wanted, Listener<T> listener, Function<JsonObject, T> read)
	{
		String notSent;
		try
		{
			notSent = !wanted.getAsBoolean() ? STOPPED : !allowed.getAsBoolean() ? TURNED_OFF : null;
			if (notSent == null)
			{
				http.newCall(request).enqueue(callback(listener, read));
				return;
			}
		}
		catch (RuntimeException e)
		{
			// OkHttp turned the call away (RuneLite is closing, say).
			log.debug("Wiki request not sent", e);
			notSent = null;
		}
		finished();
		if (STOPPED.equals(notSent))
		{
			listener.onError(STOPPED, "The reply this was for has stopped.");
		}
		else if (TURNED_OFF.equals(notSent))
		{
			listener.onError(TURNED_OFF, "Wiki look-ups are turned off in the AI Chat settings.");
		}
		else
		{
			listener.onError(null, "Couldn't reach the Wiki.");
		}
	}

	private <T> Callback callback(Listener<T> listener, Function<JsonObject, T> read)
	{
		return new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				finished();
				listener.onError(null, unreachable(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String text;
				try (ResponseBody body = response.body())
				{
					text = body == null ? "" : body.string();
				}
				catch (IOException e)
				{
					finished();
					listener.onError(null, unreachable(e));
					return;
				}
				finished();
				answer(response.code(), text, listener, read);
			}
		};
	}

	/** True to send now; false when another request is in flight, and this one waits its turn. */
	private synchronized boolean startNow(Runnable send)
	{
		if (busy)
		{
			waiting.add(send);
			return false;
		}
		busy = true;
		return true;
	}

	/** The request in flight is done: send the next one waiting, if any. */
	private void finished()
	{
		Runnable next;
		synchronized (this)
		{
			next = waiting.poll();
			if (next == null)
			{
				busy = false;
				return;
			}
		}
		try
		{
			next.run();
		}
		catch (RuntimeException e)
		{
			// Its listener threw (it can hear back at once, when look-ups were turned off). That's not this request's
			// problem: its own listener still has to hear back.
			log.warn("Wiki look-up listener failed", e);
		}
	}

	private <T> void answer(int code, String text, Listener<T> listener, Function<JsonObject, T> read)
	{
		if (code == 429)
		{
			listener.onError(null, "The Wiki is getting too many requests right now.");
			return;
		}
		if (code < 200 || code >= 300)
		{
			listener.onError(null, code >= 500
				? "The Wiki is having trouble right now (HTTP " + code + ")."
				: "The Wiki answered HTTP " + code + ".");
			return;
		}
		JsonObject error = null;
		T result = null;
		try
		{
			JsonElement parsed = gson.fromJson(text, JsonElement.class);
			JsonObject o = parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
			// Errors, a missing page among them, come back as HTTP 200 with an "error" object.
			error = o == null ? null : object(o, "error");
			if (o != null && error == null)
			{
				result = read.apply(o);
			}
		}
		catch (RuntimeException e)
		{
			// Not JSON, or not the shape asked for: the same to the reader. Nothing escapes, so the listener hears back.
			log.debug("unreadable Wiki answer", e);
		}
		if (error != null)
		{
			String errorCode = string(error, "code");
			listener.onError(errorCode, describe(errorCode, string(error, "info")));
			return;
		}
		if (result == null)
		{
			listener.onError(null, "The Wiki sent an answer AI Chat couldn't read.");
			return;
		}
		listener.onResult(result);
	}

	private static String describe(String code, String info)
	{
		if ("maxlag".equals(code) || "ratelimited".equals(code))
		{
			return "The Wiki is busy right now.";
		}
		String detail = info == null ? "" : ": " + ChatApi.shorten(info, 200);
		return "The Wiki turned the request down" + (code == null ? "" : " (" + code + ")") + detail;
	}

	private static String unreachable(IOException e)
	{
		if (ChatApi.tookTooLong(e))
		{
			return "The Wiki took too long to answer.";
		}
		String m = e.getMessage();
		// RuneLite blocks the Wiki on beta and other test worlds.
		if (m != null && m.contains("outside of LIVE"))
		{
			return "The Wiki can't be reached from this kind of world.";
		}
		return "Couldn't reach the Wiki" + (m == null ? "." : ": " + ChatApi.shorten(m, 120));
	}

	private static Search search(JsonObject o)
	{
		JsonObject query = object(o, "query");
		if (query == null)
		{
			return null;
		}
		List<SearchResult> results = new ArrayList<>();
		JsonArray hits = array(query, "search");
		if (hits != null)
		{
			for (JsonElement e : hits)
			{
				String title = e.isJsonObject() ? string(e.getAsJsonObject(), "title") : null;
				if (title != null)
				{
					String snippet = string(e.getAsJsonObject(), "snippet");
					results.add(new SearchResult(title, pageUrl(title, null), snippet == null ? "" : plainText(snippet)));
				}
			}
		}
		JsonObject info = object(query, "searchinfo");
		String suggestion = info == null ? null : string(info, "suggestion");
		return new Search(results, suggestion == null ? null : plainText(suggestion));
	}

	private static Page page(JsonObject o, int section)
	{
		JsonObject parse = object(o, "parse");
		String title = parse == null ? null : string(parse, "title");
		String wikitext = parse == null ? null : string(parse, "wikitext");
		if (title == null || wikitext == null)
		{
			return null;
		}
		String from = null;
		String anchor = null;
		JsonArray redirects = array(parse, "redirects");
		if (redirects != null && redirects.size() > 0 && redirects.get(0).isJsonObject())
		{
			JsonObject r = redirects.get(0).getAsJsonObject();
			from = string(r, "from");
			// "Whip" may lead to one part of a page.
			anchor = string(r, "tofragment");
		}
		List<Section> sections = new ArrayList<>();
		JsonArray list = array(parse, "sections");
		if (list != null)
		{
			String dbTitle = title.replace(' ', '_');
			for (JsonElement e : list)
			{
				Section s = e.isJsonObject() ? section(e.getAsJsonObject(), dbTitle) : null;
				if (s != null)
				{
					sections.add(s);
				}
			}
		}
		if (section > 0)
		{
			String heading = heading(wikitext);
			anchor = heading != null && linkable(heading) ? heading : null;
		}
		return new Page(title, from, wikitext, Collections.unmodifiableList(sections), pageUrl(title, anchor));
	}

	/**
	 * One of the page's own sections, or null. Sections that come from templates the page uses are numbered "T-1" and so
	 * on, and can't be read through this page.
	 */
	private static Section section(JsonObject s, String dbTitle)
	{
		String index = string(s, "index");
		String heading = string(s, "line");
		String fromTitle = string(s, "fromtitle");
		if (index == null || heading == null || !index.matches("[0-9]{1,4}")
			|| (fromTitle != null && !fromTitle.equals(dbTitle)))
		{
			return null;
		}
		String level = string(s, "level");
		return new Section(Integer.parseInt(index), level != null && level.matches("[1-6]") ? Integer.parseInt(level) : 2,
			plainText(heading));
	}

	/**
	 * The heading a section's wikitext starts with ("== Drops ==", maybe with a comment after it), or null. Read by
	 * hand: a pattern for it backtracks for seconds over a heading line with a long run of spaces in it.
	 */
	static String heading(String wikitext)
	{
		String s = wikitext.trim();
		int end = s.indexOf('\n');
		String line = COMMENT.matcher(end < 0 ? s : s.substring(0, end)).replaceAll("").strip();
		int open = 0;
		while (open < line.length() && line.charAt(open) == '=')
		{
			open++;
		}
		int close = 0;
		while (close < line.length() && line.charAt(line.length() - 1 - close) == '=')
		{
			close++;
		}
		// As MediaWiki reads it: the shorter run of "=" sets the level, and there's something between the two runs.
		int level = Math.min(MAX_HEADING, Math.min(Math.min(open, close), (line.length() - 1) / 2));
		String heading = level == 0 ? "" : line.substring(level, line.length() - level).strip();
		return heading.isEmpty() ? null : heading;
	}

	/** Plain words only: a heading with links, templates or formatting gets an anchor this can't predict. */
	private static boolean linkable(String heading)
	{
		return !heading.contains("[[") && !heading.contains("{{") && !heading.contains("<") && !heading.contains("''")
			&& !heading.contains("&");
	}

	/** The page's address on the Wiki: https://oldschool.runescape.wiki/w/Abyssal_whip, optionally at a heading. */
	static String pageUrl(String title, String anchor)
	{
		HttpUrl.Builder url = BASE.newBuilder()
			.addPathSegment("w")
			// Subpages ("Treasure Trails/Guide/Anagrams") keep their slashes; MediaWiki titles can't be "." or "..".
			.addPathSegments(title.trim().replace(' ', '_'));
		if (anchor != null && !anchor.trim().isEmpty())
		{
			url.fragment(anchor.trim().replace(' ', '_'));
		}
		return url.build().toString();
	}

	/**
	 * Wikitext with what isn't worth reading taken out: comments, footnotes, images, galleries and categories, layout
	 * switches, trailing spaces and runs of blank lines. Templates such as infoboxes stay: they hold the stats.
	 */
	static String clean(String wikitext)
	{
		String s = wikitext.replace("\r\n", "\n").replace('\r', '\n');
		s = COMMENT.matcher(s).replaceAll("");
		// Footnotes, where they were listed, and image galleries: nothing left to read in any of them.
		s = withoutElements(s, "ref");
		s = withoutElements(s, "references");
		s = withoutElements(s, "gallery");
		s = REFLIST.matcher(s).replaceAll("");
		s = withoutFileLinks(s);
		s = MAGIC_WORD.matcher(s).replaceAll("");
		s = TRAILING_SPACES.matcher(s).replaceAll("");
		s = BLANK_LINES.matcher(s).replaceAll("\n\n");
		return s.trim();
	}

	/**
	 * {@code s} without its {@code <name ...>...</name>} and {@code <name ... />} elements, any case. Done by hand: a
	 * regex looks for the end of every tag left open all the way to the end of the page, which takes seconds on a page
	 * full of them. A tag that's never closed, and what follows it, is left as it is.
	 */
	static String withoutElements(String s, String name)
	{
		StringBuilder out = new StringBuilder(s.length());
		int from = 0;
		int open = indexOfTag(s, "<" + name, 0);
		while (open >= 0)
		{
			int tagEnd = s.indexOf('>', open);
			if (tagEnd < 0)
			{
				break;
			}
			int end;
			int last = tagEnd - 1;
			while (last > open && Character.isWhitespace(s.charAt(last)))
			{
				last--;
			}
			if (s.charAt(last) == '/')
			{
				end = tagEnd + 1;
			}
			else
			{
				end = closeEnd(s, name, tagEnd + 1);
				if (end < 0)
				{
					break;
				}
			}
			out.append(s, from, open);
			from = end;
			open = indexOfTag(s, "<" + name, end);
		}
		return out.append(s, from, s.length()).toString();
	}

	/**
	 * Where {@code <name} starts at or after {@code from}, any case, as a whole tag name ("<ref" but not "<references"),
	 * or -1.
	 */
	private static int indexOfTag(String s, String open, int from)
	{
		for (int i = from; i + open.length() <= s.length(); i++)
		{
			if (s.charAt(i) == '<' && s.regionMatches(true, i, open, 0, open.length()))
			{
				int after = i + open.length();
				if (after == s.length() || !Character.isLetterOrDigit(s.charAt(after)) && s.charAt(after) != '_')
				{
					return i;
				}
			}
		}
		return -1;
	}

	/** Just after the first {@code </name >} at or after {@code from}, any case, or -1 if there's none. */
	private static int closeEnd(String s, String name, int from)
	{
		String close = "</" + name;
		for (int i = from; i + close.length() <= s.length(); i++)
		{
			if (s.charAt(i) == '<' && s.regionMatches(true, i, close, 0, close.length()))
			{
				int j = i + close.length();
				while (j < s.length() && Character.isWhitespace(s.charAt(j)))
				{
					j++;
				}
				if (j < s.length() && s.charAt(j) == '>')
				{
					return j + 1;
				}
			}
		}
		return -1;
	}

	/** Image links can hold links of their own in the caption: [[File:Whip.png|thumb|An [[abyssal demon]] drop]]. */
	private static String withoutFileLinks(String s)
	{
		Matcher m = FILE_LINK.matcher(s);
		StringBuilder out = new StringBuilder(s.length());
		int from = 0;
		while (m.find(from))
		{
			int end = linkEnd(s, m.start());
			if (end < 0)
			{
				// Never closed: leave the rest as it is.
				break;
			}
			out.append(s, from, m.start());
			from = end;
		}
		return out.append(s, from, s.length()).toString();
	}

	/** Where the [[link]] starting at {@code start} ends (just after its "]]"), counting links inside it; -1 if never. */
	private static int linkEnd(String s, int start)
	{
		int depth = 0;
		int i = start;
		while (i < s.length() - 1)
		{
			if (s.startsWith("[[", i))
			{
				depth++;
				i += 2;
			}
			else if (s.startsWith("]]", i))
			{
				depth--;
				i += 2;
				if (depth == 0)
				{
					return i;
				}
			}
			else
			{
				i++;
			}
		}
		return -1;
	}

	/** Search snippets and headings come as HTML: just their text, on one line. */
	static String plainText(String html)
	{
		String s = TAG.matcher(html).replaceAll("");
		Matcher m = ENTITY.matcher(s);
		StringBuffer out = new StringBuffer(s.length());
		while (m.find())
		{
			m.appendReplacement(out, Matcher.quoteReplacement(entity(m.group(1), m.group())));
		}
		m.appendTail(out);
		return SPACES.matcher(out).replaceAll(" ").trim();
	}

	/** The character an HTML entity stands for, or the entity as written if it isn't one of the usual few. */
	private static String entity(String name, String written)
	{
		if (name.startsWith("#"))
		{
			boolean hex = name.length() > 1 && (name.charAt(1) == 'x' || name.charAt(1) == 'X');
			int cp;
			try
			{
				cp = Integer.parseInt(name.substring(hex ? 2 : 1), hex ? 16 : 10);
			}
			catch (NumberFormatException e)
			{
				return written;
			}
			boolean printable = cp > 0 && Character.isValidCodePoint(cp) && !Character.isISOControl(cp);
			return printable ? new String(Character.toChars(cp)) : written;
		}
		switch (name.toLowerCase(Locale.ROOT))
		{
			case "amp":
				return "&";
			case "lt":
				return "<";
			case "gt":
				return ">";
			case "quot":
				return "\"";
			case "apos":
				return "'";
			case "nbsp":
				return " ";
			case "ndash":
				return "–";
			case "mdash":
				return "—";
			case "hellip":
				return "…";
			case "times":
				return "×";
			default:
				return written;
		}
	}

	private static JsonObject object(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
	}

	private static JsonArray array(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonArray() ? e.getAsJsonArray() : null;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}
}

