package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InterruptedIOException;
import java.net.SocketTimeoutException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * What both providers share: keys, retries and tool rounds. The providers themselves are tested against a stand-in
 * server in {@link AnthropicApiTest} and {@link OpenAiApiTest}.
 */
public class ChatApiTest
{
	@Test
	public void pastedKeysAreCleanedAndChecked()
	{
		assertEquals("sk-ant-abc", ChatApi.cleanKey(" sk-ant-​abc \n"));
		assertTrue(ChatApi.sendableKey(ChatApi.cleanKey(" sk-ant-abc ")));
		assertFalse(ChatApi.sendableKey(ChatApi.cleanKey("sk-ant-abc…")));
		assertFalse(ChatApi.sendableKey(ChatApi.cleanKey("“sk-ant-abc”")));
	}

	@Test
	public void retriesWaitAsLongAsTheProviderAsks()
	{
		assertEquals(2000, ChatApi.retryDelay(null, null, 1));
		assertEquals(6000, ChatApi.retryDelay(null, null, 2));
		assertEquals(0, ChatApi.retryDelay(null, "0", 1));
		assertEquals(3000, ChatApi.retryDelay(null, "3", 1));
		assertEquals(1500, ChatApi.retryDelay(null, "1.5", 2));
		assertEquals("milliseconds first", 1250, ChatApi.retryDelay("1250", "30", 1));
		assertEquals(120_000, ChatApi.retryDelay(null, "120", 1));
		// A date can't be read here: the usual waits instead.
		assertEquals(2000, ChatApi.retryDelay(null, "Wed, 21 Oct 2026 07:28:00 GMT", 1));
		assertEquals(6000, ChatApi.retryDelay("soon", "-5", 2));
	}

	@Test
	public void onlyPassingProblemsAreRetried()
	{
		for (int code : new int[]{408, 409, 429, 500, 502, 503, 504, 529})
		{
			assertTrue(String.valueOf(code), ChatApi.retryableStatus(code, "{\"error\":{\"message\":\"busy\"}}"));
		}
		for (int code : new int[]{400, 401, 402, 403, 404, 413, 422})
		{
			assertFalse(String.valueOf(code), ChatApi.retryableStatus(code, "{}"));
		}
		assertFalse(ChatApi.retryableStatus(429, "{\"error\":{\"message\":\"You exceeded your current quota\",\"type\":\"insufficient_quota\"}}"));
		assertFalse(ChatApi.retryableStatus(429, "{\"error\":{\"message\":\"Your credit balance is too low\"}}"));
		assertFalse(ChatApi.retryableStatus(429, "{\"error\":{\"message\":\"Monthly spend limit reached\"}}"));
		// Groq's limit per minute links to its billing page: a short wait still clears it.
		assertTrue(ChatApi.retryableStatus(429, GROQ_RATE_LIMIT));
	}

	static final String GROQ_RATE_LIMIT = "{\"error\":{\"message\":\"Rate limit reached for model `llama-3.3-70b-versatile` in "
		+ "organization `org_1` service tier `on_demand` on tokens per minute (TPM): Limit 12000, Used 11000, Requested 2000. "
		+ "Please try again in 1.5s. Need more tokens? Upgrade to Dev Tier today at https://console.groq.com/settings/billing\","
		+ "\"type\":\"tokens\",\"code\":\"rate_limit_exceeded\"}}";

	@Test
	public void waitsAreWrittenForPeople()
	{
		assertEquals(1, ChatApi.seconds(1));
		assertEquals(0, ChatApi.seconds(0));
		assertEquals(6, ChatApi.seconds(6000));
		assertEquals("1 second", ChatApi.waitText(1000));
		assertEquals("90 seconds", ChatApi.waitText(90_000));
		assertEquals("2 minutes", ChatApi.waitText(91_000));
		assertEquals("5 minutes", ChatApi.waitText(300_000));
		assertEquals("2 hours", ChatApi.waitText(7_200_000));
	}

	@Test
	public void thePromptKeyCoversModelInstructionsAndTools()
	{
		ChatApi.Conversation c = StandIn.conversation("claude-opus-5-5", "hi");
		String key = ChatApi.promptKey(c);
		c.turns.add(new ChatApi.Turn(false, "the turns don't count"));
		c.maxTokens = 100;
		assertEquals(key, ChatApi.promptKey(c));
		c.tools.add(StandIn.tool("wiki_search"));
		String withTool = ChatApi.promptKey(c);
		assertNotEquals(key, withTool);
		c.tools.clear();
		c.tools.add(StandIn.tool("ge_price"));
		assertNotEquals(withTool, ChatApi.promptKey(c));
		c.tools.clear();
		c.system = "Other";
		assertNotEquals(key, ChatApi.promptKey(c));
	}

	@Test
	public void toolsRunTogetherAndAnswerInOrderWhateverHappens() throws Exception
	{
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<ChatApi.ToolResult>> results = new AtomicReference<>();
		List<String> ran = new ArrayList<>();
		CountDownLatch secondIn = new CountDownLatch(1);
		ChatApi.ToolRunner runner = (name, input, answer) ->
		{
			ran.add(name);
			switch (name)
			{
				case "slow":
					// Answers on another thread, after the one asked for after it.
					new Thread(() ->
					{
						StandIn.await(secondIn);
						answer.accept(ChatApi.ToolResult.ok("slow " + input.get("n")));
					}).start();
					break;
				case "fast":
					answer.accept(ChatApi.ToolResult.ok("fast"));
					// A second answer is ignored.
					answer.accept(ChatApi.ToolResult.error("again"));
					secondIn.countDown();
					break;
				default:
					throw new IllegalStateException("broken tool");
			}
		};
		JsonObject n = new JsonObject();
		n.addProperty("n", 1);
		ChatApi.runTools(runner, Arrays.asList("slow", "fast", "broken", "unread"), Arrays.asList(n, new JsonObject(), new JsonObject(), null), r ->
		{
			results.set(r);
			done.countDown();
		});
		assertTrue(done.await(10, TimeUnit.SECONDS));
		List<ChatApi.ToolResult> r = results.get();
		assertEquals("unreadable arguments aren't run", List.of("slow", "fast", "broken"), ran);
		assertEquals("slow 1", r.get(0).content);
		assertEquals("fast", r.get(1).content);
		assertFalse(r.get(1).error);
		assertTrue(r.get(2).error);
		assertTrue(r.get(2).content.contains("broken"));
		assertTrue(r.get(3).error);
		assertTrue(r.get(3).content.startsWith("Arguments weren't valid JSON"));

		// No runner (a request without tools that got a call anyway), and no calls at all.
		AtomicReference<List<ChatApi.ToolResult>> none = new AtomicReference<>();
		ChatApi.runTools(null, List.of("wiki_search"), List.of(new JsonObject()), none::set);
		assertTrue(none.get().get(0).error);
		ChatApi.runTools(runner, List.of(), List.of(), none::set);
		assertTrue(none.get().isEmpty());
	}

	@Test
	public void onlySoManyToolCallsRunAtOnce()
	{
		List<String> ran = new CopyOnWriteArrayList<>();
		List<String> names = new ArrayList<>();
		List<JsonObject> inputs = new ArrayList<>();
		for (int i = 0; i < ChatApi.MAX_TOOL_CALLS + 2; i++)
		{
			names.add("wiki_page " + i);
			inputs.add(new JsonObject());
		}
		AtomicReference<List<ChatApi.ToolResult>> results = new AtomicReference<>();
		ChatApi.runTools((name, input, done) ->
		{
			ran.add(name);
			done.accept(ChatApi.ToolResult.ok("read"));
		}, names, inputs, results::set);
		assertEquals(names.subList(0, ChatApi.MAX_TOOL_CALLS), ran);
		assertEquals(names.size(), results.get().size());
		assertFalse(results.get().get(ChatApi.MAX_TOOL_CALLS - 1).error);
		ChatApi.ToolResult turnedDown = results.get().get(ChatApi.MAX_TOOL_CALLS);
		assertTrue(turnedDown.error);
		assertEquals("Too many look-ups at once: only the first 10 were run. Ask for fewer at a time.", turnedDown.content);
	}

	@Test
	public void onlyATimeoutAfterConnectingIsTakingTooLong()
	{
		// The provider had the request: it may be answering it, and billing it.
		assertTrue(ChatApi.tookTooLong(new SocketTimeoutException("timeout")));
		assertTrue(ChatApi.tookTooLong(new SocketTimeoutException("Read timed out")));
		assertTrue(ChatApi.tookTooLong(new InterruptedIOException("timeout")));
		assertTrue(ChatApi.tookTooLong(new SocketTimeoutException()));
		// Nothing answered at all.
		assertFalse(ChatApi.tookTooLong(new SocketTimeoutException("connect timed out")));
		assertFalse(ChatApi.tookTooLong(new SocketTimeoutException("failed to connect to /10.0.0.1 (port 443) after 10000ms")));
		assertFalse(ChatApi.tookTooLong(new IOException("timeout")));
	}

	@Test
	public void jsonNestedDeeperThanAnswersNeedIsCaught()
	{
		String deep = "[".repeat(ChatApi.MAX_JSON_DEPTH + 1);
		assertFalse(ChatApi.tooDeep("{\"query\":\"[[[[\",\"n\":[1,[2.5e-3]],\"ok\":true}"));
		assertFalse(ChatApi.tooDeep("[".repeat(ChatApi.MAX_JSON_DEPTH) + "]".repeat(ChatApi.MAX_JSON_DEPTH)));
		assertTrue(ChatApi.tooDeep(deep));
		assertFalse("brackets in a string, after an escaped quote", ChatApi.tooDeep("{\"q\":\"\\\"" + "[".repeat(100) + "\"}"));
		try
		{
			ChatApi.fromJson(new Gson(), "{\"a\":" + deep + "]".repeat(ChatApi.MAX_JSON_DEPTH + 1) + "}", JsonObject.class);
			fail("read");
		}
		catch (JsonParseException e)
		{
			// Refused like any other bad JSON.
		}

		// Gson also reads JSON that isn't plain, where a quote may not start a string: what follows still counts.
		assertTrue("a quote in a bare word", ChatApi.tooDeep("[a\"," + deep));
		assertTrue("single quotes", ChatApi.tooDeep("['\"'," + deep));
		assertTrue("a comment", ChatApi.tooDeep("/* ,\" */" + deep));
		assertTrue("the prefix Gson skips", ChatApi.tooDeep(")]}'\n" + deep));
		assertFalse("a few brackets in JSON that isn't plain", ChatApi.tooDeep("{query: 'x', n: [1]}"));
	}

	@Test
	public void roundsAreJoinedIntoOneReply()
	{
		assertEquals("Let me check.\n\nIt's 1.5m.", ChatApi.joinRounds(List.of(" Let me check. ", ""), "It's 1.5m.\n"));
		assertEquals("Only", ChatApi.joinRounds(List.of(), "Only"));
		assertEquals("", ChatApi.joinRounds(List.of(""), " "));
	}
}

package com.aichat;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import org.junit.After;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * "Save chat history": the saved chats are opened once and brought back, saves wait for that and then follow the chats,
 * and turning the setting off deletes the saved copy. The disk is a stand-in; the EDT is a queue the test runs.
 */
public class ChatSaverTest
{
	private final Gson gson = new Gson();
	/** Stands in for the EDT: tasks wait here until the test runs them, as invokeLater's do. */
	private final BlockingQueue<Runnable> edt = new LinkedBlockingQueue<>();
	private final Scheduler executor = new Scheduler();
	private final FakeDisk disk = new FakeDisk();
	private final FakeHost host = new FakeHost();
	private final ChatSaver saver = new ChatSaver(disk, gson, edt::add, executor, host);

	@After
	public void stop()
	{
		executor.shutdownNow();
	}

	/**
	 * The plugin's executor, with a record of how long each save was asked to wait (in seconds; work run at once is
	 * scheduled in nanoseconds), which it doesn't wait, though.
	 */
	private static final class Scheduler extends ScheduledThreadPoolExecutor
	{
		final List<Long> delays = new CopyOnWriteArrayList<>();

		Scheduler()
		{
			super(1);
		}

		@Override
		public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
		{
			if (unit == TimeUnit.SECONDS)
			{
				delays.add(delay);
			}
			return super.schedule(command, 0, unit);
		}
	}

	private static final class FakeDisk implements ChatSaver.Disk
	{
		ChatFile.Opened opened = new ChatFile.Opened(ChatFile.State.OWNER, null);
		final AtomicInteger opens = new AtomicInteger();
		final AtomicInteger deletes = new AtomicInteger();
		/** What each save wrote, in order. */
		final List<String> writes = new CopyOnWriteArrayList<>();

		@Override
		public ChatFile.Opened open()
		{
			opens.incrementAndGet();
			return opened;
		}

		@Override
		public void write(String json, long number, BooleanSupplier wanted)
		{
			if (wanted.getAsBoolean())
			{
				writes.add(json);
			}
		}

		@Override
		public void delete()
		{
			deletes.incrementAndGet();
		}
	}

	private static final class FakeHost implements ChatSaver.Host
	{
		volatile boolean remember = true;
		final List<Chat> chats = new ArrayList<>();
		Chat current;
		Chat restored;
		final List<String> notes = new ArrayList<>();

		@Override
		public boolean rememberChats()
		{
			return remember;
		}

		@Override
		public List<Chat> chats()
		{
			return chats;
		}

		@Override
		public Chat current()
		{
			return current;
		}

		@Override
		public void restored(Chat shown)
		{
			restored = shown;
			current = shown;
		}

		@Override
		public void note(String text)
		{
			notes.add(text);
		}
	}

	/** Waits for the file work queued so far to be done. */
	private void drain() throws Exception
	{
		executor.submit(() ->
		{
		}).get(5, TimeUnit.SECONDS);
	}

	/** Waits for the file's answer to reach the EDT, then runs everything waiting there. */
	private void awaitEdt() throws InterruptedException
	{
		Runnable r = edt.poll(5, TimeUnit.SECONDS);
		assertNotNull("nothing reached the EDT", r);
		r.run();
		Runnable more;
		while ((more = edt.poll()) != null)
		{
			more.run();
		}
	}

	private Chat chat(String id, String name, String... texts)
	{
		Chat c = new Chat(id, name);
		for (String t : texts)
		{
			c.messages.add(new Chat.Message(Chat.Role.USER, t));
		}
		return c;
	}

	/** Saved chats on disk: "a" and "b", with "b" open. */
	private ChatStore.Loaded saved()
	{
		Chat a = chat("a", "Agility", "best course?");
		Chat b = chat("b", "Bank", "what to sell?");
		return ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(a, b), b));
	}

	@Test
	public void savedChatsComeBackAndAreSavedFromThenOn() throws Exception
	{
		Chat fresh = chat("new", "Chat 1");
		host.chats.add(fresh);
		host.current = fresh;
		disk.opened = new ChatFile.Opened(ChatFile.State.OWNER, saved());

		saver.apply();
		awaitEdt();
		assertEquals(1, disk.opens.get());
		// The empty chat made at start-up gave way; the one that was open is shown.
		assertEquals(2, host.chats.size());
		assertEquals("a", host.chats.get(0).id);
		assertEquals("b", host.restored.id);

		// Then saved: everything there is now.
		drain();
		assertEquals(1, disk.writes.size());
		ChatStore.Loaded written = ChatStore.fromJson(gson, disk.writes.get(0));
		assertEquals(2, written.chats.size());
		assertEquals("b", written.current.id);
		assertEquals(Long.valueOf(1), executor.delays.get(0));

		// Opened once only.
		saver.apply();
		drain();
		assertEquals(1, disk.opens.get());
		assertEquals(2, disk.writes.size());
	}

	@Test
	public void aSaveWhileTheChatsAreOpeningWaitsForThem() throws Exception
	{
		Chat asked = chat("new", "Chat 1", "a question asked at once");
		host.chats.add(asked);
		host.current = asked;
		disk.opened = new ChatFile.Opened(ChatFile.State.OWNER, saved());
		saver.apply();
		drain();
		// The chats on disk aren't in yet: saving now would write over them with this one alone.
		saver.saveSoon();
		drain();
		assertTrue(disk.writes.isEmpty());

		awaitEdt();
		drain();
		assertEquals(1, disk.writes.size());
		ChatStore.Loaded written = ChatStore.fromJson(gson, disk.writes.get(0));
		assertEquals("all three", 3, written.chats.size());
		assertSame("the chat in use stays open", asked, host.restored);
	}

	@Test
	public void chatsOwnedByAnotherWindowAreNeverWritten() throws Exception
	{
		host.chats.add(chat("new", "Chat 1", "q"));
		disk.opened = new ChatFile.Opened(ChatFile.State.OTHER_WINDOW, null);
		saver.apply();
		awaitEdt();
		assertEquals(List.of(ChatSaver.OTHER_WINDOW), host.notes);
		saver.saveSoon();
		saver.saveNow();
		assertNull(saver.close());
		drain();
		assertTrue(disk.writes.isEmpty());

		// An unreadable file is left alone too.
		FakeDisk unreadable = new FakeDisk();
		unreadable.opened = new ChatFile.Opened(ChatFile.State.UNREADABLE, null);
		ChatSaver other = new ChatSaver(unreadable, gson, edt::add, executor, host);
		other.apply();
		awaitEdt();
		assertEquals(ChatSaver.UNREADABLE, host.notes.get(host.notes.size() - 1));
		other.saveNow();
		drain();
		assertTrue(unreadable.writes.isEmpty());
	}

	@Test
	public void turningRememberChatsOffDeletesTheSavedCopy() throws Exception
	{
		host.chats.add(chat("new", "Chat 1", "q"));
		saver.apply();
		awaitEdt();
		drain();
		int written = disk.writes.size();

		host.remember = false;
		saver.apply();
		drain();
		assertEquals(1, disk.deletes.get());
		saver.saveSoon();
		drain();
		assertEquals("nothing saved while it's off", written, disk.writes.size());

		// Back on: saved again, without opening the file again.
		host.remember = true;
		saver.apply();
		drain();
		assertEquals(written + 1, disk.writes.size());
		assertEquals(1, disk.opens.get());
	}

	@Test
	public void closingSavesAtOnce() throws Exception
	{
		host.chats.add(chat("new", "Chat 1", "q"));
		saver.apply();
		awaitEdt();
		drain();
		ScheduledFuture<?> last = saver.close();
		assertNotNull("RuneLite waits for this", last);
		last.get(5, TimeUnit.SECONDS);
		assertEquals(Long.valueOf(0), executor.delays.get(executor.delays.size() - 1));
		saver.saveSoon();
		assertEquals("every change from now on, at once", Long.valueOf(0), executor.delays.get(executor.delays.size() - 1));
	}

	@Test
	public void savedChatsGoFirstWithoutDuplicates()
	{
		ChatStore.Loaded loaded = saved();
		List<Chat> chats = new ArrayList<>();
		Chat named = chat("named", "Named");
		named.namedByPlayer = true;
		Chat empty = chat("empty", "Chat 1");
		Chat again = chat("a", "Agility", "best course?");
		chats.add(named);
		chats.add(empty);
		chats.add(again);

		Chat shown = ChatSaver.restore(chats, empty, loaded);
		// "a" is already here; the empty chat gives way, the one the player named doesn't.
		assertEquals(List.of("b", "named", "a"), ids(chats));
		assertSame("the one that was open, as the shown one went", loaded.current, shown);

		// Nothing new: nothing changes.
		assertNull(ChatSaver.restore(chats, named, loaded));
		assertEquals(3, chats.size());
	}

	private static List<String> ids(List<Chat> chats)
	{
		List<String> ids = new ArrayList<>();
		for (Chat c : chats)
		{
			ids.add(c.id);
		}
		return ids;
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** What "Save chat history" keeps, and how it comes back. */
public class ChatStoreTest
{
	private final Gson gson = new Gson();

	@Test
	public void chatsComeBackAsTheyWere()
	{
		Chat first = new Chat("Agility");
		first.defaultName = false;
		Chat.Message q = new Chat.Message(Chat.Role.USER, "best way to train Agility at 50?");
		q.context = "[Character: Zezima, combat level 3]";
		first.messages.add(q);
		Chat.Message a = new Chat.Message(Chat.Role.ASSISTANT, "Rooftop courses.");
		a.who = "Claude";
		a.rawMessages = gson.fromJson("[{\"role\":\"assistant\",\"content\":[{\"type\":\"thinking\",\"thinking\":\"\",\"signature\":\"s\"}]}]", JsonArray.class);
		a.rawKey = "claude-opus-5-5";
		first.messages.add(a);
		Chat second = new Chat("Named");
		second.namedByPlayer = true;

		String json = ChatStore.toJson(gson, List.of(first, second), second);
		ChatStore.Loaded loaded = ChatStore.fromJson(gson, json);

		assertEquals(2, loaded.chats.size());
		assertSame("the chat that was open", loaded.chats.get(1), loaded.current);
		Chat back = loaded.chats.get(0);
		assertEquals(first.id, back.id);
		assertEquals("Agility", back.name);
		assertFalse(back.defaultName);
		assertTrue(loaded.chats.get(1).namedByPlayer);
		assertEquals(2, back.messages.size());
		assertEquals(Chat.Role.USER, back.messages.get(0).role);
		assertEquals(q.time, back.messages.get(0).time);
		assertEquals("[Character: Zezima, combat level 3]", back.messages.get(0).context);
		assertEquals("Claude", back.messages.get(1).who);
		// Claude's replayable reasoning isn't saved; the chat carries on as plain text.
		assertNull(back.messages.get(1).rawMessages);
		assertNull(back.messages.get(1).rawKey);
		assertFalse(json.contains("signature"));
	}

	@Test
	public void anUnfinishedReplyStaysUnfinished()
	{
		Chat c = new Chat("x");
		Chat.Message q = new Chat.Message(Chat.Role.USER, "q");
		q.unanswered = true;
		c.messages.add(q);
		Chat.Message partial = new Chat.Message(Chat.Role.ASSISTANT, "Half a");
		partial.unfinished = true;
		c.messages.add(partial);
		c.messages.add(new Chat.Message(Chat.Role.NOTE, "Stopped."));
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertTrue(back.messages.get(1).unfinished);
		assertTrue("never sent", ConversationBuilder.history(back).isEmpty());
		assertSame(back.messages.get(0), RequestRunner.retryable(back));
	}

	@Test
	public void aQuestionWithoutAnAnswerIsMarkedSo()
	{
		Chat c = new Chat("x");
		c.messages.add(new Chat.Message(Chat.Role.USER, "still waiting when RuneLite closed"));
		c.pending = new ChatApi.Pending();
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertTrue(back.messages.get(0).unanswered);
		assertFalse(back.isRunning());
	}

	@Test
	public void aQuestionSummarisedBecauseTheChatWasTooLongCanBeRetried()
	{
		// RuneLite closed while a chat too long for the model was being summarised before the question went again.
		Chat c = new Chat("x");
		c.messages.add(new Chat.Message(Chat.Role.USER, "q1"));
		c.messages.add(new Chat.Message(Chat.Role.ASSISTANT, "a1"));
		Chat.Message q = new Chat.Message(Chat.Role.USER, "q2");
		c.messages.add(q);
		c.messages.add(new Chat.Message(Chat.Role.NOTE, "This chat was too long for claude-opus-5-5, so the earlier "
			+ "messages are summarised first and the question is sent again."));
		c.pending = new ChatApi.Pending();
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertTrue(back.messages.get(2).unanswered);
		assertSame(back.messages.get(2), RequestRunner.retryable(back));
	}

	@Test
	public void longChatsKeepTheirLatestMessagesAndSaySo()
	{
		Chat c = new Chat("long");
		c.summary = "The player is training Agility.";
		for (int i = 0; i < 250; i++)
		{
			Chat.Message m = new Chat.Message(i % 2 == 0 ? Chat.Role.USER : Chat.Role.ASSISTANT, "m" + i);
			m.summarized = i < 150;
			c.messages.add(m);
		}
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertEquals(ChatStore.MAX_MESSAGES + 1, back.messages.size());
		assertEquals("m50", back.messages.get(1).text);
		assertEquals("m249", back.messages.get(back.messages.size() - 1).text);
		Chat.Message note = back.messages.get(0);
		assertEquals(Chat.Role.NOTE, note.role);
		assertSame(note, back.leftOutNote);
		assertEquals("The 50 oldest messages of this chat weren't kept when it was saved (AI Chat saves the latest 200 "
			+ "of each chat). None of them were being sent to the assistant any more: the summary covers them.", note.text);
		assertEquals("sent as before", 100, ConversationBuilder.history(back).size());

		// Saved again: one note, for every message left out so far.
		back.messages.add(new Chat.Message(Chat.Role.NOTE, "Stopped."));
		Chat again = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(back), back)).chats.get(0);
		assertEquals(51, again.leftOut);
		assertEquals(51, again.leftOutSummarized);
		assertEquals(ChatStore.MAX_MESSAGES + 1, again.messages.size());
		assertTrue(again.messages.get(0).text.startsWith("The 51 oldest messages"));

		// The next summary still counts them.
		List<Chat.Message> old = new ArrayList<>(ConversationBuilder.history(again).subList(0, 2));
		Chat.Message summary = ConversationBuilder.applySummary(again, old, "Still Agility.", null);
		assertTrue(summary.text, summary.text.startsWith("Summary of the 152 earlier messages"));
	}

	@Test
	public void messagesStillSentAreAlwaysKept()
	{
		// A chat whose summaries kept failing: everything is still sent, so everything is kept.
		Chat c = new Chat("long");
		for (int i = 0; i < 250; i++)
		{
			c.messages.add(new Chat.Message(i % 2 == 0 ? Chat.Role.USER : Chat.Role.ASSISTANT, "m" + i));
		}
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertEquals(250, back.messages.size());
		assertEquals("m0", back.messages.get(0).text);
		assertNull(back.leftOutNote);

		// Old notes and errors go first, up to the first message still sent.
		Chat noisy = new Chat("noisy");
		for (int i = 0; i < 30; i++)
		{
			noisy.messages.add(new Chat.Message(Chat.Role.ERROR, "e" + i));
		}
		noisy.messages.addAll(c.messages.subList(0, 190));
		back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(noisy), noisy)).chats.get(0);
		assertEquals(ChatStore.MAX_MESSAGES + 1, back.messages.size());
		assertEquals("e20", back.messages.get(1).text);
		assertTrue(back.messages.get(0).text, back.messages.get(0).text.endsWith("None of them were being sent to the assistant any more."));
	}

	@Test
	public void aDamagedFileIsReportedAndOddEntriesAreSkipped()
	{
		// Damaged: reported as such (the plugin moves the file aside rather than writing over it).
		assertNull(ChatStore.fromJson(gson, "not json {"));
		assertNull(ChatStore.fromJson(gson, ""));
		assertNull(ChatStore.fromJson(gson, "{\"something\":\"else\"}"));
		ChatStore.Loaded odd = ChatStore.fromJson(gson,
			"{\"chats\":[{\"id\":\"1\",\"name\":\"ok\",\"messages\":[{\"role\":\"WHAT\",\"text\":\"skipped\"},{\"role\":\"NOTE\",\"text\":\"kept\"}]},{\"name\":\"no id\"}]}");
		assertEquals(1, odd.chats.size());
		assertEquals(1, odd.chats.get(0).messages.size());
		assertEquals("kept", odd.chats.get(0).messages.get(0).text);
		assertNull(odd.current);
	}

	@Test
	public void summariesAreRemembered()
	{
		Chat c = new Chat("long");
		Chat.Message q1 = new Chat.Message(Chat.Role.USER, "Q1");
		q1.summarized = true;
		c.messages.add(q1);
		Chat.Message a1 = new Chat.Message(Chat.Role.ASSISTANT, "A1");
		a1.summarized = true;
		c.messages.add(a1);
		c.messages.add(new Chat.Message(Chat.Role.NOTE, "Summary of the 2 earlier messages, sent instead of them:\n\nS"));
		c.messages.add(new Chat.Message(Chat.Role.USER, "Q2"));
		c.messages.add(new Chat.Message(Chat.Role.ASSISTANT, "A2"));
		c.summary = "S";
		c.summaryVersion = 3;

		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertEquals("S", back.summary);
		assertEquals(3, back.summaryVersion);
		assertEquals(5, back.messages.size());
		assertTrue(back.messages.get(0).summarized);
		assertTrue(back.messages.get(1).summarized);
		assertFalse(back.messages.get(3).summarized);
		assertFalse(back.messages.get(4).summarized);
		// Sent as before: the summary, then what it doesn't cover.
		List<ChatApi.Turn> turns = ConversationBuilder.conversation(back, back.messages.get(3), "m", "s", false, null).turns;
		assertEquals(2, turns.size());
		assertEquals("[Summary of earlier messages in this chat: S]\n\nQ2", turns.get(0).text);
	}

	@Test
	public void filesFromBeforeSummariesStillLoad()
	{
		// As AI Chat 0.1 wrote it.
		String old = "{\"version\":1,\"current\":\"a\",\"chats\":[{\"id\":\"a\",\"name\":\"Old\",\"defaultName\":false,"
			+ "\"namedByPlayer\":false,\"messages\":[{\"role\":\"USER\",\"text\":\"hi\",\"time\":1,\"unanswered\":false},"
			+ "{\"role\":\"ASSISTANT\",\"text\":\"hello\",\"time\":2,\"who\":\"Claude\",\"unanswered\":false}]}]}";
		ChatStore.Loaded loaded = ChatStore.fromJson(gson, old);
		Chat back = loaded.chats.get(0);
		assertSame(back, loaded.current);
		assertNull(back.summary);
		assertEquals(0, back.summaryVersion);
		assertEquals(2, back.messages.size());
		assertFalse(back.messages.get(0).summarized);
		assertEquals(2, ConversationBuilder.history(back).size());
		// Nor what was looked up.
		assertNull(back.messages.get(1).activity);
	}

	@Test
	public void lookUpsAreRemembered()
	{
		Chat c = new Chat("Vorkath");
		c.messages.add(new Chat.Message(Chat.Role.USER, "Vorkath's weaknesses?"));
		Chat.Message a = new Chat.Message(Chat.Role.ASSISTANT, "Stab and dragonbane.");
		a.who = "Claude";
		a.activity = new ArrayList<>(List.of("Searched the Wiki for \"vorkath\"", "Read the Wiki page \"Vorkath\""));
		c.messages.add(a);
		Chat.Message stopped = new Chat.Message(Chat.Role.NOTE, "Stopped.");
		stopped.activity = new ArrayList<>();
		c.messages.add(stopped);

		String json = ChatStore.toJson(gson, List.of(c), c);
		Chat.Message back = ChatStore.fromJson(gson, json).chats.get(0).messages.get(1);
		assertEquals(a.activity, back.activity);
		// Nothing looked up: nothing saved.
		assertNull(ChatStore.fromJson(gson, json).chats.get(0).messages.get(2).activity);
	}

	@Test
	public void filesWithTokenCountsStillLoad()
	{
		// As AI Chat wrote it while it kept each reply's tokens: they're skipped, and not written again.
		String old = "{\"version\":1,\"current\":\"a\",\"chats\":[{\"id\":\"a\",\"name\":\"Vorkath\",\"messages\":["
			+ "{\"role\":\"USER\",\"text\":\"Vorkath's weaknesses?\",\"time\":1},"
			+ "{\"role\":\"ASSISTANT\",\"text\":\"Stab and dragonbane.\",\"time\":2,\"who\":\"Claude\","
			+ "\"activity\":[\"Read the Wiki page \\\"Vorkath\\\"\"],\"usage\":{\"input\":1204,\"cacheRead\":3410,"
			+ "\"cacheWrite\":12,\"output\":352,\"incomplete\":false,\"model\":\"claude-opus-5-5\"}},"
			+ "{\"role\":\"NOTE\",\"text\":\"Stopped.\",\"time\":3,\"usage\":{\"input\":0,\"cacheRead\":0,"
			+ "\"cacheWrite\":0,\"output\":0,\"incomplete\":true}}]}]}";
		ChatStore.Loaded loaded = ChatStore.fromJson(gson, old);
		Chat back = loaded.chats.get(0);
		assertSame(back, loaded.current);
		assertEquals(3, back.messages.size());
		Chat.Message reply = back.messages.get(1);
		assertEquals("Stab and dragonbane.", reply.text);
		assertEquals("Claude", reply.who);
		assertEquals(List.of("Read the Wiki page \"Vorkath\""), reply.activity);
		assertEquals("Stopped.", back.messages.get(2).text);
		assertFalse(ChatStore.toJson(gson, loaded.chats, back).contains("usage"));
	}

	@Test
	public void oddLookUpsInAFileAreTidied()
	{
		ChatStore.Loaded loaded = ChatStore.fromJson(gson, "{\"chats\":[{\"id\":\"a\",\"name\":\"x\",\"messages\":["
			+ "{\"role\":\"ASSISTANT\",\"text\":\"a\",\"activity\":[\"\",null,\"Shared your bank\"]}]}]}");
		assertEquals(List.of("Shared your bank"), loaded.chats.get(0).messages.get(0).activity);
	}

	@Test
	public void summarisedMessagesWithoutTheirSummaryAreSentAgain()
	{
		// Not something AI Chat writes, but a hand-edited file shouldn't make messages disappear from the conversation.
		ChatStore.Loaded loaded = ChatStore.fromJson(gson, "{\"chats\":[{\"id\":\"a\",\"name\":\"x\",\"summary\":\" \","
			+ "\"messages\":[{\"role\":\"USER\",\"text\":\"Q1\",\"summarized\":true},{\"role\":\"ASSISTANT\",\"text\":\"A1\",\"summarized\":true}]}]}");
		Chat back = loaded.chats.get(0);
		assertNull(back.summary);
		assertFalse(back.messages.get(0).summarized);
		assertEquals(2, ConversationBuilder.history(back).size());
	}
}

package com.aichat;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The provider's model list: which models the picker offers, what Test says about the model that's set, and the
 * picker's tooltip.
 */
public class ConnectionCheckTest
{
	private static final String SETUP = ConnectionCheck.setupKey(AiChatConfig.Provider.CLAUDE, null, "sk-ant-1");

	@Test
	public void onlyChatModelsAreOffered()
	{
		List<String> ids = Arrays.asList("gpt-6-luna", "text-embedding-3-small", "tts-1-hd", "whisper-1", "dall-e-3",
			"omni-moderation-latest", "gpt-image-1", "gpt-4o-audio-preview", "gpt-4o-transcribe", "gpt-realtime",
			"gpt-4o-search-preview", "nomic-embed-text", "GPT-6.1-sol", "gpt-6-luna", "", null);
		assertEquals(Arrays.asList("gpt-6-luna", "GPT-6.1-sol"), ConnectionCheck.chatModels(ids, true));
		// Anthropic's own order (newest first) is kept.
		assertEquals(Arrays.asList("claude-opus-5-5", "claude-haiku-4-5"),
			ConnectionCheck.chatModels(Arrays.asList("claude-opus-5-5", "claude-haiku-4-5"), false));
	}

	@Test
	public void theResultIsReadAgainstTheModelSetNow()
	{
		ConnectionCheck check = ConnectionCheck.listed(SETUP, Arrays.asList("claude-opus-5-5", "claude-haiku-4-5"), false);

		ConnectionCheck.Note ok = check.note("Anthropic", "claude-opus-5-5", true, false);
		assertEquals(ConnectionCheck.Kind.OK, ok.kind);
		assertEquals("Connected to Anthropic. claude-opus-5-5 is available.", ok.text);

		ConnectionCheck.Note missing = check.note("Anthropic", "claude-opus-9", true, false);
		assertEquals(ConnectionCheck.Kind.WARNING, missing.kind);
		assertEquals("Connected, but claude-opus-9 isn't in the list your key can use. Pick another next to Send.",
			missing.text);
	}

	@Test
	public void compatibleServicesNameTheirModelsTheirOwnWay()
	{
		ConnectionCheck check = ConnectionCheck.listed(SETUP, Arrays.asList("llama3.2:latest", "qwen3:8b"), true);
		assertEquals(ConnectionCheck.Kind.OK, check.note("localhost:11434", "llama3.2", false, false).kind);
		assertEquals("Connected to localhost:11434, but qwen3 isn't one of its models. Pick another next to Send.",
			check.note("localhost:11434", "qwen3", false, false).text);
		assertEquals("Connected to localhost:11434, but it listed no models to chat with.",
			ConnectionCheck.listed(SETUP, Arrays.asList("nomic-embed-text"), true).note("localhost:11434", "x", false, false).text);
	}

	@Test
	public void problemsAndServicesWithoutAList()
	{
		ConnectionCheck.Note testing = ConnectionCheck.testing(SETUP).note("Anthropic", "claude-opus-5-5", true, false);
		assertEquals(ConnectionCheck.Kind.TESTING, testing.kind);
		assertEquals("Testing the connection\u2026", testing.text);

		String bad = "Anthropic didn't accept your API key. Check the API key in the Claude section of the AI Chat settings.";
		ConnectionCheck.Note error = ConnectionCheck.failed(SETUP, bad).note("Anthropic", "claude-opus-5-5", true, false);
		assertEquals(ConnectionCheck.Kind.ERROR, error.kind);
		assertEquals(bad, error.text);

		// Any web server can say "not found": that's no sign the URL is right.
		ConnectionCheck.Note noList = ConnectionCheck.failed(SETUP, OpenAiApi.NO_MODEL_LIST).note("localhost:11434", "m", false, false);
		assertEquals(ConnectionCheck.Kind.WARNING, noList.kind);
		assertEquals("localhost:11434 answered, but not with a list of models, so Test can't check the URL or the model "
			+ "name. Check both on the service's website.", noList.text);
		// Without a model set, it still says where one goes.
		ConnectionCheck.Note noListNoModel = ConnectionCheck.failed(SETUP, OpenAiApi.NO_MODEL_LIST).note("localhost:11434", " ", false, false);
		assertEquals(ConnectionCheck.Kind.WARNING, noListNoModel.kind);
		assertEquals("localhost:11434 answered, but not with a list of models, so Test can't check the URL or offer a "
			+ "model. Type the model's name next to Send, as the service's website gives it.", noListNoModel.text);
	}

	@Test
	public void aListAnyoneCanReadVouchesForNoKey()
	{
		// OpenRouter lists its models without looking at the key: a green note mustn't suggest the key was checked.
		ConnectionCheck check = ConnectionCheck.listed(SETUP, Arrays.asList("openai/gpt-6-luna", "qwen/qwen3-32b"), true);
		ConnectionCheck.Note listed = check.note("openrouter.ai", "qwen/qwen3-32b", false, true);
		assertEquals(ConnectionCheck.Kind.OK, listed.kind);
		assertEquals("Connected to openrouter.ai. qwen/qwen3-32b is available. Your key is checked when you send: some "
			+ "services list their models for anyone.", listed.text);
		assertEquals("Connected to openrouter.ai. Your key is checked when you send: some services list their models for "
			+ "anyone. Pick a model next to Send.", check.note("openrouter.ai", "", false, true).text);
		// Without a key there's nothing to say about one.
		assertEquals("Connected to openrouter.ai. qwen/qwen3-32b is available.", check.note("openrouter.ai", "qwen/qwen3-32b", false, false).text);
	}

	@Test
	public void withoutAModelTheListIsOffered()
	{
		ConnectionCheck check = ConnectionCheck.listed(SETUP, Arrays.asList("llama3.2:latest", "qwen3:8b"), true);
		ConnectionCheck.Note note = check.note("localhost:11434", "", false, false);
		assertEquals(ConnectionCheck.Kind.OK, note.kind);
		assertEquals("Connected to localhost:11434. Pick a model next to Send.", note.text);
		assertEquals(Arrays.asList("llama3.2:latest", "qwen3:8b"), ConnectionCheck.choices("", check.models));
	}

	@Test
	public void thePickerOffersTheModelThatsSetAndTheListOnce()
	{
		List<String> claude = Arrays.asList("claude-opus-5-5", "claude-haiku-4-5-20251001", "claude-sonnet-5-5");
		// Set and listed: in its place in the list, by the name it's set as, never twice.
		assertEquals(Arrays.asList("claude-opus-5-5", "claude-haiku-4-5", "claude-sonnet-5-5"),
			ConnectionCheck.choices("claude-haiku-4-5", claude));
		assertEquals(claude, ConnectionCheck.choices(" claude-opus-5-5 ", claude));
		assertEquals(Arrays.asList("llama3.2", "qwen3:8b"),
			ConnectionCheck.choices("llama3.2", Arrays.asList("llama3.2:latest", "qwen3:8b")));
		// Set but not listed (or no list at all): still there, first.
		assertEquals(Arrays.asList("my-fine-tune", "claude-opus-5-5", "claude-haiku-4-5-20251001", "claude-sonnet-5-5"),
			ConnectionCheck.choices("my-fine-tune", claude));
		assertEquals(Arrays.asList("claude-opus-5-5"), ConnectionCheck.choices("claude-opus-5-5", null));
		assertTrue(ConnectionCheck.choices(null, null).isEmpty());
	}

	@Test
	public void aModelIsFoundByTheNameTheProviderListsItUnder()
	{
		assertTrue(ConnectionCheck.sameModel("llama3.2", "llama3.2"));
		assertTrue(ConnectionCheck.sameModel("llama3.2:latest", "llama3.2"));
		assertFalse("another tag", ConnectionCheck.sameModel("llama3.2:1b", "llama3.2"));
		assertFalse(ConnectionCheck.sameModel("qwen3:8b:latest", "qwen3:8b"));
		assertTrue(ConnectionCheck.sameModel("claude-haiku-4-5-20251001", "claude-haiku-4-5"));
		assertFalse("not the other way round", ConnectionCheck.sameModel("claude-haiku-4-5", "claude-haiku-4-5-20251001"));
		assertFalse(ConnectionCheck.sameModel("claude-haiku-4-5-2025100", "claude-haiku-4-5"));
	}

	@Test
	public void thePickersTooltipSaysWhyItsListIsShort()
	{
