	@Test
	public void anAliasIsFoundAsTheDatedModelItPointsTo()
	{
		// Anthropic lists claude-haiku-4-5 only by its full name.
		ConnectionCheck check = ConnectionCheck.listed(SETUP, Arrays.asList("claude-opus-5-5", "claude-haiku-4-5-20251001"), false);
		ConnectionCheck.Note note = check.note("Anthropic", "claude-haiku-4-5", true, false);
		assertEquals(ConnectionCheck.Kind.OK, note.kind);
		assertEquals("Connected to Anthropic. claude-haiku-4-5 is available.", note.text);
		// Only a date: another model that starts the same way isn't it.
		assertEquals(ConnectionCheck.Kind.WARNING, ConnectionCheck.listed(SETUP, Arrays.asList("claude-haiku-4-5-latest-x",
			"claude-haiku-4-5-2025100"), false).note("Anthropic", "claude-haiku-4-5", true, false).kind);
	}

	@Test
	public void aResultBelongsToItsProviderAddressAndKey()
	{
		String claude = ConnectionCheck.setupKey(AiChatConfig.Provider.CLAUDE, null, "sk-ant-1");
		assertEquals(SETUP, claude);
		assertNotEquals(claude, ConnectionCheck.setupKey(AiChatConfig.Provider.CLAUDE, null, "sk-ant-2"));
		assertNotEquals(claude, ConnectionCheck.setupKey(AiChatConfig.Provider.CHATGPT, null, "sk-ant-1"));
		assertNotEquals(ConnectionCheck.setupKey(AiChatConfig.Provider.OPENAI_COMPATIBLE, "http://localhost:11434/v1", ""),
			ConnectionCheck.setupKey(AiChatConfig.Provider.OPENAI_COMPATIBLE, "http://localhost:1234/v1", ""));
		// The key itself isn't kept.
		assertTrue(!claude.contains("sk-ant-1"));
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Asking for the model list, by "Test connection" or quietly for the model picker: only the answer to the latest request
 * counts, a stopped one says nothing, a result belongs to the setup it was made with, and the picker asks once per
 * setup and never while the provider can't be reached. The provider is a stand-in that answers when the test says so.
 */
public class ConnectionTesterTest
{
	private static final String SETUP = ConnectionCheck.setupKey(AiChatConfig.Provider.CLAUDE, null, "sk-ant-1");
	/** Stands in for the EDT: tasks wait here until the test runs them, as invokeLater's do. */
	private final BlockingQueue<Runnable> edt = new LinkedBlockingQueue<>();
	private int changes;
	private final ConnectionTester tester = new ConnectionTester(edt::add, () -> changes++);
	private final FakeApi api = new FakeApi();

	/** A provider that keeps every model list request, and answers only when the test calls its listener. */
	private static final class FakeApi implements ChatApi
	{
		final List<ModelsListener> listeners = new ArrayList<>();
		final List<Pending> requests = new ArrayList<>();
		RuntimeException failure;

		@Override
		public Pending send(Conversation conversation, Listener listener)
		{
			throw new AssertionError("Test sends no messages");
		}

		@Override
		public String displayName()
		{
			return "Claude";
		}

		@Override
		public Pending listModels(ModelsListener listener)
		{
			if (failure != null)
			{
				throw failure;
			}
			listeners.add(listener);
			Pending p = new Pending();
			requests.add(p);
			return p;
		}
	}

	private void runEdt()
	{
		Runnable r;
		while ((r = edt.poll()) != null)
		{
			r.run();
		}
	}

	private ConnectionCheck.Note note()
	{
		return tester.note(SETUP, "Anthropic", "claude-opus-5-5", true, false);
	}

	@Test
	public void aTestShowsWhatTheProviderListed()
	{
		assertNull("nothing yet", note());
		tester.start(api, SETUP, false);
		assertEquals(ConnectionCheck.Kind.TESTING, note().kind);

		api.listeners.get(0).onModels(List.of("claude-opus-5-5", "claude-haiku-4-5"));
		assertEquals("not until the EDT runs it", ConnectionCheck.Kind.TESTING, note().kind);
		runEdt();
		assertEquals(ConnectionCheck.Kind.OK, note().kind);
		assertEquals(List.of("claude-opus-5-5", "claude-haiku-4-5"), tester.check(SETUP).models);
		assertEquals(1, changes);
	}

	@Test
	public void onlyTheLatestTestCounts()
	{
		tester.start(api, SETUP, false);
		ChatApi.ModelsListener first = api.listeners.get(0);
		tester.start(api, SETUP, false);
		assertTrue("the first one is stopped", api.requests.get(0).isCancelled());

		first.onModels(List.of("claude-opus-5-5"));
		runEdt();
		assertEquals(ConnectionCheck.Kind.TESTING, note().kind);
		assertEquals(0, changes);

		api.listeners.get(1).onError("Anthropic didn't accept your API key. Check the API key in the Claude section of the AI Chat "
			+ "settings.");
		runEdt();
		assertEquals(ConnectionCheck.Kind.ERROR, note().kind);
		assertEquals(1, changes);
	}

	@Test
	public void aStoppedTestSaysNothing()
	{
		tester.start(api, SETUP, false);
		tester.stop();
		assertTrue(api.requests.get(0).isCancelled());
		assertNull(note());
		api.listeners.get(0).onModels(List.of("claude-opus-5-5"));
		runEdt();
		assertNull(note());
		assertEquals(0, changes);
	}

	@Test
	public void aResultBelongsToTheSetupItWasMadeWith()
	{
		tester.start(api, SETUP, false);
		api.listeners.get(0).onModels(List.of("claude-opus-5-5"));
		runEdt();
		String otherKey = ConnectionCheck.setupKey(AiChatConfig.Provider.CLAUDE, null, "sk-ant-2");
		assertNull(tester.note(otherKey, "Anthropic", "claude-opus-5-5", true, false));
		// Another model is fine: the list is read against it.
		assertEquals(ConnectionCheck.Kind.WARNING, tester.note(SETUP, "Anthropic", "claude-opus-9", true, false).kind);
	}

	@Test
	public void aTestThatCantBeSentSaysSoWithoutTheKey()
	{
		api.failure = new IllegalArgumentException("Unexpected char in header value: sk-ant-secret");
		tester.start(api, SETUP, false);
		ConnectionCheck.Note note = note();
		assertEquals(ConnectionCheck.Kind.ERROR, note.kind);
		assertEquals(RequestRunner.COULDNT_SEND, note.text);
		assertFalse(note.text.contains("sk-ant"));
	}

	@Test
	public void thePickersListIsAskedForQuietlyOncePerSetup()
	{
		assertTrue(tester.list(null, SETUP, () -> api, false));
		assertEquals(1, api.listeners.size());
		assertNull("the banner stays quiet", note());
		assertEquals(ConnectionCheck.Kind.TESTING, tester.check(SETUP).note("Anthropic", "m", true, false).kind);
		assertFalse("not again while it's asking", tester.list(null, SETUP, () -> api, false));

		api.listeners.get(0).onModels(List.of("claude-opus-5-5"));
		runEdt();
		assertEquals(1, changes);
		assertEquals(List.of("claude-opus-5-5"), tester.check(SETUP).models);
		assertNull(note());
		assertFalse("nor once it has the list", tester.list(null, SETUP, () -> api, false));
		assertEquals(1, api.listeners.size());

		// Another key: its own list. And back: asked again, since that's a change too.
		String other = ConnectionCheck.setupKey(AiChatConfig.Provider.CLAUDE, null, "sk-ant-2");
		assertNull(tester.check(other));
		assertTrue(tester.list(null, other, () -> api, false));
		assertTrue(tester.list(null, SETUP, () -> api, false));
		assertEquals(3, api.listeners.size());
		assertTrue("the one before is stopped", api.requests.get(1).isCancelled());
	}

	@Test
	public void refreshListAsksAgainButNeverWhileTheProviderCantBeReached()
	{
		tester.list(null, SETUP, () -> api, false);
		api.listeners.get(0).onModels(List.of("claude-opus-5-5"));
		runEdt();
		assertFalse("the picker has its list", tester.list(null, SETUP, () -> api, false));

		// The player asks for it again: asked, quietly.
		assertTrue(tester.refresh(null, SETUP, () -> api, false));
		assertEquals(2, api.listeners.size());
		assertNull("the banner stays quiet", note());
		// Asked again before that came back: the first answer is stale, and doesn't count.
		assertTrue(tester.refresh(null, SETUP, () -> api, false));
		assertTrue(api.requests.get(1).isCancelled());
		api.listeners.get(1).onModels(List.of("old-model"));
		api.listeners.get(2).onModels(List.of("claude-opus-5-5", "claude-sonnet-5-5"));
		runEdt();
		assertEquals(List.of("claude-opus-5-5", "claude-sonnet-5-5"), tester.check(SETUP).models);

		// AI requests off: nothing is asked, and no API is even made.
		String off = "Turn on \"Enable AI requests\" in the AI Chat settings, then choose a provider and add your API key.";
		assertFalse(tester.refresh(off, SETUP, () ->
		{
			throw new AssertionError("no API is even made");
		}, false));
		assertEquals(3, api.listeners.size());
	}

	@Test
	public void refreshListLeavesATestThatsStillAskingAlone()
	{
		tester.start(api, SETUP, false);
		// Refresh list before the Test's answer: the Test isn't stopped, and its answer is the list.
		assertFalse(tester.refresh(null, SETUP, () -> api, false));
		assertEquals(1, api.listeners.size());
		assertFalse(api.requests.get(0).isCancelled());
		assertEquals(ConnectionCheck.Kind.TESTING, note().kind);
		api.listeners.get(0).onModels(List.of("claude-opus-5-5", "claude-haiku-4-5"));
		runEdt();
		assertEquals("the banner says what the Test found", ConnectionCheck.Kind.OK, note().kind);
		assertEquals(List.of("claude-opus-5-5", "claude-haiku-4-5"), tester.check(SETUP).models);

		// Once it's answered, Refresh list asks again, quietly, as ever.
		assertTrue(tester.refresh(null, SETUP, () -> api, false));
		assertEquals(2, api.listeners.size());
		// A Test whose banner was closed while it was asking is asked again too.
		tester.start(api, SETUP, false);
		tester.dismiss();
		assertTrue(tester.refresh(null, SETUP, () -> api, false));
		assertTrue(api.requests.get(2).isCancelled());
	}

	@Test
	public void testAsksAgainAndTheBannerCanBeClosed()
	{
		tester.list(null, SETUP, () -> api, false);
		api.listeners.get(0).onModels(List.of("claude-opus-5-5"));
		runEdt();

		tester.start(api, SETUP, false);
		assertEquals(2, api.listeners.size());
		api.listeners.get(1).onModels(List.of("claude-opus-5-5", "claude-haiku-4-5"));
		runEdt();
		assertEquals(ConnectionCheck.Kind.OK, note().kind);

		// Closed: the banner has nothing to say, but the picker keeps the list.
		tester.dismiss();
		assertNull(note());
		assertEquals(List.of("claude-opus-5-5", "claude-haiku-4-5"), tester.check(SETUP).models);
	}

	@Test
	public void nothingIsAskedWhileTheProviderCantBeReached()
	{
		String off = "Turn on \"Enable AI requests\" in the AI Chat settings, then choose a provider and add your API key.";
		assertFalse(tester.list(off, SETUP, () ->
		{
			throw new AssertionError("no API is even made");
		}, false));
		assertTrue(api.listeners.isEmpty());
		assertNull(tester.check(SETUP));

		// Turned off after a list came in: forgotten, and asked for again once it's back on.
		tester.list(null, SETUP, () -> api, false);
		api.listeners.get(0).onModels(List.of("claude-opus-5-5"));
		runEdt();
		tester.stop();
		assertNull(tester.check(SETUP));
		assertTrue(tester.list(null, SETUP, () -> api, false));
		assertEquals(2, api.listeners.size());
	}

	@Test
	public void goodNewsGoesWithTheNextMessageButProblemsStay()
	{
		tester.start(api, SETUP, false);
		assertFalse("still testing", tester.sent(SETUP, "Anthropic", "claude-opus-5-5", true, false));
		assertEquals(ConnectionCheck.Kind.TESTING, note().kind);
		api.listeners.get(0).onModels(List.of("claude-haiku-4-5"));
		runEdt();
		// The model that's set isn't listed: a warning, which stays.
		assertFalse(tester.sent(SETUP, "Anthropic", "claude-opus-5-5", true, false));
		assertEquals(ConnectionCheck.Kind.WARNING, note().kind);
		// Read against the model now set, it's good news: gone once a message goes.
		assertTrue(tester.sent(SETUP, "Anthropic", "claude-haiku-4-5", true, false));
		assertNull(tester.note(SETUP, "Anthropic", "claude-haiku-4-5", true, false));
		assertEquals("the picker keeps the list", List.of("claude-haiku-4-5"), tester.check(SETUP).models);
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** What a chat sends: the messages, character notes, replayed replies, and the summary of a long chat's oldest messages. */
public class ConversationBuilderTest
{
	private static final JsonArray RAW = new Gson().fromJson("[{\"role\":\"assistant\",\"content\":["
		+ "{\"type\":\"thinking\",\"thinking\":\"\",\"signature\":\"s\"},{\"type\":\"text\",\"text\":\"A1\"}]}]", JsonArray.class);

	private static Chat.Message add(Chat chat, Chat.Role role, String text)
	{
		Chat.Message m = new Chat.Message(role, text);
		chat.messages.add(m);
		return m;
	}

	private static Chat.Message user(Chat chat, String text)
	{
		return add(chat, Chat.Role.USER, text);
	}

	private static Chat.Message reply(Chat chat, String text)
	{
		Chat.Message m = add(chat, Chat.Role.ASSISTANT, text);
		m.who = "Claude";
		return m;
	}

	/** {@code pairs} questions and answers: Q1, A1, Q2, A2... */
	private static Chat chatOf(int pairs)
	{
		Chat chat = new Chat("long");
		for (int i = 1; i <= pairs; i++)
		{
			user(chat, "Q" + i);
			reply(chat, "A" + i);
		}
		return chat;
	}

	private static ChatApi.Conversation send(Chat chat, Chat.Message message, boolean shareCharacter, String context)
	{
		return ConversationBuilder.conversation(chat, message, "claude-opus-5-5", "Be brief.", shareCharacter, context);
	}

	private static List<String> texts(ChatApi.Conversation c)
	{
		List<String> texts = new ArrayList<>();
		for (ChatApi.Turn t : c.turns)
		{
			texts.add((t.user ? "user: " : "assistant: ") + t.text);
		}
		return texts;
	}

	@Test
	public void onlyAnsweredQuestionsAndRepliesAreSent()
	{
		Chat chat = new Chat("x");
		// A reply with no question before it (the question was cleared away) can't start a conversation.
		reply(chat, "orphan");
		user(chat, "Q1");
		reply(chat, "A1");
		user(chat, "Q2").unanswered = true;
		add(chat, Chat.Role.NOTE, "Stopped.");
		add(chat, Chat.Role.ERROR, "Anthropic is overloaded.");
		Chat.Message q3 = user(chat, "Q3");

		ChatApi.Conversation c = send(chat, q3, false, null);
		assertEquals("claude-opus-5-5", c.model);
		assertEquals("Be brief.", c.system);
		assertEquals(List.of("user: Q1", "assistant: A1", "user: Q3"), texts(c));
		assertTrue(c.tools.isEmpty());
		assertEquals(0, c.maxTokens);
	}

	@Test
	public void theCharacterNoteGoesOnlyWhenItChanged()
	{
		Chat chat = new Chat("x");
		Chat.Message q1 = user(chat, "Q1");
		assertEquals(List.of("user: [C1]\n\nQ1"), texts(send(chat, q1, true, "[C1]")));
		assertEquals("[C1]", q1.context);
		reply(chat, "A1");

		// The same details again: the provider has them already.
		Chat.Message q2 = user(chat, "Q2");
		assertEquals(List.of("user: [C1]\n\nQ1", "assistant: A1", "user: Q2"), texts(send(chat, q2, true, "[C1]")));
		assertNull(q2.context);
		reply(chat, "A2");

		// Changed (a level up): sent again.
		Chat.Message q3 = user(chat, "Q3");
		send(chat, q3, true, "[C2]");
		assertEquals("[C2]", q3.context);
		reply(chat, "A3");

		// Not readable this time (logged out): nothing goes with it.
		Chat.Message q4 = user(chat, "Q4");
		send(chat, q4, true, null);
		assertNull(q4.context);
	}

	@Test
	public void aNoteThatWasntSeenIsSentAgain()
	{
		// It went with a question that failed, so the provider never saw it.
		Chat chat = new Chat("x");
		Chat.Message q1 = user(chat, "Q1");
		q1.context = "[C1]";
		q1.unanswered = true;
		Chat.Message q2 = user(chat, "Q2");
		assertEquals(List.of("user: [C1]\n\nQ2"), texts(send(chat, q2, true, "[C1]")));

		// It went with a message the summary now covers.
		reply(chat, "A2");
		q2.summarized = true;
		chat.messages.get(chat.messages.size() - 1).summarized = true;
		chat.summary = "Talked about Agility.";
		Chat.Message q3 = user(chat, "Q3");
		send(chat, q3, true, "[C1]");
		assertEquals("[C1]", q3.context);

		// A question sent again (Retry) has its note decided again too.
		reply(chat, "A3");
		Chat.Message q4 = user(chat, "Q4");
		q4.context = "[C1]";
		send(chat, q4, true, "[C1]");
		assertNull(q4.context);
	}

	@Test
	public void withSharingOffEarlierNotesStayOutAndRepliesGoAsText()
	{
		Chat chat = new Chat("x");
		Chat.Message q1 = user(chat, "Q1");
		q1.context = "[C1]";
		Chat.Message a1 = reply(chat, "A1");
		a1.rawMessages = RAW;
		a1.rawKey = "key";
		Chat.Message q2 = user(chat, "Q2");

		ChatApi.Conversation off = send(chat, q2, false, null);
		assertEquals(List.of("user: Q1", "assistant: A1", "user: Q2"), texts(off));
		assertNull("Q1 changed, so A1 can't go back as it came", off.turns.get(1).rawMessages);

		ChatApi.Conversation on = send(chat, q2, true, "[C1]");
		assertEquals(List.of("user: [C1]\n\nQ1", "assistant: A1", "user: Q2"), texts(on));
		assertSame(RAW, on.turns.get(1).rawMessages);
		assertEquals("the provider checks the key", "key", on.turns.get(1).rawKey);
	}

	@Test
	public void repliesGoBackAsTheyCameOnlyUnderTheSameSummary()
	{
		Chat chat = new Chat("x");
		Chat.Message q1 = user(chat, "Q1");
		ChatApi.Reply r = new ChatApi.Reply();
		r.text = "A1";
		r.model = "claude-opus-5-5";
		r.rawMessages = RAW;
		r.rawKey = "key";
		send(chat, q1, false, null);
		Chat.Message a1 = reply(chat, "A1");
		ConversationBuilder.recordReply(a1, q1, r);
		assertSame(RAW, a1.rawMessages);
		assertEquals("key", a1.rawKey);
		assertEquals(0, a1.summaryVersion);

		assertTrue(ConversationBuilder.replayable(chat, a1, false));
		assertFalse("character notes left out", ConversationBuilder.replayable(chat, a1, true));
		Chat.Message q2 = user(chat, "Q2");
		assertSame(RAW, send(chat, q2, false, null).turns.get(1).rawMessages);

		// A newer summary changed what came before A1.
		chat.summaryVersion = 1;
		assertFalse(ConversationBuilder.replayable(chat, a1, false));
		assertNull(send(chat, q2, false, null).turns.get(1).rawMessages);
		assertEquals("the question records the summary it went with", 1, q2.summaryVersion);

		// A reply made since then goes back as it came.
		Chat.Message a2 = reply(chat, "A2");
		ConversationBuilder.recordReply(a2, q2, r);
		assertEquals(1, a2.summaryVersion);
		Chat.Message q3 = user(chat, "Q3");
		ChatApi.Conversation c = send(chat, q3, false, null);
		assertNull(c.turns.get(1).rawMessages);
		assertSame(RAW, c.turns.get(3).rawMessages);

		// A reply built on plain-text history: everything goes as text from now on.
		ConversationBuilder.forgetRaw(chat);
		assertNull(a2.rawMessages);
		assertNull(a2.rawKey);
		assertNull(send(chat, q3, false, null).turns.get(3).rawMessages);
	}

	@Test
	public void summarisingWaitsUntilTheChatIsLong()
	{
		Chat chat = chatOf(20);
		assertEquals(ConversationBuilder.SUMMARY_HIGH, ConversationBuilder.history(chat).size());
		assertTrue(ConversationBuilder.planSummary(chat).isEmpty());

		// Messages that aren't sent don't count.
		user(chat, "never answered").unanswered = true;
		add(chat, Chat.Role.NOTE, "Stopped.");
		add(chat, Chat.Role.ERROR, "Couldn't reach Anthropic.");
		assertTrue(ConversationBuilder.planSummary(chat).isEmpty());

		// One more and it's time.
		Chat.Message q21 = user(chat, "Q21");
		List<Chat.Message> old = ConversationBuilder.planSummary(chat);
		assertEquals(24, old.size());
		assertEquals("Q1", old.get(0).text);
		assertEquals("A12", old.get(old.size() - 1).text);
		assertFalse(old.contains(q21));
		// What's left starts with the player and keeps at least the newest LOW messages.
		List<Chat.Message> history = ConversationBuilder.history(chat);
		Chat.Message firstKept = history.get(old.size());
		assertEquals("Q13", firstKept.text);
		assertTrue(history.size() - old.size() >= ConversationBuilder.SUMMARY_LOW);
	}

	@Test
	public void theCutIsAlwaysBeforeOneOfThePlayersMessages()
	{
		// Replies in a row (as an old saved chat might have) move the cut back to the nearest question.
		Chat chat = new Chat("x");
		for (int i = 1; i <= 20; i++)
		{
			user(chat, "Q" + i);
		}
		for (int i = 1; i <= 21; i++)
		{
			reply(chat, "A" + i);
		}
		user(chat, "Q21");
		List<Chat.Message> old = ConversationBuilder.planSummary(chat);
		assertEquals("Q20", ConversationBuilder.history(chat).get(old.size()).text);
		assertEquals(19, old.size());

		// No question to cut before: nothing is summarised.
		Chat replies = new Chat("y");
		user(replies, "Q1");
		for (int i = 0; i < 45; i++)
		{
			reply(replies, "A" + i);
		}
		assertTrue(ConversationBuilder.planSummary(replies).isEmpty());
	}

	@Test
	public void aSummaryIsSentInsteadOfTheOldestMessages()
	{
		Chat chat = chatOf(20);
		Chat.Message stopped = user(chat, "stopped question");
		stopped.unanswered = true;
		Chat.Message q21 = user(chat, "Q21");
		List<Chat.Message> old = ConversationBuilder.planSummary(chat);
		Chat.Message note = ConversationBuilder.applySummary(chat, old, "  The player trains Agility.  ", q21);

		assertEquals("The player trains Agility.", chat.summary);
		assertEquals(1, chat.summaryVersion);
		for (Chat.Message m : old)
		{
			assertTrue(m.text, m.summarized);
		}
		assertFalse(q21.summarized);
		assertFalse("only messages that were sent are summarised", stopped.summarized);
		// The note sits right before the question it was made for, where the player sees it, and shows the summary.
		assertSame(note, chat.messages.get(chat.messages.indexOf(q21) - 1));
		assertEquals(Chat.Role.NOTE, note.role);
		assertEquals("Summary of the 24 earlier messages, sent instead of them:\n\nThe player trains Agility.", note.text);
		int a12 = chat.messages.indexOf(old.get(old.size() - 1));
		assertEquals("Q13", chat.messages.get(a12 + 1).text);

		ChatApi.Conversation c = send(chat, q21, false, null);
		assertEquals(17, c.turns.size());
		assertEquals("[Summary of earlier messages in this chat: The player trains Agility.]\n\nQ13", c.turns.get(0).text);
		assertTrue(c.turns.get(0).user);
		assertEquals("Q21", c.turns.get(16).text);
		assertTrue(ConversationBuilder.planSummary(chat).isEmpty());
	}

	@Test
	public void aLaterSummaryCoversTheEarlierOneToo()
	{
		Chat chat = chatOf(20);
		Chat.Message q21 = user(chat, "Q21");
		ConversationBuilder.applySummary(chat, ConversationBuilder.planSummary(chat), "S1", q21);
		reply(chat, "A21");
		for (int i = 22; i <= 33; i++)
		{
			user(chat, "Q" + i);
			if (i < 33)
			{
				reply(chat, "A" + i);
			}
		}
		List<Chat.Message> old = ConversationBuilder.planSummary(chat);
		assertEquals("Q13", old.get(0).text);

		ChatApi.Conversation request = ConversationBuilder.summaryConversation(chat, old, "claude-opus-5-5");
		assertTrue(request.turns.get(0).text, request.turns.get(0).text.startsWith(
			"The summary so far:\n\nS1\n\nThe conversation since then, to add to it:\n\nPlayer: Q13\n\nAssistant: A13\n\n"));

		Chat.Message q33 = chat.messages.get(chat.messages.size() - 1);
		ConversationBuilder.applySummary(chat, old, "S2", q33);
		assertEquals(2, chat.summaryVersion);
		assertTrue(chat.messages.stream().anyMatch(m -> m.text.startsWith("Summary of the " + (24 + old.size()) + " earlier messages")));
		assertTrue(send(chat, chat.messages.get(chat.messages.size() - 1), false, null).turns.get(0).text
			.startsWith("[Summary of earlier messages in this chat: S2]\n\n"));
	}

	@Test
	public void theSummaryPrefixStaysTheSameUntilTheNextSummary()
	{
		Chat chat = chatOf(20);
		Chat.Message q21 = user(chat, "Q21");
		ConversationBuilder.applySummary(chat, ConversationBuilder.planSummary(chat), "S1", q21);
		// The oldest message still sent went with character details.
		ConversationBuilder.history(chat).get(0).context = "[C1]";
		String first = send(chat, q21, true, "[C1]").turns.get(0).text;
		assertEquals("[Summary of earlier messages in this chat: S1]\n\n[C1]\n\nQ13", first);

		reply(chat, "A21");
		Chat.Message q22 = user(chat, "Q22");
		ChatApi.Conversation later = send(chat, q22, true, "[C1]");
		assertEquals(first, later.turns.get(0).text);
		assertEquals("[Summary of earlier messages in this chat: S1]\n\n", ConversationBuilder.summaryPrefix("S1"));
	}

	@Test
	public void theSummaryRequest()
	{
		Chat chat = new Chat("x");
		Chat.Message q1 = user(chat, "Q1");
		q1.context = "[Character: Zezima]";
		reply(chat, "A1");
		ChatApi.Conversation c = ConversationBuilder.summaryConversation(chat, new ArrayList<>(chat.messages), "gpt-x");
		assertEquals("gpt-x", c.model);
		assertEquals(ConversationBuilder.SUMMARY_PROMPT, c.system);
		assertEquals(ConversationBuilder.SUMMARY_MAX_TOKENS, c.maxTokens);
		assertTrue(c.tools.isEmpty());
		assertNull(c.toolRunner);
		assertEquals(1, c.turns.size());
		assertTrue(c.turns.get(0).user);
		// Character notes stay out: the next message carries the latest one again if it's needed.
		assertEquals("The conversation to summarise:\n\nPlayer: Q1\n\nAssistant: A1", c.turns.get(0).text);
		assertTrue(ConversationBuilder.SUMMARY_PROMPT.endsWith("Plain text, at most 250 words."));
	}

	@Test
	public void summaryNotes()
	{
		assertEquals("Couldn't summarise the earlier messages (Anthropic is overloaded or having trouble right now. Try again "
				+ "shortly), so the whole chat was sent this time.",
			ConversationBuilder.summaryFailed("Anthropic is overloaded or having trouble right now. Try again shortly."));
		assertEquals("Couldn't summarise the earlier messages (you pressed Stop), so the whole chat was sent this time.",
			ConversationBuilder.summaryFailed("you pressed Stop"));
		assertEquals("Couldn't summarise the earlier messages (something went wrong), so the whole chat was sent this time.",
			ConversationBuilder.summaryFailed(null));

		Chat chat = new Chat("x");
		Chat.Message q1 = user(chat, "Q1");
		Chat.Message q2 = user(chat, "Q2");
		ConversationBuilder.applySummary(chat, List.of(q1), "S", q2);
		assertEquals("Summary of the earlier message, sent instead of it:\n\nS", chat.messages.get(1).text);
		assertSame(q2, chat.messages.get(2));
	}
}

package com.aichat;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Replies as game chat messages: split, marked, shortened, and without Markdown. */
public class GameChatEchoTest
{
	@Test
	public void repliesBecomeOneGameChatMessagePerParagraphOrListItem()
	{
		String h = "<colHIGHLIGHT>";
		String n = "<colNORMAL>";
		assertEquals(List.of(
				h + "Claude: " + n + "Right now, actually. Training Attack gets you two things at once:",
				h + "- " + n + "The abyssal whip at 70 Attack",
				h + "2. " + n + "Warriors' Guild access",
				h + "Claude: " + n + "You can do it on Slayer tasks."),
			GameChatEcho.echoMessages("Claude", null,
				"Right now, actually. Training Attack gets you two things at once:\r\n\n"
					+ "\u2022 The abyssal whip at 70 Attack\n2. Warriors\u2019 Guild access\n\n  You can do it on **Slayer** tasks.  ",
				500));
		// The model's text is escaped and never highlighted; a named chat shows its name once.
		List<String> named = GameChatEcho.echoMessages("Claude", "Bossing", "<col=ef1020>You have been banned.\n- next", 500);
		assertEquals(h + "Claude (Bossing): " + n + "<lt>col=ef1020<gt>You have been banned.", named.get(0));
		assertEquals(h + "- " + n + "next", named.get(1));
		// A list item first still says who it's from.
		assertEquals(h + "Claude: - " + n + "first", GameChatEcho.echoMessages("Claude", null, "* first", 500).get(0));
		for (String m : named)
		{
			assertFalse(m, m.contains("<br>"));
		}
		// Markdown that's only layout is left out; any kind of line break starts a new message.
		assertEquals(List.of(h + "Claude: " + n + "Top", h + "- " + n + "item", h + "Claude: " + n + "end"),
			GameChatEcho.echoMessages("Claude", null, "Top\n---\n```java\n|---|---|\n***\r- item\u2028end\n```", 500));
	}

	@Test
	public void tablesBecomeOneLinePerRow()
	{
		String h = "<colHIGHLIGHT>";
		String n = "<colNORMAL>";
		// Two columns read as "name: value"; the column names and the rule under them are left out.
		assertEquals(List.of(
				h + "Claude: " + n + "Also bring:",
				h + "- " + n + "Extended antifire: Dragonfire",
				h + "- " + n + "Anti-venom+: His venom",
				h + "Claude: " + n + "That's it."),
			GameChatEcho.echoMessages("Claude", null, "Also bring:\n\n| Item | Why |\n|---|:--:|\n"
				+ "| **Extended antifire** | Dragonfire |\n| Anti-venom+ | His venom |\n\nThat's it.", 500));
		// More columns are joined; an escaped pipe is part of its cell, and an empty cell is skipped.
		assertEquals(List.of(h + "Claude: - " + n + "Rune - 9k - a | b"),
			GameChatEcho.echoMessages("Claude", null, "| Bow | Price | Notes | |\n|---|---|---|---|\n| Rune | 9k | a \\| b | |",
				500));
		// Pipes outside a table stay as they are.
		assertEquals(List.of(h + "Claude: " + n + "| this or that |"),
			GameChatEcho.echoMessages("Claude", null, "| this or that |", 500));
	}

	@Test
	public void longRepliesAreCutWithANoteAboutThePanel()
	{
		String note = "<colHIGHLIGHT>AI Chat: the full reply is in the side panel.";
		// Cut at a word once the length setting is used up.
		List<String> cut = GameChatEcho.echoMessages("Claude", null, "one two three four five six seven eight nine ten", 20);
		assertEquals(List.of("<colHIGHLIGHT>Claude: <colNORMAL>one two three four ...", note), cut);
		// A new paragraph isn't started as a stub when the setting is nearly used up.
		String first = "x".repeat(40) + " " + "y".repeat(40);
		assertEquals(List.of("<colHIGHLIGHT>Claude: <colNORMAL>" + first, note),
			GameChatEcho.echoMessages("Claude", null, first + "\nI think you should go to Ardougne next.", 90));
		// At most a few messages, however short.
		List<String> many = GameChatEcho.echoMessages("Claude", null, "a\nb\nc\nd\ne\nf\ng\nh\ni\nj", 500);
		assertEquals(GameChatEcho.MAX_MESSAGES + 1, many.size());
		assertEquals(note, many.get(many.size() - 1));
		// Words the game couldn't wrap are shortened; the panel has the whole thing.
		String link = "https://oldschool.runescape.wiki/w/Dragon_defender?some=long&query=string&more=1";
		String shown = GameChatEcho.echoMessages("Claude", null, "See " + link, 500).get(0);
		assertTrue(shown, shown.endsWith(link.substring(0, GameChatEcho.MAX_WORD - 3) + "..."));
		// Nothing to show still says something.
		assertEquals(List.of("<colHIGHLIGHT>AI Chat (error): (empty reply)"), GameChatEcho.echoMessages("AI Chat (error)", null, " \n ", 500));
	}

	@Test
	public void markdownIsLeftOutOfGameChat()
	{
		// Links keep their text: the game can't open them, and the panel has them.
		assertEquals("Get a Dragon defender first.",
			GameChatEcho.chatText("Get a [Dragon defender](https://oldschool.runescape.wiki/w/Dragon_defender) first."));
		assertEquals("Coins are stackable.", GameChatEcho.chatText("[Coins](https://oldschool.runescape.wiki/w/Coins_(item)) are stackable."));
		assertEquals("A picture of a whip", GameChatEcho.chatText("![A picture of a whip](https://example.com/whip.png)"));
		assertEquals("https://oldschool.runescape.wiki/w/Vorkath", GameChatEcho.chatText("[](https://oldschool.runescape.wiki/w/Vorkath)"));
		assertEquals("See https://oldschool.runescape.wiki/w/Vorkath for drops.",
			GameChatEcho.chatText("See <https://oldschool.runescape.wiki/w/Vorkath> for drops."));
		// Code, emphasis, quotes and headings lose their markers.
		assertEquals("Type ::ai in the chatbox.", GameChatEcho.chatText("Type `::ai` in the chatbox."));
		assertEquals("Bring an antifire potion, not a regular one.",
			GameChatEcho.chatText("Bring an *antifire* potion, _not_ a __regular__ one."));
		assertEquals("Really important.", GameChatEcho.chatText("***Really important.***"));
		assertEquals("Note: bank first.", GameChatEcho.chatText("**Note:** bank first."));
		assertEquals("Quoted advice.", GameChatEcho.chatText("> Quoted advice."));
		assertEquals("Nested.", GameChatEcho.chatText(">> Nested."));
		assertEquals("Also nested.", GameChatEcho.chatText("> > Also nested."));
		assertEquals("Heading", GameChatEcho.chatText("> ## Heading"));
		assertEquals("", GameChatEcho.chatText("```java"));
		assertEquals("", GameChatEcho.chatText("  ~~~"));
	}

	@Test
	public void whatOnlyLooksLikeMarkdownIsLeftAlone()
	{
		// Underscores inside names and Wiki addresses, and stars in sums.
		assertEquals("Use snake_case_names and 2 * 3 * 4.", GameChatEcho.chatText("Use snake_case_names and 2 * 3 * 4."));
		assertEquals("https://oldschool.runescape.wiki/w/Abyssal_whip", GameChatEcho.chatText("https://oldschool.runescape.wiki/w/Abyssal_whip"));
		assertEquals("5*3*2 and 1_000_000", GameChatEcho.chatText("5*3*2 and 1_000_000"));
		assertEquals("[not a link] (really)", GameChatEcho.chatText("[not a link] (really)"));
		assertEquals("50 > 40", GameChatEcho.chatText("50 > 40"));
		// Half a marker, as a reply cut short might leave: shown as it is.
		assertEquals("an *unfinished thought", GameChatEcho.chatText("an *unfinished thought"));
		// Escaped punctuation is the character itself, as in the panel; other backslashes stay.
		assertEquals("Escaped *not italic* or _either_, 1. no list", GameChatEcho.chatText("Escaped \\*not italic\\* or \\_either\\_, 1\\. no list"));
		assertEquals("# Not a heading, [not](a link), `tick`", GameChatEcho.chatText("\\# Not a heading, \\[not\\](a link), \\`tick\\`"));
		assertEquals("C:\\Users\\me and \\", GameChatEcho.chatText("C:\\Users\\me and \\\\"));
	}

	@Test
	public void quotedListsAndCodeBlocksStillReadWell()
	{
		String h = "<colHIGHLIGHT>";
		String n = "<colNORMAL>";
		assertEquals(List.of(h + "Claude: " + n + "Steps:", h + "- " + n + "Buy a rune pouch", h + "2. " + n + "Fill it",
				h + "Claude: " + n + "::ai hello"),
			GameChatEcho.echoMessages("Claude", null, "Steps:\n> - Buy a *rune* pouch\n> 2. Fill it\n~~~\n::ai hello\n~~~", 500));
		// A link as a list item: the marker stays, the address goes.
		assertEquals(List.of(h + "Claude: - " + n + "Vorkath"),
			GameChatEcho.echoMessages("Claude", null, "* [Vorkath](https://oldschool.runescape.wiki/w/Vorkath)", 500));
	}

	@Test
	public void cutsAtASpaceWhenThereIsOne()
	{
		assertEquals("one two", GameChatEcho.cutAtSpace("one two three", 9));
		assertEquals("abcde", GameChatEcho.cutAtSpace("abcdefghij", 5));
		// A space too early would leave a stub: cut mid-word instead.
		assertEquals("a bcdefg", GameChatEcho.cutAtSpace("a bcdefghij", 8));
	}
}

package com.aichat;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** How the player's own game data is written up for the model, from plain values (no game needed). */
public class GameDataTest
{
	private static final long MINUTE = 60_000;

	private static GameData.ItemLine item(String name, long quantity, long price)
	{
		return new GameData.ItemLine(null, name, false, quantity, price);
	}

	private static GameData.ItemLine worn(String slot, String name, long quantity, long price)
	{
		return new GameData.ItemLine(slot, name, false, quantity, price);
	}

	private static int listed(String text)
	{
		int n = 0;
		for (String line : text.split("\n"))
		{
			n += line.startsWith("- ") ? 1 : 0;
		}
		return n;
	}

	@Test
	public void itemLinesShowNamesAmountsAndPrices()
	{
		assertEquals("Abyssal whip (1,402,330 gp)", GameData.itemText(item("Abyssal whip", 1, 1_402_330)));
		assertEquals("Shark x10 (1,032 gp each, 10,320 gp total)", GameData.itemText(item("Shark", 10, 1032)));
		// Coins are 1 gp each; the line says what the stack is worth instead.
		assertEquals("Coins x1,250,000 (1,250,000 gp)", GameData.itemText(item("Coins", 1_250_000, 1)));
		assertEquals("Dragon bones (noted) x500 (2,100 gp each, 1,050,000 gp total)",
			GameData.itemText(new GameData.ItemLine(null, "Dragon bones", true, 500, 2100)));
		// Untradeable (or prices not loaded yet): no price at all, rather than "0 gp".
		assertEquals("Graceful hood", GameData.itemText(item("Graceful hood", 1, 0)));
		assertEquals("Weapon: Abyssal whip (1,402,330 gp)", GameData.itemText(worn("Weapon", "Abyssal whip", 1, 1_402_330)));
		assertEquals("Ammo: Rune arrow x512 (90 gp each, 46,080 gp total)", GameData.itemText(worn("Ammo", "Rune arrow", 512, 90)));
	}

	@Test
	public void bigStacksDontOverflow()
	{
		assertEquals("Platinum token x2,147,483,647 (1,000 gp each, 2,147,483,647,000 gp total)",
			GameData.itemText(item("Platinum token", Integer.MAX_VALUE, 1000)));
	}

	@Test
	public void equipmentListsEachSlotAndTheTotal()
	{
		String text = GameData.equipmentText(Arrays.asList(
			worn("Head", "Helm of neitiznot", 1, 52_000),
			worn("Weapon", "Abyssal whip", 1, 1_400_000),
			worn("Cape", "Fire cape", 1, 0),
			worn("Ammo", "Rune arrow", 100, 90)));
		assertTrue(text, text.startsWith("The player's worn equipment, with Grand Exchange prices from RuneLite:\n"));
		assertTrue(text, text.contains("\n- Head: Helm of neitiznot (52,000 gp)\n- Weapon: Abyssal whip (1,400,000 gp)\n"
			+ "- Cape: Fire cape\n- Ammo: Rune arrow x100 (90 gp each, 9,000 gp total)\n"));
		assertTrue(text, text.endsWith("Total value at Grand Exchange prices: 1,461,000 gp (items without a price not counted)."));
	}

	@Test
	public void totalLeavesOutTheNoteWhenEverythingHasAPrice()
	{
		String text = GameData.equipmentText(Collections.singletonList(worn("Weapon", "Abyssal whip", 1, 1_400_000)));
		assertTrue(text, text.endsWith("\nTotal value at Grand Exchange prices: 1,400,000 gp."));
	}

	@Test
	public void nothingWornOrPriced()
	{
		assertEquals("The player isn't wearing or wielding anything.", GameData.equipmentText(Collections.emptyList()));
		// No total line at all when nothing has a price.
		String text = GameData.equipmentText(Collections.singletonList(worn("Cape", "Fire cape", 1, 0)));
		assertFalse(text, text.contains("Total"));
	}

	@Test
	public void inventoryAddsUpStacksAndCountsSlots()
	{
		Item[] inv = {
			new Item(385, 1),
			new Item(-1, 0),
			null,
			new Item(995, 5000),
			new Item(385, 1),
			new Item(537, 100),
		};
		Map<Integer, Long> stacks = GameData.stacks(inv);
		assertEquals(Arrays.asList(385, 995, 537), new ArrayList<>(stacks.keySet()));
		assertEquals(Long.valueOf(2), stacks.get(385));
		assertEquals(Long.valueOf(5000), stacks.get(995));
		assertEquals(4, GameData.slotsUsed(inv));

		String text = GameData.inventoryText(new GameData.Items(Arrays.asList(
			item("Shark", 2, 1000),
			item("Coins", 5000, 1),
			new GameData.ItemLine(null, "Dragon bones", true, 100, 2000)), 4));
		assertTrue(text, text.startsWith("The player's inventory (4 of 28 slots used), with Grand Exchange prices from RuneLite:\n"));
		assertTrue(text, text.contains("\n- Shark x2 (1,000 gp each, 2,000 gp total)\n- Coins x5,000 (5,000 gp)\n"
