		assertEquals("[t:a |b:bold|t: b]", inline("a __bold__ b"));
		assertEquals("[t:a |i:it|t: b]", inline("a *it* b"));
		assertEquals("[t:a |i:it|t: b]", inline("a _it_ b"));
		assertEquals("[bi:both]", inline("***both***"));
