		// Not from a service that didn't send any.
		server.clear();
		server.answer(PATH, events(toolCalls("[{\"index\":0,\"id\":\"c\",\"type\":\"function\",\"function\":{\"name\":\"ge_price\",\"arguments\":\"{}\"}}]"),
