		// A model stuck writing "[": the call isn't run, and the model is told why.
		JsonObject function = new JsonObject();
		function.addProperty("name", "wiki_search");
		function.addProperty("arguments", "{\"query\":" + "[".repeat(5000) + "]".repeat(5000) + "}");
