	private List<Chat.Role> roles()
	{
		return roles(chat);
	}

	private static List<Chat.Role> roles(Chat c)
	{
		List<Chat.Role> roles = new ArrayList<>();
		for (Chat.Message m : c.messages)
		{
			roles.add(m.role);
		}
		return roles;
	}
