import okio.Buffer;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Reading server-sent events: what both providers stream their replies in. */
public class SseTest
{
	private static List<String> read(String stream) throws IOException
	{
		List<String> events = new ArrayList<>();
		Sse.read(new Buffer().writeUtf8(stream), (event, data) ->
		{
			events.add(event + "|" + data);
			return true;
		});
		return events;
	}

	@Test
	public void eventsAreSplitAtBlankLines() throws IOException
	{
		assertEquals(List.of("message_start|{\"a\":1}", "ping|{}", "message|second"),
			read("event: message_start\ndata: {\"a\":1}\n\nevent: ping\ndata: {}\n\ndata: second\n\n"));
	}

	@Test
	public void dataOnSeveralLinesIsJoined() throws IOException
	{
		assertEquals(List.of("message|one\ntwo\n three"), read("data: one\ndata:two\ndata:  three\n\n"));
	}

	@Test
	public void commentsAndOtherFieldsAreSkipped() throws IOException
	{
		assertEquals(List.of("message|x"), read(": keep-alive\n\nid: 7\nretry: 1000\n: note\ndata: x\n\n"));
		assertEquals("an event without data isn't one", List.of(), read("event: ping\n\n"));
	}

	@Test
	public void windowsLineEndingsAndAByteOrderMarkAreFine() throws IOException
	{
		assertEquals(List.of("e|a", "message|b"), read("﻿event: e\r\ndata: a\r\n\r\ndata: b\r\n\r\n"));
	}

	@Test
	public void anEventCutOffByTheEndIsDropped() throws IOException
	{
		assertEquals(List.of("message|whole"), read("data: whole\n\ndata: {\"half\":"));
		assertEquals(List.of("message|whole"), read("data: whole\n\ndata: not followed by a blank line\n"));
	}

	@Test
	public void theHandlerCanStopReading() throws IOException
	{
		List<String> seen = new ArrayList<>();
		Buffer source = new Buffer().writeUtf8("data: a\n\ndata: [DONE]\n\ndata: after\n\n");
		Sse.read(source, (event, data) ->
		{
			seen.add(data);
			return !Sse.DONE.equals(data);
		});
		assertEquals(List.of("a", "[DONE]"), seen);
		assertEquals("the rest is left unread", "data: after\n\n", source.readUtf8());
	}

	@Test
	public void onlyEventStreamsAreReadAsOne()
	{
		assertTrue(Sse.isEventStream(response("text/event-stream; charset=utf-8")));
		assertTrue(Sse.isEventStream(response("Text/Event-Stream")));
		assertFalse(Sse.isEventStream(response("application/json")));
		assertFalse(Sse.isEventStream(response(null)));
	}

	private static Response response(String type)
	{
		Response.Builder b = new Response.Builder()
			.request(new Request.Builder().url("http://127.0.0.1/").build())
			.protocol(Protocol.HTTP_1_1)
			.code(200)
			.message("OK");
		if (type != null)
		{
			b.header("Content-Type", type);
		}
		return b.build();
	}
}

package com.aichat;

import java.awt.Dimension;
import javax.swing.JComponent;
import javax.swing.JPanel;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The transcript's layout: children stacked at full width (or hugging their content on their side), and only the ones
 * that changed measured again.
 */
public class StackLayoutTest
{
	/**
	 * A child that counts how often it's measured. Off screen nothing counts as laid out (that takes a window), so it
	 * keeps track of that itself, the way it would on screen.
	 */
	private static class Counted extends JComponent
	{
		int height;
		int measured;
		private boolean laidOut;

		Counted(int height)
		{
			this.height = height;
		}

		@Override
		public Dimension getPreferredSize()
		{
			measured++;
			return new Dimension(10, height);
		}

		@Override
		public boolean isValid()
		{
			return laidOut;
		}

		@Override
		public void invalidate()
		{
			laidOut = false;
			super.invalidate();
		}

		@Override
		protected void validateTree()
		{
			super.validateTree();
			laidOut = true;
		}
	}

	/** Lays itself out the way Swing does on screen, which marks what was laid out as valid. */
	private static final class Root extends JPanel
	{
		Root()
		{
			super(new StackLayout(2));
		}

		void layOut()
		{
			synchronized (getTreeLock())
			{
				validateTree();
			}
		}
	}

	@Test
	public void onlyWhatChangedIsMeasuredAgain()
	{
		Root root = new Root();
		Counted first = new Counted(10);
		Counted live = new Counted(20);
		root.add(first);
		root.add(live);
		root.setSize(100, 500);
		root.layOut();
		assertEquals(100, first.getWidth());
		assertEquals(10, first.getHeight());
		assertEquals(12, live.getY());
		assertEquals(20, live.getHeight());

		// The reply streaming in grows: only it is measured again.
		first.measured = 0;
		live.measured = 0;
		live.height = 35;
		live.invalidate();
		root.layOut();
		assertEquals(0, first.measured);
		assertTrue(live.measured > 0);
		assertEquals(35, live.getHeight());
		assertEquals(10 + 2 + 35, root.getPreferredSize().height);

		// Another width: everything is measured again.
		root.setSize(80, 500);
		root.layOut();
		assertTrue(first.measured > 0);
		assertEquals(80, first.getWidth());
	}

	/** A child that's only as wide as it needs, up to what it's given. */
	private static final class Narrow extends Counted implements StackLayout.Fitted
	{
		final int natural;

		Narrow(int natural, int height)
		{
			super(height);
			this.natural = natural;
		}

		@Override
		public int fittedWidth(int available)
		{
			return Math.min(natural, available * 85 / 100);
		}
	}

	@Test
	public void aFittedChildHugsItsContentOnItsSide()
	{
		Root root = new Root();
		Counted full = new Counted(10);
		Narrow bubble = new Narrow(40, 20);
		bubble.setAlignmentX(1f);
		Narrow wide = new Narrow(500, 20);
		wide.setAlignmentX(1f);
		Narrow left = new Narrow(30, 5);
		left.setAlignmentX(0f);
		root.add(full);
		root.add(bubble);
		root.add(wide);
		root.add(left);
		root.setSize(200, 500);
		root.layOut();
		assertEquals(200, full.getWidth());
		assertEquals("as wide as its content", 40, bubble.getWidth());
		assertEquals("on the right", 160, bubble.getX());
		assertEquals("never wider than its share", 170, wide.getWidth());
		assertEquals(30, wide.getX());
		assertEquals(0, left.getX());
		assertEquals(30, left.getWidth());

		// Unchanged, it isn't measured again at its own width either.
		bubble.measured = 0;
		root.invalidate();
		root.layOut();
		assertEquals(0, bubble.measured);
		assertEquals(160, bubble.getX());
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.sun.net.httpserver.Headers;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import okhttp3.HttpUrl;
import static org.junit.Assert.assertTrue;

/**
 * A stand-in for a provider's API on 127.0.0.1, for the provider tests: canned answers by path, served in order (the
 * last one repeats), and a record of every request. No real API is ever called.
 */
final class StandIn
{
	/** One canned answer: a status, a body and its type, and any extra headers. */
	static final class Answer
	{
		final int code;
		final String body;
		final String type;
		final Map<String, String> headers = new LinkedHashMap<>();

		Answer(int code, String body, String type)
		{
			this.code = code;
			this.body = body;
			this.type = type;
		}

		Answer header(String name, String value)
		{
			headers.put(name, value);
			return this;
		}
	}

	/**
	 * Waits at most 10 seconds for {@code latch}: how a stand-in holds an answer back until the test lets it go. Like the
	 * plugin, the tests never sleep or interrupt a thread.
	 */
	static void await(CountDownLatch latch)
	{
		try
		{
			latch.await(10, TimeUnit.SECONDS);
		}
		catch (InterruptedException e)
		{
			// The stand-in is shutting down: the answer goes nowhere anyway.
		}
	}

	static Answer json(int code, String body)
	{
		return new Answer(code, body, "application/json");
	}

	/** A streamed answer: the events, each already written out with its blank line. */
	static Answer events(String... events)
	{
		return new Answer(200, String.join("", events), "text/event-stream");
	}

	private final Gson gson = new Gson();
	private final HttpServer server;
	private final ExecutorService threads = Executors.newCachedThreadPool();
	private final Map<String, List<Answer>> answers = new ConcurrentHashMap<>();
	/** The JSON bodies of the requests, in order (null for one without a body). */
	final List<JsonObject> bodies = new CopyOnWriteArrayList<>();
	final List<Headers> headers = new CopyOnWriteArrayList<>();
	final List<URI> uris = new CopyOnWriteArrayList<>();

	StandIn() throws IOException
	{
		server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
		server.setExecutor(threads);
		server.createContext("/", exchange ->
		{
			String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
			bodies.add(body.isEmpty() ? null : gson.fromJson(body, JsonObject.class));
			headers.add(exchange.getRequestHeaders());
			uris.add(exchange.getRequestURI());
			List<Answer> queue = answers.getOrDefault(exchange.getRequestURI().getPath(), Collections.singletonList(json(404, "{}")));
			Answer answer = queue.size() > 1 ? queue.remove(0) : queue.get(0);
			byte[] out = answer.body.getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().set("Content-Type", answer.type);
			answer.headers.forEach((k, v) -> exchange.getResponseHeaders().set(k, v));
			exchange.sendResponseHeaders(answer.code, out.length);
			try (OutputStream os = exchange.getResponseBody())
			{
				os.write(out);
			}
		});
		server.start();
	}

	void stop()
	{
		server.stop(0);
		threads.shutdownNow();
	}

	HttpServer server()
	{
		return server;
	}

	HttpUrl url(String path)
	{
		return HttpUrl.get("http://127.0.0.1:" + server.getAddress().getPort() + path);
	}

	void answer(String path, Answer... queue)
	{
		answers.put(path, Collections.synchronizedList(new ArrayList<>(Arrays.asList(queue))));
	}

	void clear()
	{
		bodies.clear();
		headers.clear();
		uris.clear();
	}

	static ChatApi.Conversation conversation(String model, String... texts)
	{
		ChatApi.Conversation c = new ChatApi.Conversation();
		c.model = model;
		c.system = "Be brief.";
		for (int i = 0; i < texts.length; i++)
		{
			c.turns.add(new ChatApi.Turn(i % 2 == 0, texts[i]));
		}
		return c;
	}

	static ChatApi.ToolSpec tool(String name)
	{
		return new ChatApi.ToolSpec(name, "Looks up " + name + ".", new Gson().fromJson(
			"{\"type\":\"object\",\"properties\":{\"query\":{\"type\":\"string\"}},\"required\":[\"query\"]}", JsonObject.class));
	}

	/** All the tokens a request used, however they were billed. */
	static long tokens(ChatApi.Usage u)
	{
		return u.input + u.cacheRead + u.cacheWrite + u.output;
	}

	/** Everything a request told its listener. */
	static final class Heard implements ChatApi.Listener
	{
		final List<String> partials = new CopyOnWriteArrayList<>();
		/** "why seconds" for each retry. */
		final List<String> retries = new CopyOnWriteArrayList<>();
		final AtomicInteger answers = new AtomicInteger();
		volatile ChatApi.Reply reply;
		volatile String error;
		volatile ChatApi.Failure failure;
		private final CountDownLatch done = new CountDownLatch(1);
		private final CountDownLatch retrying = new CountDownLatch(1);

		@Override
		public void onPartial(String textSoFar)
		{
			partials.add(textSoFar);
		}

		@Override
		public void onRetrying(String message, int seconds)
		{
			retries.add(message + " " + seconds);
			retrying.countDown();
		}

		@Override
		public void onReply(ChatApi.Reply r)
		{
			reply = r;
			answers.incrementAndGet();
			done.countDown();
		}

		@Override
		public void onError(ChatApi.Failure f)
		{
			failure = f;
			error = f.message;
			answers.incrementAndGet();
			done.countDown();
		}

		/** Waits for the answer. */
		Heard await() throws InterruptedException
		{
			assertTrue("no answer", done.await(10, TimeUnit.SECONDS));
			return this;
		}

		/** Waits for the reply, failing with the error if there was one instead. */
		ChatApi.Reply reply() throws InterruptedException
		{
			await();
			assertTrue("error instead of a reply: " + error, reply != null);
			return reply;
		}

		String error() throws InterruptedException
		{
			await();
			assertTrue("a reply instead of an error: " + (reply == null ? null : reply.text), error != null);
			return error;
		}

		boolean answeredWithin(long ms) throws InterruptedException
		{
			return done.await(ms, TimeUnit.MILLISECONDS);
		}

		void awaitRetrying() throws InterruptedException
		{
			assertTrue("no retry", retrying.await(10, TimeUnit.SECONDS));
		}
	}

	/** Tool runs, recorded: "name {input}". Answers at once, or as {@code answer} decides. */
	static final class Tools implements ChatApi.ToolRunner
	{
		final List<String> calls = new CopyOnWriteArrayList<>();
		private final Map<String, Consumer<Consumer<ChatApi.ToolResult>>> special = new ConcurrentHashMap<>();

		/** How a tool answers instead of at once with "result of name". */
		Tools on(String name, Consumer<Consumer<ChatApi.ToolResult>> answer)
		{
			special.put(name, answer);
			return this;
		}

		@Override
		public void run(String name, JsonObject input, Consumer<ChatApi.ToolResult> done)
		{
			calls.add(name + " " + input);
			Consumer<Consumer<ChatApi.ToolResult>> answer = special.get(name);
			if (answer != null)
			{
				answer.accept(done);
			}
			else
			{
				done.accept(ChatApi.ToolResult.ok("result of " + name));
			}
		}
	}
}

