package com.aichat;

import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** How a table's columns share the width, and when it's drawn as cards instead. Pure: no drawing here. */
public class TableViewTest
{
	@Test
	public void columnsThatFitAreAsWideAsTheirText()
	{
		assertArrayEquals(new int[]{50, 120}, TableView.columnWidths(new int[]{50, 120}, 200));
		assertArrayEquals(new int[]{80, 120}, TableView.columnWidths(new int[]{80, 120}, 200));
	}

	@Test
	public void narrowColumnsKeepTheirWidthAndTheWideOnesShareTheRest()
	{
		// 200 for three: the 50 fits in a third, and keeps it; the other two share the 150 left.
		assertArrayEquals(new int[]{50, 75, 75}, TableView.columnWidths(new int[]{50, 300, 120}, 200));
		// The 70 doesn't fit in a share of 66 at first, but does in the 75 left once the 50 has its own.
		assertArrayEquals(new int[]{50, 70, 80}, TableView.columnWidths(new int[]{50, 70, 300}, 200));
		// The odd pixels go to the first of the wide ones; together they're the room there is.
		assertArrayEquals(new int[]{101, 100}, TableView.columnWidths(new int[]{400, 300}, 201));
		assertArrayEquals(new int[]{220}, TableView.columnWidths(new int[]{900}, 220));
	}

	@Test
	public void aTableThatDoesntFitTurnsIntoCards()
	{
		// Fits as it is: a table, however many columns.
		int[] five = {40, 40, 40, 40, 40};
		assertFalse(TableView.cards(five, TableView.columnWidths(five, 220)));
		// More than three that don't fit: cards.
		int[] four = {60, 60, 60, 60};
		assertTrue(TableView.cards(four, TableView.columnWidths(four, 220)));
		// Three, squeezed but none under 60: a table, its text wrapped.
		int[] three = {50, 300, 300};
		assertFalse(TableView.cards(three, TableView.columnWidths(three, 220)));
		// Squeezed under 60: cards.
		int[] squeezed = {100, 300, 300};
		assertTrue(TableView.cards(squeezed, TableView.columnWidths(squeezed, 160)));
		// A narrow column that has all it wants is fine, even under 60.
		int[] narrow = {30, 400};
		assertArrayEquals(new int[]{30, 190}, TableView.columnWidths(narrow, 220));
		assertFalse(TableView.cards(narrow, TableView.columnWidths(narrow, 220)));
	}
}

package com.aichat;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Redrawing a streaming reply: the newest text is always shown, but not more often than the gap allows. */
public class ThrottleTest
{
	private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
	/** For the test's own waits and offers, apart from the throttle's scheduler. */
	private final ScheduledExecutorService clock = Executors.newSingleThreadScheduledExecutor();
	/** Stands in for the EDT: one thread, tasks in order. */
	private final ExecutorService edt = Executors.newSingleThreadExecutor();
	private final List<String> passed = new CopyOnWriteArrayList<>();

	@After
	public void stop()
	{
		scheduler.shutdownNow();
		clock.shutdownNow();
		edt.shutdownNow();
	}

	/** Waits for the EDT stand-in to run what it has, including passes queued after a wait. */
	private void settle(long millis) throws Exception
	{
		clock.schedule(() ->
		{
		}, millis, TimeUnit.MILLISECONDS).get(5, TimeUnit.SECONDS);
		edt.submit(() ->
		{
		}).get(5, TimeUnit.SECONDS);
	}

	@Test
	public void theFirstValueGoesAtOnceAndTheNewestComesLast() throws Exception
	{
		Throttle<String> throttle = new Throttle<>(edt, scheduler, 50, passed::add);
		throttle.offer("a");
		settle(0);
		assertEquals(List.of("a"), passed);

		// A quick burst: one pass after the gap, with the newest text.
		for (int i = 0; i < 200; i++)
		{
			throttle.offer("a" + i);
		}
		assertEquals("a199", throttle.latest());
		settle(150);
		// Usually one pass for the whole burst; a machine that stalls mid-burst may let one more through, but the
		// newest text always comes last.
		assertEquals("a", passed.get(0));
		assertEquals("a199", passed.get(passed.size() - 1));
		assertTrue(passed.toString(), passed.size() <= 3);
	}

	@Test
	public void passesAreSpacedOut() throws Exception
	{
		Throttle<String> throttle = new Throttle<>(edt, scheduler, 40, passed::add);
		AtomicInteger offered = new AtomicInteger();
		long start = System.nanoTime();
		// A fast stream: a new text every millisecond for 400ms.
		ScheduledFuture<?> stream = clock.scheduleAtFixedRate(() -> throttle.offer("t" + offered.getAndIncrement()),
			0, 1, TimeUnit.MILLISECONDS);
		clock.schedule(() -> stream.cancel(false), 400, TimeUnit.MILLISECONDS).get(5, TimeUnit.SECONDS);
		String last = throttle.latest();
		settle(120);
		long elapsed = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
		// Hundreds offered, at most one pass per gap (and the first at once).
		assertTrue(passed.size() + " passes in " + elapsed + "ms", passed.size() <= elapsed / 40 + 2);
		assertTrue(passed.size() >= 2);
		assertTrue(offered.get() > passed.size());
		assertEquals(last, passed.get(passed.size() - 1));
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import net.runelite.http.api.item.ItemPrice;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** The tools that go with a request: which, in what order, and which runner answers each call. */
public class ToolBoxTest
{
	private final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
	private final List<String> activity = new CopyOnWriteArrayList<>();
	private final AtomicInteger started = new AtomicInteger();
	/** Never sends anything: look-ups count as turned off. */
	private final WikiClient wiki = new WikiClient(new OkHttpClient(), new Gson(), () -> false);

	@After
	public void stop()
	{
		executor.shutdownNow();
	}

	/** One tradeable item; no client thread needed. */
	private static final class OnePrice implements LookupTools.Prices
	{
		@Override
		public List<ItemPrice> search(String text)
		{
			ItemPrice whip = new ItemPrice();
			whip.setId(4151);
			whip.setName("Abyssal whip");
			whip.setPrice(1_400_000);
			whip.setWikiPrice(1_450_000);
			return "abyssal whip".contains(text.toLowerCase()) ? Collections.singletonList(whip) : Collections.emptyList();
		}

		@Override
		public long price(ItemPrice item)
		{
			return item.getWikiPrice();
		}

